INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (5502,'zhCN','部落孤儿的看护者','从奥格瑞玛暗巷区的布雷克斯·瓶装火箭那里购买泡沫塑料剑架，然后将你的孤儿送回奥格瑞玛孤儿院，同暗巷区的孤儿监护员巴特维尔交谈，送你的孤儿回家。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (5634,'zhCN','与铁炉堡的高阶牧师洛汉谈一谈。','最近有位牧师来这里找过你，年轻的$R。他说受命来寻你，希望你尽快赶回铁炉堡的秘法大厅。等你到了那儿，去找高阶牧师洛汉——他会向你说明一切。$B$B愿圣光与你同在，$N。',0) ON DUPLICATE KEY UPDATE `LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (6984,'zhCN','烟林牧场的感谢','和奥格瑞玛的冬天爷爷谈一谈。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (7364,'zhCN','诺莫瑞根大通缉！','你被指派去杀死奥特兰克山谷中的牛头人玩家。$B$B杀死一个牛头人，然后把牛头人的蹄子交给丹巴达尔的德尔克。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (7365,'zhCN','鹿盔的挽歌','你被指派去杀死奥特兰克山谷中的巨魔玩家。$B$B杀死一个巨魔，将暗矛巨魔魔精交给丹巴达尔的亚斯拉玛尼斯。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (7366,'zhCN','大主教的仁慈','你被指派去杀死奥特兰克山谷中的被遗忘者玩家。$B$B杀死一个被遗忘者，然后把一枚被遗忘者的精华交给指挥官卡尔·菲利普（他一般在伐木场和矿井之间徘徊）。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (7381,'zhCN','科尔拉克归来','如果科尔拉克重新出现在奥特兰克山谷的冰斧山洞中，就找到并干掉他。$B$B将科尔拉克的徽记交给霜狼要塞的拉格隆德。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (7382,'zhCN','永生的科尔拉克','如果科尔拉克重新出现在奥特兰克山谷的冰斧山洞中，就找到并干掉他。$B$B将科尔拉克的徽记交给丹巴达尔的哈格丁中尉。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (7402,'zhCN','通缉：兽人！','你被指派去杀死奥特兰克山谷中的兽人玩家。$B$B杀掉一个兽人，然后把兽人的獠牙交给丹巴达尔的诺雷格·雷矛中尉。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
