INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (65593,'zhCN','爱人的徽记','把阿薇丽娜·莉莉和艾萨克·皮尔森的徽记带给诅咒神殿的凯伦丁·哈加尔。','夜魔会被情人的徽记所吸引，而最让人心痛的爱会产生最无法抗拒的诱饵。$B$B我的占卜显示有两个人可以完美地完成这项任务。$B$B在银松森林，阿薇丽娜·莉莉为安伯米尔的堕落巫师提供裁缝服务；在贫瘠之地，艾萨克·皮尔森希望在海滨城市棘齿城做出一番事业。$B$B他们在世界的两端忙碌着，但他们的心渴望着彼此。把他们的徽记带给凯伦丁。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (65597,'zhCN','束缚','使用情人的徽记，召唤并征服一只夜魔，然后将情人的徽记还给幽暗城魔法区诅咒神庙里的凯伦丁·哈加尔。','终于，时候到了。把徽记放到下面的召唤法阵，放在中央，召唤夜魔。$B$B恶魔发现你引诱它进入了陷阱的话，肯定不会高兴的。别成为它的诱惑法术的牺牲品。$N。你必须彻底征服它。$B$B只有那时我才能教你法术，让你把它和你的意志绑定在一起。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (65601,'zhCN','要爱就会受伤害','和奥格瑞玛的玛加尔谈一谈。','男性萨亚德被称作夜魔。那是种心中只有纯粹邪恶的生物。$B$B恶魔只能被有诱惑力的物品引诱进我们的世界——这个物品要能够代表强烈的爱和奉献。$B$B唔……如果你相信盲人给你的指引的话，那就听仔细了，$N。在奥格瑞玛的暗巷区里暗影裂谷的东面，住着玛加尔。他渴望着格莱基的回归。$B$B去找他吧。他会请你去寻找宝贵的东西。那东西很关键，你找到后必须交给甘鲁尔。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (65602,'zhCN','爱是什么？','取得木雕，把它交给暴风城法师区里的黑暗缚灵者加科因。','你需要强大的反应物才能吸引到夜魔，得是一件代表伟大的奉献和爱的东西。$B$B我通过占卜确定了一个小雕像的位置，应该很适合在你的仪式上使用。$B$B数千年前，这个雕像属于两个年轻人。他们已经不在了，但这份纪念品一直留存到了现在。$B$B顺着北方的道路进入灰谷，然后向西经过迈斯特拉岗哨。你会在树林里看到一座房屋，在里面就是你要找的东西。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (65603,'zhCN','束缚','使用木雕召唤并制服一个夜魔，然后将木雕还给已宰的羔羊旅店的黑暗缚灵者加科因。','时候到了。拿上木雕，前往下方的地穴。召唤法阵已经准备完成，你必须把木雕放在中间。$B$B然后传送门就会打开，夜魔会进入我们的世界。$B$B绝对不能低估萨亚德。这种恶魔一旦发现你在耍诈就会立刻攻击你。你必须全力以赴才能击败它。$B$B成功后回来找我，我会把这生物和你的意志绑定。失败的话，你的灵魂就不属于你了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (65604,'zhCN','束缚','使用皱缩头巾召唤并征服一只夜魔，然后皱缩头巾还给奥格瑞玛的甘鲁尔·血眼。','嗯，我明白了。我感觉到了丝线中残留的情感。一针一线中织入了爱。夜魔肯定无法抵抗。$B$B把这个带到尼尔鲁的帐篷里的召唤法阵，$N。召唤一只邪恶的夜魔，然后成为它的主人。别指望它会安静地屈从于你。准备好使用魔法作战。低估恶魔是很多术士犯下的最后一个错误。$B$B你击败它后，把布还给我。我会告诉玛加尔你找到了什么。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (65610,'zhCN','希望你还在','调查灰谷的坠星湖并将你的发现告诉奥格瑞玛的甘鲁尔·血眼。','我在灰谷制作月布时认识了格莱基。他驻扎在那里保护平民，然后他失踪了……$B$B他们已经停止搜索了，觉得他是个逃兵，但我不信。$B$B我们经常在坠星湖见面，然后那里就被那些充满进攻性的沼泽兽占据了。$B$B我并不是喜欢请人帮忙，但如果你去灰谷寻找一下他的踪迹，我会感激不尽。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (76156,'zhCN','大地母亲与匿同在','潜入雷霆崖东南部的风险投资公司矿区，从冲击补给品货车中收集5个爆盐采矿炸弹，随后交给雷霆崖的巴通·阴影图腾。','$C，我看得出，你很有几分潜行的天分。戴上这副面具，混进附近的风险投资公司矿区，偷些补给回来。别看这伪装不怎么像样，真正高明的潜行者只消笑一笑，再巧妙地分散对方的注意，就能从任何守卫眼皮底下溜过去。我相信，你也做得到。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (76160,'zhCN','大地母亲与匿同在','在雷霆崖北部收集8个风怒球果，在研钵和捣杵中使用它们，随后带着成果返回雷霆崖的巴通·阴影图腾处。','也许你更擅长用毒，而非伪装。北边的鹰身人将巢筑在树上，那树能分泌出剧毒树脂。去巢穴周围收集掉落的球果，捣碎熬成毒膏。把它涂抹在刀刃上，不仅能烧烂对手的皮肉，还能让他们的血液化作盐粒。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (76240,'zhCN','大地母亲与匿同在','购买或捕捉一条新鲜的闪亮小鱼，在雷霆崖的巴通·阴影图腾面前使用一套匕首将其大卸八块。','我还有最后一个能够成功的办法。我依然觉得你具有隐藏的天赋，我们要用不那么直接的方式把它激发出来。$B$B你去找一条新鲜的闪亮小鱼，把它带回来，再用匕首大卸八块。不要深思，自然就好。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (78091,'zhCN','刻苦赚盐','从赤脊山的黑石召唤师处收集14份召唤师之盐，随后返回暴风城的厄苏拉·德林处。','我会研究这颗宝珠，把我的发现告诉你，但你必须先替我办事。$B$B黑石氏族的术士会使用特制的精盐来增强召唤仪式。从赤脊山的兽人身上收集一些精盐。$B$B等你回来了，我就把研究的结果告诉你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
