INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (79008,'zhCN','……以及你找到的那张字条','残存的焦灼纸条是你唯一的向导。','<余烬的微光渐渐暗去，你偶然发现了不久前一场火灾留下的残迹。$B$B散落的补给品中，有一张被火烤得起泡的字条。>$B$B“并非所有燃烧之物都会消逝。找到孪生之地，便能找到那里。”',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
