INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (79097,'zhCN','拜克斯坦：论毁灭性魔法',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (79192,'zhCN','垫脚石','你扯下了木板上的纸条，读着那七扭八歪的字迹。','纸条上写着，“任务说他们都在给新瘟送货。我看这都是简单的药剂事故。如果想找个安全的地方和我谈谈，就到贫瘠之地和凄凉之地接壤的群山中，找到我那舒适的歇脚处。”',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`QuestDescription`,`VerifiedBuild`) VALUES (79358,'zhCN','风暴、大地与火焰','水淹千针石林绝非小事，$N。若非亲身感受到元素的狂怒，我根本不敢相信。但事实已摆在眼前。$B$B野猪人不是第一个把元素当成武器滥用的，也绝不会是最后一个。要想准备反制仪式，我们得深入摸清这些扭曲的元素。拿着这本书。里面详细记载了艾泽拉斯的各族生灵，以及他们研习萨满教的历程。$B$B如果你能从中悟出点什么，或许就能找到破局之法。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (79360,'zhCN','元素救兵','在剃刀沼泽击败卡尔加·刺肋，收集有关野猪人计划的情报。','既然你已驾驭了元素，就该对它们、对整个艾泽拉斯肩负起责任。我们呼唤元素的援助，而非强取豪夺。是时候投桃报李了。我正好有个主意。$B$B野猪人为了私欲扭曲元素，甚至还在不断扩张地盘。去剃刀沼泽，粉碎他们的阴谋。必须保卫这片土地。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (79362,'zhCN','格兰特的盾牌','去乌鸦岭墓地，从某具骷髅身上找回格兰特的钉锤，然后返回夜色镇，向希拉·沃宁迪打探更多线索。','这是由瓦洛家族的先祖、乌鸦岭的英雄——格兰特·瓦洛的幽魂遗落的盾牌。$B$B格兰特的灵魂至今仍在与亡灵厮杀。也许他执念未消，非要亲手斩杀那头在乌鸦岭墓地重创他的天灾怪物不可——那怪物的身上，多半还嵌着他的钉锤呢。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (79363,'zhCN','西尔维娅的剑','在腐草农场击败7名迪菲亚夜贼和7名迪菲亚附魔师，然后返回夜色镇向希拉·沃宁迪了解更多情况。','这是乌鸦岭守卫西尔维娅·瓦罗的灵魂留下的长剑。她一生都在保护平民及其家园。$B$B西尔维娅的灵魂仍在各处农庄徘徊，也许她的未竟之事，就是赶走盘踞在乌鸦岭以南腐草农场的迪菲亚匪徒。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (79364,'zhCN','仰望天空','与千针石林的普拉特·白云交谈。','你找到的字条上写着，钢鬃潜入了千针石林，正密谋一场仪式。狂风呼啸，潮水漫灌……$B$B野猪人肯定是动用了从希尔泽克那儿学来的残忍巫术。那个萨满祭司为了扭曲元素，可谓不择手段。想要淹没峡谷，必须动用毁天灭地的元素力量。$B$B我们对此束手无策，但像你这样强大的萨满祭司定有对策。回去找你的盟友，看看能不能寻得破局之法。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
