INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (79974,'zhCN','肮脏活计','你从泥巴里拖出了一个信使行囊，拂去尘埃后，你发现补给品中夹着一卷羊皮纸。','“我总喜欢在附近留些备用物资，以防哪天不得不仓促逃命。$B$B这片山壁美极了，说是由时光的瀑布雕成也不为过。$B那里就是鹰巢，也是你要找的地方。”',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (79975,'zhCN','雄鹰之拳','水汽四散，润雾乘风，这番风光不可思议。','<你在工具箱里发现了一封仔细折好的信。>$B$B“从这里出发，只要工具趁手，一切都由你做主。这里很适合放出降落伞滑翔翼。$B$B为了更好地效忠鹰与拳，我必须与他们保持距离。这道壁垒早已不复当年，就像它曾拱卫的旧日王国一样，但我永远不会抛弃它。”',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (79976,'zhCN','一定就是这里','不管原先谁在这里，你都与其失之交臂。','“所以，我决定把自己的研究带回地底，以免落入歹人之手。”$B$B<这张纸只撕下了刚好容纳这段话的一小块。你无法确定这是作者最后留下的消息，还是指向下一个藏身处的线索。一个没有扎牢的睡袋正缓缓铺到你的脚边……>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (79980,'zhCN','翻山越岭','探寻接下来的遭遇。','“还不错吧？既然你读到了这张字条，就说明我的储藏还在。朝正北走一百步，下陡坡时可别摔断脚踝。那里的东西应该足够你继续上路。”',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
