INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (86574,'zhCN','石爪峰补给运输','从巨翼双足飞龙那里收集6份石爪补给品，并将它们交给旅店老板法拉莉亚。','<这具不幸的遗体上留有巨翼双足飞龙的多次袭击痕迹。附近的背包皱巴巴地被丢弃在一旁，里面的东西已不翼而飞。信使手中紧紧攥着的一张小纸条指明了遗失之物：一批原本要送给石爪峰旅店老板法拉莉亚的货物。>$B$B<双足飞龙很可能已经把补给包叼走去垫窝了。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (86576,'zhCN','血怒饰品','把15块闪光的太阳石带给摩罗加尔。','除了在焦炭谷散播污秽之外，血怒鹰身人还会收集它们能找到的任何闪亮物品。我听说它们收集各种金黄色的太阳石用来做装饰。我对这种小物件没什么用，但摩罗加尔以前曾提到过要用它们。$B$B当你在谷中与鹰身人战斗时，请留意闪光太阳石。把找到的石头都带给我们在上方山丘里的摩罗加尔。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (86585,'zhCN','阵亡者的旗帜','举起铁炉堡的旗帜，引出穴居人劈头斧并将其消灭，然后向拉格弗斯上尉报告。','这名倒下的巡山人带着一面铁炉堡的旗帜。也许她当时正在侦察，或者进行着一场注定失败的冲锋。不管怎样，这面旗帜已经被丢弃并遭到践踏。这名巡山人的头部遭到了重击，头盔都被打飞了。她被一名穴居人当场击杀，凶器很可能是一根带刺的木棒。$B$B杀死她的穴居人很可能还在附近，并且很可能记得这面旗帜。再次举起铁炉堡的旗帜也许能把它引出来。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (86614,'zhCN','浪中银光','将刻有姓名缩写的银发夹物归原主。','<残骸中的钓鱼杂物里有一些生锈的鱼钩、断裂的线轴，还有一枚略微腐蚀却依旧精美的银质发夹，上面刻着字样“卡·深”。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (86667,'zhCN','困于风雪','把一瓶雪罐送到洛克湖西北岸诺里克·洛克赛恩家里。','我的老导师诺里克派来了一个次级元素，还带来了一个奇怪的请求。他的萨满仪式居然需要一罐雪！我不知道他打算用它做什么，但我很久以前就学到了，在魔法方面永远不要质疑他的做法。$B$B我正忙着了解当地的元素生物，所以抽不开身去帮他。前往南门小径的隧道入口处吧，那里终年积雪。用这个陶罐装点雪，在它融化前交给他。这个罐子应该能让雪保持冰凉。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (86757,'zhCN','减缓兽人的攻势','将6把锯齿兽人剑和4把弧形兽人匕首，带去交给珊蒂瑞亚。','那些粗鄙的兽人已经彻底占领了东部森林，现在，整片林子里都潜伏着他们的斥候和步兵！如今我们再想在灰谷里随便走动，已经变得极不安全了。$B$B我们必须设法击退这些兽人，保卫这片森林。之前，我们借着小心翼翼地潜行到他们营地的边缘地带，好歹也算是解决掉了几个落单的步兵和斥候。$B$B去跟那些兽人战斗吧，把他们手里用的锯齿长剑和弯曲匕首全给我带回来。我会派人把这些武器统统回收，然后重新熔铸利用，保证不浪费一点儿有用的材料。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (86758,'zhCN','补上一刀','找到并消灭那只名叫刀齿鳄的鳄鱼，把马雷克的刀给带回来。','我有没有跟你提起过，之前有一次，我差点就被一只大鳄鱼给咬掉了一只手？当时我拼了老命，才勉强把刀给卡进了它的下巴里，然后趁机飞快地逃了出来。我之前一直以为那把刀就掉在这附近了，可找了半天怎么也找不到。$B$B总而言之，那只该死的鳄鱼，现在多半还在这片湖边转悠着捕猎呢。哪怕仅仅只是为了保障其他猎人的生命安全，咱们也得想个办法把那头凶兽给彻底除掉。$B$B我甚至连名字都给它想好了，就叫它刀齿鳄。你要是在路上碰巧撞见了它，记得替我非常“友好”地向它问声好！当然了，我所说的“问好”，意思就是“给我狠狠地捅它一刀”。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (87288,'zhCN','柔软的夜刃豹皮','将6张柔软的夜刃豹毛皮交给阿尔德里亚。','旅途平安，朋友。多兰纳尔是个宁静祥和的村子，大家都很随和，希望你会喜欢这里。$B$B我是个行商，专卖各种出门在外用得着的零碎物件。要是你想搭把手做笔交易，我这儿正缺几张夜刃豹的皮毛。虽说这群大猫身姿矫健，但野性难驯，极具攻击性。你为了自保剥下它们的皮，也不必觉得有什么罪过。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (87760,'zhCN','神圣潜水员','找到一名雷鳞兽王，除掉她，并带回她的深渊统御法杖。','$N，达纳苏斯回信了！$B$B通过分析动物样本，我们发现纳迦用心智控制了这些海洋生物，强迫它们充当坐骑和驮兽。对于那些过于倔强、年迈或是伤势过重的，纳迦干脆就把它们像赶去取乐一样驱逐掉。简直丧心病狂！$B$B阻止这等暴行是我们的神圣职责！$B$B纳迦在玛塞斯特拉废墟驻扎了一支部队，他们肯定在捕捉近海的长尾鲨。去找到他们的驭兽者，除掉她，然后把她用来奴役野兽的工具带回来！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91294,'zhCN','巡视营地','与班达里安堡的居民交谈。','眼下鱼人袭击的威胁已得到控制，我建议你四处看看，熟悉一下我们的据点。这里还称不上宏伟，但已经是我们的家。$B$B参观完后，去找我们的领袖丹妮莎·莫尔。她会帮你在这里安顿下来。$B$B很高兴认识你，$N。愿圣光指引你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91316,'zhCN','修理伐木机','从提瑞斯法林地的影谷收集12块坚固的木材。','此地远离幽暗城，补给线拉得太长。我们极度缺乏修缮堡垒的建材，希望你能搭把手。$B$B西南方的耳语森林里，坐落着沦为废墟的影谷村。那儿有间屋子连着个旧地窖，里面堆着各种杂物。下面可能还有能用的建材。去搜刮一番，把能用的带回来交给我们。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91317,'zhCN','黯淡者','在提瑞斯法林地消灭8个黯淡的苦工和6个黯淡的狂热者，并收集指挥官鲁道夫·盖尔哈特的徽记。','正如你所见，并非所有复生的圣骑士都能适应这种新的存在方式。有些人仍执迷于生前的偏见，继续对被遗忘者同胞施加暴力。$B$B族人本就对我们心存芥蒂——他们可没忘记生者曾以圣光之名降下的迫害，而这些袭击无疑是雪上加霜。一些黯淡者已经在西南方的影谷盘踞。去解决他们，把他们首领的徽记给我带回来。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91723,'zhCN','精密仪器','在玉石矿洞消灭8名狗头人地卜师，然后返回阿祖拉之塔，向哈米什·伯格沃特复命。','真该死！每当我试着校准这些精密的奥术仪器，总有一阵能量涌动把读数再次扰乱。$B这些能量似乎来自北方，那里的原始狗头人正在摆弄粗陋的魔法。你能赶走一批狗头人，让我继续工作吗？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91724,'zhCN','精密仪器','在石碑湖消灭8名迪菲亚流浪巫师，然后返回阿祖拉之塔，向哈米什·伯格沃特复命。','就快好了，接下来……空灵在上！怎么还有东西在干扰我的仪器！$B$B真是让人恼火，$N。我听说本地的匪徒正在石碑湖附近练习法术。也许让他们停手，这些干扰就能彻底消失，我也终于能干点正事了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91725,'zhCN','失窃的附魔补给','从石碑湖周围的豺狼人营地收集5份失窃的附魔补给，然后交给阿祖拉之塔附近的布里克斯·菲兹温克。','塞欧克瑞图斯大师派我去贸易站取些附魔材料，可我在回程途中却遭到了一群豺狼人的伏击！$B$B我扔下包裹侥幸逃生，可要是就这么空手而归，接下来的几周我肯定会被罚去清理变形实验的烂摊子！你能不能帮我找回那些材料？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91732,'zhCN','好钢','从玉石矿洞收集4件采矿工具，然后交给东谷伐木场的哈加尔·洛。','战后，好钢极为短缺，我们的工具也因此破损严重。玉石矿洞的矿工曾使用工艺精良的矿镐，我想矿洞深处应该还留着一些。你能替我取回几件吗？我会看看能否重新利用其中的钢材。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91733,'zhCN','顺流而下','找回从东谷伐木场顺流漂走的浸水的斧头、浸水的锯子和浸水的工具箱，然后交给奥尔敏·佩尔福德。','我从贸易站运补给回来，半路上货车翻了，东西全掉进河里！还没来得及打捞，就被水冲到了下游。$B$B那边又是鱼人，又是狼，靠我自己根本没法把补给找回来。看你身手不凡，能帮我找回来吗？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (91736,'zhCN','苹果酒酿造炉',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (91738,'zhCN','苹果佳酿',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91745,'zhCN','采矿顾问','去跟北郡山谷回音山矿洞外的凯尔西·法戈谈谈。','去找新来的采矿学徒凯尔西·法戈谈谈吧。她平时就在矿洞外头干活，八成见过那些狗头人在搞什么名堂。说不定她还能顺手教你两招采矿的本事。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91751,'zhCN','粗糙的狼皮','在艾尔文森林猎杀狼并剥皮，取得7张粗糙的狼皮，然后交给闪金镇附近的海伦尼·派特斯金纳。','想找个机会练习剥皮吗？我丈夫平时会帮忙猎狼，可他正在修道院附近忙活。我手头还有不少订单，正缺狼皮，你能帮我收集一些吗？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91752,'zhCN','着眼大局','从寻宝者纳夫手里夺回一袋图画书，然后把袋子交给北郡修道院入口处的治安官玛克布莱德。','每隔一阵子，就会有个狗头人跑过来大喊“给纳夫的图画！”我不知道纳夫是谁。没准是矿洞深处的某个狗头人头目？我敢打赌，他现在肯定已经攒了整整一大袋子书了。$B$B去把那些书夺回来，然后交给我们当地的执法官——治安官玛克布莱德。你最好找个朋友搭把手。矿洞里的狗头人可比外面的凶狠多了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91753,'zhCN','附魔一课','阿祖拉之塔的基塔·费温德需要你收集3份发光的残渣。$B$B发光的残渣可以通过分解狗头人地卜师掉落的粗制的蜡像来获取。','对附魔师的技艺而言，严谨的学术态度固然不可或缺，但扎实的实践基础同样能带来丰厚回报。就拿卑微的狗头人来说吧。他们缺乏正规教育，却对简单的戏法和附魔展现出某种天生的悟性。$B$B去弄些他们的蜡像来，拆解封存在其中的附魔。你或许能从中获得启发。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91758,'zhCN','跟上那个狗头人！','与北郡修道院后方马厩附近的托德林·斯特恩布雷德交谈。','你跟那些狗头人的账可还没算完。凯尔西刚传来消息，说有个狗头人扛着一大袋书溜出了矿洞。你得顺藤摸瓜追踪这个狗头人，好让我们替帕克斯顿修士把书给夺回来。$B$B去找托德林·斯特恩布雷德谈谈。他是刚从铁炉堡过来的新猎人训练师，就在修道院后边的马厩附近。他能帮你追踪那个狗头人小偷。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91772,'zhCN','狩猎狗头人','沿着狗头人的踪迹追查，带上狗头人追踪工具包，去向闪金镇的治安官杜汉报告你的发现。','好吧。拿上这套狗头人追踪工具。它能帮你追踪治安官玛克布莱德提到的那个狗头人。$B$B顺着踪迹追下去，把你找到的线索带给闪金镇的治安官杜汉。$B$B我有种预感，这些害虫正在北郡外头憋着什么坏水。所以你肯定用得上杜汉的帮忙。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`QuestDescription`,`VerifiedBuild`) VALUES (91775,'zhCN','归还书籍','调查法戈第矿洞时，看看能否顺道找回帕克斯顿修士的书。帕克斯顿特别担心其中一本名为《和元素一起玩》的书，他认为即便是狗头人，也可能借此召唤出元素仆从。当心点，矿洞深处十分危险。你最好叫上几个朋友同行。$B$B带上这个书袋，找到书时可以用来保护它们！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91777,'zhCN','珍稀书籍','取回《好奇小巫师的地卜术》和《奥术详解：用简单的话解释魔法》，并交还给北郡修道院内的帕克斯顿修士。','帕克斯顿修士的书单上还缺两本书：《好奇小巫师的地卜术》和《奥术详解：用简单的话解释魔法》。$B$B狗头人肯定把它们带到玉石矿洞去了。请寻回这两本书，并将其交还给北郡修道院内的帕克斯顿修士。$B$B不过恐怕此行极为凶险。如果那个“学徒”狗头人都能召唤出元素，谁知道它的师傅能使出什么手段。换作是我，肯定会找几个朋友结伴而行。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91858,'zhCN','外交风波','前往银松森林的瑟伯切尔，与特雷凡·罗尔谈谈失踪的大地之环旅客。','银松森林发生了一场极为不幸的变故，却也给了我们一个难得的机会，可以向部落证明自身的价值。$B$B两名大地之环的要员在穿越银松森林前往塔伦米尔途中失踪。我们所知不多，只听说此事正逐渐演变成一场严重的外交风波。如果能找回失踪者，或许能为我们赢得迫切需要的认可。$B$B我们有个人驻守瑟伯切尔，名叫特雷凡·罗尔。去那里找他谈谈。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91859,'zhCN','古怪的二人组','与亡灵卫兵巴尔德伦交谈，询问最近经过瑟伯切尔的那两名神秘大地之环旅客。','我就直说了，这两位“要员”可不是什么普通外交官。其中一位是牛头人，这对大地之环来说倒不稀奇；可另一位——你恐怕很难相信——竟是个精灵，还是一名*高等*精灵。他们虽然都披着斗篷，但我以前见过奎尔多雷，敢拿自己的小拇指担保，我绝不会认错。$B$B一个精灵为什么会陪着牛头人穿越部落领地？你的猜测不会比我的更差。我知道的就这些。建议你去镇子入口附近找亡灵卫兵巴尔德伦谈谈。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91860,'zhCN','悲惨的命运','调查东边的芬里斯岛，查明大地之环旅队的下落。','昨晚巡逻时，我看见一群豺狼人把一具硕大的尸体扔上了芬里斯岛岸边的火堆。我没看到精灵，也没发现其他较小的尸体，但这对他们来说恐怕不是什么好兆头。$B$B如果你够勇敢，或者够愚蠢，大可以闯进芬里斯岛查个究竟。不过要我说，为了找一个多半早已死透的傲慢精灵费这么大力气，实在不值。$B$B我知道你们圣骑士最爱立誓，也最爱揽下无望的差事，但这件事不值得。相信我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91861,'zhCN','进入芬里斯城堡','前往北方的芬里斯城堡展开调查，设法寻找大地之环队伍中失踪的成员。','<你只找到了一具尸体，或许这意味着还有希望。特雷凡和哈德瑞克提到的那名高等精灵，也许仍活在附近堡垒的更深处？>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91862,'zhCN','卢米娜·风歌','从腐皮豺狼人手中夺回芬里斯岛钥匙，解救卢米娜·风歌。','奎尔多雷？不，我才不是什么“奎尔多雷”。我是卢米娜·风歌，我是申多雷。塑风者天裔的一员。$B$B我作为大地之环的客卿来到此地。我和同伴巴农原计划穿过银松森林前往阿拉希高地，研究那里的元素汇聚。很显然，我们在半路折戟了。$B$B现在没时间闲聊了。去干掉附近的豺狼人，找出笼子的钥匙，放我出去。等我们安全脱身，我再把剩下的事讲给你听。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
