INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91921,'zhCN','再次返回奎恩身边','将奎恩的药水带给瑟伯切尔北方伊瓦农场的奎恩·尤瑞克。','这是帮助奎恩恢复的新药水，里面满载着从整整六颗心脏中提取出的爱意。$B$B现在，请容我先行告退，免得你的出现又让我多添几份文书工作。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92109,'zhCN','我的第一套炼金设备','将5个空瓶、5株银叶草和5株宁神花交给西部荒野月溪镇谷仓里的那位年轻的炼金术学徒。','呃……你好，$G先生:小姐;。爸爸说不能和陌生人说话，可是……嘿，你背包里露出来的那些亮晶晶的瓶子是什么呀？你是炼金师吗？简直太酷了！$B$B我长大以后也想当个炼金师。爸爸从来不让我碰他的草药，他总说太危险了。$B$B可我现在就想学嘛。你能不能帮我弄点材料来？拜托拜托！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92110,'zhCN','我的第一瓶真正的药水','为西部荒野月溪镇谷仓里的炼金术小梦想家收集3颗鱼人的眼球。','哇，我的第一瓶药水！你刚学炼金那会儿，知道把这两种草药混在一起会让药水变成鲜红色吗？$B$B真好玩，可只是把几朵花混在一起，总感觉不像是爸爸做的那种炼金术。他还会用到别的材料呢。$B$B我也不知道还能加点什么，不如就试试我脑子里最先想到的东西吧！让我想想……鱼人的眼球怎么样？听起来怪恶心的，不过肯定会有奇效。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92124,'zhCN','图书盘点','与图书馆中帕克斯顿修士的助手丹尼尔交谈。','我们得好好清点一下到底丢了多少书！$B$B去叫我那个没用的助手丹尼尔过来。他手脚快，能帮我们清点库存，看看情况到底有多糟。$B$B这小子整天沉迷于艾尔文森林的各种专业，正经事一点都不上心。$B$B别听他没完没了地扯什么专业技能，赶紧弄清楚我的书到底怎么了！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92415,'zhCN','记住我爱你','将染血的信交给暴风城的孤儿监护员奈丁加尔。','<在这片满是亡灵足迹的墓地中，一卷残破不堪、沾满污渍的羊皮纸侥幸留存了下来。上面提到了织心家族一个失踪的孩子。暴风城的孤儿院院长或许能提供些线索。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92421,'zhCN','圣光的正义','在洛丹伦废墟收集25个完好的肢体，交给幽暗城的莫宾·圣光之灾。','贯彻黑暗女王的意志，满足同胞的需求，是我作为被遗忘者圣骑士的天职。天赐良机，眼下刚好能一石二鸟。$B$B幽暗城之上，海量的天灾残党仍在废墟间游荡。为了光复故土，我们的兵力日渐损耗。腐烂的血肉无法凭空再生——我们需要新鲜的肢体来修补躯壳。$B$B如果加瑞克·班达里安队长还在世，他必定会这么做。完成他的遗志，治愈我们的同胞。为了洛丹伦！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92432,'zhCN','紧急求援','前往达拉然城附近，向大法师茉德拉的影像复命。','我从达拉然带来了坏消息。有某种力量扰乱了我们的魔网，导致城里的构造体彻底失控，四处大肆破坏。$B$B我们至今还不知道，这场混乱的罪魁祸首究竟是谁。最高议会下令封锁消息，免得给肯瑞托抹黑。可这件事根本瞒不了多久——就在我们说话的这会儿，整座城市都快沦陷了！$B$B大法师茉德拉派我出来秘密求援。去达拉然附近的洛丹米尔湖畔，找她的影像吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92434,'zhCN','喋血街头','沿着洛丹米尔湖，寻找潜入达拉然的路线。','无论是什么削弱了达拉然的结界，整座城市如今已彻底陷入混乱。既然你已经打发了巡逻兵，眼下正是潜入城中、挖出他们底细的绝佳时机。$B$B带上你从收容所搜来的钥匙，去城市北边找下水道入口。运气好的话，那些自命清高的法师压根不屑于在这种……令人作呕的地方设下防御。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92456,'zhCN','绿色样本','从达拉然城内摘取一朵注入邪能的花朵，交给暴风城的莎拉米尔。','既然你非要来烦我，那至少得派上点用场。我有个差事需要人去跑一趟。$B$B对于一座法师之城来说，达拉然对植物学的兴趣出奇地浓厚。肯瑞托一直都很孤僻，但我很想弄到一份他们那里注入了法力的植被样本。$B$B显然，你很擅长潜入那些不欢迎你的地方，也许你能找到进城的方法。如果你成功了，把他们中央花园里生长的任何东西带回来给我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92457,'zhCN','饥渴的奥术','在达拉然城内击败8个探求残渣、8个饱和残渣以及8个法力回响，而后向城外的大法师茉德拉复命。','结界受损导致城内大量自动装置和附魔失效，连外围的防御设施也未能幸免。逸散的奥术能量引来了大批狂暴的元素，它们贪婪地想要饱餐这股四溢的魔力。$B$B眼下我们正忙于修复结界和处理其他棘手的大麻烦。如果你能帮忙清理掉这群元素，肯瑞托会记下你这份人情的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92458,'zhCN','动乱之源','为达拉然城附近的大法师茉德拉的影像收集奥术微粒。','无论是什么引发了魔网暴走，源头都在紫罗兰城堡的顶端。上方的大厅传来一声巨响，紧接着，狂暴的奥术能量便将我们吞没。我们已经竭尽全力，却也只能勉强维持结界。$B$B不能再这样耗下去了。我们需要外援。$B$B城里的肯瑞托法师已经乱成一团，你得设法找条隐蔽的路潜入城中。带上这把钥匙，进城后直接来城堡找我。我们必须从源头平息这场动乱。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92459,'zhCN','肯瑞托之友','与达拉然城的大法师塞琳德拉交谈。','议会知道我们的暗中行动后肯定不会高兴，但他们绝对无法否认我们的成效。城里正在慢慢恢复平静，我们终于可以撤下结界了。$B$B这个好消息理应由你亲自去传达。把这枚微粒带给紫罗兰城堡里的大法师塞琳德拉吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`QuestDescription`,`VerifiedBuild`) VALUES (92467,'zhCN','大地的呼唤','灵契是一种蕴含魔力的药剂，能让意志坚定的人看见常人无法看见的元素。饮下之后，你的灵魂便会与这份灵契所对应的元素相连。配制它的秘方，只有极少数萨满知晓。$B$B切记，灵契只能在神圣之地饮用，绝不可在别处喝下。$B$B去东边小路上的众灵高地，在那里饮下灵契。然后……嗯，你自然会看见你需要看见的东西。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92479,'zhCN','潦草的信件','阅读潦草的信件，与北郡修道院的托尔德林·茎刃交谈。','你从狗头人营地回来后，有人立刻让我把这个交给你，$N。看起来是一封信，封蜡上有本地猎人训练师托尔德林·茎刃的印记。在处理修道院里的其他事情之前，先抽空读一读吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92481,'zhCN','奥术学徒','检查闪光回溯水晶，然后前往森达尔林地与多莉·明语交谈。','你去处理瓦尔德伦的事时，村里的法师训练师多莉·明语给你留了这枚回溯水晶，里面似乎存着一则给你的消息。先查看水晶，再去我身后的建筑里找她。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92483,'zhCN','隐于暗影','阅读简易便笺，然后前往森达尔林地的瞭望塔与阿克利·暮刃交谈。','你去处理瓦尔德伦的事时，村里的潜行者训练师阿克利·暮刃说想见你，还留了这张字条。先看看上面写了什么，再去村里的瞭望塔找他。$B$B那家伙总是神神秘秘的。不过话说回来，你也差不了多少。我看你们准能合得来。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92484,'zhCN','拥抱元素','检查嗡鸣回溯水晶，然后前往森达尔林地与塑风者波罗交谈。','你去处理瓦尔德伦的事时，村里的萨满祭司训练师塑风者波罗给你留了这枚回溯水晶。先查看水晶，再去村子中心附近找他。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92485,'zhCN','自然学徒','阅读折叠的羊皮纸，然后前往森达尔林地与锡顿·银风交谈。','你去处理瓦尔德伦的事时，村里的德鲁伊训练师锡顿·银风给你留了这张字条。尽快看看，然后去我身后这棵巨树的一层找他。$B$B用心听他的教诲，你能从他那里学到不少东西。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92489,'zhCN','势不可挡','在达拉然城内击杀法力元素，向暴风城的高阶巫师安多玛斯复命。','肯瑞托一直都是联盟坚实的盟友。自大恶魔阿克蒙德将其化为废墟后，这座曾经高傲的法师之城便封闭了自我，对任何外来者都充满戒备。$B$B近年来，他们正大兴土木，试图让达拉然重现昔日辉煌。然而情报显示，城内突然爆发了一场失控的奥术能量灾难，他们正疲于应对。$B$B我们必须帮助他们击退这些袭击，否则就会失去我们最强大的盟友之一。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92596,'zhCN','高阶会','坐下来，与拉西里尔·日矛谈谈。','你身上散发出的奥术光环非常强烈，哪怕你还没被正式接纳为一名法师。我敢说你绝对会成为一名出色的冒险者。而且，你与我们古老魔法的这份羁绊只会对你大有裨益，哪怕你这辈子都不会开口念出半句施法咒语。$B$B来，坐下来吧。咱们聊聊我的教团、泽风岛上奥术的本质，还有咱们族人面临的困境。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92597,'zhCN','阅读魔网','在森达尔林地的魔网处使用你的阅读魔网种族技能。','在这个元素位面，我们的大部分奥术力量都源自脚下流淌的魔网。最近，这些魔网开始冲破地表，让我们得以更直接、更高效地汲取地下蕴藏的奥术能量。$B$B去东北方的立石那边吧，那里有一处魔网节点。唤醒你与生俱来的天赋，汲取其中的能量。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92644,'zhCN','不幸的消息','将发光的水晶交给瓦拉纳尔的塔拉尼斯·影歌。','<你从叛变教徒尚有余温的尸体下摸出一颗小小的蓝色发光水晶。它似乎已经损坏，但或许仍然十分重要。影歌大长老可能会对它感兴趣。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92646,'zhCN','直面洛苏娜','乘坐传送门前往上方的罗哈什尖塔，与伊拉德林·晚风和阿耶莎·晨歌会合，共同对抗高阶女祭司洛苏娜。','洛苏娜通过某种传送门逃到了上面的尖塔。阿耶莎和伊拉德林紧跟着追了进去。就是刚刚的事。$B$B恐怕我伤得太重，只能留在这儿了。穿过传送门，去找到阿耶莎，帮他们阻止洛苏娜。$B$B除非伊拉德林和阿耶莎请的救兵能快点赶到，否则接下来就全靠你自己了。祝你好运，$C。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92698,'zhCN','我的使命是什么？','去找阿米莉亚·风野谈谈那台出故障的旋风构造体。','<你凑近试图听清这台巨型构造体装甲板下传出的声音。>$B$B……功能故障……$B$B……疑问……$B$B……什么是……$B$B……功能……$B$B<这些支离破碎的词句似乎在不断重复。也许附近的什么人会更了解这台构造体？>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92703,'zhCN','传递消息','在瓦拉纳尔与阿尔瓦里昂·风野交谈。','经历了这一切，我想再叫你陌生人就不太合适了，所以……谢谢你，$N。$B$B如果你不介意再跑一趟的话，请去告诉阿尔瓦里昂这儿发生的事。另外，跟他说一声，等他养好伤，得带个塑风者回来帮我们看看那台构造体，好确保把它留在我们……留在咱们一家人身边是安全的。$B$B<阿米莉亚轻抚着自己的肚子。>$B$B他还不知道这件事。咱们俩就先保守这个秘密吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92727,'zhCN','失踪的学者','查明菲里昂·炎风的下落。','探求知识是高阶会的首要使命，但在如今的泽风岛，这差事变得前所未有地凶险。$B$B我们的一位学者——菲里昂·炎风——前往申达尔高地，采集那里聚集的风系魔法的数据，却就此失踪了。他至今杳无音信，我们很担心他在路上出了什么意外。$B$B如果你有空，能不能帮我们找找他？他最后一次露面，是在瓦拉纳尔向西通往申达尔高地的大路上。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92745,'zhCN','矿洞近况','在詹戈洛德矿洞消灭4名狗头人掘地工，并在金海岸矿洞消灭6名河爪矿工。','你采集的井水样本中含有有毒金属！如果不尽快遏制这种污染，今后几十年里，这片土地都将寸草不生。$B迪菲亚兄弟会已经占领了西部荒野的矿洞，并奴役生物开采其中的资源。去北边的詹戈洛德矿洞和西边的金海岸矿洞，消灭他们手下的矿工，扰乱其采矿活动。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92747,'zhCN','月溪镇谍报','从月溪镇收集8份可疑的工业补给品。','真奇怪——这毒素似乎并不是从你调查过的矿井里冒出来的。$B$B听人说，月溪镇下方的死亡矿井才是西部荒野最大、最深的矿井，但自从第一次战争以来那里就一直荒废着。难道死亡矿井又重新运作起来了？$B$B请跑一趟月溪镇吧，$N，去看看有没有采矿或是工业活动的痕迹。这是我们最后的线索了！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92748,'zhCN','爆破咨询','前往暴风城的矮人区，寻找一名能够提供帮助的工程师。','你找到的物资表明，死亡矿井某处正在进行一场规模庞大的工业生产。毫无疑问，那就是污染西部荒野农田的毒素源头。我们必须尽快阻止它。$B$B不管下面藏着什么，肯定都很难摧毁。去一趟暴风城的矮人区，找个能给咱们提供炸药的工程师吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92749,'zhCN','炸药计划','通过制造、交易或拍卖行获得10个劣质炸药，然后返回暴风城矮人区的斯普莱特处。','工业破坏？你可引起我的兴趣了！$B先从一些炸药开始吧……',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92750,'zhCN','远程引爆','与暴风城情报部门的人员交谈，设法取得一台远程引爆器。','我猜你想要一次“受控”的爆炸？虽然没那么有趣，但如果你想保住四肢，这确实是个明智的选择。$B恐怕我这里没有远程引爆器。何不去问问暴风城情报部门那些神出鬼没的家伙？他们应该能替我们找到合适的东西。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92751,'zhCN','远程引爆','将远程引爆器工具包交给暴风城矮人区的斯普莱特。','你想摧毁什么东西？这该不会和你在月溪镇的行动有关吧？别这么惊讶。暴风城领地里发生的一切，军情七处都了如指掌。$B$B如果你打算在西部荒野地下的洞穴中引爆炸弹，最好提前撤得远远的。拿上这套远程引爆器——这是我们自己的工程师最近制造的原型机。$B$B哦，还有，最好别向你的精灵朋友提起我参与了此事。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92752,'zhCN','爆破咨询','返回西部荒野的阿尔巴·晴月处。','完成了，炸弹已经准备就绪！现在可要小心使用那个引爆器。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92753,'zhCN','爆破死亡矿井','找到深藏于死亡矿井中的熔炉，在旁安放强效炸药。随后，在死亡矿井出口与阿尔巴·晴月会合。','毒素的源头多半是某种大型冶炼熔炉。想办法潜入死亡矿井，找到那座熔炉，将炸药安放妥当。$B我会在月溪镇后方的山丘上接应你。等你安全撤回，我们就立刻引爆。只要熔炉一毁，这片土地就有重焕生机的希望。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (92811,'zhCN','经济战',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (92812,'zhCN','经济战',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92818,'zhCN','大型铁斧，不，巨型铁斧','保持你在玛格拉姆氏族的声望，并将2把巨型铁斧交给凄凉之地玛格拉姆村的格罗尔卡。','我们需要更多的武器。$B$B更多的。武器！$B$B不然玛格拉姆拿什么去粉碎那些孱弱的吉尔吉斯人？$B$B外来者，让我看看你都能打造出什么破铜烂铁。给我弄些斧子来。要大的，不，要巨型的！$B$B赶紧的！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92819,'zhCN','爆破死亡矿井','使用起爆器。','我们马上就大功告成了。按下起爆器，结束这一切吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92834,'zhCN','十倍奉还','从瓦拉纳尔以北阵风莓田或阿基尔神殿附近的奥拉凯斯教徒身上，收集10枚奥拉凯斯风石护符。','当密教开始诉诸暴力时，维和者与塑风者只知道虚张声势。我觉得这种愚蠢的冲突升级毫无意义，所以主张和平对话。昨天，我派我的挚友贝拉萨恩·明愿前往阿基尔神殿，希望能跟他们谈谈。$B$B可刚刚有人送来了一个盒子，里面装着贝拉萨恩的舌头，还浸泡在银色颜料里。$B$B现在我算是彻底明白了，跟这帮密教徒根本没道理可讲。见一个杀一个，把他们身上的祈祷护符给我带回来。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92841,'zhCN','白骨之谷','提升你在玛格拉姆氏族的声望，前往玛格拉姆村以南的白骨之谷附近寻找奥尔格鲁尔。','外来者，是时候让你知晓我们的伟大发现了……但这话瓦鲁格可不会亲自说！$B$B往南走，去村子的另一头。找一个体型巨大、浑身散发着恶臭的半人马，他叫奥尔格鲁尔。$B$B你到了那儿自然会明白。$B你见到他自然会知晓。$B要是他觉得你配得上这个秘密，你就会知道。$B$B要是他觉得你不配呢？哼，那你就为了瓦鲁格得到了一顶新王冠而偷着乐吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92860,'zhCN','为泽风岛效力','向瓦伦妮亚·风暴之拳报告，告诉她高阶会将在对抗奥拉凯斯的战斗中与他们并肩作战。','高阶会一直尽量避免与密教发生正面冲突，但这显然已经行不通了。他们毫不掩饰自己的敌意，眼下更有传言说，岛上出现了更大规模的密教活动。他们显然在密谋着什么，而且不管是什么，对泽风岛的居民来说绝对没好事。$B$B去向瓦伦妮亚·风暴之拳报告，告诉她只要有需要，高阶会必将全力支持瓦拉纳尔对抗奥拉凯斯的行动。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92871,'zhCN','为泽风岛效力','向瓦伦妮亚·风暴之拳报告，告诉她塑风者将在对抗奥拉凯斯的战斗中与他们并肩作战。','瓦伦妮亚·风暴之拳和她的维和者一直是泽风岛的守护者，我们也在力所能及地提供援助。眼下有传言说，岛上出现了更大规模的密教活动，他们显然在密谋着什么。$B$B去向瓦伦妮亚报告，告诉她只要有需要，塑风者必将全力支持瓦拉纳尔对抗奥拉凯斯的行动。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92880,'zhCN','返回瓦拉纳尔','将尤拉娜的报告交给瓦拉纳尔的瓦伦妮亚·风暴之拳。','扫清残敌估计还要花点时间，但咱们现在的赢面大多了。回瓦拉纳尔去，告诉他们咱们这儿已经稳住了。$B$B我真不知道该怎么谢你。要不是有你在，我们的处境可就惨了。我本来只是请求增援，没想到却盼来了一位正在崛起的英雄。这可是我的荣幸。$B$B愿四风保佑你，$C。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92881,'zhCN','大长者的请求','在瓦拉纳尔与塔拉尼斯·影歌交谈。','东西两座瞭望塔同时遇袭，这绝不可能是巧合。结合你在西部瞭望塔和那个天空祭司交手的情况来看，最合理的猜测是，密教正打算对锚点水晶塔动手脚。$B$B去跟大长者影歌谈谈吧。他会告诉你一条很有希望的线索。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92893,'zhCN','对弱者绝不留情','保持你在玛格拉姆氏族的声望，并消灭散布在白骨之谷各处的5名吉尔吉斯俘虏。任务完成后向奥尔格鲁尔复命。','当你继续深入白骨之谷时，会碰到一些胆敢擅闯我们领地的吉尔吉斯流浪者。我原本下令留他们一口气，好用来喂食地下钻行的骨虫，但那些虫子似乎对活蹦乱跳的猎物不感兴趣。$B$B这项任务易如反掌。找到那些俘虏，彻底掐断他们的生机。别给他们留下哪怕一丝逃出生天的奢望。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92911,'zhCN','收割傀儡被收割','萨丁农场的奥兹温·铁链要你为他带回8个魔像同位弹簧、4个铜质调节器和一个粗制瞄准镜。','我明白了……这让我摸清了那些怪物到底是怎么运作的。我想到一个法子，说不定能覆盖它们的系统——至少能撑一小会儿。$B$B我会继续摆弄你带回来的这些组件。在此期间，你能不能再去帮我搜罗点零件？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93034,'zhCN','白骨之谷','提升你在吉尔吉斯氏族的声望，并在吉尔吉斯村远东的白骨之谷附近找到奈尔洛克。','趁你不在时，我们的一名侦察兵赶回了村子，他带来的消息证实了我的忧虑。$B$B玛格拉姆氏族正在谋划什么，$N。恐怕不是什么好事。$B$B遥远东方的白骨之谷是一片受诅咒的土地，很少有半人马敢去，能回家的更是少之又少。我们的死敌却在那里发现了某种邪恶之物，我们必须查清那是什么。$B$B去南面的入口找侦察兵奈尔洛克。不过，你可能还得进一步赢得吉尔吉斯氏族的信任。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93035,'zhCN','肆虐的劫掠者','保持你在吉尔吉斯氏族的声望，击杀6个亡灵劫掠者，再到白骨之谷南入口向奈尔洛克复命。','只要稍加留意，你就能看见前方那些摇摇晃晃的亡灵，但你察觉出它们有什么古怪之处了吗？$B$B它们是用两条腿走路的，而不是四条腿！这些骷髅压根就不是我们阵亡的同胞。早在这片凄凉之地成为我们的猎场之前，这些人就已经长眠于此，玛格拉姆人肯定是在亵渎他们的遗骸！我简直无法想象，他们究竟是用了怎样无耻的借口，才敢公然背弃大地母亲瑟莱德丝，去刨食这些沉睡了数百年的尸骨。$B$B让这些苦命的亡灵重新安息吧，$N。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93037,'zhCN','揪出叛徒','保持你在吉尔吉斯氏族的声望，将1件通灵法衣带给白骨之谷入口处的奈尔洛克。','就在我等你汇合的时候，我透过那些拱门往深处扫了一眼，发现了一点蹊跷，我需要你去替我求证。$B$B在彻底敲定我的猜测之前，我根本不忍心把它说出口。$B$B$N，你在山谷里摸索地形的时候，顺手解决掉几个看起来比较弱的死灵法师。小心扯下他们的法袍，带回来给我。我必须搞清楚，到底是我老眼昏花，还是这个世界疯了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93062,'zhCN','埋葬骸骨','保持你在吉尔吉斯氏族的声望，在白骨之谷中寻找并驱散8个召唤失败的骨架身上的诅咒。','话说回你的这根法杖。我认出它是乌泰克的法器，你刚才说它是用瑟莱德丝之泪打造，又镶嵌了德莱尼水晶来强化，能够驱散黑魔法？$B$B我注意到，在山谷深处，有一些骨架被卡在了岩土之下。我敢肯定，这些都是流放者通灵法师召唤失败的半成品，恐怕要永远困在泥土里遭受折磨。$B$B让它们重新安息对我们的事业大有裨益，对它们的灵魂也是一种解脱。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93089,'zhCN','下一步','等你准备好离开泽风岛了，去和伊拉德林·晚风谈谈。','请代我向伊拉德林道声谢，感谢高阶会和你们那些来自“肯瑞托”的新朋友为泽风岛所做的一切。我知道高阶会计划离开这座岛，我衷心祝愿你们教团此次远征一切顺利。$B$B我只希望，无论高阶会能找到什么样的奥术法子，都能真正为我们带来这几年来一直奢望的安宁。如果你打算与他们同行……这次任务定会如虎添翼。$B$B愿狂风与你同在，$N。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93090,'zhCN','下一步','等你准备好离开泽风岛了，去和阿耶莎·晨歌谈谈。','请代我向阿耶莎道声谢，感谢塑风者和你们那些来自“大地之环”的新朋友为泽风岛所做的一切。我知道塑风者的萨满祭司们准备离开这座岛，我衷心祝愿你们教团此次远征一切顺利。$B$B我只希望，无论塑风者能找到什么样的解决之法，都能真正为我们带来这几年来一直奢望的安宁。$B$B愿狂风与你同在，$N。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93128,'zhCN','杰恩可汗','保持你在吉尔吉斯的声望，在玛格拉姆村击杀杰恩可汗。得手之后，前往凄凉之地的吉尔吉斯村，向智者乌泰克复命。','尽管我非常希望能由乌泰克或是沙卡可汗亲自下达这道命令，但我怕机不可失，时不再来。我们已经没时间赶回吉尔吉斯村去请示了。$B$B白骨之谷的战局已经牵制了玛格拉姆的大量兵力，我敢断言，杰恩可汗身边的防卫力量绝对异常薄弱。如果要对其他氏族的可汗发动斩首行动，现在就是绝佳时机。$B$B但是$N，任何可汗都不是等闲之辈，杰恩更是个难缠的狠角色。如果你有胆量动手，务必要速战速决，千万别轻敌。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93224,'zhCN','雕刻半人马图腾','消灭凄凉之地任意氏族的半人马，收集5枚雕刻半人马图腾，再交给尼耶尔前哨站的本迪加斯上尉。','无论哪个半人马氏族，都不情愿接受外族的援助，这你应该不觉得奇怪。尤其是对待像你我这样——非半人马的种族。$B$B但大家都有一个共识：有钱能使鬼推磨。我们打听到当地的半人马习惯用木雕来进行物物交换。如果你能给我弄来几件样品，我就能加急订做一批仿制品。说不定，我们能花钱给自己买出一条捷径。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93225,'zhCN','雕刻半人马图腾','消灭凄凉之地任意氏族的半人马，收集5枚雕刻半人马图腾，再交给幽灵岗哨的古尔达·蛮鬃。','我发现，不同氏族的半人马有时会在远离村落的地方进行交易。我连着观察了好几个晚上，似乎每个氏族都参与其中；而最关键的是，我发现他们交易用的货币是：雕刻图腾。$B$B我相信，只要能把一大捆图腾直接送到吉尔吉斯或玛格拉姆的手里，我们就能扭转局势，让他们倒向我们这边。我已经开始仿造了一些，但如果没有真品混在里面打掩护，他们估计没那么容易上当。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93227,'zhCN','收买友谊：吉尔吉斯','把图腾手提包交给凄凉之地吉尔吉斯村的吉尔吉斯军需官，以大幅提高你在该氏族中的声望。你在吉尔吉斯半人马中的声望至少必须达到中立。','明眼人一看就知道，吉尔吉斯现在举步维艰。他们人少得可怜，我们的斥候也极少察觉到他们的动静。$B$B可不管怎么说，他们作为凄凉之地的主要氏族之一，硬是挺到了今天。这说明他们绝不是一无是处。$B$B你要是想跟吉尔吉斯交好，就带着这袋图腾去西南边大老远的吉尔吉斯村。别看他们原始，管账的人多半还是有的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93320,'zhCN','保卫瞭望塔','向阵风浆果低地东部瞭望塔的尤拉娜·风苇报到。','我刚收到消息，密教正在攻打镇外的水晶瞭望塔。我已经把手里仅剩的几名维和者派了出去，试图突破敌人的后方防线去解救守军。但眼下哪怕再多一份支援，都可能决定那里的人是死是活。$B$B请立刻赶赴东部瞭望塔，尽你所能帮帮他们。$B$B带队的是我的副官，尤拉娜·风苇。如果她还活着，会告诉你该怎么做的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93459,'zhCN','更多奥拉凯斯的徽饰','从影风森林、阿基尔神殿或阵风浆果低地的奥拉凯斯密教徒身上收集10只奥拉凯斯密教徒的徽饰，并将它们交给影风森林的瓦恩·月爪。','奥拉凯斯的教徒通常不敢踏足这片森林，因为他们害怕这里闹鬼的传闻……而我们也很乐意让他们一直这么以为。我们教团的德鲁伊只求在影风森林里过平静安宁的日子，可这帮人却成了个大麻烦。$B$B大伙儿心里都怕得很。$B$B我有个提议。替我们去对付那些教徒，把被你杀死的人的徽饰带给我。你每带回一个徽饰，我都会付给你真金白银。而且，只要你证明自己是个真正的朋友，等时机成熟，我还会向你传授我们的秘密。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93461,'zhCN','欢迎来到申达尔村','在申达尔村与拉西里尔·日矛和科里埃拉·平风交谈。','你身上有那种“高阶会”的做派。拥有上层精灵血统的人，眼神里总闪着特有的光芒，一眼就能认出来。在我正式给你派活儿前，你最好先去拜访一下驻扎在这儿的高阶会长老——拉西里尔·日矛。你可以在主旅馆找到他，就在我这儿转角处。$B$B哦，顺便也去见见科里埃拉·平风，她开着当地的旅店，要是你需要食宿和补给，找她准没错。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93585,'zhCN','我的这束圣光','护送塔特尔神父前往避难营。','谢天谢地，总算来了个文明人！$B$B我代表圣光教会来到这里，准备与避难营的德莱尼人接触。你也知道，联盟在这里没有立足之地，与本地人展开一些外交往来或许能改善这种局面。毕竟，圣光欢迎所有人投入它的怀抱！$B$B可是桥那头的道路上，到处都是德莱尼人更加野蛮的同族。想安全抵达避难营，我就需要有人保护。你愿意帮助我吗，$C？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93663,'zhCN','运输途中失踪','找到失踪的信使，确保达尔的货物被送到避难营。','避难营的德莱尼人捕鱼技术高超，也愿意前往比我更危险的水域拖网捕鱼。我们偶尔会做些交易。他们分给我们一些鱼获，我们则拿出多余的补给作为交换。$B$B我派了一个地精信使去运送最近的一批货，可他一直没有回来。多半是被鳄鱼当成了点心。$B$B更重要的是，我做生意的信誉正岌岌可危。必须找到那批货并送到避难营。可以的话，请帮我找找。沿路检查一下水边。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (93680,'zhCN','城市大门钥匙','为塔伦米尔的大法师沃迪恩·伍德格莱尔取得达拉然下水道钥匙。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93736,'zhCN','不受欢迎的精魂','从影风森林的空洞风灵身上收集10份空洞风灵精华。','塑风者的首要任务，是查明风之灵为什么离开我们，以及我们能做些什么把他们请回来。北边影风森林里有个奇特的现象——那儿聚集着一种古怪的风系妖精，有人管它们叫“空洞风灵”。我们对它们知之甚少，也不清楚它们为什么会在那儿，只知道它们是在风之灵离开我们后才开始冒出来的。$B$B我需要你去那儿驱散它们。把它们的残骸收集起来带给我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93738,'zhCN','损坏的构造体','向瓦拉纳尔的阿耶莎·晨歌复命。','明愿，是吗？这么说是高阶会出于某种目的拆走了这些组件。可这是为什么呢？$B$B高阶会向来喜欢多管闲事，老是妄图拿风之灵的魔法来做实验。他们简直胆大包天，我们曾严禁他们染指塑风者管辖的学识，可这阵子他们却一再试探我们的底线。$B$B我想你应该去向阿耶莎·晨歌报告你的发现。她会告诉你接下来该怎么做。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93739,'zhCN','部落之旅','到格罗玛什要塞向纳兹格雷尔询问指引，再依照他的指示，分别拜访沃金、凯恩·血蹄和希尔瓦娜斯·风行者女士。','艾泽拉斯辽阔，部落的疆域也十分广大。幽暗城、奥格瑞玛和雷霆崖，各有不同的族群与风俗。$B$B你既然来到艾泽拉斯，成为部落的客人，不妨依次走访这几座主城。我的顾问纳兹格雷尔会为你指路。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93740,'zhCN','血债血偿','从阵风浆果低地的奥拉凯斯密教徒尸体上收集10个奥拉凯斯风石护符。','今天早上，我们在高地发现了几名塑风者学徒的遗体，死状惨不忍睹。虽然还不能断言，但多半是奥拉凯斯下的毒手。我们塑风者向来血债血偿，从无例外。$B$B往北走，见一个奥拉凯斯密教徒，就杀一个。把他们的风石祈祷护符带回来，作为凭证。我们绝不宽恕，也绝不遗忘。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93786,'zhCN','血染的警告','消灭12名草甸溪农场雇农，然后带着你胜利的消息向克罗姆罗什复命。','你的刀刃是不是已经饥渴难耐，想要饱饮人类的鲜血了，$N？$B$B几年前，那帮人类叛逃者霸占了河对岸西南方的一座小农场。那片地界木材和石料丰厚，他们把爪子伸向东岸的法霍德要塞，只不过是迟早的事。$B$B当初要不是咱们吃了人数的亏，第一场遭遇战赢的绝对是咱们！是时候给这帮家伙点颜色看看，让他们别忘了这儿是谁的地盘。$B$B去砸了他们的农场。一个活口也别留。给他们送去一份血淋淋的警告！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93788,'zhCN','借刀杀人','从特纳的伐木场的伐木工那里，为洛格玛的克雷扎·暗棘夺回10把木匠的斧头。','南方有人类盘踞，西方有暮光之锤驻扎，争夺资源的战斗变得越发艰难。但既然夺取敌人的刀刃就足够了，我们又何必去费力采集资源呢？$B$B顺着河水向南前往伐木场。当你在林间听到伐木工的口哨声时，放轻脚步。一旦时机成熟，就发起雷霆一击。$B$B我会留在这里让熔炉保持高温。古尔多克负责拆解这些斧头，而我将用他们自己的材料来打造我们的武器。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93791,'zhCN','与贝兰交谈','与瓦拉纳尔的贝兰·风木交谈。','$N，很显然你的魔法技艺正在不断精进。我觉得是时候让你体验一项高阶会为满怀抱负的年轻法师准备的古老传统了——是时候打造一件属于你自己的施法法器了。$B$B去瓦拉纳尔找贝兰·风木。一个多世纪以来，他一直在为高阶会制作法杖和魔杖，找他准没错。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93797,'zhCN','风中之枝','将注入风之力的树枝带给瓦拉纳尔的贝兰·风木。','对展现出一定魔法造诣的年轻法师来说，打造专属的施法法器是项由来已久的传统。一般来说，大家会从最古老的树木上找些掉落的树枝，因为上面还残留着些许风元素的痕迹。$B$B我发现最理想的树枝，就在法拉斯村南边的风之神殿附近。去给我找一根粗壮的树枝回来，在咱们制作法器的时候，我也会把这些传统讲给你听。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93835,'zhCN','直面洛苏娜','穿过传送门前往上方的罗哈什尖塔，与伊拉德林·晚风和阿耶莎·晨歌会合，共同对抗高阶女祭司洛苏娜。','洛苏娜通过某种传送门逃到上面的尖塔去了。就在刚才，阿耶莎和伊拉德林也追了进去。$B$B恐怕我伤得太重，只能留在这儿了。穿过传送门，去找到伊拉德林，帮他们拦住洛苏娜。$B$B除非伊拉德林和阿耶莎请来的救兵能立刻赶到，否则接下来的路就全指望你了。祝你好运，$C。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93836,'zhCN','泽风岛的命运','在瓦拉纳尔与塔拉尼斯·影歌交谈。','穆恩跟我讲了不少元素领主的事。既然隐藏泽风岛的结界已经失效，恐怕我们真的得对奥拉基尔多加防备了。我们现在完全不设防，一旦他决定动手，在他的地盘上我们根本毫无胜算。$B$B大长者影歌必须了解我们正面临的危险，更重要的是，他得知道我们前往艾泽拉斯的远征究竟意欲何为。我们会找到拯救家园的办法的。我发誓。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93928,'zhCN','老鼠与牛奶','给老鼠弄一块曲奇。','我需要一块曲奇，懂吗？$B$B嗯呀！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93958,'zhCN','内殿','在阿基尔神殿的内殿与瓦伦妮亚·风暴之拳交谈。','瓦伦妮亚的部队刚刚攻破内殿。起初里面战况激烈，可现在却安静得……令人不安。进去尽力与瓦伦妮亚及其部队会合吧……如果他们还有人活着的话。$B$B我会留在这里替你照看后方。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93963,'zhCN','联盟之旅','到暴风要塞向兰达尔·埃默森询问指引，再依照他的指示，分别拜访国王麦格尼·铜须、大工匠梅卡托克和泰兰德·语风。','暴风城、铁炉堡和达纳苏斯各有不同的族群与文化。你既是联盟在艾泽拉斯的客人，不妨抽空依次造访这几座主城。$B$B先到南侧前厅找兰达尔·埃默森，他会告诉你该怎么走。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94003,'zhCN','破天者壁垒','从阿基尔神殿的扎尔·风暴之盾手里夺回破天者壁垒。','我是泽风岛上破天者血脉仅存的传人。其余的族人都遭了奥拉凯斯密教的毒手。$B$B眼下，唯有耻辱能盖过我心中的悲痛。我们家族祖传的盾牌——破天者壁垒——如今落入了一个名叫扎尔·风暴之盾的密教徒手里。家族传闻说，只要持有者配得上这面盾牌，就能免遭任何伤害。$B$B我敢肯定，扎尔那个混蛋绝对不配。去阿基尔神殿找到那家伙，帮我把盾牌夺回来。只要你能办成，我就把破天者防御的奥秘传授给你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94006,'zhCN','伟大的乌萨拉之灵','在瓦拉纳尔东北方的瀑布附近与乌尔森德里斯交谈。','你好，$N。你在德鲁伊之道的修行上已经取得了长足的进步，我想是时候让你去见见居住在泽风岛上的伟大灵体了。乌尔森德里斯是一位睿智而高贵的先灵，世世代代以来，他一直在教导德鲁伊如何化身为乌萨拉的形态。不幸的是，他的领地也开始像泽风岛的其他许多地方一样，正逐渐枯萎并坠入天空。$B$B去寻找他吧，往东北方走，他就在阿基尔神殿阴影下的瀑布附近。他会给你进一步的指引。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94007,'zhCN','驯服野兽','向瓦拉纳尔的奎尔阿娜·疾风报到。','既然你已经适应了高地野外的环境，是时候去寻找属于自己的动物伙伴了。$B$B前往东南方的瓦拉纳尔港，找那里的奎尔阿娜·疾风谈谈。他会传授你驯服野兽的技艺。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94013,'zhCN','驯服野兽','在阵风浆果低地使用驯兽棒驯服一只瓦尔德伦头狼。磨炼你的驯兽技巧，然后把驯兽棒还给瓦拉纳尔的奎尔阿娜·疾风。','你已驯服两头野兽，凯旋而归。该接受最后的试炼了。泽风岛的风声正预示着前方还有更严峻的挑战。$B$B带上这根驯兽棒，前往阵风浆果低地。在那里驯服一头瓦尔德伦头狼，证明你的驯兽本领。$B$B学完这一课，你就可以继续钻研猎人的高深技艺了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94050,'zhCN','训练野兽','与瓦拉纳尔的奎尔多拉·疾风交谈。','你现在已经拥有了驯服宠物的能力，但还得掌握训练它的技巧。奎尔多拉是我的姐妹，训练野兽的本领无人能及。她会教你如何训练新宠物。$B$B愿风指引你，年轻的$C。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94369,'zhCN','泽风岛的命运','在瓦拉纳尔与塔拉尼斯·影歌交谈。','这里的安斯雷姆跟我讲了不少关于元素领主的事。既然隐藏泽风岛的结界已经失效，恐怕我们真的得对风领主奥拉基尔多加防备了。一旦他决定动手，在他的地盘上我们根本毫无胜算。$B$B大长者影歌必须了解我们正面临的危险，更重要的是，他得知道我们前往艾泽拉斯的远征究竟意欲何为。我们会找到拯救家园的办法的。我发誓。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94373,'zhCN','大地的召唤','收集2个霜鬃熊坠饰，交给安威玛尔的提欧·暴风之锤。','没错，时候到了，年轻的萨满祭司。你已经长得结实又稳重，就像我们脚下的岩石。选择萨满祭司之路，说明你尚未证明自己，就已经拥有群山的智慧。你有岩石般的坚韧，足以踏上大地之路。$B$B但要赢得大地的青睐，你必须正面接受考验。此地南边有一座霜鬃巨魔居住的洞穴。$B$B给我带回两串他们佩戴的项链，那些项链由冰爪熊制成。之后我们再谈你的未来。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94374,'zhCN','大地的召唤','找到灵魂石，并饮下大地灵契。','没错，灵契是用魔法酿造的秘药，能将我们的精神与元素绑定。只有少数萨满祭司掌握配方，心志不坚者更是无福消受。喝下它，你就能洞察常人难见之物。切记——这东西只能在神圣之地饮用。$B$B向北走，沿着隐蔽的山间小径走到尽头，就是灵魂石地。在那儿喝下去……看看大地会向你展示什么。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94375,'zhCN','大地的召唤','将粗糙的石英交给安威玛尔的提欧·暴风之锤。','把我给你的这块粗石英交给提欧·暴风之锤，作为我们见过面的证明。他会为你制作一根图腾，这块小石子则会成为图腾的核心。它看起来虽小，但你会逐渐明白，大小并不重要，即使最微小的事物也能比许多庞然大物更加长久。$B$B保持耐心，$N。坚守力量，追寻智慧。这就是大地对你的要求。最终，你将与大地融为一体。尊重大地，它也会尊重你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94413,'zhCN','魔法挑衅','在申达尔高地消灭6名塑风者见习先知。','最近，泽风岛的魔网开始涌出地表，这对我们教团来说意义重大。我们得以更直接、更真切地感受这片土地蕴含的能量，对这种魔法的理解也随之加深。$B$B可塑风者那帮人，却把这些显露出来的魔网视为大地的伤疤，非要将其“治愈”不可。这是对我们教团的公然挑衅，我们绝不答应。$B$B去西南边的森林里找到那处魔网，把你在那里遇见的塑风者统统赶走。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94427,'zhCN','神性一课','与幽暗城的塔尼斯·桤木交谈。','成为圣骑士的一项核心信条即是对神性的追求。这并非妄图成神，而是纯粹为了行善去追求善之本身。我们皆因种种悲剧而齐聚于此，极易丧失生前将我们定义为圣骑士的那份恩典。$B$B前往幽暗城，在贸易区寻找塔尼斯·桤木。他们正急需援助，而些许恩典必将使其获益良多。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94449,'zhCN','火焰的召唤','在丹莫罗找到布鲁格斯·燃生。','距离你上次接受试炼已经过去许久了，$N。你确实展现出了非凡的耐心——但现在你该学习混沌……学习毁灭了。火焰的呼唤震耳欲聋，倘若你已准备好付出代价，它便会对你开口。$B$B去寻找远在东部群山之中的布鲁格斯·燃生。他居住在南门哨岗上方的一个洞穴内。他会知晓你是否真的做好了准备。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94465,'zhCN','火焰的召唤','将眠炎火炬带给洛克莫丹的布拉尔迪·灰烬披风。','确实，你拥有承载火焰图腾的力量，孩子——但单凭力量尚不足以证明你已准备就绪。$B$B穿过国王谷，在洛克莫丹的峭壁之间，隐藏着一条通往我们其中一座圣峰的隐秘小路。在那里，布拉尔迪·灰烬披风正守卫着眠炎圣殿。$B$B将这把火炬带给他——它能彰显你的来意。用圣殿的火盆将其点燃并带回，我便会认可你赢得了这枚图腾。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94466,'zhCN','火焰的召唤','收集1份火焰焦油和1个试剂袋，交给洛克莫丹的布拉尔迪·灰烬披风。','哼，你不辞辛劳地跑到这里可不是为了听故事的，对吧，$N？你在寻觅永恒之焰与火焰图腾。$B$B首先，你需要一剂灵契来将你的灵魂与火焰相绑定。$B$B我会负责将其制作出来——但我需要两样物品：北面狗头人洞穴内坑道鼠地卜师身上的火焰焦油，以及潜伏于南部丘陵的碎石怪先知所持有的试剂袋。这项差事凶险异常，但绝对配得上火焰的恩赐。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94467,'zhCN','火焰的召唤','击败火焰之魂，将余烬放入恒焰圣殿顶部的火盆。','火焰灵契已然就绪，$N。现在去直面火焰吧。在圣殿内使用它，随后攀上顶峰。在那里，你将会目睹精魂——除非你率先发难，否则他绝不会攻击你，但他会察觉到你已然看到了他。$B$B迅速出手，孩子。你拖延得越久，他燃烧得便会越发猛烈。当他倒下之际，取走他那发光的余烬，将它们投入火盆之中。点燃火炬，去赢取火焰的青睐吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94468,'zhCN','火焰的召唤','将恒焰火炬带给丹莫罗的布鲁格斯·燃生。','你紧紧握住火炬，转身离开火盆，俯瞰着洛克莫丹。随着风势渐强，火苗开始剧烈地跳动，你察觉到一种兴奋感正牵动着你的神思。$B$B你踏上了折返丹莫罗的小径，前去寻找布鲁格斯·燃生。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (94472,'zhCN','大地灵契','向提欧·暴风之锤要另一瓶大地灵契。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (94473,'zhCN','火焰灵契','向布拉尔迪·灰烬披风再要一个火焰灵契。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94483,'zhCN','教教他们规矩','在河流以南消灭8个法霍德牧师和12个法霍德斥候。','我们的侦察兵报告说，南边的河畔建有训练营。要是我能早点得到消息，我们俩就能省去不少麻烦，早早地把那些人类渣滓给清理干净了。$B$B继续努力，$N。把人类死死地压制在他们那宝贝的小要塞里，这样就能为我们争取时间，腾出手来处理其他紧要事务。$B$B动作快点。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94484,'zhCN','令人不安的寂静','前往影风森林东北部，寻找并与埃莱盖尔·刺爪交谈。','稍等一下，$N。你要去影风森林吗？东北边的一个山洞里有个德鲁伊集会所。我一直在等他们的消息，可早过了该有回音的时候。$B$B如今班艾萨尔沦为废墟，局势又这么乱，我真怕他们出了什么意外。求你了，你要是能去的话，去找到埃莱盖尔·刺爪，也好让我踏实点。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`QuestDescription`,`VerifiedBuild`) VALUES (94491,'zhCN','兽穴的命运','看来瓦拉纳尔某处藏着个内应，正在向密教走漏风声。我现在这副身子骨肯定是没法跑这趟差事了，但必须得让洛瑟鲁姆知道这儿发生的一切。$B$B他也该知道那些遇难同胞的结局。多亏有你帮忙，我想我们能应付接下来的局面，只可惜有些伤害已经无法挽回了。$B$B快动身吧，$N。希望有朝一日我们还能再见。在那之前，我还有密教徒要杀。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94493,'zhCN','徒劳的牺牲','与影风森林东北部的埃莱盖尔·刺爪交谈。','谢天谢地，我们的消息总算传到洛瑟鲁姆那儿了。等等，其他的援兵呢？他们总不至于只派了你一个人来吧？$B$B<听完你的解释，埃莱盖尔顿时脸色煞白。>$B$B这么说，求援的消息根本没传到瓦拉纳尔。那我们的处境真的危险了。$B$B<埃莱盖尔深深地叹了口气，随后露出了坚定的神情。>$B$B看来只能靠我们自己了。时间紧迫。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94494,'zhCN','水之召唤','在洛克莫丹找到诺里克·洛克赛恩。','距你上次接受试炼已有段时日了，$N。迄今为止，你在修行中展现出了非凡的耐心，但现在该去领悟水之纯净了。$B$B前往洛克莫丹，寻找诺里克·洛克赛恩。他就在湖泊西北岸，巨石水坝以南。你会在他那座地堡般的小屋里找到他。祝你好运，$N。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94495,'zhCN','水之召唤','在湿地找到赫尔夫达娜·赛格伦德。','若说水有什么你必须懂得的真理，那就是：水即重生。它能雕凿岩石、洗净污垢、治愈疲惫——但前提是它必须纯净。一旦遭受污染，它便会摧毁所触及的一切。$B$B若你意在寻获水之灵契，就去湿地找赫尔夫达娜·赛格伦德。她家住在南部瀑布下方的一处山洞里。$B$B去吧，别被河水抢在了前头。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94497,'zhCN','水之召唤','在赫尔夫达娜洞穴下方的瀑布底部，灌满空的棕色水囊，然后返回湿地交给她。','噢，原来你是为求取灵契而来的，对吧？那么，仔细听好，亲爱的。要想领悟并赢取灵契，你必须寻访水的种种形态。在收集样本时，务必擦亮双眼。观察那些守护它的野兽，看看它滋养的土地，以及它是如何改变万物生息的。$B$B咱们先从简单的着手：在这淡水与咸水交汇的瀑布底端，灌满这只水囊。去吧，当心沼泽。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94499,'zhCN','水之召唤','在石堡瀑布附近的鱼人夜行者处，灌满空的红色水囊，然后返回湿地交给赫尔夫达娜·赛格伦德。','没错，赤脊山豪饮着止水湖的恩泽，可当水流顺着石堡瀑布奔腾而下时，却有什么东西渗漏了进去。聚集在下方的鱼人都是些硕大且畸形的怪物。跟你在这儿或是洛克莫丹见到的截然不同。镇民们走运就走运在，这些怪物只在瀑布底下盘踞。$B$B给我带一份样本回来。我倒要查个水落石出，污染那座旧要塞周遭水域的，到底是魔法、毒液，还是更阴毒的玩意儿。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94500,'zhCN','水之召唤','在灰谷阿斯特兰纳的水域，灌满空的蓝色水囊，然后返回湿地交给赫尔夫达娜·赛格伦德。','带上这只水囊，深入灰谷那片苍翠的林荫。阿斯特兰纳安卧在免受腐化侵蚀的碧水怀抱中。湖床散落着残垣断壁，诉说着一个消逝的纪元。去湖里取一份样本回来。那水纯净、古老，甚至可能蕴含着魔法。$B$B在打发你回诺里克身边前，这是我需要的最后一份液体。$B$B去米奈希尔港搭船前往奥伯丁，客船途中会在南海镇停靠。$B$B千万当心……那片森林里有眼睛盯着你，它们可不会眨眼。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94501,'zhCN','水之召唤','将一瓶最纯净的水带给洛克莫丹的诺里克·洛克赛恩。','在赐予你图腾仪式作为奖励之前，诺里克还会交代你最后一项差事。我给你的这瓶水，正是完成那差事的必需品。现在就去找他吧。咱们后会有期。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94502,'zhCN','水之召唤','喝下水之灵契，涤净西部荒野斯特登的池塘的腐化。$B事成后返回洛克莫丹诺里克处复命。','西部荒野的月溪镇外，坐落着斯特登的池塘。那里曾是一汪纯净的涌泉，如今却遭黑暗力量染指。此地的精魂已然陷入死寂。$B$B你必须先喝下水之灵契，再直面侵染水域的腐化之力。带上那护腕，连同赫尔夫达娜药剂残存的最后几滴，置于圣坛之上。这会唤出一缕经过涤荡、显露真容的精魂。去与它交谈，尽可能探听虚实。$B$B将办妥此事的信物带回给我，我便赐你图腾。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94503,'zhCN','水之召唤','在西部荒野与水之魂交谈。','随着最后一个音节脱口而出，强光骤然迸发。水化作薄雾的嘶嘶声渐归死寂，当周遭堕落的精魂分崩离析时，你的感官一阵天旋地转，它们的精华犹如飞灰般消散于狂风之中。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94505,'zhCN','水之召唤','将水灵碎片带给洛克莫丹的诺里克·洛克赛恩。','拿着碎片。拿着碎片，赋予生命。$B$B赋予生命，便能理解。理解水就是生命……腐化会阻断生命。$B$B你借助水的力量保护生命、赋予生命。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94532,'zhCN','豺狼人泛滥','为洛格玛的涅扎·血吻消灭8个赤脊山秘法师、8个赤脊山捕兽者和6个赤脊山蛮兵。','尽管暮光势力的步步紧逼让豺狼人的数量锐减，但他们的威胁依然如芒在背。$B$B西南边的丘陵里到处都盘踞着这种生物，严重干扰了商贸路线，也危及了过往旅客的安全。$B$B拔除这颗毒瘤，为我们的盟友清理出一条安全的通道。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94533,'zhCN','斯纳格尔的鼻子','在刺毛丘陵找到斯纳格尔，将其击杀，并把他的鼻子带给涅扎·血吻。','此地西南方的刺毛丘陵里住着一群喋喋不休的怪物，其中有个名叫斯纳格尔的长者豺狼人。这头豺狼人发出的嚎叫极其刺耳。它的存在会鼓舞周围的同类，给进入该区域的盟友和斥候造成极大的麻烦。$B$B若能拿一件战利品作为解决掉这头烦人豺狼人后的纪念，放进我的收藏再合适不过。$B$B动作快点，$N。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94535,'zhCN','刺毛丘陵的强盗','从刺毛丘陵的豺狼人那里为克雷扎·暗棘收集40块被偷走的矿石。','我们在南边山丘开采矿石的盟友报告说，他们在那里屡次遭到豺狼人的袭击。$B$B一路向南，端掉他们的营地，把被偷走的矿石给我夺回来。如果有必要，就直接从他们的尸体上扒下来。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94613,'zhCN','战马危机','前往惠勒的垦野，打听丢失马匹的情况。','我们的战马由附近的两个农场供应。其中一个属于惠勒家族，就在镇外路旁，但他们显然失去了所有马匹。目前原因尚不清楚。$B$B没有马，我们就没有骑兵；没有骑兵，我们对抗部落的战役就毫无胜算。$B$B如你所见，这件事必须尽快解决。不过，我不太确定该从哪儿着手。$B$B去惠勒的垦野找本吉谈谈，听听他怎么说。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94614,'zhCN','淡水恶魔','在惠勒的垦野附近的河畔消灭8个泥鳍智者和8个泥鳍战士。','你看到西边河畔的那些鱼人了吗？真是些恶心的东西。不仅祸害了我的牲畜，连野生动物都不放过。更别提他们还霸占了我最喜欢的钓鱼点！$B$B在河林，绝对没人会反对你除掉这帮怪物，这是肯定的。$B$B拜托了，见一个杀一个。你这可是帮了我们一个大忙。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (94616,'zhCN','水之灵契',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94617,'zhCN','猎杀山狗','消灭那只名叫“煤皮”的山狗，并将它的皮毛带给本吉·惠勒。','西边的一个洞穴里住着一群山狗。有时我们能从河对岸看到它们。它们以前常在岸边抓鱼吃，但我猜是鱼人霸占了它们的觅食地，它们没辙，这才改行吃马了。$B$B山狗群的首领体型更大，长着一身深色皮毛。我们给它起了个外号叫“煤皮”。我想，只要你宰了它，剩下的山狗自然就会作鸟兽散。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94618,'zhCN','惠勒的逃马','找到一匹在山狗袭击后逃离惠勒的垦野的马，喂给它一些饲料。','从你发现的情况来看，似乎大多数马都命丧山狗之口了。不过，还有几匹下落不明。$B$B那些没被吃掉的估计受了惊吓，跑到什么地方躲起来了。我不知道到底还剩几匹，但最好赶在山狗回来前找到它们。$B$B<本吉向你递出一个袋子>$B$B拿着。如果你找到一匹，就喂给它一些我们的饲料。这能让它信任你，这样你就能把它牵回来了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94638,'zhCN','力量与怜悯','在申达尔高地找到并击杀乌尔恩德拉。','你来找我，是想学会化身为强大的形态。我有件事要托付给你，却实在难以启齿。$B$B我的伴侣乌尔恩德拉失去了理智，开始攻击自己的同族。没有了风的魔力，许多生灵都渐渐迷失了自我……她也不例外。她如今栖身在西边的一个山洞里，就在申达尔高地与阵风浆果低地交界的峭壁间。$B$B去结束她的痛苦，我便赐予你祝福。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94672,'zhCN','暮光逼近','为洛格玛的特兰古尔消灭阳光林地中的8名暮光袭击者和8名暮光新教徒。','在河林，人类并不是我们唯一的对手，$N。而且他们也不是最可怕的。$B$B一个名叫“暮光之锤”的邪教发起了一场运动，四处清除那些在他们扭曲的神明眼中被视为异端的人。西边那座被摧毁的人类定居点废墟，仅仅是他们征服之路的第一步。毫无疑问，洛格玛就是他们的下一个目标。$B$B我们绝不能让他们在离大门这么近的地方建立据点。去那个被称为“阳光林地”的地方，削减他们的数量。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94678,'zhCN','豺狼人泛滥','为南哨的塞德里克·道尔顿消灭8个赤脊山秘法师、8个赤脊山捕兽者和6个赤脊山蛮兵。','自从我们抵达这里，豺狼人就一直是我们的眼中钉。虽然他们的威胁不及暮光之锤，但他们极具攻击性，纠缠不休，最糟糕的是，他们数量庞大。$B$B这座哨所外的山丘里到处都盘踞着这种怪物，这让向北的道路变得异常危险，也对生活在法霍德要塞城墙外的人们构成了极大的威胁。$B$B如果我们要让这片土地变得安全，消除豺狼人的威胁就势在必行。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94679,'zhCN','斯纳格尔的徽记','在刺毛丘陵找到并杀死斯纳格尔，把他的徽记带给南哨的塞德里克·道尔顿。','豺狼人将力量看得高于一切。只要消灭他们中最强壮的家伙，我们不仅能削弱他们实质的战斗力，还能在他们心中种下恐惧。$B$B在刺毛丘陵的一个巢穴里，盘踞着一只名叫斯纳格尔的、臭名昭著的豺狼人。他的死毫无疑问会在赤脊山氏族中引起恐慌。$B$B把他的徽记给我带回来，动作快点。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94680,'zhCN','暮光信件','为洛格玛的特兰古尔从阳光林地的暮光暗影法师身上夺取3封暮光信件。','各处一直都零星散布着小股暮光之锤狂热者，但我从未见过这么庞大的阵势。他们似乎是受到了某人或某物的撑腰，才敢如此大肆扩张势力。$B$B我想多了解一下这些狂热者，以及他们到底在寻找什么。他们的暗影法师受到了黑暗力量的赐福，很可能是教派中最受信任的心腹，所以才会被派来领导这种规模的袭击。$B$B把你在他们尸体上找到的任何东西都带给我，也许我们能从中窥探出他们的下一步计划。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (94773,'zhCN','神圣恩典',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94774,'zhCN','神圣恩典','与暴风城的高阶牧师劳瑞娜谈一谈。','你已经引起了上层的注意，$N。他们要求你尽快前往暴风城的光明大教堂。显然，他们认为你已经证明了自己的实力，准备让你接受进一步的训练。到了那里之后，去找高阶牧师劳瑞娜。她会为你提供后续的指引。祝你好运，愿圣光与你同在。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94775,'zhCN','神圣恩典','与暴风城的高阶牧师劳瑞娜谈一谈。','愿艾露恩祝福你，善良的$R。希望你的圣光能指引你，在今天护你周全。$B$B不久前，你们的一位牧师来这里找过你。他提到要你尽快赶回光明大教堂，去和高阶牧师劳瑞娜谈谈。看来你确实表现优异，才能赢得这般关注。我建议你别在这里耽搁太久——你的人民需要你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94776,'zhCN','神圣恩典','与暴风城的高阶牧师劳瑞娜谈一谈。','是时候动身去暴风城了，$N。光明大教堂的高阶牧师劳瑞娜想见你。能让高阶女祭司点名要你亲自过去，不是天大的好事就是极坏的差事，但我猜你一直都表现不错，她找你多半是好事。$B$B别在这儿磨蹭太久了。换作是我，肯定会尽快赶过去的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94777,'zhCN','神圣恩典','与暴风城的高阶牧师劳瑞娜谈一谈。','就在不久前，你们的一位牧师来找过你，$R。他说如果我遇见你，一定要转告你立刻前往光明大教堂。他强调事情非常重要，但如果我是你，倒不会太过担忧。他的神情看起来很积极……似乎是带了什么好消息。我建议你别耽搁太久，尽快动身吧。$B$B愿艾露恩与你同在，善良的$R。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94789,'zhCN','空气的召唤','在阿拉希高地找到维里克·雷锤。','艾泽拉斯的长风向你致敬，不日你便能与我族最强横的同胞比肩而立了。我为你如今的造诣倍感自豪，你的前程将不可限量。$B$B空气元素桀骜难驯，但我确信你的能耐足以扫平一切难关。$B$B一路向北，进发阿拉希高地。在北部群陵地带，去寻找维里克·雷锤。他会传授你更深奥的学问。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94792,'zhCN','驯服野兽','使用驯兽棒驯服一头石皮野猪。练习你的技能，随后将驯兽棒交还给约瑟芬·卡森。','许多猎手热衷于与动物伙伴结伴游历。一旦有野兽傍身，你便发觉自己即便是置身最险恶的境地也能觅得生机。正所谓，多个朋友多条路。然而，获取动物伙伴必须慎之又慎。大自然的平衡极其脆弱，我们必须时刻心存敬畏。$B$B带着这根驯兽棒步入丛林吧。依靠它，你便可驯服一头石皮野猪，借此磨砺你作为猎手的技艺。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94793,'zhCN','训练野兽','与闪金镇的艾萨克·陈交谈。','你现在已经拥有了驯服宠物的能力，但你还得学会怎么训练它们。在这方面，没人比那个跟林地打了一辈子交道的艾萨克·陈更在行了。他会教你如何训练新宠物。$B$B愿风指引你，年轻的$C。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (94817,'zhCN','迷惑闪光',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (94818,'zhCN','应急方案',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94819,'zhCN','应急方案','与铁炉堡的高阶女祭司米姆斯谈一谈。','$N，你们的高阶女祭司米姆斯要在铁炉堡召见你。抓紧时间，我聪明的朋友，你的下一场考验马上就要开始了。虽然我很想亲眼见证你们种族独有的仪式，但我必须坚守此地。愿圣光护佑你的旅程。等你到了城里，直接去秘法区找米姆斯，她会在那里等你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94820,'zhCN','应急方案','与铁炉堡的高阶女祭司米姆斯谈一谈。','你们这个种族真是充满智慧，$N，我们很荣幸能与你们结为盟友。日复一日，你和你的同胞离收复故土的目标越来越近，但在此期间，你们也肩负着庇护流亡家眷的重任。那份对家园的深切渴望，想必让你们承受了巨大的压力。$B$B最近铁炉堡传来了消息，要求你立刻返回秘法区，去见高阶女祭司米姆斯。别让她久等了。愿艾露恩指引你的旅途。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94821,'zhCN','迷惑闪光','与铁炉堡的高阶女祭司米姆斯谈一谈。','最近有位牧师来这里找过你，年轻的$R。他说受命来寻你，希望你尽快赶回铁炉堡的秘法大厅。等你到了那儿，去找高阶女祭司米姆斯——她会向你说明一切。$B$B愿圣光与你同在，$N。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94822,'zhCN','迷惑闪光','与铁炉堡的高阶女祭司米姆斯谈一谈。','你已经引起了上层的注意，$N。他们要求你尽快前往铁炉堡的秘法大厅。显然，他们认为你已经证明了自己的实力，准备让你接受进一步的训练。到了那里之后，去找高阶女祭司米姆斯。她会为你提供后续的指引。祝你好运，愿圣光与你同在。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94824,'zhCN','迷惑闪光','与铁炉堡的高阶女祭司米姆斯谈一谈。','是时候动身去铁炉堡了，$N。秘法大厅的高阶女祭司米姆斯要求与你交谈。能让高阶女祭司点名要你亲自过去，不是天大的好事就是极坏的差事，但我猜你一直都表现不错，她找你多半是好事。$B$B别在这儿磨蹭太久了。换作是我，肯定会尽快赶过去的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94841,'zhCN','遗失的货箱','将遗失的货箱交给河林爆破引线港的弗里兹·法拉兹斯帕克。','<木板箱侧面贴着一张手写标签。右侧是一幅地图：东南方的海岸线上画着一个硕大的红圈，位置在一座潦草绘成的神殿以北。那座神殿四面环水，周围还有某种有翼生物。左侧则用特大号字体写着一段文字。>$B$B弗里兹·法拉兹斯帕克私有财产$B$B爆破引线港$B$B警告：严禁乱动。无人监督时严禁开启。$B$B<标签底部还有一条额外的备注。>$B$B如若遗失，请交还至河林爆破引线港的弗里兹·法拉兹斯帕克处。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94842,'zhCN','令人作呕的植物养料','收集4个巨型小龙虾壳、4份新鲜的粪便，以及8个泥鳍鱼人头，交给哈利根·特纳。','我们在这里自己配制肥料。那是我独创的秘方，虽然闻起来臭气熏天，但能让树木像野草一样疯长。$B$B配方是按1:1:2的比例混合小龙虾壳、粪便和鱼人脑袋。听起来很美味，对吧？$B$B弄点粪便倒是不难，南边就有个牧场能提供。至于脑袋和甲壳嘛，你就得亲自去河里蹚水摸了。$B$B如果你愿意搭把手，我们正缺人帮忙收集这些肥料的原料。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94857,'zhCN','假如一棵树倒下，却无人听见……','前往特纳的伐木场寻求帮助。','陌生人，听我说！$B$B我是附近伐木营地的伐木工。如你所见，我遇上事故被困在这儿了。如果不赶紧从这儿出去，我不是流血过多而死，就是被野兽吃掉。$B$B拜托了，去伐木营地叫人来帮忙！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94863,'zhCN','驯服野兽','使用驯兽棒驯服一头森林灰狼。练习你的技能，随后将驯兽棒交还给约瑟芬·卡森。','你已经学会驯服野猪了，接下来该学下一课。森林里还有更凶猛的伙伴，只要耐心相待，就能赢得它们的信任。$B$B带上这根驯兽棒，去找一头森林灰狼。记住，要尊重大自然的平衡。再证明一次你的猎人本领吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94864,'zhCN','驯服野兽','使用驯兽棒驯服一头森林熊幼崽。练习你的技巧，然后将驯兽棒还给约瑟芬·卡森。','你已通过驯服野猪与狼证明了自己，现在是时候迎接最终的挑战了。艾尔文森林的平衡维系于尊重与技巧。带上这根驯兽棒，去寻找一头森林熊幼崽。证明你甚至能赢得最强大伙伴的信任。$B$B完成这一课将加深你与野兽的契合。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94872,'zhCN','收买友谊：玛格拉姆','把图腾手提包交给凄凉之地玛格拉姆村的玛格拉姆军需官，以大幅提高你在该氏族中的声望。你在玛格拉姆半人马中的声望至少必须达到中立。','在争夺地盘的战争中，凶悍的玛格拉姆眼下无疑占据了上风。虽说咱们该庆幸沙漠里没天天打仗，但他们东边的村子可是眼见着一天比一天大，手底下的士兵也是越发肆无忌惮了。$B$B我是真怕玛格拉姆氏族就这么肆意扩张下去，但又不得不承认，他们确实有当盟友的资本。$B$B你想博得他们的信任，就把这袋图腾送给他们的军需官吧，不过自己千万当心。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94873,'zhCN','收买友谊：吉尔吉斯','把图腾手提包交给凄凉之地吉尔吉斯村的吉尔吉斯军需官，以大幅提高你在该氏族中的声望。你在吉尔吉斯半人马中的声望至少必须达到中立。','这两个强势的半人马氏族都有可能成为得力的盟友，但提到吉尔吉斯，我得给你提个醒。$B$B有可靠消息说，在玛格拉姆和吉尔吉斯的交锋中，吉尔吉斯可以说是节节败退。但这未尝不是件好事——走投无路的孤狼，说不定更愿意接受外人的援助。$B$B我给你备好了一袋图腾。你带去吉尔吉斯村交给他们的军需官，当然，前提是他们有这么号人。这步棋应该对咱们有利。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94877,'zhCN','拯救阳光林地','为法霍德要塞的德玛尔·布兰特消灭阳光林地中的8名暮光袭击者、8名暮光暗影法师和8名暮光新教徒。','当你环顾四周时，你看到了什么？破碎的家园和疲惫的人民。$B$B暴风城已经抛弃了我们，让我们自生自灭，而我们赖以生存的资源每天都在减少。这高墙内的许多人都是难民，他们勉强逃脱了劫难，甚至没能保全自己的家人。$B$B陌生人，法霍德不是暴风城。我们在西北方失去了一个定居点，被暮光之锤强占了去，但我们绝不会让他们一直霸占那里。如果你渴望战斗，就去阳光林地，把那些野蛮人从我们的土地上清除出去。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94879,'zhCN','知识碎片','从阳光林地收集5张暮光书页，将其交给法霍德要塞的艾什·安伯霍尔。','看到北边那座变成废墟的城市了吗？也就是阳光林地。德玛尔曾试图派兵过去，但我们离收复它还差得远呢。不过我有个更好的主意。$B$B说实话，暮光之锤的这次袭击并非首次。他们似乎是在某个中心位置协同行动的，我想找出那个大本营究竟在哪儿。既然你在外面干着冒险者最拿手的活儿，那就顺便留心一下他们有没有遗落什么文件。只要收集到足够的数量，我就能拼凑出他们的意图。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94881,'zhCN','奇特的饰物','为法霍德要塞的艾什·安伯霍尔，从阳光林地的暮光暗影法师和暮光新教徒身上夺取25个暮光护符。','哎呀，让我看看这是谁？一位勇敢的新晋$C来拯救我们于水火之中了？真迷人！那么，也许你能帮我个小忙？我很想多了解一下阳光林地里的这个邪教。$B$B和所有邪教一样，他们也有着森严的阶级制度。那些具有魔法天赋的人通常备受青睐，并会被赐予信物以彰显其地位。这些护符被注入了魔力，因此蕴含着极其丰富的邪教魔法。$B$B我很想亲自看看这些信物。亲爱的，去帮我带几个回来，好吗？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94884,'zhCN','令人不安的发现','将装满水的水晶催化剂交给法霍德要塞的艾什·安伯霍尔。','我受够这个山洞了。只要你杀出一条血路，我就会趁乱溜出去。$B$B遗憾的是，我现在身体太虚弱了，恐怕带不走这些样本。它们的能量极其惊人，而且天知道我被困在下面多久了。一旦我们从这儿出去，请立刻把它们交给安伯霍尔女士。我必须得休息了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94886,'zhCN','西部前线','在西边的暮光之帷附近找到里夫坦中士。','虽然你在法霍德帮了大忙，但我相信你的才能可以在其他地方发挥更大的作用。$B$B我们的一支巡逻队前阵子失踪了。他们原本负责守卫西部边界，但根据安伯霍尔女士发现的情报，我担心他们直接闯进了暮光之锤的中央营地。$B$B我们自己能应付阳光林地的清理工作。如果这位好心的女士没说错，我们当务之急是去看看那位固执的中士。他现在亟需支援。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94889,'zhCN','杀出一条血路','为里夫坦中士击败暮光之帷内的8名暮光狂热者、8名暮光腐蚀者和8名暮光勇士。','看来暮光之锤每天都在招兵买马，而我们却连暴风城的一丁点消息都没收到。我们迟早会被他们淹没。$B$B我不在乎像安伯霍尔这样的官僚怎么说。当一支敌军在我们的家园集结时，我绝不会放弃这块阵地。如果我们现在撤走，以后还得再对付这些狂热者。而且下一次，他们就会兵临城下了。$B$B如果你的命令就是来给我当保姆，那至少派点用场，帮我清理掉这些狂热者。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94911,'zhCN','自然之子','在雷霆崖与图拉克·符文图腾交谈。','你好，年轻的$R。我看得出来，你在德鲁伊法术上大有前途。雷霆崖有位名叫图拉克·符文图腾的长者，你最好去拜访他一下。他会指引你前往卡利姆多，去塞纳里奥议会的要塞——月光林地。$B$B那里的人会张开双臂欢迎你，议会的德鲁伊们也会将他们的智慧倾囊相授。$B$B正如你们族人所说的那样——带着风的祝福去吧，年轻人。祝你的冒险好运。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94912,'zhCN','自然之子','在暴风城与沙德拉斯·月树交谈。','你好，年轻的$C。$B$B你听说过塞纳里奥议会吗？我猜你肯定没听过。跟你一样，他们是一个由自然主义者和德鲁伊法术研习者组成的古老教团。你去暴风城找一位名叫沙德拉斯·月树的暗夜精灵。他会指引你前往卡利姆多，去塞纳里奥议会的要塞——一个叫月光林地的地方。$B$B去吧。如果你想拯救自己的家园，要学的东西还多着呢。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94913,'zhCN','月光林地','使用法术“传送：月光林地”抵达月光林地，在那里与永夜港的德迪利特·星焰谈一谈。','月光林地这片神圣的土地欢迎所有的德鲁伊。月光林地的守卫者——守护者雷姆洛斯，时刻注视着所有在那里休眠的同伴。我会教你传送过去的法术。每当你寻求月光林地的知识或慰藉时，便可施放它。$B$B至于你在艾泽拉斯的第一课，前往月光林地，与永夜港的德迪利特·星焰谈谈你当前选择的道路。祝你好运，年轻的德鲁伊。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94914,'zhCN','月光林地','使用法术“传送：月光林地”抵达月光林地，在那里与永夜港的德迪利特·星焰谈一谈。','月光林地这片神圣的土地欢迎所有的德鲁伊。月光林地的守卫者——守护者雷姆洛斯，时刻注视着所有在那里休眠的同伴。我会教你传送过去的法术。每当你寻求月光林地的知识或慰藉时，便可施放它。$B$B至于你在艾泽拉斯的第一课，前往月光林地，与永夜港的德迪利特·星焰谈谈你当前选择的道路。祝你好运，年轻的德鲁伊。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94923,'zhCN','不翼而飞的帽子','在河边鱼人出没的某个地方寻找罗比的帽子。','<罗比凑近你，仿佛要分享一个天大的秘密。>$B$B嘘！嘿，$G先生:小姐;，我需要你帮忙！$B$B我姐姐送了我一顶帽子当生日礼物，可我在河里玩的时候把它弄丢了。因为有鱼人，大人不准我去那里，所以我不能找爸爸或艾莉帮忙，不然他们就会知道我跑到哪儿去了！$B$B那可是顶好帽子。我敢肯定，一定是哪个鱼人捡到后据为己有了！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94924,'zhCN','猎杀猎手','为守望者科尼利厄斯消灭12名洛格玛偷猎者。','那些兽人偷猎者是一群嗜血的家伙。他们会消灭任何会动的东西——不管是人类、狮子还是马匹。他们对河林的所有生灵都是一种威胁，必须阻止他们。$B$B他们像疯狗一样成群结队地在平原上游荡。如果你看到他们，就把他们干掉。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94928,'zhCN','给弗里兹的毛皮','将这捆狮皮交给爆破引线港的弗里兹·法拉兹斯帕克。','这些兽皮要被送到爆破引线港去。那是东北方一个由地精经营的港口。$B$B等你到了那里，把兽皮交给弗里兹·法拉兹斯帕克。告诉她这是科尼利厄斯送来的。我们交易的细节都已经谈妥了，所以她会知道这些东西是干什么用的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94931,'zhCN','被偷走的锯条','为伐木厂的哈利根·特纳从刺毛丘陵的豺狼人营地找回8个锯齿利刃。','驻扎在南哨的年轻人基本上干得不错，把豺狼人挡在了外面。但时不时总有几个家伙趁着夜色溜进营地，制造点小麻烦。它们特别喜欢偷锯齿利刃，多半是想用那些锋利的金属片来做武器。$B$B如果你能帮我们夺回一些，那可就帮了大忙了。那些豺狼人很可能把它们藏在西边山丘里的营地中。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94946,'zhCN','魔法之城达拉然','搭乘破天号从泽风岛前往达拉然城，并在抵达后与德纳里斯·星风交谈。','我原本打算成为第一个踏上艾泽拉斯的人，但最近发生的教派事件打乱了计划。因此，我还得在瓦拉纳尔停留一段时间。不过不必担心，我们的法师会在达拉然接应你。趁我们处理这里的事务时，不妨去探索艾泽拉斯。需要你们的时候，我们自会召唤你们。$B$B准备好后，请前往旅店外的码头，登上那里的空中快艇。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94947,'zhCN','欢迎来到艾泽拉斯','通过天裔传送门前往暴风城，并向暴风要塞的伯瓦尔·弗塔根报到。','这下面的世界广阔无垠，我们需要族人开始向外探索。这就该你出马了。$B$B肯瑞托属于一个由志同道合的国家组成的“联盟”。这个联盟真正的核心，是位于南方的暴风城。伊拉德林让我找个人去一趟暴风城，会见那里的摄政王——一个名叫伯瓦尔·弗塔根的人类。$B$B等你准备好后就出发吧，肯瑞托的法师们已经专门为高阶会开启了一道通往暴风城的传送门。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94961,'zhCN','反咬一口','收集20块暮光徽记，交给法兹尔。','<这只豺狼人从口袋里掏出一点金子，在你面前晃了晃。>$B$B$R，我跟你做笔交易！这玩意我还有很多。帮我复仇，我就带你去找！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94978,'zhCN','驯服野兽','使用驯兽棒驯服一只在水域附近找到的风歌爬行者。$B磨炼你的技巧，然后将驯兽棒还给瓦拉纳尔的奎尔阿娜·疾风。','每个猎人都是从领悟野兽与主人的羁绊开始的。这是你的第一项挑战。假以时日，你能驯服这世界上任何角落的生物，但现在，咱们先从泽风岛的河流湖泊练起。$B$B拿着这根驯兽棒，去找一只风歌爬行者。$B$B证明你能赢得它的信任，就此踏上成为真正大师的道路吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94979,'zhCN','驯服野兽','在阵风浆果低地使用驯兽棒驯服一头暴躁的疾风陆行鸟。$B磨炼你的技巧，然后将驯兽棒还给瓦拉纳尔的奎尔阿娜·疾风。','你已经证明了自己能驯服河流里的爬行者，现在该去开阔地带试试身手了。泽风岛的平原上回荡着疾风陆行鸟的鸣叫，那是一种骄傲的长翼猎手，奔跑起来快如疾风。$B$B拿上这根驯兽棒，去找一只吧。前往低地，赢得它的信任。$B$B去证明你已经准备好迎接未来的试炼了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94999,'zhCN','爱慕守望者','将艾林诺尔的关爱包裹交给南哨的守夜人弗雷德里克斯。','哦！抱歉，没看见你在这儿。$B$B我正给我一个朋友准备点小礼物。嗯……其实更像是熟人。你见过守夜人弗雷德里克斯了吗？他就驻扎在西边的南哨。$B$B他时不时就会来农场巡视。我想送点东西表达下心意。$B$B我本想亲自送过去，但我得照看弟弟，还得打理农场。$B$B相信你能理解。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95034,'zhCN','血债','到瑟伯切尔与卢米娜·风歌交谈。','我想你应该知道，在路上袭击我们的其实并不是豺狼人。$B$B袭击我们的实际上是一种巨大的狼形生物，我现在知道那叫“狼人”。它干掉了护卫朝我扑来，但巴农挺身挡在了它面前。我设法施放了一个法术惊吓到了那怪物，迫使它逃跑，但巴农已经被咬成重伤。他坚持让我丢下他先走，但我拒绝了。$B$B当我们步履蹒跚地赶回这里时，豺狼人发现了我们。接下来发生的事情简直可怕至极……',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95041,'zhCN','数据囤积者','从诺莫瑞根附近收集7张诺莫瑞根档案数据卡片，然后交给铁炉堡的耶玛。','逃离诺莫瑞根之前，我给家族档案做了一份硬拷贝。奥术技术场方程、第二次大战的潜艇船体设计、奎克斯维奇奶奶的辣椒配方……我们最伟大的成就都在那些文件里。$B$B直到抵达铁炉堡我才发现，我的背包破了个洞！好几张穿孔卡片丢失了，没有它们，数据会乱成一团无法恢复。$B$B那些卡片一定埋在诺莫瑞根外面的某处雪地里。你能帮我找回来吗？我知道这希望渺茫……',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95042,'zhCN','寻找科尔宝石','给灰谷的乌瑞克·霜帷带去一枚科尔宝石。','一名被遗忘者圣骑士……居然出现在灰谷？有意思。$B$B这么说，你在寻找科尔宝石？不足为奇，联盟的圣骑士有时也会用它们来强化魔法武器与器具。像你这般堕落的圣骑士，又有何不同？$B$B若你真心想要一枚，就必须向北前往那片名叫黑暗深渊的废墟。仍在使用这些宝石的纳迦就在下面。切勿独自前往，$C。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95059,'zhCN','法拉兹斯帕克的板条箱','将法拉兹斯帕克的板条箱交给法霍德要塞的骑士指挥官德玛尔·布兰特。','这次有份特别的东西要送。$B$B法霍德的骑士指挥官德玛尔·布兰特正等着呢。也不知道他怎么想的，非要我每次都叫他的全名。真是个怪人。$B$B总之，去这里西南边的要塞就能找到他。那座石头堡垒大得很，一眼就能看见。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95062,'zhCN','法拉兹斯帕克的板条箱','将法拉兹斯帕克的板条箱交给洛格玛的克罗姆罗什。','该送特别快递了。$B$B老克罗姆罗什正在这儿正西边的洛格玛等着这个包裹。$B$B我建议你尽快给他送过去，但路上一定要小心。你问为什么？最好别多问。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95064,'zhCN','预防措施','为泰拉尔之望的守望者科尼利厄斯杀死12名洛格玛受训者。','自从兽人来到这里，他们就一直是个不断扩张的威胁。起初只是占领了河边的土地，现在他们的势力又扩张到了平原上……$B$B说实话，我永远也无法理解他们这种生物，我也不在乎。但如果他们认为还有更多的地方可以占领，那我可绝不答应。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95065,'zhCN','钓鱼时间','将1个闪光的小珠和3条夜色虫交给暴风城港口的吉尔伯特·格雷。','多美的景色啊……这真是我这把老骨头梦寐以求的。$B$B现在的鱼咬钩可勤快了，只可惜我已经用光了最后一点鱼饵。你身上应该没带备用的钓鱼补给吧？当然没有，原谅我。我一想到能再抛一竿就激动得不行，完全忘了可能只有我才会走到哪儿都随身带着补给。$B$B能帮我补点货吗？运河沿岸，贸易区西边的凯瑟琳·利兰那儿有各种各样的钓具。告诉她，是老格雷派你来的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95111,'zhCN','被低估的天赋','与奥特交谈，请他为你铸剑。','塔伦米尔有一位名叫奥特的武器匠。据各方说法，他不过是个不起眼的铁匠，卖些简单的刀剑给过路人。我自己也曾向他买过一把剑，后来拿到幽暗城去保养时，那里的铁匠对它的成色大为惊叹。他们以为这出自某位名匠之手，可并不是，就是奥特。$B$B我想给这个兽人一个大显身手的机会。把材料带给塔伦米尔的奥特，请他接下这单定制。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95118,'zhCN','咸水野蛮人','在东风海岸消灭8个鱼人智者和8个鱼人战士。','鱼人，鱼人，全是鱼人！我听到的全都是这玩意儿；水手在说，渔夫在说，连我自己的孩子都在说！每个人都在拿这事烦我！我承认，他们确实是个大麻烦，但我还要管理这个港口呢！$B$B帮个忙，行吗？去宰了几个那种怪物，我绝对不会让你白干的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95119,'zhCN','恶性竞争','在爆破引线港北边的东风海岸消灭10名东海冒险家和10名东海火枪手。','你知道东海海盗那帮人吗？那真是一群令人作呕的家伙，这可是从一个经营着名叫“爆破引线港”的地方的人嘴里说出来的。$B$B他们破坏力极强，嗜血成性，最糟糕的是，他们触及了我的底线。他们偷窃货物，击沉船只，这两样都让我损失了成把的金币！$B$B我们必须摧毁他们的整个行动，就从离这儿最近的那些开始。你可以在北边的海滩上找到他们。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95120,'zhCN','悬赏：老腐块','将老腐块的死亡证明交给码头管理员维兹巴兹。','水手和游泳者请注意！据当地渔民称，有一只极其好斗、绰号“老腐块”的鱼人，被发现在南面靠近一群鱼人盘踞的岛屿附近水域，频繁袭击划艇和其他小型船只。$B$B码头管理员维兹巴兹现悬赏换取该奇形生物死亡的证据。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95121,'zhCN','海之味','为芬博·格里斯米兹收集12个鱼人眼睛和6块沙行蟹肉。','欢迎来到芬博的水上餐厅！今天的菜单是烤野猪肉和烤鱼……跟每天一样……$B$B这菜单急需换换花样了。我看中了一份新的海鲜炖菜食谱，但我需要一些新鲜的肉。弄点鱼人眼睛和沙行螃蟹肉应该就够了。$B$B你可以在附近的海滩上找到这两种食材。没什么比得上地道的当地食材了！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95125,'zhCN','奥特的杰作','看着奥特为你铸剑。','这些材料着实上乘，$C。你肯把铸这把剑的差事交给我，是我的荣幸，我只希望自己不负所托。$B$B请退开些，好让我开始锻造。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95126,'zhCN','月银之刃','把奥特的杰作带给银松森林的特雷凡·罗尔。','剑在这儿。你说是一位名叫特雷凡的圣骑士派你来的？下次见到他，请代我向他致谢，感谢他给的这次机会。愿荣耀伴你同行，朋友。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95140,'zhCN','老火眼','使用月银之刃在银松森林消灭老火眼。','我看见你已经拿到武器了，$C。我祈求它不会叫你失望。$B$B当地人说，老火眼在南边一片广阔地带出没，通常能在吉尔尼斯大门附近找到它。找到它，用你的新剑了结它。事成之后回来，塑风者会感激你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95147,'zhCN','失踪的斥候','将博莱恩的信息交给南哨的道尔顿队长。','你……你是从哪儿冒出来的？你不该来这儿！$B$B<博莱恩强忍着剧痛——他浑身是伤，腿上还有一处严重感染的咬伤。>$B$B把这个交给道尔顿。沿着路向北走，然后向东，那里的平原比我这该死的腿上的伤口还要宽阔。我本想让你告诉他，他是对的，但我绝不会让他如愿以偿……至少在我死之前不会。$B$B我恨透了这些该死的山丘！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95148,'zhCN','南哨豺狼人报告','将南哨豺狼人报告交给法霍德要塞的骑士指挥官。','虽然我很想亲自把这份沾满鲜血的报告交给骑士指挥官，但我也想保住我的饭碗。我已经把它清理了一下，让它看起来没那么……血腥了。$B$B鉴于最近豺狼人的暴动，恐怕传递这个消息的苦差事只能落在你头上了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95156,'zhCN','填满并立起','为训练场的余烬收集3捆干草。','我们的训练假人已经磨损得相当严重了。如果不尽快修补，我担心我们的新兵会无法应对真正的战斗。$B$B如果你进来的时候没注意到的话，要塞外面有个小农场，是一个叫惠勒的人经营的。他那里可能还有几蒲式耳多余的干草愿意转让。$B$B如果他能为我们的行动提供物资，我会确保他得到应有的报酬。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95161,'zhCN','记住我爱你','将染血的信交给暮色森林的艾瓦特·菲尔伍德。','如果你在找杰瑞米·织心，直接去暮色森林找他的新养母，艾瓦特·菲尔伍德吧。那可是个热心肠的好女人。虽说去她那肯定免不了要干点农活，但也总好过一直缩在孤儿院里。$B$B如果你见着了小杰瑞米，千万代我们问声好，告诉他大家都很想他，拜托了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95162,'zhCN','苍牙野猪狩猎','在博尔德罗克附近为纳佐克收集10块野猪肉。','由于人类或暮光之锤没有占领的土地少之又少，这个牧场成了我们为数不多的食物来源之一。食人魔不太擅长务农，但他们对美味的烤苍牙野猪肉情有独钟，并且同意只要我一直供应肉食，就让我留在这里。$B$B随着战事的推进，对食物的需求只会与日俱增。现在我手头的食物根本不够吃，这帮食人魔看我的眼神简直就像在看他们的下一顿饭。$B$B如果我们想为洛格玛储备足够的肉，我就需要你帮忙狩猎。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95184,'zhCN','最锋利的刀刃','将8块坚硬的磨刀石交给法霍德训练场的余烬·刃语。','战斗训练的艰苦是一回事，但这些受训者还不明白，一把训练剑和身经百战的老兵精心保养的利刃之间究竟有什么区别。$B$B我想是时候向我们的新兵展示一下，一把锋利的刀刃是如何决定生死胜负的了。$B$B如果你能帮我们找几块磨刀石，我们一定会物尽其用。有些工匠专门钻研这门手艺，我建议先从他们那里着手。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95212,'zhCN','鞍具岂能将就','收集6张原始豹皮，送到冻石农场。','我们正准备派一队山羊去增援奥特兰克远征军，可制作鞍座的材料已经用光了。$B$B去东边找最大、最凶猛的豹子，剥下毛皮带来给我。那里冷得刺骨，我们的部队理应得到最上等的毛皮来保暖！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95214,'zhCN','被偷走的炸药粉','从古博拉采掘场东边的石腭怪手中夺回16份被偷走的炸药粉，再向矿场主管瑟斯丁复命。','这桶火药足够把麦格尼国王的王座厅炸成露天庭院。我们必须在石腭怪搞懂怎么点燃之前，把它夺回来。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95216,'zhCN','新的瘟疫','前往洛丹伦废墟，从枯牙身上提取剧毒的毒株，将其交给幽暗城的萨多雷·格雷夫。','欢迎来到幽暗城跳动的心脏——炼金房！我们在这里对艾泽拉斯最致命的奇珍异兽进行活体实验。$B$B算你走运，我今天心情不错，不妨向你透露点最新的研究动向。据说在我们这座美丽城市的上方废墟里，正徘徊着一种剧毒的节肢怪物。传闻它的毒素连亡灵的腐肉都能轻易蚀穿。简直令人欲罢不能！$B$B我急需证实这个传闻。要是你不幸被它咬中，感觉肉体正在迅速枯萎，务必给我带回一份样本。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95217,'zhCN','采掘场的铁匠','收集12块铜锭和4张坚韧的野猪皮，交给弗拉斯特·多克南。','这么说你想学铁匠手艺？也许咱们能互帮互助。$B$B补给迟迟未到，我需要一些材料来修缮营地。只要你能弄来我需要的东西，我就教你几手。很公平吧？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95219,'zhCN','从港口到港口','将这桶爆破引线港药水瓶交给菲拉斯羽月要塞的玛德拉克·绿井。','又有个活儿给你，孩子。你觉得环游世界怎么样？$B$B这可是你见过的最好的爆破引线港药水瓶。问题是，它得大老远送到我在菲拉斯羽月要塞的一个客户那里。当你看到你这辈子见过的最高的树时，你就知道你找对地方了。$B$B我的一个手下把它密封得很严实，但谁也说不准什么东西会把它引爆，所以一定要小心轻放，明白吗，伙计？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95250,'zhCN','憎恶生物','前往洛丹伦废墟斩下男爵的徽记，将其带给图曼上尉。','有什么事，$R？没看到这里正打得不可开交吗？$B$B主人早已身先士卒杀入敌阵，临走前命我死守此地。不过，他确实已经去了很久了。$B$B我估计你在这种战场上连十分钟都活不下来。但为了给你那生锈的脑子找点事做，不如去找大元帅吧。他是你见过的最高大、最威武的英雄，在人群中你一眼就能认出他。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95254,'zhCN','通缉：钳爪','将钳爪的钳子交给芬博·格里斯米兹。','呼叫所有钓鱼爱好者！$B$B我正在收购一些蟹肉。不只是普通的蟹肉丝，我要的是一整只蟹钳。我看到一只大螃蟹在码头下面爬来爬去，偷吃鱼饵，还咬断鱼线。$B$B谁能把那家伙的钳子给我带来，我就付他赏金。你还能品尝到我用它做的一道菜。$B$B—— 芬博·格里斯米兹',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95288,'zhCN','走私者的天堂','为爆破引线港的弗里兹·法拉兹斯帕克收集8件走私货物。','你看起来很习惯听别人的吩咐。我就喜欢跟班有这种特质。只要稍加训练，你就能成为一个巨大的资产。让我们来测试一下吧。$B$B最近那些东海海盗抢走了一批我的走私货物。这太不讲武德了。明明是我先偷的！$B$B第一课，跟班。永远不要背刺一个背刺者。去给他们点颜色看看，让他们知道自己惹错了地精，把我的东西拿回来。最好是用武力。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95329,'zhCN','在外执勤','前往泰拉尔之望，从守望者科尼利厄斯那里获取状态报告。','北边的平原上有一座瞭望塔。它是用来监视部落军队动向的观察哨。$B$B驻扎在那里的守望者名叫科尼利厄斯。去见见他，要一份战况报告。他一个人孤零零地守在那儿，所以我习惯定期去探望他。事先提醒你，他这人可能有点……闷葫芦。这也是他当初被发配到这么偏远哨所的原因。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95349,'zhCN','大地之环','搭乘破天号从泽风岛前往莫高雷，并在抵达后与阿拉娜·风暴行者交谈。','最近发生的教派事件耽搁了我前往艾泽拉斯的计划，我还得在瓦拉纳尔停留一段时间。你和其他几名塑风者将作为我们的先遣队。阿拉娜·风暴行者会在莫高雷接应你们。我们处理完这里的事务便会与你们会合，在此期间，不妨去探索艾泽拉斯。$B$B准备好后，请前往旅店外的码头，登上那里的空中快艇。$B$BBanu-Alah，$N。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95350,'zhCN','欢迎来到艾泽拉斯','前往奥格瑞玛，在智慧谷与萨尔交谈。','这下面的世界广阔无垠，而我们的新盟友正是我们生存下去的关键。$B$B大地之环属于“部落”——一个由志同道合的氏族组成的骄傲联盟。附近的雷霆崖就是部落的一部分，再往东则是首都奥格瑞玛。$B$B去雷霆崖中心找飞行管理员。他们会送你飞往奥格瑞玛，你要代表塑风者去会见部落的大酋长——萨尔。愿风指引你，$N。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95428,'zhCN','克鲁格菲斯特的法令','向洛格玛的克罗姆罗什复命。','小$R狠狠地砸碎了暮光。也许你的部落比克鲁格菲斯特想象的还要强大。$B$B你可以留在博尔德罗克。暂时。$B$B告诉其他小东西，我们很快就会再次让鲜血流淌。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95508,'zhCN','不速之客','帮助沃尔顿在遭遇泰瑞·长饮和库尔提拉斯水兵时活下来。','是的，我曾经是库尔提拉斯海军的一员。在海军上将夺取塞拉摩并在杜隆塔尔发动战役后，我对他的手段产生了……“异议”。尤其是那些处决平民的做法。$B$B这里面还有更多隐情，不过……等等……那是什么？$B$B有一群人正从山脊上过来！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95561,'zhCN','掌上明珠','为法霍德要塞的泰莎·晨明收集6个新鲜苹果。','<小艾玛响亮的哭声在法霍德要塞里回荡。泰莎带着疲惫的笑容看着你。>$B$B哦，你好，冒险者。抱歉这么吵。小艾玛今天似乎特别烦躁，但我不知道为什么。也许吃点东西会有帮助。$B$B你觉得你能帮我给她找点吃的吗？我丈夫出去买补给了，所以我实在腾不出手亲自去。如果你能在这附近找到几个苹果，我就能给她做点美味的苹果泥。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95603,'zhCN','钟楼里的蝙蝠','为罗兰修女在法霍德教堂消灭5只栖息的夜行蝙蝠。','自从洛利修士和我开始以更世俗的身份服务法霍德以来，这里的教堂就被废弃了。我愿意相信，一旦战斗结束，我们就能把圣光带回这个地方。虽然，我担心那可能需要很长一段时间……$B$B尽管如此，我们还是需要保持教堂的正常运转，以期那一天的到来。$B$B为此，一群蝙蝠在教堂的高层安了家。如果你能帮我们把它们赶走，那真是帮了大忙了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95621,'zhCN','谷中风波','前往失事商队处，查明库尔提拉斯人出现在这里的原因。','今早，我发现有一群人类在下面的山谷里搜寻什么东西。我透过步枪瞄准镜仔细看了看，很明显他们是身穿库尔提拉斯制服的士兵。$B$B如果你愿意接我这单活，请前往南边失事商队附近他们扎营的地方。解决掉你看到的任何士兵，并设法弄清他们来此的目的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95646,'zhCN','高地的恐魔','前往挖掘场击杀高地恐魔，将它的根核交给湿地的绿色守卫者雷希耶尔。','这片半咸的沼泽连接着南方更为广阔的淡水水域。每念及此，我都痛心不已。因为我能通过根须真切地感受到，一股腐化之力正顺着山谷的裂隙缓缓渗透蔓延。$B$B这里的生灵与低地的野兽一样，对这股邪恶的气息极其敏感。自诞生之初，它们便缺少海水盐分的淬炼，面对此等邪秽，几乎毫无招架之力。$B$B去趟高地，把高地恐魔的根核给我带回来。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95647,'zhCN','迷失在灌木丛中','在挖掘场中寻找阿丁·格拉斯曼的下落','我丈夫阿丁对大自然有着异乎寻常的敏锐直觉。为了帮我采集炼金所需的珍稀草药，他敢攀登最险峻的山峰，也正是因为他，我们家的药架和地窖才从没空过。$B$B但我怕他这次惹上大麻烦了。前阵子有支挖掘队路过咱们这买补给，闲聊时提到了某种前所未见的参天巨草。阿丁一听就坐不住了，非要亲自去探个究竟。可他这一去，未免也太久了！$B$B你要是能寻得他的下落，我将不胜感激。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95697,'zhCN','口味的变迁','进入湿地的挖掘场，带回灌木丛迅猛龙肉。','扎姆沙跟我抱怨，说我们需要增加点家常菜的花样。$B她觉得，要是咱们店里挂牌卖迅猛龙肉，绝对能把那些平时不怎么来“博斯坦的火坑”吃饭的客人都给吸引过来。$B$B她的主意确实不错。但我想要的是那种能彻底盖过咱们老家乡下泥土味的招牌菜。这里可是奥格瑞玛！博斯坦必须把那些平平无奇的家常菜，做成端得上台面的珍馐美味。$B$B最近有个猎人从湿地满载而归，带回了挖掘场里那种灌木丛迅猛龙的巨型利爪。$B$B想接这单买卖吗？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95737,'zhCN','寻访凯特林','与米奈希尔港的凯特林·格拉斯曼谈一谈。','我偶尔会跟同行们通信——无论是草药师，还是那些痴迷于奇花异草的怪人。我们交流新发现，也会互相提醒前方的凶险。$B$B湿地的一位炼金师在信里提到，她丈夫所在的挖掘队偶然发现了一种早已绝迹的原始巨草……但之后，她就再也没有提过那东西到底有多大产量，或者在哪能采到。$B$B如果你顺路，去米奈希尔港找凯特林·格拉斯曼打听一下。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95772,'zhCN','寻找桑布雷德','前往维尔加挖掘场，寻找多林·桑布雷德的兄弟戴温。','我那个兄弟非要拉着我，跟着洛克莫丹的一支挖掘队去湿地。他信誓旦旦地说，他们要去挖一座连矮人都没踏足过的深山。$B$B哎，要不是我手头还压着一堆没改完的束腰，我早就跟着去了。$B$B可戴温每次出远门，总会记得往家写信报平安。这次却音讯全无，这让我心里直打鼓。$B$B你要是往那边走，能不能顺道帮我找找我兄弟？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95792,'zhCN','清理干净','为吉琳达·铜光消灭8只烬鳞雏龙和4名烬鳞战士。','想发大财，就得去别人不敢涉足的险地！我身后这个洞穴里藏着丰富的未开采矿脉。要是能弄个团队进去开采，那绝对是大把大把的钞票。$B$B只是有那么点……微不足道的……小小的龙患问题。真的，不值一提。$B$B如果你愿意进去替我摆平那些龙，省去我的麻烦，我保证少不了你的好处。更别提，你还能得到一位未来矿业大亨的青睐！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95795,'zhCN','命丧沼泽','返回多林·桑布雷德处','<你取下斗篷，默默地盖在了矮人的遗体上。>$B$B前往湖畔镇，亲口告诉多林·桑布雷德他兄弟在挖掘场的悲惨结局。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95803,'zhCN','诚意的信物','将鲁道夫·盖尔哈特的首级带给幽暗城的希尔瓦娜斯·风行者。','既然我们已经拿下了那个堕落指挥官的首级，我需要你把它送到幽暗城。希尔瓦娜斯·风行者对我们极不信任，几乎快要公开贬损我们了。$B$B把鲁道夫·盖尔哈特的首级交给黑暗女王。向她证明，我们能够清理门户，并且全心全意为被遗忘者的繁荣效力。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95805,'zhCN','安瑟与穆莎的恩典','在十分钟内，赶在阴燃熏香化为灰烬之前，将它带到东南方山丘里的安瑟与穆莎的神龛！','太阳与月亮——安瑟与穆莎——不像元素那样属于我们的世界，但它们的光芒赐予我们生命、指引与希望。$B$B我们尊重世间的灵魂，自然也同样敬奉这对双生者。$B$B如果你愿表达敬意，就带上这支仍在燃烧的熏香，前往东南方山丘上的神龛。那里在野猪人以南，俯瞰着台地。动作要快，务必在熏香燃尽前赶到。$B$B别把它弄湿了！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95809,'zhCN','心之编织','返回米奈希尔港的凯特林·格拉斯曼处','我得先喘口气，然后再自己找路出去。$B$B<他从包里拽出几根芦苇，三下五除二编成了一颗心。>$B$B拿着这个，带回去交给凯特林，告诉她我马上就回家！既然你已经帮忙清空了道路，我稍微收拾下草药，循着你的脚印就能回去。$B$B谢谢你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95883,'zhCN','被折磨的灵魂','从银松森林博伦的巢穴附近的亡灵身上，收集一个被折磨的灵魂。','<一场仓促拼凑的仪式所需的物品，被随意堆放在祭坛上。根据那张残破的便条来看，所有材料均已备齐。如今只缺鲜血供奉和一个被折磨的灵魂。$B$B你周围的亡灵看起来受尽了折磨。他们身上或许就有你要找的东西。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95885,'zhCN','鲜血供奉','使用被折磨的灵魂，在博伦的巢穴供奉石前献上鲜血。','<现在只差鲜血供奉了。$B$B便条残片中提到了一次“自愿献祭”。$B$B一股强烈的恐惧感涌上心头。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95912,'zhCN','通缉：剑圣卡乔','将剑圣的战旗交给法霍德要塞的余烬·刃语。','我们每砍倒一个兽人，就会有另一个顶上来——而且不知为何，一个比一个难缠。肯定有一位技艺精湛的战士在训练这新一代的兽人。如果我们想大幅削减他们的数量，就必须切断他们的兵力补充。$B$B如果哪位士兵有足够的胆识，就必须找到这个剑圣并终结他。此刻，他很可能就在部落前哨站北边的训练营里。杀了他，夺走他的战旗，彻底摧毁兽人的士气。$B$B—— 余烬·刃语',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95913,'zhCN','公主的待遇','为法霍德要塞的泰莎·晨明收集3张山狗皮。','<泰莎轻轻摇着孩子，想哄她入睡。>$B$B如果她不是饿了，也许只是累了。老实说，小艾玛的到来是个令人欣喜的意外，但这也意味着我们有些准备不足。我丈夫为她做了这个可爱的摇篮，可我担心这些毯子太旧了。毕竟，她值得拥有最好的。$B$B如果你还愿意帮忙，请替我找些毛皮来铺她的床，我会永远感激你。如果这能让她不再哭闹，我想法霍德的所有人也都会感谢你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95934,'zhCN','利润的证明','为吉琳达·铜光寻找一块立方龙锆石。','我的勘探工具显示，这些洞穴里有一种前所未见的矿物。我叫它立方龙锆石。这玩意儿绝对价值连城。$B$B虽然这很让人兴奋，但如果我拿不出它存在的证据，是没人会来帮我挖的。没错，我有工具的读数，但人们更喜欢把一块闪闪发光的大水晶捧在手里，而不是盯着图表看。$B$B我敢肯定，里面的泥土里肯定有几块水晶露出了头。如果你愿意躲开几只龙去弄一块回来，那你可真是帮了我的大忙了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95943,'zhCN','工头的困境','将工头的板条箱还给法霍德要塞的伯特兰·铁眉。','你好啊，$G。我叫伯特兰，伯特兰·铁眉！很高兴为你效劳。$B$B<伯特兰伸出一只脏兮兮的手。>$B$B这里的好心人雇我监督要塞建设。他们经验不足，干劲倒是十足！问题是，我把工具弄丢了。$B$B我在西北边的一片小树林里撞上了几个暮光教徒，只能在小命和工具之间选一个。好处是我活下来了。坏处嘛……你也猜得到。$B$B你能帮我找回工具吗？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95957,'zhCN','干杯！','将吉兹普林克的泛沫酒杯交给爆破引线港的格雷·晨明。','给你，勇士。给那边那个满腹牢骚的家伙来一杯。如果这都不能让他清醒过来，那就没什么能做到了。$B$B哦，还有呃……碰过这玩意儿之后记得洗手。千万别弄到眼睛里。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95961,'zhCN','出去了','在爆破引线港找到格雷·晨明。','<泰莎的婴儿继续大声啼哭。>$B$B我猜她不是困了。哦……每个人都表现得好像这很容易似的。她父亲总是知道怎么逗她开心。要是他能早点回家就好了。$B$B$N，我很不想麻烦你，但你能去看看他为什么耽搁了这么久吗？他早就出发了，按理说现在应该已经回来了。艾玛一看到他就会高兴得手舞足蹈。$B$B你应该能在爆破引线港找到他——他最近似乎经常去那里。你一看到我的格雷就会认出他的。他就像阳光一样耀眼。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95984,'zhCN','陆行鸟之歌','将完整的陆行鸟喙交给泰拉尔之望的守望者科尼利厄斯。','这些抓痕是狮子留下的。看这深度和间距，这畜生体型庞大得惊人，绝对是附近狮群的头领。$B$B如果有一只食人狮在我的防区里游荡的谣言传开，德玛尔肯定会大发雷霆。幸运的是，我有个计划。$B$B我可以做一个模仿受伤陆行鸟叫声的哨子。我们可以用它把那头野兽引出来。我只需要一个陆行鸟的喙，就能让它发出正确的声音。平原上到处都是陆行鸟。给我弄个喙来，动作快点！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95988,'zhCN','顺滑入喉','为爆破引线港的旅店老板吉兹普林克收集3份海蟹唾液、新鲜的鱼饵、地精去污剂和过期的毒药。','跟格雷谈过了？那家伙简直就是个笑话。他现在最不需要的就是你再给他弄一杯酒。这里是旅店，不是酒馆。他该庆幸我还没把他扔出去。$B$B你想带他走，请便。不过我觉得他现在这副德行哪儿也去不了。除非来点地精的“提神饮料”。$B$B趁我给你这位小兄弟调制“饮料”的时候，你可以照着这张单子去给我弄点材料来。等他喝了我的特制鸡尾酒，我们再看看他是不是还想喝酒。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95991,'zhCN','通缉：幽魂之颚','将幽魂之颚的牙齿交给法霍德要塞的惠特利。','在河林里运送马匹本来就够危险的了，现在还传出有什么神秘的幽灵鳄鱼在吞食我宝贝小马驹的谣言！他们说这只鳄鱼至少有普通鳄鱼的三倍大。而且凶残两倍！$B$B我可不是个赌徒。在有人把这只一无是处的怪物干掉之前，我绝不会拿我的马去冒险。如果有人在河边发现了这个祸害，把它的牙齿给我带回来，这样我就知道路上安全了。在那之前，我哪儿也不去！$B$B—— 惠特利',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95999,'zhCN','通缉：焚化者加因姆','把焚化者加因姆的断裂法杖交给湖畔镇的所罗门镇长。','通缉！焚化者加因姆，入侵撕裂者山谷的兽人头目。据称已经和石堡要塞的黑石氏族结成了同一阵线。$B$B千万当心焚化者加因姆。他和他手下的暗影施法者都极其危险。只要哪位勇士能把焚化者加因姆已死的确凿证据交给所罗门镇长，重重有赏。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96009,'zhCN','高风险','在特纳的伐木场收集10捆木材，交给法霍德要塞的伯特兰·铁眉。','人类的干劲总是让我惊叹不已。他们看到一个到处都是兽人和邪教徒的荒凉战区，居然觉得这是个安营扎寨的绝佳地点！真是不可思议。$B$B不过，我的工作不是告诉他们该在哪儿建，而是教他们怎么建。如果我们想把这座要塞建得像他们说的那么宏伟，我们就需要大量的木材。$B$B由于道路变得越来越危险，我们从西北边伐木场运来的木材已经慢得像蜗牛爬了。你能不能帮我们一把，去弄些木材捆回来？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96031,'zhCN','露营基础：制皮','展示出你对专业技能的精通后，前往铁炉堡寻找格雷塔，学习如何制作与你专业相符的露营物品。','你成了一名制皮师。这是个好选择，$C。我想我认识某个人，可以教你如何为自己制作一顶帐篷，让你在炎夏保持凉爽，在雨天保持干爽。$B$B只要有一顶好帐篷遮风挡雨，你就能获得充分的休息，从而在旅途中保持敏锐。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96044,'zhCN','露营基础：锻造','展示出你对专业技能的精通后，前往卡拉诺斯寻找托格努斯·燧火，学习如何制作与你专业相符的露营物品。','所以，你成为了一名铁匠。如果你想确保武器的刀刃永远锋利，这绝对是个好选择。$B$B我想我认识某个人，可以教你如何制作磨刀石。在营地里摆上这个，周围所有的战士和潜行者都会排着队来打磨武器。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96045,'zhCN','露营基础：炼金术','展示出你对专业技能的精通后，前往铁炉堡寻找沃萨·布拉克塞尔，学习如何制作与你专业相符的露营物品。','既然你已经开始学习炼金术，等你掌握一些基本功后，我还能教你为营地制作法力之井。只要建起一座，治疗者和施法者都会跑来品尝这让人恢复精神的泉水。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96046,'zhCN','露营基础：采矿','展示出你对专业技能的精通后，前往卡拉诺斯寻找亚尔·锤石，学习如何制作与你专业相符的露营物品。','采矿或许不是最光鲜的行当，但绝对是份踏实的工作，也是个值得你钻研的好专业。$B$B我想我认识某个人，可以教你如何为营地制作磁石。只要建好一个，所有舞刀弄剑的家伙都会争相聚集在你的营火旁，汲取它所提供的额外“冲劲”，以此提升战斗力。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96047,'zhCN','露营基础：急救','展示出你对专业技能的精通后，前往卡拉诺斯寻找萨姆诺·普尔，学习如何制作与你专业相符的露营物品。','所以你学习了急救？作为一名$C，这是一项光荣……且务实的追求。$B$B我想我认识某个人，可以教你如何为营地制作急救包。在冒险的世界里，受伤是家常便饭，在营地里提供一些急需的治疗甚至能挽救生命。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96050,'zhCN','露营基础：钓鱼','展示出你对专业技能的精通后，前往丹莫罗的涌冰湖附近寻找帕克斯顿·冈特尔，学习如何制作与你专业相符的露营物品。','你可能觉得没什么，但作为渔夫的技能在营地里其实能派上大用场。$B$B我想我认识某个人，可以教你如何为营地制作鱼缸。你可以用这个小玩意为你自己和冒险者同伴带来一些乐趣。一个快乐的冒险者才是强大的冒险者，我相信这能在你的战斗能力上体现出来。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96055,'zhCN','露营基础：草药学','展示出你对专业技能的精通后，前往铁炉堡寻找雷纳·石枝，学习如何制作与你专业相符的露营物品。','看来你已经在草药学方面积攒了一些经验。要知道，采花可不仅仅是为了消遣。它很有用……而且有利可图。$B$B我想我认识某个人，可以教你如何为营地制作熏香蜡烛。高昂的士气是让治疗者和施法者保持战斗力的关键因素，而熏香蜡烛带来的提升一定会受到施法者们的欢迎。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96056,'zhCN','露营基础：剥皮','展示出你对专业技能的精通后，前往铁炉堡寻找伍特，学习如何制作与你专业相符的露营物品。','能够熟练地从野兽尸体上剥取皮毛，是冒险者最宝贵的技能之一。$B$B我想我认识某个人，可以教你如何为营地制作营地椅子。有时候好好歇口气非常重要，你可以用收集来的皮毛做一把舒适的椅子。片刻的放松能让你保持巅峰状态，并在下次卷入激战时打出致命一击。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96057,'zhCN','露营基础：裁缝','展示出你对专业技能的精通后，前往铁炉堡寻找阿斯拉·瑞克斯，学习如何制作与你专业相符的露营物品。','裁缝是一门极其强大且值得投入的商业技能，我相信它一定会对你大有裨益。$B$B我认识某个人，只要你的技能达标，他就能教你如何为营地制作阵营旗帜。鼓舞和士气是战场制胜的关键，而一面振奋人心的旗帜能在很大程度上让你保持斗志。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96058,'zhCN','露营基础：工程学','展示出你对专业技能的精通后，前往卡拉诺斯寻找布隆克，学习如何制作与你专业相符的露营物品。','像你这样的工程师总能捣鼓出各种零件、机器人和炸弹，既找了乐子又赚了金币。$B$B我想我认识某个人，可以教你如何为营地制作一个试剂机器人。这种实用的自动机器人能帮你保持充足的补给，这样你和盟友就永远不必担心耗尽施法所需的材料了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96059,'zhCN','露营基础：附魔','展示出你对专业技能的精通后，前往铁炉堡寻找索恩斯·火石，学习如何制作与你专业相符的露营物品。','既然你已经踏上附魔之路，等你熟悉基本功后，我想我可以教你为营地制作一把附魔的鲁特琴。$B$B休息时找点消遣非常重要，而这点魔法能帮你养足精神，以便再次踏上尘土飞扬的旅途，应对各种挑战。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96063,'zhCN','气态黄金','为斯里波·菲兹斯波特收集8个沼泽气体瓶。','未来的燃料不是煤炭，也不是石油，而是气体，宝贝！西南边那些沼泽池子里成吨成吨地喷出这种气体，而我刚好发明了一种能利用它的装置——一种以这种气体为动力的新型发动机。不过，收集这种气体可是个大麻烦。$B$B如果你有兴趣为科学和工业的未来做点微薄的贡献，何不帮我收集一些气体呢？你可以看到它从水面附近的通风口冒出来。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96081,'zhCN','伤口包扎','为法霍德要塞的洛利修士收集20块魔纹布。','如果说一支战斗部队永远缺什么，那就是绷带。不幸的是，法霍德没有可靠的布料生产途径。因此，我们只能依赖从地精那里进口，或者运气好的话，从兽人那里抢回来一些。$B$B目前，我们优质布料的库存已经见底了。用不了多久，我就得开始用旧衬衫做绷带了。如果你有能力帮助我们，你将拯救许多生命。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96107,'zhCN','制作箭羽的羽毛','将6根平原秃鹰羽毛交给洛格玛的涅扎·血吻。','一个猎人一生中消耗的箭矢，比天上的星星还要多。$B$B我个人更喜欢亲手制作箭矢。我只相信自己的手艺。$B$B附近秃鹫粗糙的羽毛是制作箭羽的绝佳材料。你愿意帮我收集一些吗？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96125,'zhCN','需要换班','在博尔德罗克的食人魔中寻找邓斯顿·威利斯。','既然狮皮已经收集完毕，兽人偷猎者也被清理干净了，我终于可以喘口气了。$B$B至少，如果那个本该来接替我站岗的家伙没有失踪的话，我本来是可以这么说的。$B$B邓斯顿·威利斯，那个自吹自擂的“非凡探险家”，几天前跑去北边的食人魔营地调查了。他走前还信誓旦旦地说，一回来就接我的班。$B$B去找找他。如果他还喘气儿，就把他全须全尾地带回来。如果他已经被挂在食人魔的肉钩上了，那就给我带点信物回来，好让德玛尔赶紧派个活人来换我的班。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96130,'zhCN','查库亚克','击败查库亚克，并带回她的毛皮。','在附近丘陵地带游荡的草原狼里，有一头生性极度好斗。我们都叫她查库亚克。如今她已然成了过路旅人的心头大患。$B$B她经常潜伏在石牛湖西侧的林地中，在树丛间来回穿梭。$B$B铲除这个隐患，并把她的毛皮带给我，我必会在酋长面前为你美言。当心，她极其危险！你或许会在外面遇到其他寻觅她踪迹的猎人，结伴同行是个不错的选择。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96137,'zhCN','艾拉的匕首','击败10只黑色破坏者幼崽和7只黑色破坏者，然后返回夜色镇的希拉·沃宁迪身边了解更多信息。','这是一把小巧的匕首，它的主人是一位自封为游侠的名叫艾拉的女子。她生前一直致力于清剿森林里的凶禽猛兽，好让路过的旅人平安无事。$B$B既然艾拉的灵魂还在树林里徘徊，想必她最大的遗憾，就是没能除尽那些至今还在四处害人的座狼吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96139,'zhCN','瓦罗家族','在乌鸦岭搜索任何有价值的东西，然后返回夜色镇的希拉·沃宁迪身边。','越是在这样的黑暗岁月里，我们越要铭记自己的英雄，也不能忘记敌人。要是没有善良的阿尔泰娅女士，要是没有那些长眠在乌鸦岭的壮士，夜色镇早就不复存在了。$B$B你翻阅过关于乌鸦岭的书籍吗？肯定没有。那段历史，连同镇上的人，早就消失得一干二净了。我这儿的藏书虽然多，但也找不到几本有用的。$B$B如果你碰巧找到了什么，哪怕是只言片语，也请带给我。那些人不能就这么被遗忘了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96204,'zhCN','塑风者之怒','陪同卢米娜·风歌，助她逃离芬里斯城堡。','既然我已经重获自由，定要让这些卑劣的畜生后悔惹上一位塑风者。$B$B我们赶紧离开这儿，$C。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96222,'zhCN','赫鲁萨可汗','把玛洛迪钥匙碎片带给凄凉之地的乌玛拉克。','这片土地上到处都在打仗，唯独玛洛迪半人马在长矛谷里逍遥自在，没人敢去惹。我真怕其他氏族再这么不管不问，这帮家伙迟早会得寸进尺，搞出更大的乱子。$B$B赫鲁萨可汗手里攥着一块玛洛迪钥匙碎片，我打算拿它当谈判的筹码。你去那边的半人马身上找个战号吹口，然后在最高那座山峰上，吹响号角向他发起挑战。$B$B拿到钥匙就回来找我，我有笔买卖要跟你谈谈。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96241,'zhCN','谈谈毒素吧，伙计','使用毒素提取器，从暮升高地那些被啃咬的尸体上采集5份暮升毒液样本。','暮升高地那边出了点怪事。老马祖康听说那儿到处都爬满了恶心的新野兽。$B$B有人说那些毛骨悚然的爬虫带有某种奇特的剧毒，这可引起了我的好奇。带上我的提取器。去那儿找找尸体，把毒液抽出来。帮我这个忙，就算我欠你个人情，伙计。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96243,'zhCN','大地的召唤','在丹莫罗找到提欧·暴风之锤。','勇敢的萨满祭司，你早该倾听大地的声音了。元素已在你的肌肤下躁动。只要你与岩石对话，大地本身就会在你的脚下，乃至你的灵魂中稳稳扎根。$B$B去寒脊山谷寻找提欧·暴风之锤。去安威玛尔找他，那是一座用战锤、烈火与意志锻造的据点。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96259,'zhCN','保卫亡者','消灭10只暮升幼蛛和5只暮升兵蛛。','在营地西北方的暮升高地，有一处古老的牛头人墓地。最近那里遭到了一群极其凶残的蜘蛛侵扰。它们不仅威胁着莫高雷的人民，还在破坏牛头人心中的圣地。$B$B若你能前往暮升高地终结这场灾祸，肯定是大功一件。事成之后，先祖们也定会向你展颜微笑。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96260,'zhCN','坚逾精钢','从暮升织网者身上收集3缕结晶丝。','你听说暮升高地墓地的事了吗？巨型蜘蛛正在那里疯狂滋生。传闻其毒液之强，甚至足以唤醒死者。依我看，这真是个大麻烦。$B$B派去调查的一名斥候半死不活地逃了回来，浑身裹满了极其坚韧的结晶蛛丝。我尽力采集了一些。若是能获得更多蛛丝样本作进一步研究，那就太好了。$B$B多带些这种结晶丝给我，我必有重谢。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96261,'zhCN','巢母','在暮升高地杀死蛛母瓦尔拉克斯。','暮升高地目前的虫害也是如此。一只强大的母蛛往往会导致整个攻击性蛛群迅速扩张。$B$B想要永远驱逐这些野兽，就必须找到其始祖并除掉她。前往暮升高地，找到那里的蛛母并将其消灭。我建议你带上盟友，做好万全准备。它们似乎绝非普通的蜘蛛。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96264,'zhCN','元素救兵','在剃刀沼泽击败卡尔加·刺肋，收集有关野猪人计划的情报。','这么说你现在是个了不得的萨满祭司了，嗯？已经掌控元素，想让它们派上大用场了？我这正好有件事交给你。$B$B想赢得元素的尊重，就必须偿还欠它们的债。它们帮你，你也得帮它们。眼下它们急需援助，去对付那些滥用其力量的家伙。$B$B大地在轰鸣，$N。它诉说野猪人正在集结，企图举行某种拥有可怕力量的仪式。我们必须去调查他们盘踞的剃刀沼泽，看看他们到底在搞什么名堂。把你的发现都带回来给我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (96339,'zhCN','传承奖励：仿制的铁炉堡火枪',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96390,'zhCN','防患于未然','在丹莫罗消灭10名黑铁间谍。','黑铁间谍已经渗透进了丹莫罗。我不知道他们有何企图，但这事儿必须防患于未然，绝不能听之任之。$B$B往东去铁环营地，把在那儿发现的黑铁间谍统统干掉。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96392,'zhCN','法森的守望','与大地先知法森交谈，请他借助视界术帮你探明黑铁矮人的威胁。','你好，朋友。我叫大地先知法森，从鹰巢山来丹莫罗拜访。在旅途中，我发现咱们遇上了点……嗯，黑铁矮人的小麻烦。$B$B如果你有空，我可以给你演示一下。我懂点魔法，应该能派上用场。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96393,'zhCN','旧铁炉堡入侵','深入旧铁炉堡底层的领主大厅，拿回杜根·挽锤的徽记。','召集几位盟友，深入旧铁炉堡地下的洞穴。穿过领主大厅，深入底层宝库。$B$B我的黑铁语不太灵光了，但勉强能认出一个名字——杜根·挽锤。他多半就是指挥官。拿到他的徽记，献给国王麦格尼·铜须。$B$B哦，见到国王时，别忘了带句话：他的老朋友法森向他致以问候！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96394,'zhCN','永不安息的亡者','消灭15个被激怒的幽灵、10个被折磨的幽魂，让安威玛尔的灵魂得到安息。','有东西惊扰了领主大厅地下的陵墓，宝库深处传出了诡异的响声。亡魂的睡眠向来很浅，不管下面发生了什么，似乎都惊动了他们。$B$B下去看看能不能帮我们摆平这事。如果发现有亡者苏醒——那就让他们重新安息吧！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96395,'zhCN','远古的宿怨','让法德林·安威玛尔的灵魂安息，然后返回领主大厅，向鬼魅随从复命。','领主……我那强大的……领主……他……需要……安息。$B$B求求你……帮助他……帮他……安息……$B$B被……古老的……怨恨……吞噬……无法……安息……',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96403,'zhCN','重要的传家宝','从领主大厅收集8件矮人传家宝。','喂，那位冒险者……我真的需要你帮个忙。$B$B我本来在宝库里潜行——呃，我是说“巡逻”，结果一群黑铁矮人开着钻探机从地下冒了出来！天知道他们来干嘛，但那下面可全是无价的赃物——不，我是说，极其重要的“文化传家宝”！请帮我把你能找到的这类遗物全带回来。$B$B我向你保证，所有找回来的东西都会登记造册，并物归原主，放回它们该在的位置。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96408,'zhCN','丹莫罗的访客','调查俯瞰古博拉采掘场的营地。','昨晚，我们的巡山人发现东边山坡上升起了一丛篝火。位置挺高，刚好能俯瞰古博拉采掘场。$B$B估计没什么大碍，但我还是想请你去探探那个营地。如果是自己人，自然皆大欢喜。如果来者不善……哼，你知道该怎么做。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96606,'zhCN','广阔天地','在莉瑞娜的基础营火旁坐下休息，直到获得“强化休息”增益。','你好，$C。我看得出你浑身上下透着股冒险者的气质。这很好。这世界正需要更多像我们这般渴求财富与荣耀的不羁灵魂。$B$B想吃这碗饭，你得学会怎么在荒野中求生。不知道你的野外生存本事如何，但只要你肯学，我也许能教你两手。$B$B在营火旁找个位置坐下，放松点。我会一步步教你的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96608,'zhCN','广阔天地','在埃里克的基础营火旁坐下休息，直到获得“强化休息”增益。','你好，$C。我看得出你浑身上下透着股冒险者的气质。这很好。这世界正需要更多像我们这般渴求财富与荣耀的不羁灵魂。$B$B想吃这碗饭，你得学会怎么在荒野中求生。不知道你的野外生存本事如何，但只要你肯学，我也许能教你两手。$B$B在营火旁找个位置坐下，放松点。我会一步步教你的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96628,'zhCN','冒险者','将补给包交给卡拉诺斯附近的埃里克·明锤。','等等，$N。在你勇闯那条隧道前，我还有件事拜托你。$B$B我的巡山人报告说卡拉诺斯城外出现了一名冒险者。你能把这些补给交给他吗？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96629,'zhCN','露营基础：烹饪','与卡拉诺斯的格雷姆罗克·匹斯诺尔交谈，学习烹饪手艺。','所以你想多学点露营的门道，对吧？好样的，$C。对任何冒险者来说，这第一步就是学着当个厨子，弄懂怎么生起营火。$B$B烹饪可不光是为了填饱肚子，它更是你扎营的根基。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96630,'zhCN','冒险者','将日记带给多兰纳尔附近的莉瑞娜·暮刃。','<这本日记平平无奇，记录了一个无名之辈的生活与冒险。$B$B里面有不少关于露营的记载。看起来……相当有趣。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96634,'zhCN','露营基础：烹饪','在多兰纳尔与扎瑞恩交谈，学习烹饪手艺。','所以你想多学点露营的门道，对吧？好样的，$C。对任何冒险者来说，这第一步就是学着当个厨子，弄懂怎么生起营火。$B$B烹饪可不光是为了填饱肚子，它更是你扎营的根基。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96652,'zhCN','冒险者','将日记交给剃刀岭附近的布拉克。','<这本日记平平无奇，记录了一个无名之辈的生活与冒险。$B$B里面有不少关于露营的记载。看起来……相当有趣。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96655,'zhCN','露营基础：烹饪','与剃刀岭的厨师托尔卡交谈，学习烹饪手艺。','所以你想多学点露营的门道，对吧？好样的，$C。对任何冒险者来说，这第一步就是学着当个厨子，弄懂怎么生起营火。$B$B烹饪可不光是为了填饱肚子，它更是你扎营的根基。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96661,'zhCN','露营基础：烹饪','前往血蹄村与派尔·沉默行者交谈，学习烹饪手艺。','所以你想多学点露营的门道，对吧？好样的，$C。对任何冒险者来说，这第一步就是学着当个厨子，弄懂怎么生起营火。$B$B烹饪可不光是为了填饱肚子，它更是你扎营的根基。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96779,'zhCN','破坏辛迪加','潜入希尔斯布莱德丘陵的敦霍尔德城堡，找到并杀死托马斯领主，然后回去向麦洛克斯复命。','有时候，$R，只要在精准的位置划上一刀，就能让敌人当场毙命。对付一个组织，往往也是如此。$B$B我们的探员在辛迪加的队伍中锁定了一个关键目标，一个名叫托马斯领主的人。$B$B他在希尔斯布莱德丘陵的敦霍尔德城堡中扮演着举足轻重的角色。如果你想为拉文霍德效力，就去敦霍尔德除掉他。越快越好，而且要不留痕迹。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96821,'zhCN','拔腿就跑','在杜隆塔尔南部消灭6只脊影爬行者和6只脊影潜伏者，然后向剃刀岭的加索克报到。','近些日子从剃刀岭过来的旅人越来越少了。那些蝎子本就够烦人的，现在听说又有蜘蛛沿大路筑起了巢。$B$B若你要往北走，顺手在路上解决掉一些蜘蛛吧。然后去通知剃刀岭的人，告诉他们这条路稍微安全些了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96822,'zhCN','为了荣耀！','从提拉加德城堡外围收集袭击者战斧、袭击者之弓与袭击者之盾，交还给剃刀岭的图罗克。','攻打提拉加德城堡时，部落失去了许多英勇的战士。如今人类加固了那片废墟，我们无法收敛遗骸，也就无法妥善纪念他们的牺牲。$B$B去城堡周围的废墟里，搜寻阵亡同袍留下的武器吧。我们会将其陈列在荣耀之地。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96825,'zhCN','这果子会咬人','剃刀岭的厨师托尔卡要你从镇子西边的钢鬃营地收集8个仙人掌果。','我们的猎手和渔夫给部队带回了许多美味的肉食，但甜食却十分罕见。$B$B我见过一种仙人掌，结出的果子长满尖刺，却异常美味。不过它只长在西边的丘陵地带，也就是那些可恶的野猪人扎营的地方。穿过野猪人的营地，给我带些这种果子回来。当心——这些果子可跟野猪人一样扎手！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96873,'zhCN','脖子上的麻烦','森金村的帕祖拉需要你收集3份发光的残渣。发光的残渣可以通过分解回音群岛巨魔掉落的被诅咒的坠饰来获取。','东边的巨魔已屈服于巫医扎拉赞恩。他用各种残忍的魔法控制俘虏的心智，其中最拿手的把戏，就是让他们戴上附有邪恶束缚法术的坠饰。$B$B拿你的附魔技巧练练手，剥除坠饰上的魔法，然后把成果带给我。要是你还珍惜自由，可千万别不小心把它戴到自己脖子上！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96875,'zhCN','雷霆山的野兽','奥格瑞玛的卡玛瑞要你从雷霆山的野兽身上收集5张粗糙蜥蜴皮，以及2张熟化轻毛皮。','奥格瑞玛在不断扩建，$C。当苦工们需要兽皮来铺设新建筑的墙壁与屋顶时，就会来找我！$B$B雷霆山蜥蜴的皮通常太厚，不适合制作护甲，却是极好的建筑材料。带些它们的皮来，再带几张轻巧些的熟化轻毛皮。让我见识下你的制皮手艺吧！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96895,'zhCN','银色特使','在幽暗城入口附近找到银色黎明成员。','不知你听说没有，两名银色黎明的使者刚从这经过。我倒不反感银色黎明，却也不喜欢他们在无人监管的情况下，在提瑞斯法四处窥探。两人都是被遗忘者……但这丝毫未能减轻我的紧张。$B$B其中一人刚路过这儿，往东南方向去了。那边的城郊正好有一群天灾教徒在鬼祟活动。如果那两人听闻此事，无疑会引起他们的注意。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96896,'zhCN','正义事业','观察丹妮莎·莫尔与尊敬的莱尼德·巴萨罗梅之间的谈话。','当纳克萨玛斯大军压境时，丹妮莎和我曾并肩死战天灾，保卫幽暗城。那一战，我们折损了太多挚友，其中就包括加瑞克·班达里安——这座要塞正是以这位英雄的名字命名的。$B$B他或许是第一个重新掌握圣光之力、重拾圣骑士身份的被遗忘者。看到他的遗志由丹妮莎和她的队伍在这里薪火相传，我也算是老怀安慰了。$B$B要是其他同胞也能明白这个道理，该有多好……',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96984,'zhCN','动乱之源','在达拉然城，为塔伦米尔的大法师沃迪恩·伍德格莱尔收集奥术微粒。','你也许并不在乎我们的死活，但我绝不会拒绝送上门来的帮手。若是达拉然倾覆，所有的一切都会跟着遭殃——包括你们的幽暗城。$B$B所以，你的主子想横插一脚？行。我会在你的钥匙上注入法力，让你畅通无阻地穿过我的结界进城。进城之后，到紫罗兰城堡来找我，一切都是从那里开始的。眼下局势动荡，肯瑞托自顾不暇，根本没空搭理你。$B$B你想搜刮什么悉听尊便，但无论如何，当务之急是阻止这场浩劫。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96986,'zhCN','墓穴骑士','在达拉然城击败墓穴骑士阿特雷克斯，向塔伦米尔的梅里萨拉复命。','在北边那座法师之城的暗处，藏着一个我们同族的叛徒。一个天赋异禀得令人作呕的通灵师。他居然在肯瑞托的眼皮底下，拉起了一支亡灵大军。$B$B我才不在乎那座法师之城的死活，$N，但这个墓穴骑士的存在，简直是在把我们被遗忘者的信仰踩在脚下践踏。去解决他。让他知道，没有任何人能逃出黑暗女王的掌心。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96987,'zhCN','投机教育','在达拉然城，为下水道入口附近的雷克希·铜抓取回《达拉然的建立》。','哟，这不是志同道合的生意人嘛。在这节骨眼上潜入达拉然？啧啧。$B$B你这$R正对我胃口！$B$B趁着咱们的法师朋友忙得焦头烂额，咱们正好可以顺手牵羊，弄点“无主”的宝贝。他们有整栋大楼塞满了那些花里胡哨的奥术秘籍。你要是能给我顺一本出来，我绝对能卖出个天价。到时候赚了钱，咱们五五分账。$B$B喂喂，别这么看着我。你来这儿总不会是为了观光吧？到底干不干，给句痛快话！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96988,'zhCN','力量之源','在达拉然城，为幽暗城的马丁·费尔本收集6个开裂的哨兵核心。','达拉然正被他们自己的构造体围攻，这绝对是个绝佳的机会，我们可以去……借几个样本回来。$B$B试想一下，一支由奥术驱动的憎恶大军。到时候，黑暗女王就算再挑剔，也得承认我在炼金术上的造诣。说不定还会提拔我当皇家药剂师学会的主管呢？$B$B进城去，找到那些构造体的核心。它们肯定不会乖乖交出来，所以，该下狠手时千万别客气。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96989,'zhCN','你的第一只迅猛龙坐骑','仔细端详那些可供骑乘的迅猛龙，挑选你的第一只坐骑。','嘿，伙计！看来今天对你是个大日子。你觉得自己准备好驾驭这些凶猛的猛兽了，是吗？$B$B多数人都低估了它们的智慧与凶残。一旦结下羁绊，你绝找不到比它们更好、更快也更致命的伙伴。$B$B因此你要做出一个重要抉择。你和你的迅猛龙将一同游历世界，而它也需要反过来选中你。$B$B去看看吧，选定后再回来找我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96994,'zhCN','你的第一只座狼坐骑','仔细端详那些可供骑乘的座狼，挑选你的第一只坐骑。','Lok\'tar，$C。来与你的第一头狼结契？很好。$B$B没有任何羁绊能胜过兽人与狼。它们绝非寻常坐骑，而是一生的同伴与挚友。$B$B我们的纽带绝非出于虚荣。不，每一名兽人和每一头狼之间，都会结下超越单纯买卖的特殊羁绊。$B$B它们会选中你，正如你会选中它们。等你见到它们就会明白的。$B$B去找出那头与你心意相通的狼，有了答案后再回来找我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96996,'zhCN','你的第一只疾风陆行鸟坐骑','仔细端详那些可供骑乘的陆行鸟，挑选你的第一只坐骑。','既然训练已经结业，看来风儿也期盼你与第一只陆行鸟结下羁绊。$B$B这疾风陆行鸟，我们的祖辈世代骑乘。别看它们身姿轻盈纤细，性情却极为猛烈，更是无比可靠的坐骑。$B$B往后你们就要结伴闯荡世界了，这可是个关键抉择。莫要害怕，无论作何选择，都将是正确的指引。$B$B去仔细端详那些陆行鸟吧，选好了再来找我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96997,'zhCN','生当做战马，死亦为骐骥','仔细端详那些可供骑乘的亡灵战马，挑选你的第一只坐骑。','你好，$C。我想我猜得到你今日为何光临我的马厩。$B$B若是在寻找坐骑，那你来对地方了。不过请当心，驾驭亡灵战马绝非胆小之辈所能胜任。$B$B因此你面临着一个重要的选择。无论吉凶，你都将与你的亡灵战马结伴游历世界。别怕，无论作何选择都是对的。$B$B去看看那些亡灵马匹，选定后再回来找我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97005,'zhCN','噬灭者乔拉鲁克','将乔拉鲁克的头颅交给贫瘠之地的贝恩哈姆。','传闻在西北方荆棘岭高地的洞穴里盘踞着一头憎恶巨兽。钢鬃部族称其为乔拉鲁克，即“噬灭者”。见过它的人说它体型庞大，甚至能将一名兽人活吞。$B$B鲜少有人相信这类传说，但我信……因为我曾亲自与类似的怪物交过手。以那些丧生于此的弟兄们的荣誉起誓，这头野兽必须死。$B$B召集强大的盟友，找出乔拉鲁克的巢穴。除掉这只憎恶，并把它的头颅带给我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97220,'zhCN','菲尔莫尔的委托','将门楼的货物送到贸易区提亚斯奶酪店的仓库入口处。','这周码头天天都缺人手。$B$B你要不要搭把手，帮我们赶赶货运的进度？$B$B把这包东西送到门楼仓库的入口。地方就在贸易区提亚斯奶酪店二楼。老板娘伊莱恩熟门熟路了。门楼那边经常私下进点货，好给卫兵的军官们搞点仪式上的小惊喜。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97222,'zhCN','门楼的物资','将门楼货物搬上提亚斯奶酪店的二楼，并放在门外。','是啊，就差这一层楼梯了，既然是举手之劳，那你自己把货送上门肯定没问题吧！$B$B提亚斯奶酪店和门楼不是一家的，也不归他们管库存，但我们都在同一层楼。$B$B把箱子放在他们仓库门外就行——卫兵会定期派人来收。他们看到包裹送到了，换岗的时候自然会顺手搬进去。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97223,'zhCN','血爪族母','把血爪族母的蛋交给森金村的克萨尔迪。','你眼前的这些迅猛龙全是由我亲手训练的。它们来自卡利姆多各地，但最优秀的一批全都出自近海岛屿上的血爪迅猛龙。$B$B其中有一头血爪族母尤为凶残，已经夺走了我们村里许多人的性命。继续放任它在边境游荡实在太危险了。如果你能将其击杀，请带回它的蛋，这样我们就能把幼崽培养成盟友，而不是敌人。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97225,'zhCN','被遗忘的洛阿神像','从回音群岛收集8尊被遗忘的洛阿神像，将它们交给森金村的加德林大师。','当初我们逃离扎拉赞恩及其党羽占据的群岛时，遗落了许多珍贵的神像。它们能协助我们与所崇拜的神灵——洛阿进行沟通。这对整个部族至关重要。$B$B扎拉赞恩的追随者对洛阿毫无敬意，将这些神像散落在了最大的那座岛屿各处。$B$B如果我们不能收回这些神像，这种举动必将引起洛阿的注意，而冒犯神灵是一件极其严重的事情。$B$B去吧，尽可能多地找到洛阿神像，然后把它们交给我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97234,'zhCN','阅览室','将打包好的阅读材料送到暴风城图书馆。','你是来探讨那些古老传说的深层含义的吗？不是？$B$B那行吧，等你随便逛完了，能不能帮我把这个送到图书馆去？我们要把一些冷门的书卷，换成更现代的作品。我这儿有份书单，相信图书管理员绝对能在我们的合作权限内把书弄来。$B$B只要你肯帮忙，俱乐部里的茶水点心随你享用。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97237,'zhCN','书架寻书','在图书馆的各处找到所需的阅读材料，然后带给暴风城花园区的罗伊·勒维尔斯。','我查过库存了，勒维尔斯先生要的书现在全都有。$B$B不过，你得自己去书架上找。保持警觉可是我们图书管理员的职责，所以我得接着去盯账本了。$B$B你替罗伊把书送回去，责任算不到你头上。就跟他便条里写的一样，你只管当好读书会的跑腿信使，还书的担子由他们扛。$B$B祝你今天过得愉快，$N。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97243,'zhCN','火焰的召唤','把眠炎火炬交给阵风浆果低地烈焰神殿里的奥拉里安·迅燃。','尽管我们身处天空之墙，但这里依然是元素位面。只要愿意倾听，四大元素的灵魂都会向我们诉说。我们塑风者中有一位对火焰元素有着特殊的共鸣。他是一位名叫奥拉里安·迅燃的申多雷。$B$B把这个带到阵风浆果低地的烈焰神殿交给他。你会发现那里隐藏在岛屿的边缘，就在瓦拉纳尔西边。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97244,'zhCN','火焰的召唤','在阵风浆果低地消灭天空祭司法拉迪尔，并收集法拉迪尔的徽记。','有一位名叫法拉迪尔的奥拉凯斯天空祭司。他曾是一名烈焰呼唤者，也是一名坚定的塑风者。和许多奥拉凯斯信徒一样，他为了力量出卖了忠诚，如今双手沾满了昔日兄弟姐妹的鲜血。$B$B穿过瓦拉纳尔向东北走，在阿基尔神殿正南方的农场里就能找到他。去杀了那个叛徒，把他的徽记带给我。这是一项残酷的任务，但对于我们要进行的仪式而言必不可少。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97245,'zhCN','火焰的召唤','在申达尔高地找到库拉玛的家，并在战斗中击败这个灵魂。获胜后，把库拉玛的面具交给阵风浆果低地的奥拉里安·迅燃。','申达尔高地的居民谈起过一个名叫库拉玛的古老森林精怪。他们说它住在高地锚点水晶塔附近，一座山顶上的扭曲树桩里。$B$B去高地找到这个树桩。用拳头敲击树皮，库拉玛就会现身。在战斗中击败这个灵魂，把它的木制面具带给我。$B$B不过要提醒你，这个实体对你的大部分魔法都具有极强的抵抗力。只有烈焰的碰触才能将其击倒。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97257,'zhCN','火焰的召唤','在祭祀火盆旁等待奥拉里安开始仪式，并遵循他的指示。$B$B你必须在计时结束前将永恒之火送到瓦拉纳尔。','现在我们将开始仪式。$B$B我会把材料放到祭坛上，召唤火焰之灵。如果它们接受了供品，就会现身并点燃永恒烈焰。然后你需要举起火炬，捕获那团火焰。$B$B将点燃的火炬带到瓦拉纳尔，放入永恒烈焰火盆中。你必须动作快点，因为火焰之地的烈焰在天空之墙这里很容易消散。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97263,'zhCN','你的包裹到了','送达埃尔德伦被错放的包裹。','<邮箱旁放着几个被放错位置的包裹。你注意到其中一个标记着从鹰巢山寄往铁炉堡的埃尔德伦·风暴破坏者。上面还标有“紧急”字样。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97265,'zhCN','痛恨怨怒','在凄凉之地的萨格隆击败各种怨怒萨特，然后返回葬影村的阿卡莱身边。','你和萨特做过交易吗，伙计？$B$B我做过。面临那样的诱惑，又有谁能抗拒得了？力量的承诺、远超寻常典籍的深奥知识……更别提还有一个热情而迷人的仆从时刻相伴。我还能再奢求什么呢？$B$B呸，他们当然永远都不可能向凡人屈膝。我一无所有的时候选择与他们交易，结果被他们抛弃时，我失去的反而更多了。$B$B现在，我要复仇。我要向怨怒萨特复仇。去突袭他们位于东北方的营地！用他们肮脏的污血染红那片土地。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97275,'zhCN','伍特急什么','把耶尔玛克的药水交给伍特。','伍特是个天才，这一点毋庸置疑。但他的经验、智慧，以及搅拌药剂所积累的时日都还远远不够，根本不懂得尊重炼金的严谨流程。$B$B他正在挥霍我们手头所有最稀有、最奇特的材料，却从未停下脚步，去好好练习和磨炼自己的基本功。$B$B把这瓶用速效滋补法酿制的药水交给他。等他明白本地药方和细致入微的手法才是最先需要掌握的真本事时，他就会重新审视自己现在所做的一切。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97277,'zhCN','格伦德与戈兹温','去西北面的山丘找到格伦德和戈兹温的营地，取回戈兹温的机械日志，并消灭雪豹潜伏者。','喂，我当时正转过身准备烤野猪，就听到老伙计戈兹温在拼命尖叫！$B$B等我转过头时，只看到凶狠的尖牙和一团模糊的影子。那爪子真大！一头雪豹正把它的侏儒猎物拖走。我抓起猎枪，朝那畜生的头顶开了一枪。它丢下他逃跑了。$B$B幸运的是，除了给老戈兹留下几道深深的抓痕外，它没造成更大的伤害。$B$B回西北面山丘的营地去，取回戈兹温的机械日志。如果你看到那头雪豹，顺手也把它杀了！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97279,'zhCN','遗失的武器','收集6件被遗弃的训练武器，然后拿回去交给兽穴的克赞·荆条。','随着像你这样的新兵不断涌入，我们的武器补给变得越来越吃紧。武器匠克赞手头的训练武器马上就要见底了，而我也想看看你到底有几分本事，好盘算一下自己手底下能调遣怎样的人手。你的运气很不错，我正好有个一举两得的妙计。$B$B你在拿野猪练手的时候，顺便去找回六件被遗弃的训练武器。那些没能熬过训练的新兵把它们随便丢在了地上。收集齐之后，把武器交给我身后兽穴里的武器匠克赞。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97282,'zhCN','风暴潜能','把5个带电的雷霆蜥蜴器官带给枯水谷附近的雷兹拉克。','“雷兹拉克，当机会来敲门时，你必须时刻准备好抓住它。”这是加兹鲁维教给我的另一句金玉良言，这也正是我打算做的。$B$B这颗宝珠似乎没有损坏，看起来只是没能量了。但我有个主意，可以给它强力充能，让它恢复全部力量！$B$B西边的峡谷里有一群雷霆蜥蜴。它们的器官能储存强电荷，用来做这个再合适不过了。$B$B去收集一些，然后带回来给我！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97284,'zhCN','瓦拉里尔的复仇','前往凄凉之地的雷斧堡垒，消灭那里的火刃氏族兽人，然后回尼耶尔前哨站向瓦拉里尔·屠魔者复命。','如果玛雷姆还活着，那么火刃氏族的兽人想必早就料到，很快就会有人来找她。他们肯定已经做足了战斗准备。$B$B我希望你能保持低调，尽量避开他们的锋芒，但现实更可能是，他们会抓住每一个机会主动找你交手，以刀刃来迎战火刃。$B$B所以我们不妨从一开始就记下你的战果。尽可能多杀一些，我绝对不会亏待你的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (97286,'zhCN','研究特权',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97287,'zhCN','精明的谈判','与达拉然附近的大法师茉德拉的影像对话。','能够成功潜入这座法师之城，你做得确实很好。但我认为，现在是时候采取更……圆滑一些的谈判手段了。$B$B尽管承认这一点令我深感痛苦，但放眼整个艾泽拉斯，再没有哪个地方能拥有如此浩瀚的奥术知识了。即使是我那些才华横溢的研究成果，与肯瑞托多年来积累的古老智慧相比，依然显得黯然失色。我想，我们早就该获准加入这个排外的组织了，难道不是吗？$B$B带上你取得的微粒。为了把它拿回来，他们一定愿意付出任何代价。任何代价。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97289,'zhCN','无尽的折磨','将男爵的头颅带到幽暗城中奥斯玛尔的躯体旁。','拼凑憎恶脑袋不过是我们的日常消遣，但这一颗可大有来头。它生前曾是联盟的一位大元帅，脾气还特别臭，没记错的话名字是奥斯玛尔。黑暗女王可是满怀兴致地亲自送他上了路。$B$B要是这颗脑袋还能开口讲话，肚子里绝对藏着不少天大的秘密。巧了，它确实还能说话！只要我们给它接一副合适的躯体。$B$B去，把它放到隔壁那具现成的躯体旁边。但先别急着缝合。现在还不是时候。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97290,'zhCN','无尽的折磨','将你的发现汇报给幽暗城的大药剂师法拉尼尔。','你这个……怪物……$B$B凭什么……要我帮你……$B$B滚开……',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97292,'zhCN','无尽的折磨','替大药剂师法拉尼尔将嘶嘶血清注入奥斯玛尔躯体上方的仪器中。','我特制了一副美妙的血清，咱们这位新客人肯定会觉得相当……提神醒脑。$B$B拿着这个。灌进他头顶那个正往下滴水的装置里。咱们这就让他好好长长记性，认清死心塌地效忠才是他唯一的活路。$B$B手脚稳当点，别给我洒了。我可没闲钱再雇个新助手。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97530,'zhCN','砂槌欠款','塔纳利斯热砂港的保安主管图拉·比尔吉维兹要你找回一只格外闪亮的手镯，它遗失在砂槌食人魔营地附近。','一支商队在沙漠里拐错了弯，遭到砂槌食人魔袭击。他们能活着逃出来，全靠把一些货物扔下车，分散那些蛮子的注意力。$B$B这个商人肯定认识操办船运和飞艇的大人物，因为他们现在居然要我去捡回丢失的东西。$B$B我得留在这里干活。但如果你揍食人魔时看到一个闪闪发亮的手镯，我会让你觉得这趟很值。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97538,'zhCN','绘画颜料','雷霆崖的塔恩·冰蹄需要30份暗色湖的幽暗草荚。','你好，朋友。我能请你帮个忙吗？我的红色颜料刚好用完了，想找一位蹄子更年轻的人，替我长途跋涉前往石爪山脉。$B$B山间隘口中央有一座巨大的环形湖泊，名叫暗色湖，水中生长着一种独特的植物。那种植物名为幽暗草，豆荚晒干后会变成鲜艳的红色。替我收集一些豆荚，我一定会好好酬谢你的付出。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97539,'zhCN','丝滑缝合','将12份外科蛛丝交给阿拉希高地落锤镇的格里高利·维克托医生。','这座营地已经被听之任之，放任自流了。攻城造成的破坏至今无人修缮，仿佛玩忽职守成了这里的规矩。我绝不允许这种腐败在这里蔓延。医务室归我管，我就得让它正常运转。$B$B我们的物资快见底了。我需要更多设备——得够让工人和守卫们坚持下去才行。$B$B紧急情况下，用扭曲的蜘蛛丝做成野战缝合线，效果奇佳。$B$B$C，去高地里找那些潜伏的蜘蛛，给我弄点蛛丝回来。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97583,'zhCN','扭起来。','购买一些营养丰富的泥浆怪淤泥，回去喂给你结识的那只小软泥怪。如果它显得没精打采，就再陪它跳支舞，重新吸引它的注意力。','<小软泥怪兴高采烈地学着你的舞步扭来扭去，可渐渐地，它似乎有些体力不支了。$B$B它飘到一小滩淤泥上方，将脏水吸进体内，顿时又恢复了几分精神。$B$B看来刚才那支舞把它累得够呛。也许幽暗城的运河附近，会有人兜售这种营养丰富的淤泥？>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97891,'zhCN','争分夺秒送药水','在规定时限内，将不稳定药水交给炼金房的马丁·费尔本医生。','对，就是你！快点，我需要你把这瓶药水送过软泥运河，交给炼金房里的马丁·费尔本医生！$B$B这药水的保质期可是极其有限的。别问我为什么不亲自去，只要我一试着跑起来，我的膝盖就会嘎嘎作响，甚至直接脱臼飞出去。$B$B看来，这显然又是不死之身带来的某种“可爱”副作用了。$B$B哎呀，我们正在浪费时间！快拿着这个，赶紧走！$B$B<奥雷萨多不耐烦地挥手赶你离开。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97894,'zhCN','奥伯丁的生意','去黑海岸的奥伯丁找高尔博德·钢手看看情况。$B$B博古斯提过，暴风城港口最南边的码头有艘船能直达那里。','幸会幸会！我叫博古斯，出自独一无二的钢手家族。和我们钢手家族做买卖，永远童叟无欺！$B$B几个礼拜前，我兄弟高尔博德在奥伯丁的商铺谋了份差事。听我说，在那儿给船只供应补给可赚大钱了！那小子运气真好。$B$B不过从那以后我就再没他的消息了——要是你顺路的话，能不能帮我去看看他？$B$B港口正好有艘新船能直达那儿。去最南边的码头，你绝对找得到！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97899,'zhCN','露营基础：炼金术','展示出你对专业技能的精通后，前往奥格瑞玛寻找伍特，学习如何制作与你专业相符的露营物品。','所以，你选择成为一名炼金师来熬制药剂和药水。我相信这在旅途中一定会派上用场。$B$B我想我认识某个人，可以教你如何为营地制作法力之井。只要建好一个，所有的治疗者和施法者都会跑来品尝这让人恢复活力的泉水。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97900,'zhCN','露营基础：锻造','展示出你对专业技能的精通后，前往剃刀岭寻找杜克，学习如何制作与你专业相符的露营物品。','所以，你成为了一名铁匠。如果你想确保武器的刀刃永远锋利，这绝对是个好选择。$B$B我想我认识某个人，可以教你如何制作磨刀石。在营地里摆上这个，周围所有的战士和潜行者都会排着队来打磨武器。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97901,'zhCN','露营基础：附魔','展示出你对专业技能的精通后，前往奥格瑞玛寻找夏格，学习如何制作与你专业相符的露营物品。','附魔师能让一切锦上添花，因此在野外的任何营地都大受欢迎。$B$B我想我认识某个人，可以教你如何为营地制作一把附魔的鲁特琴。在闲暇时找点乐子非常重要，这股小小的魔法能让你在再次踏上风尘仆仆的旅途时，做好迎接各种挑战的准备。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97902,'zhCN','露营基础：工程学','展示出你对专业技能的精通后，前往剃刀岭寻找穆德拉克，学习如何制作与你专业相符的露营物品。','像你这样的工程师总能捣鼓出各种零件、机器人和炸弹，既找了乐子又赚了金币。$B$B我想我认识某个人，可以教你如何为营地制作一个试剂机器人。这种实用的自动机器人能帮你保持充足的补给，这样你和盟友就永远不必担心耗尽施法所需的材料了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97903,'zhCN','露营基础：急救','展示出你对专业技能的精通后，前往剃刀岭寻找拉乌克，学习如何制作与你专业相符的露营物品。','所以你学习了急救？作为一名$C，这是一项光荣……且务实的追求。$B$B我想我认识某个人，可以教你如何为营地制作急救包。在冒险的世界里，受伤是家常便饭，在营地里提供一些急需的治疗甚至能挽救生命。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97904,'zhCN','露营基础：钓鱼','展示出你对专业技能的精通后，前往森金村附近寻找劳迪克，学习如何制作与你专业相符的露营物品。','你可能觉得没什么，但作为渔夫的技能在营地里其实能派上大用场。$B$B我想我认识某个人，可以教你如何为营地制作鱼缸。你可以用这个小玩意为你自己和冒险者同伴带来一些乐趣。一个快乐的冒险者才是强大的冒险者，我相信这能在你的战斗能力上体现出来。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97905,'zhCN','露营基础：草药学','展示出你对专业技能的精通后，前往奥格瑞玛寻找加迪，学习如何制作与你专业相符的露营物品。','看来你已经在草药学方面积攒了一些经验。要知道，采花可不仅仅是为了消遣。它很有用……而且有利可图。$B$B我想我认识某个人，可以教你如何为营地制作熏香蜡烛。高昂的士气是让治疗者和施法者保持战斗力的关键因素，而熏香蜡烛带来的提升一定会受到施法者们的欢迎。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97906,'zhCN','露营基础：制皮','展示出你对专业技能的精通后，前往奥格瑞玛寻找卡洛雷克，学习如何制作与你专业相符的露营物品。','你成了一名制皮师。这是个好选择，$C。我想我认识某个人，可以教你如何为自己制作一顶帐篷，让你在炎夏保持凉爽，在雨天保持干爽。$B$B只要有一顶好帐篷遮风挡雨，你就能获得充分的休息，从而在旅途中保持敏锐。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97907,'zhCN','露营基础：采矿','展示出你对专业技能的精通后，前往剃刀岭寻找克鲁恩，学习如何制作与你专业相符的露营物品。','采矿或许不是最光鲜的行当，但绝对是份踏实的工作，也是个值得你钻研的好专业。$B$B我想我认识某个人，可以教你如何为营地制作磁石。只要建好一个，所有舞刀弄剑的家伙都会争相聚集在你的营火旁，汲取它所提供的额外“冲劲”，以此提升战斗力。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97908,'zhCN','露营基础：剥皮','展示出你对专业技能的精通后，前往奥格瑞玛寻找苏尔德，学习如何制作与你专业相符的露营物品。','能够熟练地从野兽尸体上剥取皮毛，是冒险者最宝贵的技能之一。$B$B我想我认识某个人，可以教你如何为营地制作营地椅子。有时候好好歇口气非常重要，你可以用收集来的皮毛做一把舒适的椅子。片刻的放松能让你保持巅峰状态，并在下次卷入激战时打出致命一击。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97914,'zhCN','拓宽视野','将桑迪斯的信件送达暴风城的巴隆斯·阿历克斯顿手中。$B$B桑迪斯提到奥伯丁有一艘可以载你过去的船。','奥伯丁不过是个不起眼的小地方，$C。在达纳苏斯的那些高枝上，你根本听不到它的名字。世人念叨的，往往只是大分裂从我们手中夺走的那些——昔日繁盛的亚米萨兰、巴莎兰，还有……拉萨拉扎。$B$B可奥伯丁至今仍被它们的光芒遮蔽。$B$B我渴望我们在这里的付出能被世人看见。如今，一艘崭新的航船将我们与暴风城王国相连，为我们的海岸运来了生机与给养。我恳请你搭乘它的下一班船，将这封信转交给一个名叫巴隆斯·阿历克斯顿的人类。$B$B让我们的家园扬名于世。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97915,'zhCN','露营基础：炼金术','展示出你对专业技能的精通后，前往暴风城附近的艾尔文森林寻找炼金师玛洛瑞，学习如何制作与你专业相符的露营物品。','所以，你选择成为一名炼金师来熬制药剂和药水。我相信这在旅途中一定会派上用场。$B$B我想我认识某个人，可以教你如何为营地制作法力之井。只要建好一个，所有的治疗者和施法者都会跑来品尝这让人恢复活力的泉水。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
