INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97923,'zhCN','露营基础：采矿','展示出你对专业技能的精通后，前往暴风城寻找吉尔曼·石手，学习如何制作与你专业相符的露营物品。','采矿或许不是最光鲜的行当，但绝对是份踏实的工作，也是个值得你钻研的好专业。$B$B我想我认识某个人，可以教你如何为营地制作磁石。只要建好一个，所有舞刀弄剑的家伙都会争相聚集在你的营火旁，汲取它所提供的额外“冲劲”，以此提升战斗力。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97924,'zhCN','露营基础：剥皮','展示出你对专业技能的精通后，前往闪金镇寻找海伦尼·派特斯金纳，学习如何制作与你专业相符的露营物品。','能够熟练地从野兽尸体上剥取皮毛，是冒险者最宝贵的技能之一。$B$B我想我认识某个人，可以教你如何为营地制作营地椅子。有时候好好歇口气非常重要，你可以用收集来的皮毛做一把舒适的椅子。片刻的放松能让你保持巅峰状态，并在下次卷入激战时打出致命一击。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97925,'zhCN','露营基础：裁缝','展示出你对专业技能的精通后，前往艾尔文森林的东谷伐木场寻找艾尔丁，学习如何制作与你专业相符的露营物品。','裁缝是一门极其强大且值得投入的商业技能，我相信它一定会对你大有裨益。$B$B我认识某个人，只要你的技能达标，他就能教你如何为营地制作阵营旗帜。鼓舞和士气是战场制胜的关键，而一面振奋人心的旗帜能在很大程度上让你保持斗志。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97926,'zhCN','勉强度日','将阿历克斯顿的回信带给黑海岸奥伯丁的桑迪斯·织风。','我真希望帮忙能有那么简单，$C。我是发自内心的。$B$B等你在我们的土地上待久了，你就会发现，勒紧裤腰带过日子的人比比皆是。暴风城的国库早就不比当年了，剩下的那么点家底，分摊下来连塞牙缝都不够。$B$B下次见到那位长者时，把这封回信交给他。这结果肯定让他大失所望，但这已经是我目前能拿得出手的全部了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97927,'zhCN','露营基础：炼金术','展示出你对专业技能的精通后，前往雷霆崖寻找克瑞，学习如何制作与你专业相符的露营物品。','所以，你选择成为一名炼金师来熬制药剂和药水。我相信这在旅途中一定会派上用场。$B$B我想我认识某个人，可以教你如何为营地制作法力之井。只要建好一个，所有的治疗者和施法者都会跑来品尝这让人恢复活力的泉水。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97928,'zhCN','露营基础：锻造','展示出你对专业技能的精通后，前往雷霆崖寻找瑟拉格·石蹄，学习如何制作与你专业相符的露营物品。','所以，你成为了一名铁匠。如果你想确保武器的刀刃永远锋利，这绝对是个好选择。$B$B我想我认识某个人，可以教你如何制作磨刀石。在营地里摆上这个，周围所有的战士和潜行者都会排着队来打磨武器。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97929,'zhCN','露营基础：附魔','展示出你对专业技能的精通后，前往雷霆崖寻找莫特·晨行者，学习如何制作与你专业相符的露营物品。','附魔师能让一切锦上添花，因此在野外的任何营地都大受欢迎。$B$B我想我认识某个人，可以教你如何为营地制作一把附魔的鲁特琴。在闲暇时找点乐子非常重要，这股小小的魔法能让你在再次踏上风尘仆仆的旅途时，做好迎接各种挑战的准备。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97931,'zhCN','露营基础：急救','展示出你对专业技能的精通后，前往血蹄村寻找维尔拉·幼蹄，学习如何制作与你专业相符的露营物品。','所以你学习了急救？作为一名$C，这是一项光荣……且务实的追求。$B$B我想我认识某个人，可以教你如何为营地制作急救包。在冒险的世界里，受伤是家常便饭，在营地里提供一些急需的治疗甚至能挽救生命。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97933,'zhCN','露营基础：草药学','展示出你对专业技能的精通后，前往雷霆崖寻找克米恩·冰蹄，学习如何制作与你专业相符的露营物品。','看来你已经在草药学方面积攒了一些经验。要知道，采花可不仅仅是为了消遣。它很有用……而且有利可图。$B$B我想我认识某个人，可以教你如何为营地制作熏香蜡烛。高昂的士气是让治疗者和施法者保持战斗力的关键因素，而熏香蜡烛带来的提升一定会受到施法者们的欢迎。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97934,'zhCN','露营基础：制皮','展示出你对专业技能的精通后，前往血蹄村寻找查尔·硬皮，学习如何制作与你专业相符的露营物品。','你成了一名制皮师。这是个好选择，$C。我想我认识某个人，可以教你如何为自己制作一顶帐篷，让你在炎夏保持凉爽，在雨天保持干爽。$B$B只要有一顶好帐篷遮风挡雨，你就能获得充分的休息，从而在旅途中保持敏锐。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97935,'zhCN','露营基础：采矿','展示出你对专业技能的精通后，前往雷霆崖寻找布瑞克·石蹄，学习如何制作与你专业相符的露营物品。','采矿或许不是最光鲜的行当，但绝对是份踏实的工作，也是个值得你钻研的好专业。$B$B我想我认识某个人，可以教你如何为营地制作磁石。只要建好一个，所有舞刀弄剑的家伙都会争相聚集在你的营火旁，汲取它所提供的额外“冲劲”，以此提升战斗力。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97936,'zhCN','露营基础：剥皮','展示出你对专业技能的精通后，前往血蹄村寻找姚恩·深刺，学习如何制作与你专业相符的露营物品。','能够熟练地从野兽尸体上剥取皮毛，是冒险者最宝贵的技能之一。$B$B我想我认识某个人，可以教你如何为营地制作营地椅子。有时候好好歇口气非常重要，你可以用收集来的皮毛做一把舒适的椅子。片刻的放松能让你保持巅峰状态，并在下次卷入激战时打出致命一击。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97937,'zhCN','露营基础：裁缝','展示出你对专业技能的精通后，前往雷霆崖寻找范恩，学习如何制作与你专业相符的露营物品。','裁缝是一门极其强大且值得投入的商业技能，我相信它一定会对你大有裨益。$B$B我认识某个人，只要你的技能达标，他就能教你如何为营地制作阵营旗帜。鼓舞和士气是战场制胜的关键，而一面振奋人心的旗帜能在很大程度上让你保持斗志。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97938,'zhCN','露营基础：炼金术','展示出你对专业技能的精通后，前往多兰纳尔寻找塞恩德拉·细语者，学习如何制作与你专业相符的露营物品。','所以，你选择成为一名炼金师来熬制药剂和药水。我相信这在旅途中一定会派上用场。$B$B我想我认识某个人，可以教你如何为营地制作法力之井。只要建好一个，所有的治疗者和施法者都会跑来品尝这让人恢复活力的泉水。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97939,'zhCN','露营基础：锻造','展示出你对专业技能的精通后，前往黑海岸奥伯丁寻找艾丽萨·钢拳，学习如何制作与你专业相符的露营物品。','所以，你成为了一名铁匠。如果你想确保武器的刀刃永远锋利，这绝对是个好选择。$B$B我想我认识某个人，可以教你如何制作磨刀石。在营地里摆上这个，周围所有的战士和潜行者都会排着队来打磨武器。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97940,'zhCN','露营基础：附魔','展示出你对专业技能的精通后，前往泰达希尔的神谕林地寻找奥兰纳·鸦眼，学习如何制作与你专业相符的露营物品。','附魔师能让一切锦上添花，因此在野外的任何营地都大受欢迎。$B$B我想我认识某个人，可以教你如何为营地制作一把附魔的鲁特琴。在闲暇时找点乐子非常重要，这股小小的魔法能让你在再次踏上风尘仆仆的旅途时，做好迎接各种挑战的准备。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97941,'zhCN','露营基础：工程学','展示出你对专业技能的精通后，前往黑海岸奥伯丁寻找洁娜·雷姆尼利，学习如何制作与你专业相符的露营物品。','像你这样的工程师总能捣鼓出各种零件、机器人和炸弹，既找了乐子又赚了金币。$B$B我想我认识某个人，可以教你如何为营地制作一个试剂机器人。这种实用的自动机器人能帮你保持充足的补给，这样你和盟友就永远不必担心耗尽施法所需的材料了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97942,'zhCN','露营基础：急救','展示出你对专业技能的精通后，前往多兰纳尔寻找拜恩希，学习如何制作与你专业相符的露营物品。','所以你学习了急救？作为一名$C，这是一项光荣……且务实的追求。$B$B我想我认识某个人，可以教你如何为营地制作急救包。在冒险的世界里，受伤是家常便饭，在营地里提供一些急需的治疗甚至能挽救生命。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97943,'zhCN','露营基础：钓鱼','展示出你对专业技能的精通后，前往达纳苏斯寻找阿斯坦娅，学习如何制作与你专业相符的露营物品。','你可能觉得没什么，但作为渔夫的技能在营地里其实能派上大用场。$B$B我想我认识某个人，可以教你如何为营地制作鱼缸。你可以用这个小玩意为你自己和冒险者同伴带来一些乐趣。一个快乐的冒险者才是强大的冒险者，我相信这能在你的战斗能力上体现出来。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97944,'zhCN','露营基础：草药学','展示出你对专业技能的精通后，前往多兰纳尔寻找玛洛尼·刃叶，学习如何制作与你专业相符的露营物品。','看来你已经在草药学方面积攒了一些经验。要知道，采花可不仅仅是为了消遣。它很有用……而且有利可图。$B$B我想我认识某个人，可以教你如何为营地制作熏香蜡烛。高昂的士气是让治疗者和施法者保持战斗力的关键因素，而熏香蜡烛带来的提升一定会受到施法者们的欢迎。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
