INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97954,'zhCN','露营基础：工程学','展示出你对专业技能的精通后，前往幽暗城寻找格拉哈姆·范·塔伦，学习如何制作与你专业相符的露营物品。','像你这样的工程师总能捣鼓出各种零件、机器人和炸弹，既找了乐子又赚了金币。$B$B我想我认识某个人，可以教你如何为营地制作一个试剂机器人。这种实用的自动机器人能帮你保持充足的补给，这样你和盟友就永远不必担心耗尽施法所需的材料了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97957,'zhCN','露营基础：草药学','展示出你对专业技能的精通后，前往布瑞尔寻找法鲁萨，学习如何制作与你专业相符的露营物品。','看来你已经在草药学方面积攒了一些经验。要知道，采花可不仅仅是为了消遣。它很有用……而且有利可图。$B$B我想我认识某个人，可以教你如何为营地制作熏香蜡烛。高昂的士气是让治疗者和施法者保持战斗力的关键因素，而熏香蜡烛带来的提升一定会受到施法者们的欢迎。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97958,'zhCN','露营基础：制皮','展示出你对专业技能的精通后，前往布瑞尔通往幽暗城的路上寻找舍伦尼·洛巴尔特，学习如何制作与你专业相符的露营物品。','你成了一名制皮师。这是个好选择，$C。我想我认识某个人，可以教你如何为自己制作一顶帐篷，让你在炎夏保持凉爽，在雨天保持干爽。$B$B只要有一顶好帐篷遮风挡雨，你就能获得充分的休息，从而在旅途中保持敏锐。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97959,'zhCN','露营基础：采矿','展示出你对专业技能的精通后，前往幽暗城寻找布罗姆·基里安，学习如何制作与你专业相符的露营物品。','采矿或许不是最光鲜的行当，但绝对是份踏实的工作，也是个值得你钻研的好专业。$B$B我想我认识某个人，可以教你如何为营地制作磁石。只要建好一个，所有舞刀弄剑的家伙都会争相聚集在你的营火旁，汲取它所提供的额外“冲劲”，以此提升战斗力。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97960,'zhCN','露营基础：剥皮','展示出你对专业技能的精通后，前往布瑞尔通往幽暗城的路上寻找兰德·洛巴尔特，学习如何制作与你专业相符的露营物品。','能够熟练地从野兽尸体上剥取皮毛，是冒险者最宝贵的技能之一。$B$B我想我认识某个人，可以教你如何为营地制作营地椅子。有时候好好歇口气非常重要，你可以用收集来的皮毛做一把舒适的椅子。片刻的放松能让你保持巅峰状态，并在下次卷入激战时打出致命一击。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97961,'zhCN','露营基础：裁缝','展示出你对专业技能的精通后，前往丧钟镇通往布瑞尔的路上寻找博文·布里斯博埃斯，学习如何制作与你专业相符的露营物品。','裁缝是一门极其强大且值得投入的商业技能，我相信它一定会对你大有裨益。$B$B我认识某个人，只要你的技能达标，他就能教你如何为营地制作阵营旗帜。鼓舞和士气是战场制胜的关键，而一面振奋人心的旗帜能在很大程度上让你保持斗志。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97969,'zhCN','露营基础：制皮','展示出你对专业技能的精通后，前往申达尔村寻找因达里·日缝，学习如何制作与你专业相符的露营物品。','你成了一名制皮师。这是个好选择，$C。我想我认识某个人，可以教你如何为自己制作一顶帐篷，让你在炎夏保持凉爽，在雨天保持干爽。$B$B只要有一顶好帐篷遮风挡雨，你就能获得充分的休息，从而在旅途中保持敏锐。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97972,'zhCN','露营基础：裁缝','展示出你对专业技能的精通后，前往申达尔村寻找塔琳·闪线，学习如何制作与你专业相符的露营物品。','裁缝是一门极其强大且值得投入的商业技能，我相信它一定会对你大有裨益。$B$B我认识某个人，只要你的技能达标，他就能教你如何为营地制作阵营旗帜。鼓舞和士气是战场制胜的关键，而一面振奋人心的旗帜能在很大程度上让你保持斗志。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97977,'zhCN','自然的召唤','收集4个瘤背图腾，然后将它们交给塔琳德拉。','瘤背熊怪绝不会如此轻易地背弃他们古老的盟友。我们必须进一步查明，他们究竟遭遇了什么样的苦难。$B$B去搜索一下他们废弃的家园，找找那里的图腾。如果有哪些图腾在他们仓促离去时的混乱中幸存了下来，那上面的刻纹或许就能向我们揭示更多这里曾发生过的真相。$B$B你可以在幽影谷的西侧边缘找到他们的营地。不过，那些劣魔和小劣魔说不定早就把图腾给弄得到处都是了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97979,'zhCN','女神的恩赐','施放艾露恩之光与影遁。','你生来便是卡多雷——群星之子——并继承了这份世间独一无二的天赋。艾露恩的恩典既能彰显出我们的力量，让我们的攻击精准无误；也能像月亮遮蔽太阳那般，将我们的身姿完全隐匿在暗影之中。$B$B在海加尔山防御战之后，我们漫长的守望已经结束，并加入了一个由其他种族组成的联盟——你迟早会与他们相见。目前，你正栖息在泰达希尔的枝干上。$B$B去展现月神母亲的恩赐，沐浴在她的祝福之中吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97985,'zhCN','雷霆之心','消灭千针石林的风暴之心，夺取它的心脏。','这些笔记简直太有意思了，不是吗？这还是我头一次有机会，能窥探到制造憎恶的秘密呢。$B$B我一直在仔细琢磨这些笔记，看来我们现在最缺的就是一颗心脏。而且得是一颗硕大无比的心脏！$B$B我听说在千针石林那儿，有一只体型惊人的雷霆蜥蜴，名叫风暴之心，它成天沿着峡谷边缘到处巡游。既然它能叫这么个霸气的名字，那它的心脏绝对是再合适不过了。我不管，我必须得到那颗心脏！$B$B噢，对了，我强烈建议你多带几个朋友一起去。风暴之心那家伙，可从来不是什么善茬。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98013,'zhCN','不断壮大的势力','替古树之林的阿尔巴尔消灭12名雷鳞侍从、8名雷鳞巫师和6名雷鳞战士。','让你自己做好深入这片废墟的心理准备吧，年轻人……那里可没法让你像散步一样随便瞎转悠。$B$B无数受诅咒的上层精灵如今已经化作了纳迦，在这座昔日的伟大城市里四处游荡。一路向东北方进发，把他们从这片土地上彻底清除出去。$B$B他们曾经的样子……早就不复存在了。如果他们非要给暮光之锤当帮凶，那只会给曾经庇护过他们的森林招来无穷无尽的痛苦。$B$B既然他们如此渴求战争，$C。那我们就……给他们战争。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98021,'zhCN','前往哨兵岭的旅程','向西部荒野哨兵岭的格里安·斯托曼报到。','如果你想在我们的世界里行侠仗义，我建议你往南走，去西部荒野的哨兵岭向格里安·斯托曼报到。他的人民正急需援助。$B$B你从另一个存在位面远道而来，我们这片土地上的麻烦在你眼里或许微不足道。但我向你保证，你的援助对那些饱受苦难的人来说意味着一切，而你也会在磨砺中变得更加强大。$B$B祝你好运，冒险者！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98024,'zhCN','十字路口之旅','向贫瘠之地十字路口的索克报到。','你从元素位面远道而来，我们这片土地上的麻烦在你眼里或许微不足道。但请相信，部落面临的危险实打实地存在，只要你能活着完成服役，必将变得势不可挡。$B$B如果你想在我们的世界里建功立业，请向西南方行进，前往那片名为贫瘠之地的广袤土地。那里有一处名为十字路口的定居点，那些骄傲的居民总是需要人手帮忙。$B$B带着荣耀出发吧，冒险者！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98025,'zhCN','通缉：贾伊瓦内尔','找到并消灭那只名叫贾伊瓦内尔的猫头鹰，然后拔下它的一根羽毛。最后一次有人瞧见这只黑色猫头鹰，还是在亚米萨兰废墟北边的山脚底下。拿着羽毛，去向奥伯丁的哨兵戈琳达·纳希恩报告贾伊瓦内尔的死讯。','敬告各位！$B$B现悬赏消灭名为“贾伊瓦内尔”、又被称作“剑羽”的猫头鹰。$B$B不幸的是，这只猫头鹰如今已经发了狂，甚至开始袭击所有途经奥伯丁附近大路的旅人。$B$B有人最后一次见到贾伊瓦内尔，是在亚米萨兰废墟北边的山脚附近。带回它的一根乌黑羽毛，作为它已死的凭证。$B$B所有赏金的申领，请统一找奥伯丁的哨兵戈琳达·纳希恩办理。$B$B奥伯丁村议会敬上',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98042,'zhCN','开玩笑也要有个限度……','从黑海岸主宰之剑的暮光信徒或暮光暴徒身上夺取一颗无双之眼，然后在奥伯丁里找到那个愿意接手这烫手山芋的人。','<就在你从那本暮光之书上撕下唯一一页书页的时候，一个不祥的声音突然不请自来，瞬间充斥了你的整个脑海。>$B$B他们已经失败了。$B$B而你，必将被历史彻底遗忘。$B$B至于他们，终将失去那只刚刚夺来的眼睛。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98046,'zhCN','大地之冠','将排空的器皿送至达纳苏斯月神殿的拉瑞亚手中。','<大德鲁伊范达尔·鹿盔眯起了双眼。>$B$B你怎么还在这里？$B$B带着这个破瓶子从我眼前消失，$C。事情很明显，我要的答案根本不在这些水里，就跟以前一样。$B$B或许南边月神殿里的那群女祭司会有闲工夫处理这玩意。$B$B<范达尔扭过头去，不愿再多看你一眼。>$B$B如果想要这法子奏效，我看来必须另辟蹊径了……',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98059,'zhCN','希尔斯布莱德的囤积','将密封的连队请求带进希尔斯布莱德的镇政厅，然后把它安放在记账桌上。','希尔斯布莱德的议会，至今都没有回复我们新任执政官写去的那些信件。我好不容易才从一个刚好路过镇子的商人口中撬出了一点消息，但这也完全没法用来解释他们为什么要一直保持沉默。$B$B我们明明只要求他们派出一小个排的兵力——可我却听说，他们在一个封闭的院落里，还停放着好多台保养得极好的攻城弩炮。$B$B伪装成一名去交还人口普查表的普通居民，大摇大摆地走进他们的镇政厅，然后把这封信整整齐齐地摆在他们的记账桌上。$B$B事情办妥之后，立刻回来向我复命。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98065,'zhCN','大地之冠','将月亮井残骸交予达纳苏斯月神殿的泰兰德·语风。','你必须火速把这个呈交给泰兰德！我这就替你把它装进更庄重的器皿里。$B$B别紧张。艾露恩的高阶女祭司虽然威严，但内心仁慈。她庇护着每一个踏入达纳苏斯的人，将女神的光辉洒向众生。$B$B她一定会非常乐意收下这份圣水的。你直接上去就能见到她。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98067,'zhCN','哨兵之目','替达纳苏斯月神殿里的哨兵达莉亚·炎刃，分别在塞纳里奥要塞下层的入口、达纳苏斯银行、工匠区旅店以及城市的大门处安置好哨兵猫头鹰。','羽月将军一直在极力确保每位哨兵都能留出向艾露恩祈祷的时间。一名合格的女猎手，可不能只懂得依靠刀剑去作战，我们还得学会灵活运用女神所赐予的恩典来战胜强敌。$B$B你可以来帮我分担一些日常的职责。去城里四处安置哨兵——先去北面通往塞纳里奥要塞地下部分的隧道入口，然后再去市中心的那家银行，接着去东北边工匠区里的那家旅店，最后再去城市的大门那儿看看。那些卫兵会从旁协助你的。$B$B最近泰达希尔似乎有些不太对劲——我们必须时刻保持着警惕才行。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98070,'zhCN','阻止尖啸','消灭5名尖啸鹰身人、5名尖啸游荡者以及5名尖啸唤风者。','尖啸峡谷里盘踞着一群本地的鹰身人。她们向来以性情凶残和擅长劫掠而臭名昭著。最近这几支胆敢硬闯此地的补给车队，无一例外全遭到了她们的狠毒伏击。$B$B我真怕要是再不赶紧采取点什么行动，以后就再也不会有哪支车队敢冒着生命危险，长途跋涉去往乱风岗了。$B$B去吧，拿出你的全部本事，尽可能多地去消灭那群该死的鹰身人。事成之后回来向我复命，我一定会好好重赏你这番努力的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98072,'zhCN','天上的鳄鱼','收集8片无瑕的赤红鳞片，把它们交给米奈希尔港的詹姆斯·哈洛兰。','你可真是个实干家！我手头还有最后一件事想请你帮忙，如果你不介意接点更危险的活儿的话。$B$B鳄鱼买卖确实是笔稳定的收入，但跟雏龙鳞片能带来的利润相比，简直是小巫见大巫。人们愿意花高价买上一袋那种鳞片。$B$B我管它们叫天上的鳄鱼！我的学徒绝对拿不到那些东西——但这似乎正是你擅长的！$B$B顺着遥远东方的绿带走，你就能找到雏龙。但务必小心，那些山丘里盘踞着凶恶的兽人！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98093,'zhCN','肃清田野','贫瘠之地南部的苏尔哈萨需要你清理该区域内的7只雷鳞蜥蜴与7名乱齿捕猎者，以确保她能安全地离开大树。','幸好你发现了我！$B$B今天早上天气很好，我便从陶拉祖营地顺着黄金之路散步。可到了该往回走的时候，我却回不去了——一群鬣狗开始在四周盘旋，雷鳞蜥蜴也堵住了我唯一的退路。$B$B我慌忙爬上了这棵树，而现在外面的敌人实在太多了，我根本没法穿过田野跑回家。$B$B能劳驾你帮我清理掉这些雷鳞蜥蜴和乱齿捕猎者吗？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98155,'zhCN','完好的杂毛兽皮','收集5张完好的杂毛兽皮，带回去交给克里斯蒂·格兰特。','要知道，千针石林里的那些杂毛土狼，身上可长着最漂亮的皮毛了。我走南闯北去过那么多地方，还从来没见过哪种动物的毛皮，能呈现出那么鲜艳动人的色泽！$B$B我打算弄一些兽皮，寄给我那几个远在暴风城的姐妹们，我太了解她们了，她们肯定能用这些极品毛皮，做出极其惊艳的东西来。$B$B可惜我毫无战斗经验。如果你愿意大发慈悲，替我去收集一些杂毛兽皮的话，我一定会非常非常感激你的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98156,'zhCN','包裹好的完美毛皮','将一包完好的毛皮交给金伯利·格兰特。','$N，你已经帮了我这么大的忙，我实在不好意思再开这个口了。我恐怕还要很久才能回到暴风城的家。不知你是否愿意帮我跑个腿，把我手头的这些毛皮送去给我妹妹？$B$B我想，你肯定比我更早踏上回去的路。请务必将这些毛皮转交给暴风城的凯莉和金伯利·格兰特姐妹俩。去花园区准能找到她们。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98189,'zhCN','归还雕像','将米奈希尔雕像送给米奈希尔城堡的斯托菲队长。','天哪，它……它太美了！$B$B在悲剧发生之前，盲眼公主号原本是要将这件物品送到米奈希尔港的。我们就差那么一点！$B$B我想它本该由我们后方米奈希尔城堡里的斯托菲队长签收。不如就由你代劳完成这项任务吧？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98190,'zhCN','家族之友','把米奈希尔雕像带给暴风要塞的伯瓦尔·弗塔根公爵。','你需要立刻把这个带去暴风城。尽管我很自豪这座城堡和港口以泰瑞纳斯·米奈希尔二世国王的名字命名，但在敌人掀起的恶劣风暴中，我们也不过是一处避风港。这里并不安全。$B$B特别是龙喉氏族，为了抢夺这种东西，他们会不惜付出一切代价……我简直不敢想象他们会拿它做什么。$B$B这件事你不必费心去层层上报，$G先生:女士;。带着它直接去找伯瓦尔·弗塔根公爵。他知道它最好该保管在什么地方。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98191,'zhCN','家族之友','把米奈希尔雕像交给圣光大教堂的格雷森·沙东布瑞克公爵。','泰瑞纳斯国王是个好人，也是个虔诚的人。他深受人民的爱戴，更是我们建立这个联盟的真正原因。$B$B讽刺的是，他为人谦逊——他讨厌这种纪念物，所以存世的数量极少。而在这些为数不多的雕像中，能在洛丹伦陷落后幸存下来的更是寥寥无几。$B$B圣光似乎凝聚在了这座雕像中。最好把它存放在市中心教堂广场的光明大教堂里。把它带去交给格雷森·沙东布瑞克公爵妥善保管。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98197,'zhCN','战争横财','替瓦斯塔格·铁腭从米奈希尔港找回6份卡兹莫丹木材和30份卡兹莫丹铁矿。','这座港口最初是由旧部落建造的，用作他们从海路入侵希尔斯布莱德的集结地。完全绕开了洛丹伦的防御！$B$B无数生命就此消逝……$B$B更糟糕的是，那支舰队是用他们从卡兹莫丹窃取的资源建造的！$B$B在普罗德摩尔海军上将击溃那些野蛮人并为联盟建造了这个地方之后，港口中还留存着大量的资源。随着龙喉氏族再次蠢蠢欲动，我们需要这些资源来加强城镇的防御。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98208,'zhCN','天堂之花','为米奈希尔港的塞莱莎·暮语找回诺德尔。','我从奥伯丁的泰达希尔巨树来到米奈希尔港，是为了找回一朵对我的人民至关重要的花。$B$B数月前，我们族人的船只飞翔的鱼鹰号连同库尔提拉斯第三舰队在这里坠毁。在那批货物中，有一朵名叫诺德尔的花——用你们的话说叫天堂之花——那是在我们的故乡海加尔山的山顶上，于满月下绽放的珍宝。$B$B请帮我找回它！残骸就在城市正南方，但那里盘踞着凶猛的鱼人劫掠者！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98209,'zhCN','天堂之花','把诺德尔带给黑海岸奥伯丁的桑迪斯·织风。$B$B你回想起塞莱莎曾提到过，米奈希尔港的一艘船可以带你去那里。','能请你把诺德尔送给奥伯丁的长者桑迪斯·织风吗？$B$B从这里开出的客船应该能让你迅速到达那里。$B$B实在抱歉提出这个请求，我并非有意推脱。仅仅是一路奔波而来——再加上头一次试图从那群鱼人恶魔手中抢夺圣花时的惊险逃生，直到现在，我依然疲惫不堪！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98216,'zhCN','了解现状','在戈阿兹守卫者附近使用戈阿兹之石，随后将泰坦钥匙之石带给勘察员维尔加。','上古之神？！这绝对不是什么好消息！$B$B我又辨认出了石头上的一小部分内容，它提到了某种守护者。不管那到底是个什么东西，它肯定与这块石头有关！$B$B带上它，去挖掘场看看你是否能找到某种大型的泰坦构造体。宣读石头上的这最后一段文字，看看会发生什么！$B$B如果我是对的，你这举动会激活那个东西。如果发生了这种情况，解决掉它，但尽量保留任何有价值的东西！我们必须了解更多真相！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98219,'zhCN','蒙羞的中尉','前往希尔斯布莱德丘陵的南海镇，与法尔林·奥里涅尔中尉交谈。','再次感谢你安全地送达了雕像，$N。$B$B我在另一件事上可能还需要你的帮助。城防军中有一名成员被重新分配到了希尔斯布莱德丘陵的南海镇服役。$B$B他的父亲曾是我的一位朋友，虽然我并不反对让他趁机吸取点教训……但我仍然希望看到他取得成功。如果能有像你这样的人帮他一把，他真的会受益匪浅。$B$B如果你回去时碰巧路过米奈希尔港，那里有一艘船可以带你去那。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98221,'zhCN','灰烬新生','米奈希尔城堡的斯托菲队长要你摧毁怒牙营地里的4份进攻计划。','在第二次战争中，龙喉氏族正是踏在我们现在所站的地方建造了一支舰队，企图拿下希尔斯布莱德。他们几乎就成功了！$B$B后来他们被红龙击溃，只剩下一群在深山中苟延残喘的散兵游勇。然而，在米奈希尔东北部的营地里，他们的活动近期出现了激增。$B$B丹奥加兹就是他们企图再次开战并夺回这片土地的证明。找到他们的进攻计划，记下所有关键信息，然后销毁它们。我们需要知道他们下一步会袭击哪里！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98223,'zhCN','积习难改','将破损的法术书交给米奈希尔港的斯托菲队长。','这本书被严重烧毁了——也许是因为那场摧毁了龙喉氏族大部分成员的龙焰。$B$B在那些为数不多还能辨认的内容中，它似乎描述了与使用恶魔之魂相关的仪式，而该氏族曾用恶魔之魂来控制巨龙。$B$B它太残缺了，已经没有实际用处，但根据粗略插入的兽皮纸页来看，纳克罗什似乎曾试图复原它。上面刚刚干涸的墨迹提到了一个“暗影议会”。$B$B米奈希尔港的斯托菲队长肯定会想知道这件事。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98230,'zhCN','故土易主','沿着大路向东走，在米奈希尔港外围找到霍文·鹰羽。','在那场摧毁了我们所熟知的矮人生活方式的三锤之战过后，蛮锤矮人定居于此，建立了山地要塞格瑞姆巴托。$B$B那曾是个奇妙的地方。无论望向哪里都能看到翱翔的狮鹫，它们不时俯冲进湿地去抓鱼。$B$B可悲的是，好景不长。$B$B霍文·鹰羽是多年来首批返回这里的蛮锤矮人之一。他深居简出，就住在远离城镇的地方。顺着路往东走——你最终会找到他的。他肯定需要帮助。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98240,'zhCN','猩红板条箱运送','把猩红板条箱带给米奈希尔港以东道路旁的霍文·鹰羽。','关于那些雏龙的消息已经正式传开了，$N。我们已经接到订单了！$B$B我会为你把它们妥善打包，然后由你送去给客户。我知道，我知道。我保证，这真的是最后一次麻烦你了！$B$B这批货是给一个叫“霍文·鹰羽”的家伙。他居然专门派狮鹫飞进城里送订单！信里交代他就住在东边的大路边上，稍微过了维尔加挖掘场一点。要是你熟悉那一带，应该很容易找到。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98245,'zhCN','刺喉钻针','替霍文·鹰羽收集10颗刺喉龙门牙。','我不知道我更恨谁：该死的黑铁矮人，龙喉氏族，还是他们骑乘的巨龙。$B$B<霍文啐了一口。>$B$B我打算把一切拨乱反正。但我们需要一些物资。$B$B这些雏龙鳞片能很好地抵御龙焰，但要把它们编织在一起真是太麻烦了。$B$B东北方恐龙岭和西北方盐沫沼泽里的刺喉迅猛龙，顾名思义，长着一嘴锋利无比的尖牙，应该能刺穿这些鳞片。$B$B给我带几颗门牙来。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98251,'zhCN','永不再来','消灭6头黑角鹿和6头灰谷熊，然后返回坠星湖西北方的瓦克苏格·火怒身边。','啊啊啊！$B$B我快气疯了。他们说灰谷的路很好认。对谁好认？野兽？还是鸟？$B$B前一刻我还在采药，下一刻我就被困在这个峡谷里了。我难道真的得绕过半座森林，才能回到刚才站着的地方吗？$B$B当我在这种情绪下时，我的法术会变得非常不稳定，而且效果……异于平常。$B$B你能减少附近的野兽数量吗？就连它们愚蠢的蹄声都令我心烦。我恨透了这片该死的森林。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98282,'zhCN','炼金险情','从瑟根石收集一颗未破裂的追猎者腺体，交给米奈希尔港的凯特林·格拉斯曼。','有些炼金配方所需的材料，往往藏在危机四伏的险地之中。而且这些通常还只是基础草药！其他辅助材料只会更加致命！$B$B我必须再配置一些抗毒药剂才能动身离开。我敢打赌这片沼泽里到处都是毒物，简直就像是毒素早已渗透进了这片大地的血脉！$B$B你能帮我个忙吗？我需要极东南方瑟根石里那些蜘蛛的毒腺。记住，毒腺必须完好无损，否则还没等你带回来，毒液早就漏得一干二净了。麻烦你了！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98283,'zhCN','诛灭','把诛灭的头颅交给绿带草地的绿色守卫者雷希耶尔。','这片土地的自然秩序正在土崩瓦解。曾经，刺喉迅猛龙抑制着植被的无序疯长；可如今，它们却对自己的首领心生恐惧。那头野兽根本没有名字，人们只能用它制造的无尽杀戮来称呼它。$B$B恐怕正是那种我们还未能彻底根除的疫病，逼疯了这头野兽。$B$B东北方恐龙岭下方的那些染病熊怪，它们身上溃烂的血肉能将它引出来。把熊怪的内脏留在它的巢穴之中即可。$B$B诛灭定会现身。把它的头颅给我带回来。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98284,'zhCN','露营基础：附魔','熟练掌握专业技能后，与申达尔村的娜萨兰娜·风歌交谈，学习制作一件对应专业的露营物品。','附魔师能让一切锦上添花，因此在野外的任何营地都大受欢迎。$B$B我想我认识某个人，可以教你如何为营地制作一把附魔鲁特琴。在闲暇时找点乐子非常重要，这股小小的魔法能让你在再次踏上风尘仆仆的旅途时，做好迎接各种挑战的准备。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98285,'zhCN','露营基础：工程学','展示出你对专业技能的精通后，前往影风森林寻找奇怪的隐士，学习如何制作与你专业相符的露营物品。','身为工程师，脑子向来最灵光！要是孤身一人流落荒野，能把看家本领派上用场可太关键了。一个像样的营地，哪能少得了几台趁手的机械造物！$B$B没错，等你在工程学上多攒点门道，随时回我这儿来，我包管教你造个绝妙的稀罕玩意儿！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98286,'zhCN','露营基础：附魔','熟练掌握专业技能后，与申达尔村的娜萨兰娜·风歌交谈，学习制作一件对应专业的露营物品。','附魔师能让一切锦上添花，因此在野外的任何营地都大受欢迎。$B$B我想我认识某个人，可以教你如何为营地制作一把附魔的鲁特琴。在闲暇时找点乐子非常重要，这股小小的魔法能让你在再次踏上风尘仆仆的旅途时，做好迎接各种挑战的准备。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98291,'zhCN','龙喉之死','在龙喉营地消灭8名龙喉收复者、5名龙喉缚魂者和3名龙喉间谍，向霍文·鹰羽复命。','我打算重返格瑞姆巴托，以蛮锤之名将其夺回，$N。就算退一步讲，至少也得探清里头的虚实。$B$B别用那种眼神看着我。我深知这其中的风险，自然没打算一头扎进去抡着锤子乱砸一气。$B$B不过话说回来，我得先请你帮个忙。龙喉兽人正在大举进军，他们已经控制了整个龙喉营地——也就是当年红龙将他们杀得溃不成军的地方。$B$B你必须先想办法削减他们的兵力，我才有机会潜入进去。沿着大路一直向东走，你绝对能找到他们。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98293,'zhCN','强制缴械','在龙喉营地收集30件龙喉军械，然后交给米奈希尔城堡的斯托菲队长。','龙喉兽人正在疯狂囤积各类武器。我们最好赶在他们武装起更多士兵之前，将这些军备尽数收缴。$B$B米奈希尔城堡的斯托菲队长肯定会对这批物资很感兴趣。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98297,'zhCN','终结循环','在龙喉大门消灭被制服的龙兽，向霍文·鹰羽复命。','趁你外出的工夫，我驾着狮鹫去试飞了一圈。好消息是，你帮贝斯比克打造的那身护甲简直太合身了！$B$B但坏消息是，我亲眼看到一群龙喉兽人正在设法奴役一头红色龙人。$B$B这绝对不行。历史决不能重演。$B$B你必须去解决那头龙人。这件事肯定得叫上朋友帮忙才行。先干掉那些负责压制它的术士，这样就能解开它的束缚。然后再痛快地结束它的痛苦。$B$B谁也别想阻挡蛮锤的脚步。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98298,'zhCN','阿鲁高的愚行','把6份狼人残骸交给瑟伯切尔的达拉尔·道恩维沃尔。','呵，真相已经摆在眼前，真是可笑至极！阿鲁高那点微末的魔力，根本不足以创造出狼人。“阿鲁高的诅咒”？呸！那点法力弱得连几秒钟都撑不住。$B$B这些镣铐足以证明，他顶多也就是能困住野兽，绝非它们的造物主。狼人显然是通过其他途径来传播诅咒的。我非要把这背后的原理弄个水落石出不可。$B$B去南边的格雷迈恩之墙看看。狼人似乎正在把诅咒传染给附近的人类。去把那些野兽撕成碎片，然后把你找到的一切都带回来见我。对付它们，就得用这种简单粗暴的手段。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98299,'zhCN','阻止蔓延','为瑟伯切尔的达拉尔·道恩维沃尔消灭5名病怏怏的难民和5名哈迦德难民。','如果有一件事是我们确切知晓的，那就是阿鲁高必须为银松森林里的狼人负责。无论这是他自己的阴谋还是别的什么原因。而我们不知道的，是这种诅咒的传播方式。$B$B在我研究如何阻止诅咒期间，首要任务是控制它的蔓延。看来这种疫病无法感染被遗忘者，但一大群人类已经聚集在了格雷迈恩之墙附近。$B$B去那堵墙边，赶在这些难民有机会沦为阿鲁高的仆从之前，把他们解决掉。另外，小心点，千万别被咬了，$R。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98300,'zhCN','致信铁炉堡','把霍文的密函交给铁炉堡的国王麦格尼·铜须。','我在这里的工作还远未结束，$N。我还得给远在鹰巢山的妻子克莱拉捎个信——并向弗斯塔德汇报一下最新进展。$B$B不过这些都是我自己的私事，是我们蛮锤内部的事。$B$B话虽如此，你应该把这里发生的一切告知铁炉堡的国王麦格尼·铜须。湿地离他的领地近在咫尺，在家门口发生这些事可绝不是什么好兆头。这封信应该能派上用场。$B$B你可以穿过丹奥加兹回去，或者从米奈希尔港乘飞行坐骑前往铁炉堡。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98310,'zhCN','探寻未来','在阿度斯、莫德尔、高尔姆和奈尔鲁附近使用戈阿兹之石，然后把它们的心脏带给勘察员维尔加。','湿地四处还散落着体型更为庞大的魔像。它们身上各自镌刻着阿度斯、莫德尔、高尔姆以及奈尔鲁的铭文——刚好与你找到的戈阿兹之石所缺失的碎片一一对应！$B$B我敢打包票，只要能把它们的残骸一并带回来，我们绝对能揭开戈阿兹之石隐藏的惊天秘密！$B$B你可以去东边格瑞姆巴托附近的龙喉大门寻找阿度斯。莫德尔就在北边丹莫德的城墙外。高尔姆藏在丹奥加兹以东的格瑞姆巴托地底。至于奈尔鲁，它潜伏在东北方恶铁岭的后方。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (98313,'zhCN','深入研究','把维尔加圣物包裹交给铁炉堡的史学家卡尼克。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98319,'zhCN','确保山区安全','替巡山人格雷琴在灰色洞穴里找到巡山人科尼利厄斯。','巨魔惹出的乱子就已经够让人头疼的了，谁能想到这深山老林里竟然又窜出这么多雪怪！这帮畜生平时都老老实实地待在自己的洞穴里，现在却像繁殖过剩的兔子一样到处乱窜。北边的灰色洞穴早被它们给挤得水泄不通了。$B$B要是咱们还想拿到白须的那份报告，就必须得先找到我那倒霉搭档科尼利厄斯。那个一根筋的蠢货当时兴奋过了头，脑子一热就单枪匹马地冲了进去。勇气可嘉是不假，但未免也太愚不可及了。$B$B去洞穴深处搜一搜，看看那家伙到底藏哪儿了。如果路上遇到那些野兽，顺手宰掉几只那是再好不过。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98321,'zhCN','燧火的货物','在灰色洞穴收集8份燧火货物，交给卡拉诺斯的托格努斯·燧火。','霍哈！很高兴见到一位不怕弄脏双手的$R。$B$B如果你是在找活干，恐怕我眼下正有点缺少物资。我们最可靠的矿脉已经被雪怪占领了，现在那个洞穴已经被废弃。矿工们逃跑时不得不丢下一切！$B$B我说，你为什么不去西边的灰色洞穴附近转转，看看能不能找到我们丢失的货物。那会帮我们省去一大笔麻烦。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98322,'zhCN','确保山区安全','去卡拉诺斯以西检查巡山人格雷琴的情况。','钻那些黑灯瞎火的洞穴是你们冒险者的行当。我的本职工作只是把事情一五一十地写进报告，然后火速递呈给铁炉堡。$B$B可棘手的地方就在于，我手里的一份报告……呃，至今都没人回来交差。我之前派了几个得力的巡山人去实地勘察雪怪泛滥的问题，可直到现在，我连个鬼影子都没见着。$B$B既然你整天在外面跑江湖，不如顺道去镇子西边瞅瞅巡山人格雷琴的情况。我的这份报告已经拖延得够久了，可不能再耽搁了！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98323,'zhCN','确保山区安全','把巡山人格雷琴的报告交给卡拉诺斯的森内尔·白须。','希望你在洞里大开杀戒，狠狠教训了那帮畜生。科尼利厄斯没能活着出来，确实令人惋惜。$B$B照你这么说，除了确认那座洞穴彻底没救了之外，也没什么有价值的情报好上报了。白须那老头肯定对这个结果大发雷霆，但我绝不会再派任何一个弟兄去那种鬼门关里白白送死了。$B$B劳驾你替我把口信捎过去吧，$N。只要这片山区一天不太平，我就一天死守在这里。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98326,'zhCN','霜嚎','消灭霜嚎并收集一袋鲜鱼，交给烈酒村的格雷塔·甘特。','你知道在结冰的湖面上钓鱼有多难吗？我可怜的丈夫帕克斯顿在湖心冻了好几天，我们却连满满一袋子鱼都没凑齐。$B$B好吧，我们本来确实钓满了一袋。直到那只杀千刀的雪怪突然袭击我，抢走了我们所有的收获。我们还得再熬上好几个星期，才能把那些鱼重新钓回来！前提是那个大嗓门的霜嚎没把鱼全吓跑。$B$B帮我们个忙，把鱼夺回来行吗？那个流口水的畜生就躲在东南方灰色洞穴的深处。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98340,'zhCN','巨豹之灵','与月光林地永夜港的德迪利特·星焰交谈。','看来你已准备好踏上旅程的下一步，年轻的德鲁伊。德迪利特·星焰传来了消息，希望你再次前往月光林地找他。$B$B你已经学会使用魔法前往月光林地，如果愿意，现在就可以启程。如果你想继续德鲁伊训练，我建议你尽快动身。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98341,'zhCN','驭风巨豹之灵','在月光林地南部寻找塞利楠的化身，听听它要向你传授哪些关于驭风巨豹本性的知识。','最近，一个来自你家乡的灵魂在这里显现，并要求我指引你去见它。这只驭风巨豹之灵是来担任你的导师的，好让你能化身为泽风岛上的猎豹形态。$B$B所有德鲁伊最终都会探寻这种智慧，不过看来你们家乡的形态与我们传统的形态略有不同。如果你渴望化身这只灵魂的猎豹形态，就需要接受我们的试炼。$B$B你可以在月光林地南部，双子桥以南的地方找到它。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98342,'zhCN','巨豹之灵','从怒风兽穴找回尖牙圣物、利爪圣物和静影圣物，并将它们交给巨豹之灵。','想借用我的灵力，光说几句话可不够。要理解并尊重我的形态，你必须证明自己能够展现狡诈与潜行，并在走投无路时爆发出凶猛本性。$B$B东边的兽穴中有三件承载我恩泽的圣物，你必须将它们取来。强大而狂怒的灵魂守护着圣物，见到你便会发动攻击。入口处的一尊雕像会暂时赐予你潜行能力，助你绕过它们。$B$B把圣物带回来交给我。我们会看看你是否已准备好化作我的形态。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98362,'zhCN','前往雷霆崖','回到雷霆崖，与长者高地的图拉克·符文图腾谈一谈。','我们又到了分别的时候，年轻人。为了运用所学，你必须回到派你来见我的人身边。看来你的导师图拉克·符文图腾找到了一名出色的学生，我也看到了同样的资质。听从他的教诲，很快你就能借用巨豹之灵的力量，化作它的形态。$B$B回到你来时的地方吧。时机成熟时，我们会再次相见。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (98372,'zhCN','不幸的结局',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98386,'zhCN','奥瑟尔伐木场','为赤脊山的工头奥斯洛消灭奥瑟尔伐木场的12只巨型狼蛛，并摧毁6枚狼蛛卵。','兽人、豺狼人、鱼人。所有东西似乎都想阻止我按时修好这座桥。现在又有消息说，我们的伐木场闹起了狼蛛！$B$B如果你想多赚点钱，就去东边的奥瑟尔伐木场，解决那里的蜘蛛问题。要是我不能安全地派工人收取木料，那地方对我就毫无用处。$B$B噢，如果见到老奥瑟尔，告诉他清理烂摊子的费用该由他来付。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98387,'zhCN','封锁黑石','把8件失窃的武器和10份黑石补给品交给湖畔镇的治安官马瑞斯。','打仗离不开武器。$B$B黑石兽人已经侵入这片土地，行事虽嚣张，却并非无懈可击。$B$B从石堡要塞往东南方去，找到他们的营地，把武器和补给夺过来。$B$B等他们失去这些作战装备，我们就看看他们还剩几分威胁。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98391,'zhCN','艾露恩姐妹会','与达纳苏斯的艾奎恩妮修女谈一谈。','愿神明赐福于你，$C。千百年来，艾露恩姐妹会始终是卡多雷社会的擎天玉柱。$B$B远在大分裂之前，在上古之战的硝烟燃起之前，我们熬过了漫长的岁月，在无尽的黑夜里指引并治愈着我们的族人。这不仅是我们的使命，更是至高无上的月神母亲所下达的神旨。$B$B眼下，有一件十万火急的要事亟需你的援手。艾奎恩妮修女正在达纳苏斯静候你的大驾。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98392,'zhCN','林地潜伏的黑暗','为神谕林地的哨兵阿瑞尼亚·碎云收集仇恨尖啸的护身符、风之主母加德雷丝的护身符，以及巫母阿瑞莎的护身符。','这些腰带……仔细瞅瞅皮革的纹理，$N。你看到纤维里渗透出来的腐化痕迹了吗？$B$B对于这东西的来头，我心里多少有点谱了，但要想下定论，咱们还得找点更硬的铁证。$B$B再去跑一趟西边那群鹰身人的老窝，把她们的首领统统干掉。如果她们脖子上的项链也带着和腰带一样的邪恶气息，那真相就大白了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98393,'zhCN','巨豹之灵','与月光林地永夜港的德迪利特·星焰交谈。','看来你已准备好踏上旅程的下一步，年轻的德鲁伊。德迪利特·星焰传来了消息，希望你再次前往月光林地找他。$B$B你已经学会使用魔法前往月光林地，如果愿意，现在就可以启程。如果你想继续德鲁伊训练，我建议你尽快动身。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98394,'zhCN','巨豹之灵','寻找月光林地南部的巨豹之灵，听它讲述猎豹的天性。','在月光林地南部，有一座山丘俯瞰着桥梁，那里住着一位被我们称为巨豹之灵的睿智而狡黠的存在。$B$B就像巨熊之灵一样，它一直是希望化作猎豹的德鲁伊的导师。所有德鲁伊最终都会寻求它的智慧。如果你希望化作猎豹，也必须如此。$B$B去见巨豹之灵，听取它的教诲。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98396,'zhCN','巨豹之灵','从怒风兽穴找回尖牙圣物、利爪圣物和静影圣物，并将它们交给巨豹之灵。','想借用我的灵力，光说几句话可不够。要理解并尊重我的形态，你必须证明自己能够展现狡诈与潜行，并在走投无路时爆发出凶猛本性。$B$B东边的兽穴中有三件承载我恩泽的圣物，你必须将它们取来。强大而狂怒的灵魂守护着圣物，见到你便会发动攻击。入口处的一尊雕像会暂时赐予你潜行能力，助你绕过它们。$B$B把圣物带回来交给我。我们会看看你是否已准备好化作我的形态。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98397,'zhCN','前往达纳苏斯','回到达纳苏斯，与塞纳里奥区的玛斯雷·驭熊者谈一谈。','我们又到了分别的时候，年轻人。为了运用所学，你必须回到派你来见我的人身边。看来你的导师玛斯雷·驭熊者找到了一名出色的学生，我也看到了同样的资质。听从他的教诲，很快你就能借用巨豹之灵的力量，化作它的形态。$B$B回到你来时的地方吧。时机成熟时，我们会再次相见。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98398,'zhCN','神谕之树','在附近寻找神谕树皮，聆听它传达的启示。','我对你在如此短的时间内完成任务感到非常惊讶，$N。或许我该请求你留下来帮助我……但是我知道接下来还有更艰巨的任务在等着你。$B$B我注意到神谕之树已经脱落了一层树皮，看来又有任务需要你去完成了，你得去和它谈谈。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98403,'zhCN','扭曲的仇恨','消灭8只被污染的树林蜘蛛，并将邪恶的泽索尔手中成熟的魔苔带给多兰纳尔的塔隆凯·捷根。','迈雷纳斯领主可不是一个人在单干；他是受人指使的。你要揪出的是那个外号叫“邪恶者”的泽索尔。看起来，他故意扭曲了栖息在泰达希尔的那些蜘蛛，企图用它们的毒液来酝酿一场肮脏的阴谋。$B$B这家伙一直龟缩在森林的深处，就在西北方那片叫大断崖的地方。一定要多加小心，记得多带几个帮手，这个泽索尔可不是什么好捏的软柿子。$B$B把他的徒子徒孙杀个干净，顺道给我带回点任何能揭露这个萨特在此图谋不轨的线索。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98404,'zhCN','驭风巨豹之灵','从怒风兽穴找回尖牙圣物、利爪圣物和静影圣物，并将它们交给塞利楠的化身。','为了汲取我的灵魂力量，你需要接受一次试炼。要理解并尊重我的形态，你必须证明自己精通狡诈与潜行，并在被逼入绝境时能爆发出足够的凶猛。$B$B就在东边的兽穴里，有三件圣物你必须拿到手。它们由强大的狂怒之灵守卫着，一旦发现你就会立刻发起攻击。入口处的雕像会赐予你暂时的潜行能力，好让你绕过它们。$B$B把这些遗物带给我，完成这片土地上的德鲁伊试炼。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98405,'zhCN','巨豹之灵','寻找月光林地南部的巨豹之灵，听它讲述猎豹的天性。','在月光林地南部，有一座山丘俯瞰着桥梁，那里住着一位被我们称为巨豹之灵的睿智而狡黠的存在。$B$B就像巨熊之灵一样，它一直是希望化作猎豹的德鲁伊的导师。所有德鲁伊最终都会寻求它的智慧。如果你希望化作猎豹，也必须如此。$B$B去见巨豹之灵，听取它的教诲。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98407,'zhCN','力量的展示','为湖畔镇附近的菲尔顿副队长从赤脊山鞭笞者身上收集5个尖刺项圈。','豺狼人竟敢在如此靠近人类的地方扎营，谁也不知道它们还会向前推进多远。我们必须阻止它们。$B$B这些野兽几乎毫无组织，却似乎格外崇尚力量。如果我们消灭它们中最凶恶的成员，再夺取一些战利品，或许就能提醒这些豺狼人，它们应该老老实实留在山里。$B$B如果见到豺狼人鞭笞者，就把它们的项圈带给我。这样应该能让它们重新畏惧联盟。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98423,'zhCN','谅解条约','将这块《谅解条约》亲手交予铁炉堡的麦格尼·铜须。','在金库内部，你找到了一块石板，上面详细记载了铜须与蛮锤两大矮人部族缔结和平条约的具体条款。从年代来看，这似乎是三锤之战刚刚平息时的产物，这绝对是矮人历史上不可多得的重磅史料。如果把这宝贝送给铁炉堡的国王，他绝对会非常感兴趣。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98430,'zhCN','漫行者','帮助佩里斯·雷蹄逃离白鬃石，并前往雷霆崖向凯恩·血蹄汇报他已脱险。','很高兴见到你，$C。是什么让你深入这般黑暗且充斥着暴力的险地？$B$B我是奉大酋长凯恩·血蹄之命来此的，为了尝试与盘踞在这里的豺狼人进行交涉。我的其他任务必须绝对保密，漫行者的所有行动都是如此，我们是大酋长最信任的耳目。$B$B你只需要知道，我们的外交努力换来的全是暴力相向。要是没有你帮我脱身，今晚我恐怕就要沦为这群豺狼人的盘中餐了。$B$B你愿意接下这个任务吗？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`QuestDescription`,`VerifiedBuild`) VALUES (98435,'zhCN','雷角的报告','多亏了你的鼎力相助，我们才在这里取得了进展，雷霆崖的长者们必须知道这个消息。$B$B请把这份报告带给雷霆崖的大德鲁伊哈缪尔·符文图腾。你可以在城市东侧的长者高地找到他。你必须先乘坐升降梯抵达市中心，然后再穿过桥梁才能到达。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98459,'zhCN','美德尽失','把汤姆的礼物交给湿地米奈希尔港的巴特·泰德沃特。','巴特·泰德沃特就是个一毛不拔的吝啬鬼，我跟你说！$B$B他还自称什么“处女号的船长”。那艘船开过的路，跟塔纳利斯的石头挪过的地方差不多远！他根本不是船长，只是个靠打牌赢够了钱、买下处女号的演员！$B$B如果你哪天到了湿地的米奈希尔港，就把这个交给他，告诉他是老半鱼捎来的。$B$B顺便说，这里有船能直达那个港口——第二站就是！$B$B还有，他打牌会作弊！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98461,'zhCN','单相思','把霍莉的字条交给湿地米奈希尔港附近的塔雷尔·石纹。','如果你要离开奥伯丁，我正好有事想请你帮忙！$B$B我的好朋友塔雷尔和我是老同学。哦，一提到考古发掘，他的脑子转得可快了！毕业后我们就各奔东西了——他去了湿地，而我来到了黑海岸。$B$B<霍莉叹了口气，随即微微皱起眉头。>$B$B抱歉，还有他那个妻子……梅林。$B$B不管这些了。如果你要去湿地，能不能帮我确认一下他是否平安无事？顺便把这个交给他行吗？他大概就在米奈希尔港附近。这里刚好有艘船能直达那儿。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98463,'zhCN','街头巷议','去荆棘谷藏宝海湾的水手之家旅店，找尼克拉克斯·菲拉莫格碰个头。','听着，你能来我的酒馆光顾，我打心眼里高兴，也正因如此，我才决定跟你掏心窝子说这事。$B$B想找点真正的刺激？那你得去藏宝海湾的水手之家旅店。没错，就是荆棘谷里大名鼎鼎的那个藏宝海湾。$B$B别拿那种眼神看我。我知道那是地精开的黑店。可调酒师嘴巴闲不住，那些酒客更是能把天给吹破了。我的意思是，如果你想看点真正无法无天的狂欢，去那儿准没错。$B$B尼克拉克斯·菲拉莫格保证让你的酒杯满得溢出来，这你完全不用操心。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98517,'zhCN','火焰的召唤','向泽风岛的塞萨瑞亚·漫空或阿诺尔·风暴打击报到，继续你的萨满祭司训练。$B$B你可以搭乘停靠在莫高雷观天者台地——雷霆崖西北方——的驭空者运输工具返回泽风岛。','你好，年轻的天裔。灵魂提到了你的事，还说你已经准备好响应火焰的召唤。但引导你踏上这条道路的人并不是我。回到元素位面的家园，寻找你在那里的导师。他们会告诉你该做什么。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98545,'zhCN','莱尼德的信','将密封的信函交给幽暗城的格利克斯·希基克斯。','既然你来了，我想请你把这封信交给幽暗城的一位老朋友。我本该亲自送去，但我和黑暗女王的过往有些复杂，还是由中立的第三方送信更好。$B$B你要找的是名叫格利克斯·希基克斯的地精，他就在幽暗城的贸易区。我相信他很乐意补偿你花费的时间。$B$B<莱尼德低声笑着，将信交到你手中。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98574,'zhCN','神圣备忘录','阅读神圣备忘录，并与安威玛尔的布兰斯托克·卡德尔交谈。','你刚才在外面忙碌的时候，有人让我把这个备忘录交给你。如果你有时间的话就看一下吧，好像是牧师训练师布兰斯托克写给你的，他就在安威玛尔里面。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98575,'zhCN','被污染的石板','阅读被污染的石板，并与试炼谷大兽穴中的纳托克交谈。','啊，刚刚你不在的时候，有人送来了这块石板，$N。$B$B一般来说我是不会去招惹术士的，但是如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这是你新上任的训练师纳托克送来的，他有事找你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98576,'zhCN','雕文羊皮纸','阅读雕文羊皮纸，并与试炼谷大兽穴入口附近的迈安交谈。','啊，刚刚你不在的时候，有人送来了这张羊皮纸，$N。$B$B如果你有时间的话，还是看看这上面说些什么的好。如果我没搞错的话，这块羊皮纸是法师训练师迈安写的，她有事找你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98581,'zhCN','古老符文','阅读注能符文石，然后与安威玛尔里面的提欧·暴风之锤交谈。','你刚才帮我忙的时候，有人把这枚符文交给我，让我转交给你。有空就读一读吧。从铭文的蛮锤风格来看，我猜这是萨满祭司训练师提欧·暴风之锤送来的。找时间看看，然后去安威玛尔里面找他。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98731,'zhCN','巨豹之灵的祝福','到月光林地的西北部去寻找巨熊之灵，向它学习关于熊的知识，然后回到月光林地的永夜港去找德迪利特·星焰。','既然你已得到我的祝福，就回到德迪利特那里。他会继续指导你。希望我们有朝一日还能再见。$B$B年轻人，愿暗影永远将你隐匿，愿敌人轻易成为你利爪下的猎物。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98738,'zhCN','驭风巨豹之灵的祝福','到月光林地的西北部去寻找巨熊之灵，向它学习关于熊的知识，然后回到月光林地的永夜港去找德迪利特·星焰。','既然你已得到我的祝福，就回到德迪利特那里。他会继续指导你。$B$B可惜眼下我已没什么可教你的了。希望你有朝一日还能回泽风岛看我。我在你身上看到了潜力，年轻的申多雷。$B$B愿暗影永远将你隐匿，愿敌人轻易成为你利爪下的猎物，也愿长风指引你的脚步。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98739,'zhCN','巨豹之灵的祝福','与德迪利特交谈。','既然你已得到我的祝福，就回到德迪利特那里。他会继续指导你。希望我们有朝一日还能再见。$B$B年轻人，愿暗影永远将你隐匿，愿敌人轻易成为你利爪下的猎物。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98815,'zhCN','高地兽皮','将4张灌木丛迅猛龙皮交给米奈希尔港的制皮匠詹姆斯·哈洛兰。','高地那头埋着不少遗迹，眼下正有一支探险队在发掘里头的秘密。不过我知道的，也就是那片山间沼地里潜伏着当地的野兽。不如你叫上几个全副武装的朋友进去探探路，回头咱俩做笔买卖，如何？$B$B不管那帮畜生有多能躲，我要的是它们的皮！替我剥四张灌木丛迅猛龙皮回来，我包管给你开一个值当的公道价。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98824,'zhCN','史前棱镜','将这件泰坦圣物带给铁炉堡探险者大厅的资深探险家麦格拉斯。','瞧瞧这各个截面上刻着的符文，看着就像泰坦的手笔，除了铁炉堡的探险者大厅，天底下就没别的地方配收下它！$B$B我已经能预见到馆藏总录上青史留名的样子了——“由$N起获！勘察员维尔加亲自鉴定……”哎呀，瞧我，一激动就扯远了！$B$B资深探险家麦格拉斯会亲自接见你。鉴于你手中这宝贝精妙绝伦，你要是肯捐给博物馆，他老人家绝不会亏待你！$B$B干得漂亮，真是捡到大宝贝了！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98887,'zhCN','暗矛群岛之战','把3枚暗矛群岛荣誉奖章交给战场外的部落战争使者。','塞拉摩远征军十分顽固，还在不断增派援军，妄图死守他们在暗矛群岛的阵地。$B$B去吧，让他们见识一下部落的力量！把这处关键战场的胜利凭证带回来，我会重重有赏。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (98888,'zhCN','暗矛群岛之战',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98895,'zhCN','暗矛群岛冲突','将3枚暗矛群岛荣誉奖章交给战场外的联盟准将。','我们与暗矛突袭者的战斗愈演愈烈。若不火速驰援，暗矛群岛必将落入敌手。$B$B身为联盟的一员，你绝不能坐视此事发生。把你在前线立功的凭证带回来，联盟会将你奉为英雄！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (98896,'zhCN','暗矛群岛冲突',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98906,'zhCN','暗矛群岛之战！','在暗矛群岛战场取得一次胜利，然后返回商旅海岸向尼祖克·布夫复命。','暗矛群岛的战局还僵持不下，$C。让那群联盟蠢货看看谁才是真正的强者。$B$B昂起头来，为暗矛而战，夺下胜利。洛阿一定会赐福于你，$C！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99046,'zhCN','失踪的信使','沿通往神谕林地的道路寻找哨兵埃拉莉亚·叶影。','森林议会前些时候派出一小队哨兵前往神谕之树。神树会把讯息交给我们的长老，而我们则负责将讯息安全送到达纳苏斯。$B$B我刚刚得到消息，最近派出的信使至今仍未抵达。神谕之树传递讯息的时间本就不固定，但这次实在拖得太久了。$B$B请沿西边的道路前往神谕林地，看看她出了什么事。这次本该轮到埃拉莉亚·叶影，而她还只是个见习哨兵。愿艾露恩指引你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99047,'zhCN','尚存一息','前往多兰纳尔向拜恩希求助，救治哨兵埃拉莉亚·叶影。','我和姐妹们……奉命……前往神谕之树……$B$B树……传来讯息。我……鹰身人……到处都是……$B$B<埃拉莉亚咳出一口鲜血，痛苦地皱起眉头。>$B$B我恐怕……撑不了多久……等不到救援了。求你……去多兰纳尔……找拜恩希……',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99048,'zhCN','失踪的碎手','在提拉加德城堡以北找到赫格兰·影眼。','碎手氏族的一名成员原本一直在远处监视提拉加德城堡。他们这群人的战斗方式向来比较……隐秘，可她的报告突然彻底中断了。$B$B我不认为那些人类士兵有本事抓住她，所以担心是有更危险的状况发生了。去看看能不能找到她。但愿只是消息延误。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99049,'zhCN','来自深海的威胁','寻找袭击赫格兰·影眼的凶手留下的线索。','附近一片狼藉，到处都是激战留下的痕迹。伏击赫格兰的凶手显然也没能全身而退，周围应该留有线索。$B$B奥戈尼尔多半会想看看袭击者留下的证据。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99050,'zhCN','巨树的馈赠','为多兰纳尔的拜恩希收集6份沾露的鞭笞者叶片、一个空瓶和一份清凉的泉水。','我需要你帮忙找齐材料，暂时压制埃拉莉亚体内的病症，好让她有时间回到这里接受进一步治疗。$B$B所幸这片生生不息的家园依然物产丰饶，会在我们需要时伸出援手。$B$B最关键的是沾露的鞭笞者叶片。正南方的奥拉密斯湖周围就有，西北方的涌泉湖及下游河岸也能找到。$B$B此外，我还需要一个空瓶和一些泉水。这两样在镇上可以买到，也可以找人交换。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99051,'zhCN','来自深海的威胁','收集9份纳迦脊鳍。','那些蛇崽子已经不是第一次来骚扰我们了。得让它们明白，这里容不得它们撒野。$B$B找到它们斥候扎营的地方，把它们杀个干净，再带回它们的鳍作证。动作要快，务必让它们记住这次教训。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99053,'zhCN','逃离班尼希尔','帮助哨兵莱妮莎·暮花逃出班奈希尔兽穴，并向多兰纳尔的哨兵凯拉·星歌禀报她已安全脱险。','我的祈祷终于有了回应！感谢你一路杀到这里。$B$B神谕之树派我来给此地沉睡的德鲁伊传递讯息，没想到这里早已被熊怪占领！我还没来得及折返，就遭到伏击，被它们拖到了这里——恐怕我就要成为它们的下一顿饭了。$B$B不知道你怎么想，反正我恨透了这个地方。地底绝不是卡多雷该待的地方。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99073,'zhCN','缓解痛苦','把鞭水愈膏带给通往神谕之树道路旁的哨兵埃拉莉亚·叶影。','药膏已经调好了，快给埃拉莉亚送去。$B$B我不知道这药能不能真正治好她。腐化溃烂得极快，而且越蔓延，力量越强。$B$B但至少，它能减轻痛苦。只为这一点，你也必须争分夺秒。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99079,'zhCN','漫行者玛拉','在血蹄村以东、靠近莫高雷边缘的地方寻找漫行者玛拉·长风。','漫行者是我们族人最信赖的斥候。虽然他们只听命于大酋长，但年轻的贝恩偶尔也会请他们相助。$B$B这次正是如此。漫行者玛拉奉命前往东部边境附近，离开三天后，昨夜仍未归来。遇到这种情况，我们有责任确认她是否安全。$B$B我必须留下守卫村庄。你去寻找玛拉，以此证明自己。漫行者都佩戴发带、手持羽饰法杖，你可以凭这些特征认出她。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99080,'zhCN','将他们驱逐出去','消灭6名加拉克半人马、4名加拉克前锋，并将掠夺者赫拉克的头颅带给贝恩·血蹄。','把我的话听好了：我们绝不会向半人马让出一寸土地，一根草都不行！$B$B他们还没休息好，来不及向村庄发起冲锋。趁现在杀进营地，把他们统统杀光。绝不能让任何活口逃去贫瘠之地搬救兵。$B$B如果找到了这群袭击者的头目，就把他的脑袋带回来。我要用它警告那些胆敢践踏我们祖辈家园的家伙。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`QuestDescription`,`VerifiedBuild`) VALUES (99081,'zhCN','噩耗','顺着玛拉背上箭矢射来的方向望去，能看到一座似乎刚刚搭起的半人马营地。那里人影攒动，看来一支小型劫掠队已经潜入莫高雷。$B$B这位漫行者的手中仍紧攥着一份报告。卫兵萨拉莫尼·野蹄会想知道玛拉的遭遇——以及杀害她的凶手是谁。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99082,'zhCN','大酋长','前往雷霆崖求见大酋长凯恩·血蹄。','你挺身守护族人的勇气，应当得到嘉奖。前往西北方的雷霆崖，求见我的父亲。那座雄伟之城高耸入云，炎热时节，崖壁投下的阴影会为我们遮阳。$B$B当年正是他与年轻的大酋长萨尔并肩冲锋，夺回这片平原，将半人马彻底赶走。你以行动传承了他的勇气；身为大酋长，他定会慷慨嘉奖你。$B$B大酋长位于中央高地，你必须乘坐升降机才能抵达。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99101,'zhCN','古老的宿敌','将漫行者玛拉的报告带给贝恩·血蹄。','贝恩·血蹄是我们村庄的领袖。他必须立刻得知这次入侵。$B$B把漫行者玛拉的报告交给他。他就在村子中央。$B$B快去，不能再耽搁了！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99108,'zhCN','切磋比试','为塔恩·石蹄在决斗中击败3名玩家或新手战士。','你好，年轻的$C。虽然你并非战士，我也无法领你入门，但这不代表你不能从我这里学到点什么。$B$B竞技场就在你的眼前。踏进这片场地，不管你的出身，也不管你手里端的是长剑还是硬弓，众生皆平等。所有人都得在死斗中磨出自己的血性。$B$B你可愿下场比划比划，亲身领会我们的生存之道？去挑个顺眼的新手，或者随便找个敢应战的对手。我不在乎你揍谁。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99123,'zhCN','迷失于暗影','帮助帕尔朱逃离科卡尔峭壁，然后前往森金村，向沃纳尔大师报个平安。','我一时逞强，独自摸进峭壁侦察。偏偏在最要命的时候耗尽了魔力，只好一直窝在这里躲避风头。$B$B你要是能搭把手带我逃出去，这恩情我一定记下。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99127,'zhCN','渔网横祸','检查水晶湖里的捕鱼陷阱。','今天这鱼像是中了邪，死活就是不咬钩。水里绝对出了大问题——绝不只是空军那么简单，整片水面我甚至连条小鱼苗的影子都没见着。$B$B李昨晚在这儿下了几网，你去替我瞅瞅，看网里好歹有没有兜住点东西。要是碰到什么邪门的情况，一定要回来告诉我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99128,'zhCN','黏滑的威胁','在水晶湖杀死7只鱼人和4只鱼人士兵，然后向贾森·玛瑟斯复命。','准是湖对面那帮鱼人干的好事！这群小杂碎要多恶心有多恶心，脾气还跟它们那口尖牙一样臭。$B$B要是任由它们接着闹腾，水晶湖里迟早连一片鱼鳞都剩不下。你要是能替我清剿掉一批，那可真是帮了我的大忙了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99129,'zhCN','谈谈鱼人的事','找雷米谈谈贾森碰上的鱼人麻烦。','前几天雷米也跟我念叨过鱼人的事……我敢打包票，他绝对跟我一样恨透了这帮小畜生。$B$B他脑子活络，也许有法子让这帮怪物以后再也不敢打我鱼群的主意。你去替我跑一趟，找他探探口风，看他能憋出什么好屁来。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99130,'zhCN','诱人的提议','收集6瓶动物血液和18份暮草花瓣以制作鱼人诱饵，然后向闪金镇的雷米复命。','要整治这帮鱼人，我脑子里有的是招，其中一招还能顺手帮别人一把。$B$B这附近农田里经常长一种叫“暮草”的野草，只要剂量够大，它的花瓣就能毒翻大部分牲口。我们只要把这玩意儿掺进鱼人诱饵里，包准能给那帮小畜生狠狠上一课，让它们再也不敢靠近鱼群。$B$B而且去地里拔草，等于顺手帮农夫除了害。这可真是双赢……彻头彻尾的双赢啊。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99131,'zhCN','诱饵制胜','向贾森·玛瑟斯复命。','去告诉玛瑟斯，他今天晚些时候就能来提货。到时候我会手把手教他怎么用。$B$B希望他能早点把他的卖鱼摊重新支起来。至于咱们嘛，就当是替这世界清理鱼人垃圾了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`QuestDescription`,`VerifiedBuild`) VALUES (99134,'zhCN','整肃纪律','既然你还不是亡灵卫兵的一员，自然也就还没干出什么让我糟心的蠢事。$B$B看在你相对还算机灵的份上，我给你个差事——去替我收拾那帮成事不足败事有余的饭桶。$B$B动作快点。你叫$N，对吧？别逼我把你的名字也记进悬赏账册，让别人来领你的赏金。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99142,'zhCN','墓穴杂草','收集5株墓穴杂草，把它们交给初级药剂师霍兰德。','如果你正要去东边的那座巴尼尔农场，顺道再替我办点事。这年头想找个不添乱的帮手比登天还难，你跟葛尔多那堆烂肉打过交道，想必深有体会。$B$B每当我搞到末日草，我都会用炼金术稍微“改良”一下，再种到那座农场去，培育我最完美的杰作。我管它叫“墓穴杂草”——等着看吧，它必将开启我无比辉煌的命运！$B$B你在那边办事的时候，顺便盯着点附近的天灾爪牙。它们似乎……对这种草很着迷。真有意思。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99143,'zhCN','破铜烂铁','从附近的鱼人营地里搜刮6件闪亮的破烂。','这帮鱼人的脑回路估计跟真鱼没什么两样，对吧？也就是说，它们相中的宝贝，水里的鱼肯定也喜欢！$B$B你去它们的垃圾堆里翻翻，要是能掏出点适合做鱼饵的小玩意儿带回来，我绝对少不了你的好处。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99152,'zhCN','地上生变，地下招灾','为破坏者希尔达收集6根散发微光的骸骨。','西南方影谷里那帮黯淡者固然是个大麻烦，但我们同样不能放任镇子底下的地窖继续恶化，否则迟早会在班达里安堡掀起一场天灾暴乱。$B$B要是真有那一天，我手底下的这群新兵必须得能扛起事。至于你，我要给你上点强度，来一趟真正的“魔鬼速成课”。$B$B潜进影谷的地下室，去给老娘敲点那种怪物的烂骨头回来研究。记住了，我要那种还残留着复生魔力的货色——也就是会发光的那种。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99153,'zhCN','漏网之晶','替埃弗拉姆·巴巴罗找出藏在影谷地下的水晶碎片。','喂！我们这儿消息传得可快。听说你在纳克萨玛斯的废墟那边，把那群邪教徒收拾得挺利索？$B$B问题是，有个漏网之鱼顺走了一块聚焦水晶的碎片。那玩意儿里面似乎还残存着力量。我们估摸着，它现在就藏在影谷地下的某个地方。那东西要么在唤醒死尸，要么在强化他们——不管哪种，绝对没好事。$B$B趁这烂摊子还没彻底失控，赶紧把那块水晶给我挖出来。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99156,'zhCN','巡查后方','把撕裂者的心脏交给亡灵卫兵林奈。','该死！你出去巡逻这会儿，又送来一份新报告。有人在提瑞斯法林地东部、毒蛛峡谷那带，看见一只脱离控制的憎恶在瞎转悠。$B$B事情不对劲。这种大块头绝不可能悄无声息地溜过亡灵壁垒。$B$B把嘴闭严实，这事不准外传。不过话说回来，那头缝合怪可不是纸糊的，不想变成它的下一顿口粮，就去多找几个帮手。$B$B把这事办妥，少不了你的好处。把它的心脏挖回来见我，就当是交差的凭证。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99158,'zhCN','群山中的曙光','把那箱蜡烛送到雾松避难所，交给伽文神父。','山里住着位神父，属于银色黎明。这个神圣组织专门搜寻并消灭邪恶、反常之物。$B$B不过，伽文神父更愿意治病救人，而不是拿起武器。他把一栋老房子修整好，改成旅人歇脚的地方，取名“雾松避难所”。我这儿有批圣烛要送给他。你要是顺路，能帮我送去吗？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99159,'zhCN','寻得暖意','收集14份木柴。','这里的炉火愿为每一个灵魂驱散严寒。不过，如果可以的话，我想请你帮个小忙。$B$B我的柴火快见底了。平时这都是我自己去劈，可最近杂事缠身，实在抽不开身。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99160,'zhCN','霜寒之怒','消灭10只小型冰元素。','你大概已经留意到附近那些元素生物了。几天前，山顶塌下来一大片冰岩，惊扰了它们。$B$B对普通的矮人或人类来说，这片雪山本来就够要命了，更别提现在连元素都跑出来作祟。我这把老骨头已经打不动了——所以，哪怕你只能除掉几只元素，也能让这条山路少几分凶险。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99161,'zhCN','霜寒之怒','击杀阿瓦拉并带回其核心。','我注意到，雪崩后第一个冒出来的元素，个头比其他同类大得多。据我观察，最近莫名其妙的天气突变，还有那些小规模的塌方，恐怕都是它搞的鬼。$B$B我叫它“阿瓦拉”。如果你能除掉它，带着它的核心回来见我，我绝不会让你白跑一趟。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99162,'zhCN','冰雪无情','收集遇难巡山人的步枪。','就算是铁炉堡的老练巡山人，在这丹莫罗的群峰里走动，也得时刻打起十二分精神。一阵落雪碎冰，往往就能要了那些新兵的命。$B$B每次雪崩之后，我总会去附近找找有没有幸存者，或者……遇难者。一边找，一边向圣光祈祷最好什么也别发现。但最近元素闹得太凶，我没敢走远。如果你能去找找那些失踪的巡山人，把他们的步枪带回来，我会想办法把遗物送回铁炉堡。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
