INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99260,'zhCN','菲里昂的任务','与瓦拉纳尔的伊拉德林·晚风交谈。','我奉命去瞰台立石采集元素能量流动的数据。要想安全往返天空之墙与艾泽拉斯，我们就离不开这些数据。没有它们来辅助计算，破天船就无法顺利穿越元素位面。$B$B如今数据多半已经丢了，我这副样子，也没法再去采集一次。我已向至高法师说了你救我的事，他想再见见你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99411,'zhCN','凯雷失踪了！','莫高雷血蹄村的阿哈布·麦蹄请你喂饱他的宝贝小狗——疯狂的凯雷。$B$B用鲜嫩的陆行鸟肉喂饱凯雷，然后向阿哈布·麦蹄复命。','帮帮我，$N！我的宝贝小狗凯雷跑丢了！它肯定还在血蹄村里乱跑，迷了路，饿着肚子。$B$B你能找到它，喂它吃点东西吗？吃饱了，它就会消停下来，乖乖回家。$B$B你得先弄点吃的。它最爱鲜嫩的陆行鸟肉。往东走，那边应该有不少陆行鸟。猎杀一只，把鲜美的肉带给凯雷。在村里见到它后，就把肉放在地上，它准会跑过来找你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`QuestDescription`,`VerifiedBuild`) VALUES (490,'zhTW','懸賞：瘤背熊怪','根據哨兵的法令，我對瘤背部落發出通緝令。它們已經不再是森林的朋友，而是威脅著我們的人民和這片土地的墮落的怪物。$B$B根據命令，任何能幫助泰達希爾減輕熊怪的威脅的冒險者都可以獲得嘉獎。如果你也有志於幫助我們的話，就把它們的利牙帶給我作為證明。$B$B你可以在多蘭納爾西方、道路南側的班尼希爾谷地，以及東方的星風村找到大量熊怪。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (960,'zhTW','正在冥想的安努',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (1288,'zhTW','維米斯的報告','把維米斯的報告送給塞拉摩的珍娜·普勞德摩爾女士。','你的表現不錯，$N，算是我見過的非專業人士中最好的。$B$B普勞德摩爾女士讓我把這件事的新消息都報告給她，不過我已經有一段時間沒去見她了。$B$B我正準備把我的報告給她送去，不過你去和她談可能更合適一些，因為你應該能比我更好地回答她的問題。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`QuestDescription`,`VerifiedBuild`) VALUES (6241,'zhTW','冬泉熊怪的活動','木喉部族傾向於防守，$N。雖然我們允許那些值得信賴的朋友安全地通過，但我們還是盡可能地避開其他熊怪部族。$B$B最近我注意到冬泉部族與我們的敵對情緒有所增長。他們似乎處於極度憤怒的狀態，完全陷入了對一切他們無法理解的事物的恐慌和仇視。$B$B如果你能削減他們的數量，那對我們來說將是莫大的幫助，$N。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`QuestDescription`=VALUES(`QuestDescription`);
