INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (65593,'zhTW','戀人的心臟','把艾芙琳娜‧莉蕾和艾薩克‧佩爾森的心臟交給詛咒神殿的凱倫丁。','夢魔會受到戀人的心吸引，越刻骨銘心的愛情，那誘惑就越難以抵抗。$B$B我的占卜揭示出兩個可能非常有用的人選。$B$B在銀松森林，有個艾芙琳娜‧莉蕾為安伯米爾的墮落巫師縫製服裝。 在貧瘠之地，有個艾薩克‧佩爾森希望在靠海的棘齒城打下自己的一番天地。$B$B他們在世界的兩頭辛勤工作，但是他們的心只渴望彼此。把兩顆心臟帶去給凱倫丁。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (65597,'zhTW','誓縛','使用這對戀人的心臟，把夢魔召喚出來然後加以制伏，再把戀人的心臟送去給幽暗城魔法區的凱倫丁·哈加爾。','是時候了。把心臟放在下面那個召喚陣的中央，然後召喚夢魔。$B$B惡魔意識到自己被你引誘到陷阱裡面時，會非常不高興。別淪為對方的獵物，$N，你必須完全制服惡魔才行。$B$B這樣一來我就能教你咒語，讓你使喚夢魔。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (65601,'zhTW','痛心的愛','和奧格瑪的瑪加爾交談。','薩亞德的男性被稱為夢魔，是一種骨子裡散發邪惡和奇異思想的生物。$B$B你必須使用媒介來引誘惡魔進入我們的世界，一個足以代表偉大愛情和奉獻的媒介。$B$B如果你相信我這個瞎子能夠幫助你的話，那就聽著吧，$N。從暗影裂谷向東走，穿過奧格瑪的主要街道，就會找到瑪加爾。他一直在等他的伴侶克里吉回來。$B$B去找他，他會要求你協尋某種重要的東西，這同時是你必須帶去給甘盧爾的關鍵事物。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (65602,'zhTW','愛為何物?','取回木雕刻像，然後交給暴風城法師區的『黑暗縛靈師』加金。','你需要足以代表偉大愛情和奉獻的強力媒介來引誘夢魔。$B$B我占卜了一下，發現一個屬於一對年輕愛侶的物品，應該很適合用在你的儀式裡面。$B$B數千年前，有個屬於一對年輕愛侶的刻像。雖然當時的擁有者已經不在了，不過這個紀念品仍留存至今。$B$B沿著路，一路向北進入梣谷，然後向西，經過邁斯特拉崗哨，接下來會看到一棟蓋在樹上的房子，你會在那裡找到你要的東西。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (65603,'zhTW','誓縛','使用木雕刻像來召喚夢魔並加以制伏，然後將木雕刻像還給已宰的羔羊旅店的『黑暗縛靈師』加金。','是時候了，拿著刻像走進下面的地下室。召喚陣已經準備好了，記得把刻像放在中心點。$B$B接著就會開啟通道，讓夢魔進入我們這個世界。$B$B千萬別低估薩亞德，一旦惡魔意識到這是你的詭計，會立刻發動攻擊。你必須利用你學過的一切來打敗對方。$B$B等你成功了，就回到我身邊，我會把這個生物與你的意志結合在一起。要是失敗了，你的靈魂就會被收走。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (65604,'zhTW','誓縛','使用乾癟的圍巾來召喚夢魔，然後加以制伏，再把乾癟的圍巾交給奧格瑪的甘盧爾·血眼。','沒錯...我明白了，我感覺到殘留絲線中的情緒，每一針都融入了愛情，夢魔絕對無法抗拒這種誘惑。$B$B$N，帶著這個站在尼爾魯帳篷裡的召喚法陣上面，接著召喚邪惡的夢魔，然後展示你的能耐給他看看。別指望對方會乖乖任你制服，準備好你要用的魔法，做好戰鬥準備，許多術士最後是死於低估惡魔這種錯誤。$B$B打贏之後，把布拿回來給我，我會讓瑪加爾知道你的收穫。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (65610,'zhTW','真希望你也在這裡','調查梣谷的墜星湖，然後向奧格瑪的甘盧爾·血眼回報。','我在梣谷製作月布的時候認識克里吉，他駐紮在那裡保護當地居民，後來卻失蹤了…$B$B他們停止搜尋，把他認定是逃兵，可是我不這麼認為。$B$B我們之前常常在墜星湖碰面，不過後來湖那邊到處都是凶猛的沼澤野獸。$B$B我通常不會請人幫我忙，但是你願意去梣谷搜尋他的下落，我會很感激你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (76156,'zhTW','與大地之母一同追獵','潛入風險投資公司在雷霆崖東南方的礦坑、從爆破補給品的推車中收集5個爆鹽採礦炸藥，並到雷霆崖將它們交給波爾頓‧暗影圖騰。','$C，我發現你有隱匿行蹤的絕技。用這個面具潛入附近的風險投資公司礦坑，並竊取他們的補給品。這樣的偽裝雖然很難騙過其他人，但高超的盜賊只要透過迷人的微笑和合時宜的誘騙伎倆就可以溜過任何守衛。我相信你也有這樣的能力。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (76160,'zhTW','與大地之母一同追獵','在雷霆崖北側收集8個風怒果，用研缽和搗杵將它們磨碎之後，回到雷霆崖將結果告訴波爾頓‧暗影圖騰。','比起偽裝，也許你對毒物比較在行。北邊的鷹身人會在有劇毒樹脂的樹上築巢。在巢的附近收集掉落的松果，並將它們搗成膏狀。將這個藥膏塗抹在刀刃上，你的刀刃就可以深深砍入敵人的肉體中，讓他們的傷口無法癒合。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (76240,'zhTW','與大地之母一同追獵','購買或捕捉一隻新鮮的美味小魚，接著用到雷霆崖在波爾頓‧暗影圖騰面前用刀具組處理小魚。','我想我還有最後一個辦法會成功。我依舊認為你有潛能，但這次我們不要用這麼直接的激發方式。$B$B去抓一隻生鮮的美味小魚，然後把牠帶回來吧。接著用這些匕首把魚清乾淨然後切塊。不要想得太複雜，跟著直覺走就對了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (78091,'zhTW','爭取你的鹽巴','在赤脊山的黑石召喚師身上收集 14 個召喚者之鹽，接著再回到暴風城找厄蘇拉·德林。','我會細細研究這顆珠子並告訴你我的發現，但你得先幫我一件事。$B$B黑石術士可以使用特別處理過的鹽巴來強化召喚儀式。幫我去赤脊山的獸人身上收集一些來吧。$B$B你回來之後，我就會跟你分享我的研究成果的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
