INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (79007,'zhTW','…你找到的紙條','燒灼的紙條殘骸是你唯一的線索。','<餘燼的微弱光芒逐漸變得昏暗，你偶然發現了近期才被大火吞噬的廢墟。$B$B在四散的糧食中，你發現了一張起泡的紙條。>$B$B「燒掉的東西不會因此消逝。尋找孿生之地，找到正確的地點。」',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (79008,'zhTW','…你找到的紙條','燒灼的紙條殘骸是你唯一的線索。','<餘燼的微弱光芒逐漸變得昏暗，你偶然發現了近期才被大火吞噬的廢墟。$B$B在四散的糧食中，你發現了一張起泡的紙條。>$B$B「燒掉的東西不會因此消逝。尋找孿生之地，找到正確的地點。」',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
