INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (79192,'zhTW','墊腳石','你將木板上的紙條撕了下來，閱讀上面的草寫文字。','紙條的開頭寫著：「任務指出，他們在運送新瘟疫。在我看來，似乎只是單純的藥劑實驗意外。如果你想要找個可以安心說話的地方，可以到貧瘠之地和淒涼之地之間的山中，找我的秘密基地。」',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`QuestDescription`,`VerifiedBuild`) VALUES (79358,'zhTW','風暴、大地和火焰','$N，要淹沒千針石林可不是件小事。要不是我自己感受到了元素們的憤怒，我是絕對不會相信的。但這就是我們現在面臨的局面。$B$B野豬人不是第一批不負責任地將元素武器化的人，也絕對不會是最後一批。如果我們想準備好自己的反制儀式，就必須更深入地了解這些扭曲的元素。這本書拿去，裡面詳細記載了艾澤拉斯的許多居民以及他們是如何實踐薩滿信仰的。$B$B如果你能從他們身上學到東西，或許我們就能找到解決辦法。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (79360,'zhTW','元素援助','在剃刀沼澤擊敗卡爾加‧刺肋，並收集關於野豬人計畫的情報。','既然你已經掌握了元素，你對它們就負有一份義務，也對整個艾澤拉斯本身負有責任。我們做的是祈求它們的協助，我們不會強求它們的力量。現在是時候回報你所獲得的恩惠了，而且我想我知道該怎麼做。$B$B野豬人為了自身的目的而扭曲元素，而且似乎正在將勢力範圍延伸到這些疆域之內。進入他們的沼澤，徹底終結他們的陰謀。我們必須保護這片土地。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (79362,'zhTW','格蘭特的盾牌','在烏鴉嶺墓園的其中一個骷髏身上找到格蘭特的釘錘，然後回去夜色鎮找希拉‧沃寧迪，取得更多資訊。','維洛家族之主兼烏鴉嶺的英雄，格蘭特‧維洛的幽魂留下了一面盾牌。$B$B既然格蘭特的靈魂仍在與不死族戰鬥，也許他未竟的遺願是殺死在烏鴉嶺墓園傷害他的天譴軍團成員。目標很可能是身上嵌著他的釘錘的傢伙。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (79363,'zhTW','希爾薇雅的劍','到腐草農場擊敗7個迪菲亞夜賊和7個迪菲亞附魔師，然後回去夜色鎮找希拉‧沃寧迪，取得更多資訊。','烏鴉嶺守衛希爾薇雅‧維洛的靈魂留下了一把劍，她終其一生都在守護平民和他們的家園。$B$B既然希爾薇雅的靈魂仍在造訪農莊，也許她未竟的遺願是把鳩占鵲巢的迪菲亞趕出烏鴉嶺南邊的腐草農場。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (79364,'zhTW','注意天空','在千針石林與普拉特‧雲眼交談。','你發現的筆記上寫著，鋼鬃野豬人已經挖入了千針石林的地下，正在進行某種不為人知的儀式。發狂的風暴與上漲的潮汐…$B$B這些野豬人一定是使用了從西澤克那裡學到的殘忍巫術，他是一位竭盡所能去扭曲元素的薩滿。如果他們計劃要淹沒這座峽谷，那將會需要毀滅性的元素力量。$B$B我們目前的裝備不足以應對這種局面，但像你這樣的強大薩滿一定會有辦法。回到你的盟友那裡，看看你能不能找到解決方法。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (79535,'zhTW','石化蜥蜴：應該害怕石化嗎？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
