INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (79974,'zhTW','濕身秀','拍掉從土裡冒出來的信差包上的灰塵，你發現補給品之中有一張羊皮紙。','「我總是喜歡在身邊藏些物資，以便在需要馬上逃命的時候，可以說走就走。$B$B這一側的山坡風景非常美麗，令人讚嘆時間瀑布的鬼斧神工。$B那是老鷹的巢，也就是你在找的東西。」',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (79975,'zhTW','鷹之拳','水花讓空氣變得潮濕，景色令人嘆為觀止。','<你在工具箱中發現一封被人細心摺好的信。>$B$B「從這裡開始，只要擁有正確的工具，何時出發由你決定。這是發射降落傘滑翔翼的絕佳地點。$B$B我對鷹與拳忠心無比，但卻需要保持距離，才能好好為他們效力。這個障礙物早已破舊不堪，正如同它曾一度守護的舊王國，但我永遠不會拋棄它。」',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (79976,'zhTW','必是此地','不管這裡的人是誰，你都剛好錯過對方。','「所以，我決定帶著我的成果回到地下，防止它落入錯誤的人手中。」$B$B<撕下的紙張大小剛好能夠容納這則訊息。你不確定作者想說的話到此為止，或者這又是指向下一個藏身處的線索。有個沒固定好的睡袋正自行展開，蓋住你的腳…>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (79980,'zhTW','匆匆忙忙','找出等待著你的事物。','「嘿，還不賴吧？既然你在看這張紙條，就代表我的私藏物品還留在那裡。向北走一百步，還有，下陡坡的時候小心別扭到腳。到了之後，那裡應該有足夠的東西可以讓你撐下去。」',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
