INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (86574,'zhTW','補足石爪補給品','從巨翼蠍尾獅身上收集6個石爪補給品，並送去給旅店老闆法拉莉雅。','<不幸遇害的屍體身上有著巨翼蠍尾獅留下的傷痕。被棄置在附近的包裹相當凌亂，內容物也已遺失，只能從送貨員緊緊握在手裡的一張小紙條推測丟失的物品：寄給石爪峰的旅店老闆法拉莉雅。>$B$B<蠍尾獅可能把補給品拿去裝飾巢穴了。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (86585,'zhTW','逝者旌旗','揚起鐵爐堡的旌旗，呼喚穴居怪劈頭者並將其擊殺，之後去找拉格弗斯上尉回報。','死去的巡山人身上背著一面鐵爐堡的旌旗。或許她生前是在偵察，或者是進行孤注一擲的突擊。無論如何，旌旗都已被棄置並遭到踐踏。巡山人的頭部遭到重擊，力道之大，使她的頭盔被敲了下來，而她立刻就被穴居怪殺死，用的很可能是帶刺的棍棒。$B$B殺死她的穴居怪可能還在附近，應該也還記得這面旌旗。再次揚起鐵爐堡的旌旗或許能引他出來。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (86614,'zhTW','浪潮中的絕美白銀','把刺著字母的銀色髮夾還給它的主人。','<在漁具的殘骸中有一些生鏽的魚鉤、斷裂的釣線，還有一個略為腐蝕、上頭還刻著「K.D.」的華麗銀製髮夾。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (86667,'zhTW','雪縛','將一罐雪帶去洛克湖西北岸的諾里克‧洛克賽恩自宅，並交給他本人。','我的老導師諾里克派了一隻次級元素生物過來，還帶了一個奇怪的要求。他的薩滿工作需要一罐雪！我不知道他要拿雪來做什麼，但很久以前我就學會了不要質疑他對魔法的運用方式。$B$B我忙著研究當地的元素生物，所以無法離開去幫他。前往常年積雪的南門小徑，那裡有個隧道入口，用這個陶罐裝一點雪，並在雪融化之前帶去給他。這個陶罐應該能保持低溫。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (86757,'zhTW','拖延獸人','把6把鋸齒獸人之劍4把弧形獸人匕首交給珊蒂瑞亞。','獸人佔據了森林東部，那裡到處都是他們的斥侯與蠻兵！梣谷對我們來說再也不安全了。$B$B我們必須擊退獸人，奪回森林。我們會偷偷潛到他們營地附近，來解決掉他們的蠻兵和斥侯。$B$B解決掉那些獸人，然後把他們用的鋸齒劍和弧形匕首帶回來給我。我們可以再利用這些搜刮來的武器，這樣就不會浪費資源了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (86758,'zhTW','痛上加痛','尋找並擊敗鱷魚匕牙，然後帶回馬瑞可的刀子。','我有跟你說過有鱷魚差點把我的手咬下來嗎？當時我就把刀子往牠的嘴裡一插，才逃過這場慘劇。我以為我的刀子會在這附近，卻都找不到。$B$B不管怎麼說，那隻鱷魚或許還在這個湖邊等著獵物上門。為了獵人的安全，必須解決掉那個可惡的怪物。$B$B我幫牠取名叫匕牙。如果你有看到牠的話，記得幫我跟牠打聲招呼！我的「打招呼」當然是指給牠「顏色瞧瞧」了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (87288,'zhTW','柔軟豹皮','將6張柔軟的夜刃豹毛皮帶去給奧卓亞。','哈囉，旅行者！希望你喜歡我們的村莊。我喜歡多蘭納爾是因為這裡是個溫馨的小鄉村，而且大家都很友善。$B$B我是本地的商人，我這裡有賣各種能在你的旅途中派上用場的工具和飾品。老實說，如果你有興趣交易，我現在確實需要一些夜刃豹毛皮。雖然這些莊嚴的生物很美麗，但這裡的夜刃豹卻相當有攻擊性，所以你也不用為自己的自衛行為感到愧疚。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (87760,'zhTW','神聖潛水者','找到雷鱗訓獸師，殺死她，並帶回她的深海支配魔棒。','我收到了達納蘇斯的回信，$N！$B$B透過那些動物樣本，我們得知納迦統御著這些海洋生物，強行把牠們變成坐騎和馱獸。如果這些生物野性難馴，或是年邁或身受重傷，都會被他們趕出去，當作消遣。真令人髮指！$B$B阻止這一切是我們神聖的使命！$B$B有支納迦部隊正駐紮在瑪塞斯特拉廢墟，他們一定正在抓捕海岸上的蛇頸龍。找到他們的訓獸師，殺死她，再把她用來統御的工具帶回來！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91208,'zhTW','接受現實','在喪鐘鎮尋找害怕的聖騎士。','復活之後，並非我們所有的聖騎士同伴都能迅速適應新的現實。化身為自己生前對抗的生物後，有些人至今仍在努力與自己達成和解。$B$B這些人通常只是需要他人的善待和傾聽。遺憾的是，有不少人一下子就變得過於極端。前往這間禮拜堂西邊的山丘，找到驚慌之下逃到那裡的聖騎士。伸出友誼之手。可以的話，帶領他重回聖光的懷抱。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91209,'zhTW','繼續訓練','沿著東邊的道路離開喪鐘鎮，找到名為布瑞爾的小鎮。向夏莉‧斯迪威爾報到，繼續你的訓練。','羅德隆雖然不像往日那樣輝煌，但我們的家園依舊需要抵禦各式各樣的威脅，你也該去看看外面的世界了。你下一個該去的地方是提里斯法林地中心，一個名叫布瑞爾的城鎮。去找夏莉‧斯迪威爾，她會繼續協助你訓練。$B$B在你離開之前，我還有個建議。行經被遺忘者的領地時，身為聖騎士的你還得多加留意。這裡有許多黑暗女王的手下，他們不信任我們，也鄙視我們對聖光的信仰。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91723,'zhTW','精密儀器','在玉石礦坑擊殺8個狗頭人地卜師，然後回到阿祖拉之塔找哈米許‧柏格沃特。','可惡！每次試著校準這些精密的秘法儀器的時候，瞬間爆發的能量總是會讓它們再次失準。$B爆發的能量似乎來自北方，有些原始的狗頭人一直在那裡施展他們粗陋的魔法。你可以去清除一些，讓我能夠繼續進行工作嗎？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91724,'zhTW','精密儀器','在石碑湖殺死8個迪菲亞流浪巫師，再回到阿祖拉之塔找哈米什‧伯格沃特。','就快完成了，但是…天哪！還是有東西在干擾我的儀器。$B$B$N，真的好煩。我聽說這裡的強盜一直在石碑湖附近練習法術。如果你能阻止他們，也許就能停止干擾，我就可以繼續工作了？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91732,'zhTW','優質鋼鐵','從玉石礦坑收集4件採礦工具，然後回到東谷伐木場找哈嘉爾‧洛威。','戰爭過後，優質的鋼鐵嚴重缺乏，導致我們的工具數量不足。玉石礦坑的礦工會使用製作良好的鎬，我猜有一些應該還留在礦坑的深處。你可以幫我取回一些嗎？我會看看能不能重新利用。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (91736,'zhTW','蘋果白蘭地蒸餾器',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (91738,'zhTW','蘋果「漱」',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91751,'zhTW','堅韌狼皮','在艾爾文森林剝取狼皮，取得7張粗狼皮，然後交給閃金鎮附近的海倫尼‧派特斯金納。','你想找機會練習剝皮技巧嗎？我丈夫通常會幫忙狩獵狼群，不過他現在正忙於修道院那邊的事。我需要有人幫忙收集更多毛皮，完成手邊的訂單。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91753,'zhTW','附魔課程','阿祖拉之塔的基塔‧費溫德要你收集3個夜光殘渣。$B$B夜光殘渣可透過分解狗頭人地卜師掉落的粗製蠟像取得。','學術研究對附魔師來說固然重要，但實作也有不少的收穫。就以那些低賤的狗頭人舉例吧。雖然他們沒有受過正式教育，但還是會一些咒語和附魔。$B$B從他們身上取得蠟像，然後分解其中的附魔吧。你或許能學到些什麼。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91858,'zhTW','外交問題','前往銀松森林的瑟伯切爾，與崔凡‧羅爾交談，了解失蹤的陶土議會旅行者。','銀松森林發生一個極為不幸的事件，但這也是我們向部落展現自身價值的難得機會。$B$B兩個陶土議會的重要人士在前往塔倫米爾的路上，在銀松森林失蹤了。我們知道的情報不多，但據說這起事件逐漸演變成外交問題。如果我們可以找回失蹤的人員，或許有助於獲得我們急需的合法地位。$B$B我們有個人駐紮在瑟伯切爾，名叫崔凡‧羅爾。前往那裡，與他交談。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91859,'zhTW','奇怪的組合','與亡靈衛兵巴德瑞交談，了解最近經過瑟伯切爾的陶土議會神秘旅行者。','我就直說了，這些「重要人士」可不是普通的外交官。其中一個是牛頭人。在陶土議會中再常見不過，至於另一個，你一定難以置信，居然是個精靈。一個「高等」精靈。他們披著披風，但我以前見過奎爾多雷，我用我漂亮的小指發誓，我絕對沒看錯。$B$B為什麼一個精靈會陪著牛頭人穿越部落的地盤？我也和你一樣毫無頭緒。我知道的就只有這些，所以我會建議你去找小鎮入口附近的亡靈衛兵巴德瑞談談。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91860,'zhTW','殘酷命運','調查東邊的芬里斯島，了解陶土議會旅行隊伍的下落。','昨晚外出巡邏時，我看到一群豺狼人把一具非常大的屍體丟進芬里斯島岸邊的火堆。我沒看到精靈或任何體型較小的屍體，但我敢說這對他們來說不算什麼好事。$B$B如果你夠勇敢或夠愚蠢，歡迎你衝到芬里斯島查個清楚，但是在我看來，尋找一個可能早就死透了的傲慢精靈，是件吃力不討好的事。$B$B我知道你們聖騎士熱愛發誓和挑戰不可能，但這一次真的不值得。相信我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91861,'zhTW','前往芬里斯城堡','調查北方的芬里斯城堡，並嘗試找出陶土議會的失蹤成員。','<你只找到一具屍體，代表事情還有一絲轉機。也許崔凡和哈德瑞克口中的那個高等精靈還活著，而且人就位在附近要塞的深處？>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91862,'zhTW','露蜜娜‧風詠','從腐皮豺狼人身上取回芬里斯島鑰匙，並使用它來釋放露蜜娜‧風詠。','奎爾多雷？不，我才不是什麼「奎爾多雷」。我是露蜜娜‧風詠，我是申多雷。塑風者天裔精靈的一員。$B$B我是作為陶土議會的客人來到這片土地的。我的同伴巴諾和我正路過銀松森林前往阿拉希高地，以便研究那裡的元素匯聚現象。顯然，我們沒能成功抵達。$B$B不過我們現在沒時間說這個了。殺死附近的豺狼人。拿回這個籠子的鑰匙並釋放我。等我們安全離開後，我再告訴你事情的經過。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (91899,'zhTW','密封的箱子',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (91900,'zhTW','密封的箱子',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
