INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91920,'zhTW','狂野之眼','收集3個魚人的眼球，然後交給瑟伯切爾的藥劑師倫弗利爾。','我不敢質疑藥劑師倫弗利爾手中配方的效果，不過，要是我說那種藥水帶來明顯的變化，我就是在說謊。$B$B洛丹米爾湖的岸邊居住著一群魚人，值得留意的是，魚人有眼睛。我猜想，那個藥劑師最近著迷於心臟，抑制了他嘗試新事物的意願。帶幾顆眼睛給他。$B$B在必定死第二次，以及因質疑倫弗利爾的做法而被他殺死之間，我選擇後者。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (91921,'zhTW','回到奎恩身旁（再次）','將奎恩的藥水帶給瑟伯切爾北方伊瓦農場的奎恩‧尤瑞克。','這就是能幫助奎恩復原的新藥水，用從六顆完整心臟萃取的愛意製作而成。$B$B現在，在你的存在衍生出更多文書工作之前，我就先失陪了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92109,'zhTW','人生第一套鍊金設備','攜帶5個空瓶、5份銀葉草和5份寧神花，然後前往西部荒野的月溪鎮，交給穀倉中有志氣的年輕鍊金師。','呃…哈囉，$G先生:小姐;。我本來不該跟陌生人說話，不過…嘿，你背包裡冒出來的那些閃亮的瓶子是做什麼的？你是鍊金師嗎？未免太酷了！$B$B等我長大，我也想成為一個鍊金師。爸爸都不讓我擺弄他的草藥，他說太危險了。$B$B可是，我想現在就開始學習。你可以幫我拿到一些補給品嗎？求求你了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92110,'zhTW','人生第一瓶真正的藥水','收集3個魚人的眼球，然後前往西部荒野的月溪鎮，交給穀倉中有志氣的年輕鍊金師。','哇，我人生的第一瓶藥水！打從一開始，你就知道把那兩種草藥混合在一起，會讓藥水變成亮紅色嗎？$B$B實在太有趣了，不過，混合一些花好像跟爸爸平常進行的那種鍊金術不一樣。他也會使用其他材料。$B$B我不知道還能用什麼材料，不如看我先想到什麼就用什麼！我想想…魚人的眼球嗎？聽起來好噁心，不過我猜一定會出現什麼變化。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92415,'zhTW','銘記我對你的愛','將染血信件帶去給暴風城的孤兒監護員南丁格爾。','<這捆破損且沾滿血污的羊皮紙，在被不死生物踐踏的墓地中勉強保存了下來。上面提到了織心者家族一名失蹤的孩子。或許暴風城的孤兒監護員會知道更多細節。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92421,'zhTW','聖光的正義','為幽暗城的莫賓‧光寂在羅德隆廢墟內收集25份完好的肢體。','身為被遺忘者的聖騎士，我的職責便是在照料同胞需求的同時，確實貫徹我們黑暗女王的意志。我們很幸運，現在就有一個能同時實現兩者的機會。$B$B在幽暗城之上，大量的天譴軍團成員依舊肆無忌憚地四處遊蕩。我們的部隊在試圖收復領土的過程中不斷減少，而腐爛的血肉是無法重新縫合的。除非有替代品。$B$B要是我們光榮的隊長加瑞克‧班達利昂依舊與我們同在，我知道他會希望怎麼做。那就是去完成他未竟的事業，並治癒我們的同胞。為了羅德隆！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92432,'zhTW','令人擔憂的請求','在達拉然城附近找大法師莫德菈的影像報到。','我帶來了達拉然的壞消息。某種東西干擾了我們的地脈，導致城裡的傀儡出現異常和毀滅行為。$B$B我們目前還不知道是什麼引起了這場混亂。高階議會命令我們對此事保密，以免讓我們的組織蒙羞。但我們無法一直隱瞞下去。就在我們說話的同時，城市正在淪陷！$B$B大法師莫德菈派我來尋求外界的協助。去達拉然附近的洛丹米爾湖畔尋找她的影像。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92434,'zhTW','喋血街頭','沿著洛丹米爾湖尋找進入達拉然的路。','不論是什麼原因導致達拉然的結界失效，整座城市都已經因此陷入了混亂。既然你已經解決了他們的巡邏隊，現在就是我們潛入其中並發掘他們秘密的最佳時機。$B$B帶著你在拘留營找到的鑰匙，沿著城市北境尋找他們的下水道。運氣好的話，那些法師應該沒有理由在這麼…噁心的入口處施加結界。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92456,'zhTW','綠色樣本','為暴風城的莎拉米爾從達拉然城收集一株魔化灌注之花。','如果你非要來打擾我，你至少得先讓自己派上用場。我有件非做不可的事。$B$B作為一座法師之城，達拉然對植物學有濃厚的興趣。祈倫托與世隔絕，我卻很想要一份法力灌注植物的樣本。$B$B你顯然很習慣擅闖禁地，或許你能想辦法潛入那座城市。進去之後，將一株生長在中央花園的植物帶回來給我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92457,'zhTW','飢餓的秘法','為達拉然外的大法師莫德菈在達拉然城內擊敗8個尋找的殘渣、8個浸透的殘渣，以及8個法力回音。','這場破壞影響了我們遍布全城的許多僕役和附魔，包括許多負責防禦的設施。這些碎裂的秘法能量吸引了失控的元素生物，它們企圖讓自己吸飽這些四處逸散的魔力。$B$B在我們忙著維護結界和處理其他重大事件時，如果你能剷除這群元素生物，那將是對祈倫托的一大幫助。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92458,'zhTW','干擾之心','為達拉然城附近的大法師莫德菈的影像收集秘法微粒。','無論是什麼干擾了地脈，它都是從紫羅蘭城塞的頂端開始的。當時上方的會客室傳來一陣雷鳴般的巨響，導致我們此刻面臨著暴走的秘法能量。光是維持結界完整，就已經耗盡了我們所有的力量。$B$B我們沒辦法再拖下去了。我們需要支援。$B$B祈倫托的成員此時正在城內忙碌，但你還是需要從一個沒那麼醒目的入口潛入。拿著這把鑰匙，在你設法進入城市後，到城塞與我會合。我們必須阻止這場混亂。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92459,'zhTW','祈倫托的朋友','到達拉然城與大法師瑟琳卓交談。','議會一定不樂見我們的秘密行動，但他們無法否認成果。城市逐漸恢復安定，我們也隨時都能解除結界。$B$B我想，最好由你去傳達這個好消息。把這個微粒帶去給紫羅蘭城塞的大法師瑟琳卓。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92466,'zhTW','大地的召喚','將奧基爾徽記帶去給塑風者玻羅。','雖然我們的繁榮在很大程度上要歸功於風元素，但我們所走的道路要求我們必須服從所有四種主要元素的召喚，並進行每一種元素的試煉。然而，在真正開始你的第一場試煉之前，你必須先證明你決心的強度。$B$B前往東邊的矗立之石。有人在那裡發現了一支奧拉凱斯皈依者的部隊，必須將他們驅逐。去那裡對抗那些邪教徒，並帶給我一枚他們的徽記，作為你事蹟的證明。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`QuestDescription`,`VerifiedBuild`) VALUES (92467,'zhTW','大地的召喚','靈契是一種可以在我們的靈魂與元素之間建立起連接的特殊藥水。這種融入了魔法的藥水將使完全放開了心靈的你看到別人所看不見的元素。你的靈魂將會永久地與靈契所對應的元素連接起來，只有少數被選中的人才知道靈契的制法。$B$B你必須知道一點…只有在神聖的地方喝下靈契才有效，其他任何地方都是不行的。$B$B到這裡東邊的山口尋找「靈魂高地」。到那裡去把你的靈契喝掉，然後…嗯，到時候你就會看到你該看見的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92468,'zhTW','大地的召喚','將粗石英交給坦德爾林地的塑風者玻羅。','把這塊粗石英交給你稱為塑風者玻羅的人，以此證實我們會過面了。他將會為你製造一根圖騰，而這塊裂片則會是圖騰的核心。可能它看起來小了點，不過你馬上就會知道，大小並不重要，即使是最小的石子也可能比山川還要恒久。$B$B耐心一點，$N。繼續保持強健的體魄，並努力追尋智慧吧。這是元素對你的要求。最終，你也將融入大地中，尊重它，它也會尊重你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92479,'zhTW','潦草的信件','閱讀潦草的信件，然後與北郡修道院的托丁‧柄刃交談。','當你從狗頭人營地回來的時候，有人要我把這個交給你，$N。看起來這封信是托丁‧柄刃寫給你的，我們當地的獵人訓練師。在你去處理修道院這裡的其他事前，請先花點時間讀信。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92481,'zhTW','秘法學生','檢視發光的回溯水晶，然後與坦德爾林地的朵莉‧亮語交談。','你在外面幫我們處理弗德飛狐問題的時候，我們的法師訓練師朵莉‧亮語留了這顆回溯水晶給你。裡面有要給你的留言，記得看一下。之後，你可以在我背後的建築物找到朵莉。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92482,'zhTW','獵人之道','閱讀潦草的紙條，然後與坦德爾林地的泰芮‧遠目交談。','你在外面幫我們處理弗德飛狐問題的時候，我們的獵人訓練師泰芮‧遠目留了這張紙條給你。請你到村子中央附近一趟，和泰芮談談。看完紙條就去找她吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92483,'zhTW','以暗影為家','閱讀簡易便箋，然後到坦德爾林地的瞭望塔與阿克里‧暮刃交談。','你在外面幫我們處理弗德飛狐問題的時候，我們的盜賊訓練師阿克里‧暮刃說想和你談談。他留了這張便箋，看完之後，就去村子這裡的瞭望塔內找他。$B$B他是個陰沉的傢伙，不過你跟他是半斤八兩。我想你們會相處融洽。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92484,'zhTW','擁抱元素','檢視嗡鳴的回溯水晶，然後與坦德爾林地的塑風者玻羅交談。','你在外面幫我們處理弗德飛狐問題的時候，我們的薩滿訓練師塑風者玻羅留了這顆回溯水晶給你。請查看一下，然後到村子中央附近一趟，和玻羅談談。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92489,'zhTW','壓倒性的力量','為暴風城的高階巫士安多瑪斯在達拉然城殺死法力元素。','祈倫托長久以來一直都是聯盟的盟友。隨著他們的城市被大惡魔阿克蒙德摧毀，這座曾經令人驕傲的法師之城如今變得遺世獨立，且對外來者充滿戒心。$B$B近年來，他們開始了重建工作，打算讓達拉然城重現昔日的輝煌。然而，報告指出他們正苦於遏制失控秘法能量的爆發。$B$B我們必須協助他們瓦解這些攻勢，以免我們失去一個強大的盟友。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92646,'zhTW','面對洛舒娜','使用傳送門到上方的羅哈希尖塔，並與伊拉德林‧和風和阿雅莎‧曦詠面對高階女祭司洛舒娜。','洛舒娜用傳送門逃到上方的尖塔去了。阿雅莎和伊拉德林剛剛跑去追她了。$B$B因為我已經受了重傷，也只能待在這裡了。穿過傳送門、找到阿雅莎，然後協助他們阻止洛舒娜。$B$B除非伊拉德林和阿雅莎說的援軍會提早抵達，否則現在只能靠你了。祝你好運，$C。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92745,'zhTW','礦坑狀態','到詹戈洛德礦坑殺死4個狗頭人掘地工，並到金海岸礦坑殺死6個河爪礦工。','你收集的井水樣本含有劇毒金屬！如果我們不快點終結腐化，這裡的土壤就需要花上好幾十年，才能再次長出作物。$B迪菲亞佔領了西部荒野的礦坑，利用生物充當勞力，榨取各種資源。到北邊的詹戈洛德礦坑和西邊的金海岸礦坑殺死他們的礦工，破壞他們的行動。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92747,'zhTW','月溪鎮諜戰','從月溪鎮收集8個可疑的工業補給品。','真奇怪，毒素似乎不是源自你調查的礦坑。$B$B有人告訴我，月溪鎮底下的死亡礦坑是西部荒野最大、最深的礦坑，不過第一次大戰之後，礦坑就被棄置了。難道死亡礦坑又重新開工了？$B$B請去月溪鎮一趟，$N，尋找採礦或工業活動的證據。這是我們擁有的最後一條線索！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92748,'zhTW','炸藥諮詢','前往暴風城的矮人區，找到可以幫忙的工程師。','你找到的補給品顯示，死亡礦坑的某處有大規模的工業活動。毫無疑問，這正是讓西部荒野的農地出現毒素的源頭。我們必須阻止這一切，越快越好。$B$B不管那下面的麻煩是什麼，想要鏟除絕非易事。前往暴風城的矮人區，找到能提供我們一些炸藥的工程師。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92749,'zhTW','火藥計畫','透過製作、交易或拍賣場取得10個劣質火藥，然後回去暴風城的矮人區找斯普萊特。','工業破壞？你引起了我的注意！$B我們先從一些火藥開始…',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92750,'zhTW','遠程引爆','與暴風城情報機關的人員談話，了解如何取得遙控炸彈。','我猜你想要一場「有限度」的爆炸？不怎麼有趣的選擇，但想保全你的四肢，這的確是個好選擇。$B我恐怕沒有遙控炸彈 - 你何不去暴風城情報機構，問問那些藏頭露尾的傢伙？他們應該能幫上我們的忙。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92751,'zhTW','遠程引爆','將遙控炸彈工具組交給暴風城矮人區的斯普萊特。','你需要摧毀某個東西？這跟你在月溪鎮的行動有關嗎？不用那麼驚訝。暴風王國境內的大小事，軍情七處都瞭若指掌。$B$B如果你打算在西部荒野底下的洞穴引發一場爆炸，你一定希望事前就離開那裡。帶著這個遙控引爆器 - 這是我們的工程師最近推出的試作品。$B$B對了，你最好別向你的精靈朋友提到我的事。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92752,'zhTW','炸藥諮詢','回去西部荒野找艾芭‧皎月。','好了 - 炸彈準備好了！現在小心拿好引爆器。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92753,'zhTW','死亡礦坑破壞行動','尋找隱藏在死亡礦坑的熔爐，並在附近放置威力驚人的爆裂物。然後，在死亡礦坑的出口與艾芭‧皎月會合。','毒素的來源很可能與某種大型冶金熔爐有關。設法進入死亡礦坑並找到熔爐，然後放置炸藥。$B我會在月溪鎮後方的山丘上等你。等你回來之後，我們就可以引爆炸藥。但願隨著熔爐被摧毀，這片土地能開始恢復生機。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (92811,'zhTW','經濟戰',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (92812,'zhTW','經濟戰',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92818,'zhTW','大型，不，巨型鐵斧','繼續和瑪格拉姆部族保持良好的關係，把2把巨型鐵斧交給淒涼之地瑪格拉姆村的格羅卡爾。','我們需要更多武器。$B$B更多。武器。$B$B不然瑪格拉姆要怎麼擊潰可悲的吉爾吉斯？$B$B我想看你的能耐，外來者。把斧頭拿來給我。拿大斧頭，不，拿超大的來。$B$B動作快。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92819,'zhTW','死亡礦坑破壞行動','使用引爆器。','只差一步了。使用引爆器，結束這一切。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92834,'zhTW','十倍奉還','前往瓦拉納爾北邊的風莓低地或奧基爾聖殿，從那裡的奧拉凱斯教徒身上收集10個奧拉凱斯風石符咒。','邪教展開暴力行動的時候，保安官和塑風者的反應只不過是裝腔作勢。我認為此行非常愚蠢，所以提倡要和平對話。昨天我派了好友貝拉桑‧亮願前往奧基爾聖殿，希望能建立溝通橋樑。$B$B剛才有個箱子送達，裡頭裝著銀色的顏料，貝拉桑的舌頭就泡在裡頭。$B$B我現在清楚知道，和邪教沒有什麼道理可講。殺光你看到的所有邪教徒，把他們身上的祈禱護符帶來給我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92841,'zhTW','白骨之谷','提高你在瑪格拉姆部族的聲望，在瑪格拉姆村南方的白骨之谷附近找到歐魯爾。','外來者，是時候讓你知道我們偉大的發現了…但負責告訴你的不是瓦魯格！$B$B往南邊走，到村子另一端去。找一個又大、又臭，叫歐魯爾的半人馬。$B$B你到那就會知道了。$B你看到他就會知道了。$B如果他覺得你有資格知道，你就能知道。$B$B如果他不覺得呢？那你至少可以恭喜瓦魯格有個新皇冠了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92860,'zhTW','為微風島效命','向維菈妮雅‧颶拳回報，讓她知道高天盟會和他們一起作戰，對抗奧拉凱斯。','高天盟一直以來，都竭盡所能迴避和邪教發生正面衝突，但顯然這已經不是可行的選項了。他們的敵意非常明顯，而且根據傳聞，邪教正準備在島上展開大規模的行動。他們顯然正準備要做些什麼，不論是什麼樣的陰謀詭計，肯定都對微風島的人們不利。$B$B去向維菈妮雅‧颶拳回報，通知她如果真有需要，高天盟會在瓦拉納爾對抗奧拉凱斯的戰鬥中提供全面協助。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92871,'zhTW','為微風島效命','向維菈妮雅‧颶拳回報，讓她知道塑風者會和他們一起作戰，對抗奧拉凱斯。','維菈妮雅‧颶拳和她的保安官向來都是微風島的守護者，我們也一向盡己所能提供幫助。傳聞邪教正在島上各處進行大規模的行動，他們顯然正準備要做些什麼。$B$B去向維菈妮雅回報，並且再次向她重申，如果真有需要，塑風者會在瓦拉納爾對抗奧拉凱斯的戰鬥中提供全面協助。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92893,'zhTW','永不憐憫弱者','繼續和瑪格拉姆部族保持良好的關係，在白骨之谷四處殺死5個吉爾吉斯俘虜。完成任務後回去找歐魯爾。','你深入白骨之谷時，會發現有吉爾吉斯流浪者大膽踏入我們的領地。我下令要留他們一命，讓地底的食骨蟲有東西可吃，但牠們似乎對活著的獵物興趣缺缺。$B$B這任務相當簡單。找到那些俘虜，殺掉他們。別讓他們有一絲重獲自由的希望。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (92911,'zhTW','收割收割者','薩丁農場的歐溫‧鐵鏈要你將8個魔像等能彈簧、4個銅質調節器和1個粗製瞄準鏡交給他。','我明白了…這讓我稍微弄清楚那些怪物是怎麼運作的。我有個辦法，或許能夠接管它們的系統，但效力很短暫。$B$B我會繼續摸索你交給我的組件。在此同時，你能幫忙尋找裝置需要的一些零件嗎？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93034,'zhTW','白骨之谷','提高你在吉爾吉斯部族的聲望，在吉爾吉斯村東方遠處的白骨之谷附近找到涅洛克。','你不在時，我們的斥候回到村裡了，他們帶回來的消息證實了我的擔憂。$B$B瑪格拉姆氏族在策畫著什麼，$N。而且不是什麼好事。$B$B東邊遠處的白骨之谷是個詛咒之地，很少有半人馬敢涉蹄，能夠從那裡回來的又更少。敵人在那裡發現了某種東西，某種邪惡的事物，我們必須知道那是什麼。$B$B去南方入口找斥候涅洛克，但你必須先進一步向吉爾吉斯氏族證明你的資格。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93035,'zhTW','肆虐劫掠者','繼續和吉爾吉斯氏族保持良好的關係，殺死6個不死族劫掠者，然後回去白骨之谷的南方入口找涅洛克。','你不必仔細看，就能看到前方有蹣跚的不死生物，但你有注意到不尋常的地方嗎？$B$B他們是用兩條腿走路，而不是四條腿！這些骸骨根本不是我們死去的同胞。瑪格拉姆族一定是褻瀆了淒涼之地成為我們領地以前死去的上古死者。我無法想像他們竟敢背叛主母瑟萊德絲，褻瀆數世紀以來在此安息的屍骸。$B$B讓不死生物重新安息吧，$N。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93037,'zhTW','暴露流亡者','繼續和吉爾吉斯部族保持良好的關係，把1個死靈裝束帶給白骨之谷入口的涅洛克。','等你抵達時，我又朝拱門遠方看了看，注意到了一些東西，需要你幫忙證實。$B$B我不敢大聲說出來。直到我的疑慮被證實為止都不行。$B$B$N，你熟悉谷地的同時，順便擊殺一些看起來比其他更弱的死靈法師。拿走他們的儀式裝束，動作務必謹慎，然後帶來給我。我必須確認我的精神和雙眼是否正常。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93062,'zhTW','埋葬骸骨','繼續和吉爾吉斯部族保持良好的關係，在白骨之谷驅散8個失敗召喚物的詛咒。','關於你的那把法杖。我認得那是烏泰克的東西，你說它是用瑟萊德絲之淚製成，還用德萊尼水晶強化，能用來驅散黑暗魔法？$B$B我發現谷地深處，粗糙的岩土底下有骷髏卡在裡頭。我認為這些是流亡者死靈法師召喚失敗的結果，受害者被迫永遠悶在泥土之中。$B$B讓他們再次安息對我們來說算是正義之舉，對他們的靈魂來說也極具意義。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93089,'zhTW','接下來的事','準備好離開微風島後，就和伊拉德林‧和風交談。','請代我向伊拉德林道謝，感謝高天盟和你來自「祈倫托」的新朋友為微風島所做的一切。我知道高天盟打算離開這座島，我祝你們在遠征旅途上一路順風。$B$B我只希望高天盟能找到秘法解方，讓我們多年來一向不穩定的情勢真正安定下來。如果你想和他們一起去…也好，這樣一來，這任務就更有可能成功了。$B$B願風與你同在，$N。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93090,'zhTW','接下來的事','準備好離開微風島後，就和阿雅莎‧曦詠交談。','請代我向阿雅莎道謝，感謝塑風者和你來自「陶土議會」的新朋友為微風島所做的一切。我知道她打算帶領塑風者薩滿離開這座島，我祝你們在遠征旅途上一路順風。$B$B我只希望塑風者能找到解方，讓我們多年來一向不穩定的情勢真正安定下來。$B$B願風與你同在，$N。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93128,'zhTW','傑恩可汗','繼續和吉爾吉斯部族保持良好的關係，殺死瑪格拉姆村的傑恩可汗。成功後，向淒涼之地吉爾吉斯村的智者烏泰克回報。','雖然我希望烏泰克和沙卡可汗能發號施令，但恐怕機會是轉瞬即逝。沒時間向吉爾吉斯村的人們尋求意見了。$B$B我認為從白骨之谷的現況看來，瑪格拉姆族沒有留多少戰力負責保護傑恩可汗。如果有機會能成功襲擊其他部族的可汗，無疑就是現在了。$B$B但$N，可汗絕不是什麼能小覷的對手，更別說是傑恩了。如果你真敢前去襲擊他的話，動作必須要快，而且絕不能小看他。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93224,'zhTW','雕刻半人馬圖騰','殺死淒涼之地任何氏族的半人馬，取得5個雕刻半人馬圖騰，然後將其帶回去給尼耶爾前哨站的潘迪加斯上尉。','兩個半人馬氏族都不太樂意接受自己人以外的助力，這對你來說應該沒什麼好意外的。這點對你和我…你懂的，也就是非半人馬來說更是如此。$B$B我們的共通點，就是我們都了解金錢就是力量，而且我們也發現了當地的半人馬會用木製雕刻交易。如果你能帶來他們的雕刻樣本，我能立刻趕工製作類似的雕刻。或許我們能用錢買來優勢。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93225,'zhTW','雕刻半人馬圖騰','殺死淒涼之地任何氏族的半人馬，取得5個雕刻半人馬圖騰，然後將其帶回去給鬼旅崗哨的古爾達‧蠻鬃。','我發現不同氏族的半人馬有時會離開據點聚集在一起，進行交易。我觀測到這種現象發生好幾天，似乎每個氏族都有這種行為，最重要的是我發現了他們使用的貨幣，原來是雕刻的圖騰。$B$B我認為如果送他們一堆圖騰，我們就能扭轉局勢，和吉爾吉斯或瑪格拉姆氏族結交為盟友。我已經開始製作一些雕刻了，但我想如果其中沒有一些真品，應該唬不了他們。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93227,'zhTW','購買友誼：吉爾吉斯','前往淒涼之地的吉爾吉斯村，將圖騰手提包交給吉爾吉斯軍需官，大幅提高你在該部族的聲望。你的吉爾吉斯半人馬聲望必須至少是中立。','乍看之下，我會認為吉爾吉斯部族恐怕正在苦苦支撐。他們的人數遠遠不及瑪格拉姆，而且我很少從斥候那邊聽說他們到處巡視地盤。$B$B儘管如此，他們還是淒涼之地的優勢部族之一，而且順利延續至今。他們一定有自己的長項。$B$B如果你想與吉爾吉斯和平相處，就帶著這包圖騰前往西南邊的吉爾吉斯村。雖然他們的開化程度不高，但應該還是有守寶人之類的人物。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93459,'zhTW','更多奧拉凱斯耳朵','在影風森林、奧基爾聖殿和風莓低地收集10個奧拉凱斯教徒的耳朵，接著再交給影風森林的范恩‧月爪。','奧拉凱斯教團通常都會因為鬧鬼的傳言而避開這座森林…我們也很樂見這樣的成果。組織裡的德魯伊只想在影風森林平靜地過日子，卻反而受到他們的威脅。$B$B我們有很多人都很害怕。$B$B我是來向你打個商量的。幫助我們對抗教團，然後把他們的耳朵割下來。回來之後，我們會給你賞金。如果你能在這段時間證明自己的能耐，我們也會把秘密分享給你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93585,'zhTW','我的聖光','護送塔托神父到避難營。','喔，謝天謝地，來了個有教養的人！$B$B我代表聖光教堂來到這裡，與避難營的德萊尼接觸。你看到了，聯盟在這裡沒有據點，與當地人展開一點交流，或許對這件事有幫助。畢竟，聖光對任何人都來者不拒！$B$B不過，過了這座橋，路上盤踞著德萊尼更加野蠻的同胞。如果我想安全抵達避難營，就需要有人保護我。$C，你願意伸出援手嗎？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93663,'zhTW','在送貨時失蹤','找到失蹤的信差，並確保達爾的貨物送達避難營。','避難營的德萊尼是技術高超的漁夫，而且比我更願意去危險的水域捕魚。我們偶爾會交易。他們給我們一些漁獲，我則提供一些多餘的補給品。$B$B我派了哥布林信差去送最新的一批貨，但他卻一去不回。他可能變成鱷魚的大餐了。$B$B更重要的是，我的商譽正岌岌可危。得找到那批貨，並且送到避難營。可以的話，請去找一下。你可以在道路沿線的水域附近找找看。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93680,'zhTW','城市鑰匙','為塔倫米爾的魔導師沃迪恩‧虛無之光取得達拉然下水道鑰匙。','聯盟擁有一支被稱為祈倫托的法師大軍。雖然他們很強大，但惡魔般的燃燒軍團卻證明了自己更勝一籌。在轉瞬之間，大惡魔阿克蒙德就像摧毀小孩子的玩具一樣，將他們的城市夷為平地。倖存下來的人們則淪為了流離失所的流浪者。$B$B這個情況持續到他們重建了達拉然，而且還就在黑暗女王的眼皮底下！$B$B在他們的營地裡時，尋找能讓我們在不被發現的情況下潛入城內的方法。我必須了解更多內情。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93738,'zhTW','損壞的傀儡','到瓦拉納爾向阿雅莎‧曦詠回報。','是亮願嗎？所以高天盟出於某些原因移除這些零件。但為什麼要這麼做？$B$B高天盟向來都愛管閒事，還一直想對這些風之神靈的魔法進行實驗。他們簡直是膽大包天。我們嚴禁他們窺探塑風者的知識，但他們最近一直在試探我們的底線。$B$B我想你該把這些事告訴阿雅莎‧曦詠。她會告訴你下一步該怎麼做。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93739,'zhTW','探索部落','在葛羅瑪許堡與納茲格雷爾交談，接收進一步的指示。利用收到的指示尋找沃金、凱恩‧血蹄，和希瓦娜斯‧風行者女士，並與其交談。','艾澤拉斯是個龐大的世界，部落的領土非常遼闊。幽暗城、奧格瑪，和雷霆崖都具有獨特的民風和文化。$B$B如果你想在艾澤拉斯成為部落的賓客，你最好去一一拜訪我們的主城。你可以向我的顧問納茲格雷爾問路。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93740,'zhTW','血債血償','在風莓低地從奧拉凱斯教徒的遺體上收集10個奧拉凱斯風石符咒。','今天早上，高地發現了一些塑風者新手的遺骸。目前情勢還不夠明朗，但可以肯定，這是奧拉凱斯幹的。塑風者必定血債血償。$B$B前往北方，殺死你遇到的奧拉凱斯教徒。把他們的風石祈禱符咒帶回來當作證明。我們不會忘記，也不會縱容這樣的惡行。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93746,'zhTW','強勢的回應','在前往奧基爾聖殿的路上面對貝拉桑‧亮願。','我們已經警告高天盟他們介入塑風者之事的後果了。我們必須給貝拉桑一點顏色瞧瞧，以儆效尤，然後再讓他回到高天盟，表明我們不是好惹的。$B$B有人看到貝拉桑離開城鎮，到北方的奧基爾聖殿去了。我不知道他為什麼要去那裡，但在路上與他對峙是最安全的選項了。找到他，讓他嚐嚐恐懼的滋味。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93786,'zhTW','血訊','殺死12個草原溪地雇農，然後向克隆羅許回報成功的消息。','$N，你的刀刃也渴望人類的鮮血嗎？$B$B幾年前，那些人類叛逃者佔領了西南方河對岸的一座小農場。由於該地區擁有豐富的木材與石材，他們將勢力擴張到東岸那座被稱為遠境堡的要塞，只是時間早晚的問題。$B$B如果我們當初人數足夠，第一場衝突本該是以我們的勝利告終。是時候讓他們重新想起我們的存在了。$B$B去干擾他們的農業發展。不留任何活口。向他們傳達一個明確的訊息。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93788,'zhTW','借來的刀刃','為羅格瑪的克瑞莎‧黑棘在透納的伐木場從伐木工身上取回10把木工斧頭。','由於南方有人類出沒，西方又有暮光之錘，資源的爭奪戰已經變得十分艱難。不過，既然有敵人的兵刃就很夠用了，我們何必頂著敵人的炮火收集資源呢？$B$B順著河流向南前往磨坊。當你聽到樹林間木工的口哨聲時，記得把腳步放輕。一旦機會來臨，就迅速出手痛擊。$B$B我會留在這裡讓熔爐保持溫度。葛多克會負責熔解那些刀刃，而我則會用他們自己的材料，打造出屬於我們的武器。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93791,'zhTW','和貝藍交談','和瓦拉納爾的貝藍‧風木交談。','$N，你的魔法造詣越來越高，我認為該讓你這年輕有為的法師遵循高天盟的古老傳統了。是時候創造屬於自己的法器了。$B$B去找瓦拉納爾的貝藍‧風木吧。他為高天盟製作法杖和魔杖超過了一個世紀，也一定會幫你的忙。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93797,'zhTW','風中樹枝','把風能灌注樹枝交給瓦拉納爾的貝藍‧風木。','當年輕法師展現出自己的魔法才能時，就能在這個時候遵循傳統，製作自己的法器了。一般得在最古老的樹下收集掉落的樹枝，因為它們還有風元素殘留的力量。$B$B我已經在風之聖壇附近找到最好的樹了，就在法拉斯村南邊。幫我帶回一根巨大的樹枝，回來之後，我會一邊製作法器，一邊教你我們的古老傳統。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93835,'zhTW','面對洛舒娜','使用傳送門到上方的羅哈希尖塔，並與伊拉德林‧和風和阿雅莎‧曦詠面對高階女祭司洛舒娜。','洛舒娜用傳送門逃到上方的尖塔去了。阿雅莎和伊拉德林剛剛跑去追她了。$B$B因為我受了重傷，也只能待在這裡了。穿過傳送門、找到伊拉德林，然後協助他們阻止洛舒娜。$B$B除非伊拉德林和阿雅莎說的援軍會提早抵達，否則只能靠你了。祝你好運，$C。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93836,'zhTW','微風島的命運','在瓦拉納爾和塔拉尼斯‧影歌交談。','穆倫告訴我很多元素首領的事，我們也有充分的理由懼怕奧拉基爾。隱藏微風島的結界已然失效，而我們也完全沒有防禦能力。如果他選擇出手攻擊我們，我們在他的領地裡根本就沒有反擊的機會。$B$B高階長者影歌必須知道我們身處險境，更重要的是，他也必須知道我們前往艾澤拉斯的目的是什麼。我發誓，我們會找到拯救家園的方法。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93928,'zhTW','鼠與奶','給老鼠一塊餅乾。','我需要餅乾，知道嗎？$B$B嗯哼！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (93963,'zhTW','探索聯盟','在暴風要塞與蘭德爾‧艾默森交談，接收進一步的指示。利用收到的指示尋找麥格尼‧銅鬚國王、大工匠梅卡托克，和泰蘭妲‧語風，並與其交談。','暴風城、鐵爐堡，和達納蘇斯都具有獨特的民風和文化。身為艾澤拉斯的聯盟賓客，你應該花點時間去一一拜訪我們的主城。$B$B與南方前廳的蘭德爾‧艾默森交談，詢問該如何啟程。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94003,'zhTW','破天者壁壘','在奧基爾聖殿從札爾‧風暴盾手中奪回破天者壁壘。','我是微風島上僅存的破天者。其他成員都被奧拉凱斯殺死了。$B$B唯一能壓過傷感的只剩慚愧之心了。我家族流傳下來的「破天者壁壘」盾牌被一個名叫札爾‧風暴盾的教徒奪走了。家族流傳著一個傳說，夠格使用這面盾牌的人將堅不可摧。$B$B我很確信札爾這個人根本不夠格。到奧基爾聖殿把這個人找出來，然後奪回我的盾牌。只要你成功了，我就教你破天者防禦術。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94007,'zhTW','馴服野獸','到瓦拉納爾向奎爾安娜‧快颺回報。','既然你已經適應了高地的荒野，我想是時候去尋找你專屬的動物夥伴了。$B$B前往東南方的瓦拉納爾港口，與那裡的奎爾安娜‧快颺交談。他會教你馴服野獸的技巧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94369,'zhTW','微風島的命運','在瓦拉納爾和塔拉尼斯‧影歌交談。','安斯雷姆告訴我很多元素首領的事，我們也有充分的理由懼怕奧拉基爾。隱藏微風島的結界已然失效，如果馭風者選擇出手攻擊我們，我們在他的領地裡根本就沒有辦法保護自己。$B$B高階長者影歌必須知道我們身處險境，更重要的是，他也必須知道我們前往艾澤拉斯的目的是什麼。我發誓，我們會找到拯救家園的方法。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94373,'zhTW','土之召喚','把2個霜鬃熊紋墜飾交給安威瑪的提歐‧錘暴。','啊，是時候了，年輕的薩滿。你已經長得頑強又健壯，如同我們腳下的石頭。選擇遵循薩滿之道，這代表著早在你證明自己之前，你就擁有高山般的睿智。你擁有石頭般的堅毅，才會踏上大地的道路。$B$B但想要贏得它的青睞，你必須正確地面對它。霜鬃食人妖就居住在這裡南邊的洞穴中。$B$B他們戴在身上的項鍊是以冰爪熊製成，把兩條項鍊交給我，然後我們再來談談你的未來。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (94374,'zhTW','土之召喚','找到靈魂之石並喝下大地靈契。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94375,'zhTW','土之召喚','將粗石英帶去給安威瑪的提歐‧錘暴。','把這塊粗石英交給提歐‧錘暴，以此證明我們見過面了。他將會為你製造一根圖騰，而這塊小圓石則會是圖騰的核心。可能它看起來小了點，不過你馬上就會知道，大小並不重要，即使是最小的石子也可能比山川還要恒久。$B$B耐心一點，$N。繼續保持強健的體魄，並努力追尋智慧吧。這是大地對你的要求。最終，你也將融入大地中，尊重它，它也會尊重你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94434,'zhTW','神性的教誨','把10個亞麻布交給幽暗城的塔尼斯‧奧德伍德。','等等，你想…幫助我？為什麼聖騎士會幫我這樣的乞丐呢？$B$B你是可以幫我一個忙。$B$B是我的太太。她…她快不行了。身體被分成一塊一塊的。藥劑師可以很輕鬆地就把她拼湊起來，但他們都在忙黑暗女王的事，也暫時無法提供協助。如果你能幫我找一些乾淨的布料，我就能在藥劑師來之前先好好把她的身體纏緊在一起。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (94435,'zhTW','神性的教誨','回到班達利昂要塞找丹妮莎‧莫爾。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (94436,'zhTW','神性的教誨','在班達利昂要塞與亡靈衛兵比爾穆交談。$B$B如果你弄丟生命符記的話，就再回去找丹妮莎‧莫爾拿一個。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94438,'zhTW','神性的教誨','帶著生命符記，然後在毒蛛峽谷讓亡靈衛兵法爾根復生。$B$B如果你弄丟生命符記的話，就再回去找丹妮莎‧莫爾拿一個。','法爾根和我被派去毒蛛峽谷調查血色十字軍的活動。我們成功靠近他們的營地，還聽到他們要攻擊布瑞爾的命令。在我們決定下一步該怎麼做前，因為我不小心踩到樹枝，反而驚動他們了。$B$B法爾根要我快跑，所以我就照做了。我回過神來才發現他根本就沒跟來，而我已經在前往布瑞爾的半道上了。那個英勇的蠢蛋應該是留下來替我擋住他們了。$B$B拜託你，找到我的朋友，然後幫幫他吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94440,'zhTW','神性的教誨','在毒蛛峽谷從血色十字軍身上取回血色十字軍攻擊計畫，然後回到班達利昂要塞找亡靈衛兵比爾穆。','這些血色十字軍身上大多都攜帶著裝有部署命令的袋子。我們知道就要發動攻擊了，但如果我們能取回一些命令，就能警告剩餘的亡靈衛兵和準備伏擊。$B$B你確實是個可靠的聖騎士。殺死這些血色禽獸、取回他們的命令，然後再交給亡靈衛兵比爾穆。後面的事就交給他了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (94441,'zhTW','神性的教誨','到班達利昂要塞內和丹妮莎‧莫爾交談。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94449,'zhTW','火之召喚','到丹莫洛找布魯格斯‧燃裔。','你有好一段時間沒有進行試練了，$N。你展現了耐心，但該來學習混沌…帶來的毀滅了。火焰的呼喚強而有力，如果你已準備好付出代價，它就會回應你。$B$B到東邊的山上找布魯格斯‧燃裔。他就住在南門崗哨上方的洞穴裡。如果你準備好了，他會知道的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94465,'zhTW','火之召喚','把眠炎火炬交給洛克莫丹的布拉迪爾‧塵披。','你的確有掌握火焰圖騰的力量，但單靠力量是不夠的。$B$B國王谷之外，在洛克莫丹的峭壁那邊有一條能通往聖山的隱匿道路。布拉迪爾‧塵披就在那裡守著眠炎聖殿。$B$B帶著這個火把去找他，它能表明你的決心。放在聖殿的火盆裡後，你就能取得圖騰了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94466,'zhTW','火之召喚','找到1個火焰焦油和1個試劑袋，把它們交給洛克莫丹的布拉迪爾‧塵披。','唉，你長途跋涉不是為了追尋傳言吧，$N？你是來尋找永恆火焰和火焰圖騰的。$B$B首先，你需要讓你的靈魂與火焰連結在一起的靈契。$B$B我會幫你製作，但我需要兩樣東西。一個是北方狗頭人洞穴裡坑道鼠地卜師身上的火焰焦油，另一個則是南方山丘石裂先知身上的試劑袋。任務雖然危險，但這些都是必要的材料。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94467,'zhTW','火之召喚','擊敗小型火焰之靈體，將餘燼放在恒焰聖殿屋頂的火盆裡。','火焰靈契準備好了，$N。該面對火焰的考驗了。到聖殿使用靈契後，再爬到山頂上。你會在那裡看到火靈。它不會主動攻擊你，但它會知道你已經能看見它。$B$B出手要快，夥計。等得越久，它會燃燒得越旺。擊敗它後，把它的餘燼放到火盆裡。點燃火炬就能獲得火焰的祝福。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94468,'zhTW','火之召喚','將恆焰火炬交給丹莫洛的布魯格斯‧燃裔。','你手中緊握著火炬離開火盆，望向遠處的洛克莫丹，神聖的火焰隨風狂舞，令你感到心中充滿了激動和興奮。$B$B你沿著小路回到丹莫洛去找布魯格斯‧燃裔。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (94472,'zhTW','大地靈契','向提歐‧錘暴再要一個大地靈契。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (94473,'zhTW','火焰靈契','向布拉迪爾‧塵披再要一個火焰靈契。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94483,'zhTW','給他們一點顏色瞧瞧','在南邊河畔殺死8個遠境堡牧師和12個遠境堡斥候。','我們的斥候回報說，訓練營位在南邊的河畔。要是我早點收到消息，我們兩個就不用這麼麻煩，還得忙著及時找到並排除那些骯髒的人類。$B$B繼續努力，$N。別讓人類跑出他們寶貝的小堡壘，讓我們有時間專心處理手邊的事。$B$B記得速戰速決。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94493,'zhTW','白白犧牲','到影風森林東北方與伊蕾嘉兒‧荊爪交談。','謝天謝地，我們的消息有傳給洛瑟倫。等等，其他的援軍呢？不會只派你一個人吧？$B$B<當你在解釋情況時，伊蕾嘉兒的臉色變得蒼白起來。>$B$B所以消息根本沒傳到瓦拉納爾。我們的處境確實很艱難。$B$B<伊蕾嘉兒深深嘆口氣，然後露出堅決的神情。>$B$B看來我們得自己解決問題了。現在時間緊迫。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94494,'zhTW','水之召喚','到洛克莫丹尋找諾里克‧洛克賽恩。','從你上次接受測驗到現在已經有很長的時間了，$N。迄今為止，你展示了足夠的耐心，不過現在你應該去瞭解水的純潔。$B$B去洛克莫丹找諾里克‧洛克賽恩，沿著湖的西北岸向巨石水壩的南方走，就可以在一間地底居所找到他。祝你好運，$N。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (94495,'zhTW','水之召喚','到濕地尋找赫妲娜‧薩格魯。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94497,'zhTW','水之召喚','到赫妲娜的洞穴下方，用瀑布的水裝滿空的棕色水囊，然後把水囊交給她。','啊，所以你是來找靈契的嗎？那要聽仔細了，親愛的。若要習得智慧和獲得靈契，你必須尋找來自各處的水。採集樣本的同時，一定要睜大眼睛觀察。觀察護衛水源的動物、其滋養的大地，還有它是如何改變生命的。$B$B就先從簡單的開始吧。到瀑布的底端把水囊裝滿，那裡是淡水和鹹水的交會處。去吧，小心不要困在沼澤裡了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94499,'zhTW','水之召喚','到夜行者魚人附近的石望瀑布把空的紅色水囊裝滿水，然後回到濕地找赫妲娜‧薩格魯。','沒錯，赤脊山的水源自止水湖，但湖水隨水流從石望瀑布而下時，卻已經遭到玷汙了。那邊的魚人是體型龐大且遭到扭曲的蠻兵。和你在洛克莫丹看到的不一樣。幸好鎮上的居民都住在瀑布底部附近。$B$B幫我收集那邊的水源樣本。我必須透析其中是否有魔法、劇毒，或是有更糟的東西汙染了古堡附近的水域。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94500,'zhTW','水之召喚','到梣谷的阿斯特蘭納水域附近把未裝滿的藍色水囊裝滿水，然後回到濕地找赫妲娜‧薩格魯。','帶著這個水囊，然後深入梣谷的叢林。阿斯特蘭納那裡有還未受到腐化的水域。那裡有許多遺跡沉於湖中，訴說著過往歲月的故事。幫我從那口湖收集樣本。那裡的水一定很純淨，說不定還蘊含著魔法。$B$B在我讓你回去找諾里克前，這是我需要的最後一個樣本了。$B$B到米奈希爾搭船前往奧伯丁，途中會在南海鎮停靠。$B$B不過要當心…森林是有眼睛的，還會仔細看著你的一舉一動。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94501,'zhTW','水之召喚','把一瓶最純淨的水交給洛克莫丹的諾里克‧洛克賽恩。','在給你水之圖騰之前，諾里克還會有一個任務讓你去完成。我給你的那瓶水在任何情況下都會很有用。去吧，去找諾里克。我們會再見的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94502,'zhTW','水之召喚','到西部荒野，喝下水靈契並淨化斯特登的池塘。$B完成後再回到洛克莫丹找諾里克。','在西部荒野的月溪鎮有個斯特登的池塘。那裡曾有純淨的泉水，但現在卻遭到黑暗力量的玷汙。之後就再也沒人看過那裡的水靈了。$B$B你必須喝下水靈契，然後淨化那片水域。帶著護腕和赫妲娜的最後幾滴藥水，然後放在神殿上。這樣就能召喚未受玷污的水靈。與它交談，看看能不能問出些什麼情報。$B$B完成之後帶著證據回來找我，我再把圖騰交給你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (94503,'zhTW','水之召喚','在西部荒野與小型水之靈體交談。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94505,'zhTW','水之召喚','把水靈碎片交給洛克莫丹的諾里克‧洛克賽恩。','拿著裂片，拿著裂片並且賦予生命。$B$B賦予生命並且理解，理解水就是生命…而墮落則會扼殺生命。$B$B你保護了生命，並將水的力量賦予了生命…',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94532,'zhTW','豺狼人出沒','為羅格瑪的妮莎‧血鼻殺死8個赤脊山秘法師、8個赤脊山陷捕者和6個赤脊山蠻卒。','雖然因為暮光的到來，豺狼人越來越少出現，但他們仍然是威脅。$B$B西南邊的山丘飽受他們的肆虐，導致貿易中斷，旅人也無法通行。$B$B解決這個威脅，為我們的盟友清出一條路。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94533,'zhTW','史納戈的鼻子','到鬃丘找到史納戈，將他殺死，為妮莎‧血鼻取回他的鼻子。','在這裡西南邊的鬃丘那裡咯咯叫的豺狼人當中，有個名叫史納戈的老豺狼人。這傢伙發出的聲音特別惱人。因為那會激勵周圍的豺狼人，為進入那個地區的盟友和斥候帶來麻煩。$B$B成功解決這個最惱人的豺狼人後，把當作紀念的戰利品帶回來，那一定是非常不錯的收藏品。$B$B記得速戰速決，$N。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94535,'zhTW','鬃丘強盜','為克瑞莎‧黑棘從鬃丘的豺狼人身上收集40個遭竊的礦石。','我們的盟友在南邊的山丘採礦，他們回報多次遭到當地的豺狼人攻擊。$B$B去南邊一趟，找到他們的營地，取回遭竊的礦石。需要的話，也能從他們的屍體取得。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94613,'zhTW','馬上王國','前往威勒的農莊，調查消失的馬匹。','我們的戰馬都是來自附近的兩個農場。其中一個農場位在鎮外的那條路上，是由威勒家族所有，他們顯然失去了所有馬匹。其原因目前尚不得而知。$B$B沒有戰馬，我們就沒有騎兵，沒有騎兵，我們就不可能贏過部落。$B$B所以，你懂的，必須用最快的速度化解這個困境。不過，要從哪裡著手，我並不是很確定。$B$B前往威勒的農莊，跟班吉談談。看看他有什麼話說。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94614,'zhTW','淡水惡魔','在威勒的農莊附近的河畔擊殺8個泥鰭神諭者和8個泥鰭戰士。','你看到下面河邊的那些魚人了嗎？就在這裡的西邊。糟糕的東西。對我的牲畜有害，也對野生動物有害。更別說，他們就定居在我最喜歡的釣魚點上！$B$B要是你能除掉一些魚人，我敢說，大河林地的每個人都會對你感激不盡。$B$B拜託，殺掉你看到的所有魚人。這麼做真的能幫我們一個大忙。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (94616,'zhTW','水之靈契',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94617,'zhTW','捕獵山狗','擊殺名叫「煤皮」的山狗，將牠的毛皮交給班吉‧威勒。','這附近棲息著一群山狗，牠們的巢穴就在這裡的西邊。我們有時候可以看到牠們出現在河的對岸。牠們通常會在岸上捉魚，我猜魚人的到來，導致牠們失去平常的食物來源，不得不去獵食馬匹。$B$B那群山狗的首領體型稍大，一身黑毛。我們替牠取了「煤皮」的綽號。我想，只要你殺了牠，其他山狗就會落荒而逃。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94618,'zhTW','威勒的逃跑駿馬','找到其中一匹沒被山狗獵殺、跑出威勒的農莊的馬，餵牠吃一些飼料。','根據你的發現，山狗似乎吃了絕大部分的馬。不過，還有幾匹倖免於難。$B$B沒被吃掉的馬很可能跑去別的地方了。我不知道有幾匹馬順利逃生，但我們最好在山狗回來之前找到牠們。$B$B<班吉向你遞出一個袋子>$B$B拿去。如果你找到馬，就餵牠吃一些飼料。這能讓你得到牠的信任，順利把牠帶回來這裡。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94672,'zhTW','侵略暮光','為羅格瑪的特朗古爾在陽光林地擊敗8個暮光劫掠者和8個暮光低階教徒。','在大河林地，我們的對手不光只有人類，$N，而他們也不是我們最迫切的問題。$B$B名為暮光之錘的邪教已經開始迫害他們扭曲神明眼中的異教徒。第一個慘遭毒手的目標，就是西邊那個被破壞殆盡的人類定居地。羅格瑪無疑會是下一個。$B$B絕不能讓他們在我們家門口建立據點，我們承擔不起這種風險。前往這個所謂的陽光林地，削減他們的數量。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94678,'zhTW','豺狼人出沒','為南方守望的塞德瑞克‧戴爾頓擊殺8個赤脊山秘法師、8個赤脊山陷捕者和6個赤脊山蠻卒。','打從我們來到這裡，豺狼人就一直是我們的心腹大患。雖然他們的威脅不如暮光之錘大，但他們極為好鬥，又很難纏，更糟的是，他們還數量龐大。$B$B過了這個哨站，那裡的山林深受豺狼人肆虐，導致前往北邊的道路危機四伏，而且居住在遠境堡要塞牆外的民眾也倍受威脅。$B$B如果我們想讓這片土地變得安全，就必須消滅豺狼人。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94679,'zhTW','史納戈的鼻子','在鬃丘找到史納戈，擊殺他，然後將他的鼻子交給南方守望的塞德瑞克‧戴爾頓。','豺狼人重視力量勝過一切。藉由擊殺他們的最強者，我們不只從實際層面上削弱他們的威脅，也能將恐懼植入他們的內心。$B$B鬃丘的某個地穴中，有個惡名昭彰的豺狼人，名叫史納戈。他的死無疑會讓赤脊山的豺狼人陷入恐慌。$B$B把他的鼻子帶來給我，越快越好。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94680,'zhTW','暮光信函','為羅格瑪的特朗古爾前往陽光林地，從暮光暗影術師身上取回3份暮光信函。','一小群、一小群的暮光之錘教徒一直都在各地出沒，但我從沒看過他們這麼多人聚在一起。他們似乎被某個人或某件事鼓舞，開始擴張自己的勢力。$B$B我很想進一步了解這些教徒，還有他們的目的。他們的暗影術師受到黑暗力量祝福，而且很可能是他們當中最受信任的成員，才能主導如此規模的攻擊行動。$B$B把你從他們的屍體上找到的東西帶來給我，我們或許能一窺他們的真實意圖。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (94773,'zhTW','神聖恩典',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94774,'zhTW','神聖恩典','與暴風城的高階牧師勞瑞娜談話。','你已經引起了我們高層的注意，$N。他們要你儘快到暴風城的聖光大教堂去一趟。顯然，他們認為你已經證明了自己的實力，也已經準備好接受下一步的訓練了。當你到了那裡之後，就去找高階牧師勞瑞娜，她會進一步地指導你。祝你好運，願聖光與你同在。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94775,'zhTW','神聖恩典','與暴風城的高階牧師勞瑞娜談話。','伊露恩祝福你，好心的$R。我願聖光與你同在，願它一直保護著你。$B$B你們的一位牧師不久之前來找過你，他說要你到光明大教堂去找高階牧師勞瑞娜，希望你可以儘快動身。我不會在這裡浪費你寶貴的時間——你的人民需要你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94776,'zhTW','神聖恩典','與暴風城的高階牧師勞瑞娜談話。','是時候到暴風城去了，$N。光明大教堂的高階牧師勞瑞娜要你去找她，看來她有什麼事要與你商議，但是在我看來，你迄今為止表現得一直很出色，看來她要和你談的是件好事情。$B$B不要在這裡浪費太多的時間。如果我是你，我會儘快去那裡的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94777,'zhTW','神聖恩典','與暴風城的高階牧師勞瑞娜談話。','不久之前，你們的一位牧師來這裡找你，$R。他說如果我看到你，就讓我告訴你趕快回光明大教堂去。他說這件事很重要，但是換了我是你的話，我不會過於擔心。他似乎並不是很焦急的樣子…看來是好事情。不過還是趕快動身吧。$B$B願伊露恩與你同在，好心的$R。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94789,'zhTW','風之召喚','到阿拉希高地找維里克‧雷鎚。','願艾澤拉斯的風能祝福你，你很快就能和我們最強大的族人比肩了。看到你通過了這麼多考驗，我十分驕傲，你的前途肯定是一片光明。$B$B風元素確實難以駕馭，但我相信你也能通過挑戰。$B$B到北方的阿拉希高地去。你可以在北方的山丘找到維里克‧雷鎚，他會再告訴你更多細節。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94792,'zhTW','馴服野獸','使用馴獸棒馴服一隻石皮野豬。練習你的技能，然後將馴獸棒還給約瑟芬‧卡森。','許多獵人喜歡有其他動物的陪伴。身邊多了動物夥伴的你會發現，就算是最危險的情況也能存活下來。正如人們所說，出門靠朋友嘛。不過，要得到動物夥伴需要的是細心。自然的平衡很容易就被破壞，所以必須崇敬待之。$B$B帶著這個馴獸棒到森林裡去，你就能馴服石皮野豬和訓練成為獵人的技巧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94793,'zhTW','訓練野獸','到閃金鎮與艾薩克‧查交談。','你現在擁有了馴服寵物的力量，但是你還必須掌握訓練寵物的技能。這部分沒有人比護林者艾薩克‧查奎爾朵菈還厲害。他會讓你學會訓練新寵物的技能。$B$B願風與你同在，年輕的$C。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (94817,'zhTW','惑淆閃光',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (94818,'zhTW','應變計畫',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94819,'zhTW','應變計畫','與鐵爐堡的高階女牧師敏絲談話。','$N，高階女牧師敏絲希望能在鐵爐堡與你會面。快點去吧，我聰明的朋友，你的下一次試煉即將到來。雖然我希望能親眼看著你通過你們種族的特殊儀式，但是我的職責讓我必須留在這裡。願聖光照耀你前行的道路。敏絲應該是在秘法區裡等你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94820,'zhTW','應變計畫','與鐵爐堡的高階女牧師敏絲談話。','你的種族非常聰明，$N。我們很高興能稱你們為盟友。你和你們的種族每一天都向奪回自族城市的目標邁進一步，還肩負保障流亡族人安全的重擔。這種對家園的渴望肯定非常難受。$B$B最近從鐵爐堡傳來消息說，秘法區的高階女牧師敏絲要你回到那裡去找她。如果我是你的話，我可是不會讓她久等的。願伊露恩指引你的旅程。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94821,'zhTW','惑淆閃光','與鐵爐堡的高階女牧師敏絲談話。','最近有一個牧師到我們這裡來找過你，年輕的$R。他說你應該儘快回到鐵爐堡的秘法大廳去。高階女牧師敏絲在那裡等著你，她會告訴你更多的資訊。$B$B願聖光與你同在，$N。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94822,'zhTW','惑淆閃光','與鐵爐堡的高階女牧師敏絲談話。','你已經引起了我們高層的注意，$N。他們要你儘快到鐵爐堡的秘法大廳去一趟。顯然，他們認為你已經證明了自己的實力，也已經準備好接受下一步的訓練了。當你到了那裡之後，就去找高階女牧師敏絲，她會進一步地指導你。祝你好運，願聖光與你同在。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94824,'zhTW','惑淆閃光','與鐵爐堡的高階女牧師敏絲談話。','是時候到鐵爐堡去了，$N。秘法大廳的高階女牧師敏絲要你去找她，看來她有什麼事要與你商議，但是在我看來，你迄今為止表現得一直很出色，看來她要和你談的是件好事情。$B$B不要在這裡浪費太多的時間。如果我是你，我會儘快去那裡的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94841,'zhTW','遺失的貨箱','前往大河林地的火線港，將遺失的貨箱交給佛利茲‧焦炫。','<木箱側面有張手寫標籤。右側是一張地圖，在東南方海岸線一帶畫著一個巨大的紅圈，紅圈南方則是一座畫得相當拙劣、被水域與某種有翼生物包圍的神廟。左側則是一張用超大字體寫成的紙條。>$B$B佛利茲‧焦炫的財產$B$B火線港$B$B警告：禁止篡改。未經監督禁止開啟。$B$B<標籤下方還有一張紙條。>$B$B如果遺失，請送還給佛利茲‧焦炫。火線港。大河林地。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94842,'zhTW','難聞的植物肥料','為哈利根‧透納收集4個特大螯蝦殼、4份新鮮肥料，以及8個泥鰭魚人頭顱。','我們在這裡製造出自己的肥料。這是我的特殊配方，味道超級難聞，不過能讓樹木像雜草一樣瘋長。$B$B將螯蝦殼、糞肥和魚人頭顱用 1:1:2 的比例混合而成。很美味，對吧？$B$B糞肥很容易取得。我們在南邊有個牧場專門提供糞肥。至於頭顱和甲殼嘛，那些東西你得到河裡一趟才能獲得。$B$B如果你願意伸出援手，我們絕對歡迎你幫忙取得一些肥料原料。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94857,'zhTW','要是樹倒的時候沒人聽見…','前往透納的伐木場求援。','陌生人，聽我說！$B$B我是在附近的伐木場工作的伐木工。就像你看到的，因為一場意外，我被困在這裡。如果不快點脫身，我不是失血過多而死，就是被野生動物吃掉。$B$B拜託，快去伐木場找人來救我！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94863,'zhTW','馴服野獸','使用馴獸棒馴服一隻森林灰狼。練習你的技能，然後將馴獸棒還給約瑟芬‧卡森。','你已經學會如何馴服野豬，現在該進行下一課了。森林裡有更兇狠的動物，如果能細心對待牠們，你就能贏得牠們的信任。$B$B帶著馴獸棒去找森林灰狼。記住，必須以森林的平衡為重。再次證明自己身為獵人的實力吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94864,'zhTW','馴服野獸','使用馴獸棒馴服一隻小森林熊。練習你的技能，然後將馴獸棒還給約瑟芬‧卡森。','你已經透過馴服野豬和灰狼來證明自己的能耐，現在該進行最後一項挑戰了。艾爾文森林的平衡需要靠崇敬的心與獵人的技藝來維護。帶著馴獸棒去找小森林熊。證明自己也能贏得強大動物的信任吧。$B$B完成這個挑戰就能進一步與動物同調。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94872,'zhTW','購買友誼：瑪格拉姆','前往淒涼之地的瑪格拉姆村，將圖騰手提包交給瑪格拉姆軍需官，大幅提高你在該部族的聲望。你的瑪格拉姆半人馬聲望必須至少是中立。','目前，勇猛的瑪格拉姆無疑正在贏得這場地盤之戰。值得慶幸的是，雙方並未頻繁地在沙漠各地爆發衝突，而且他們在東邊的村莊每天都會變大一點，士兵也會勇敢一點。$B$B不知道失去制衡的瑪格拉姆部族會帶來什麼後果，令人憂心忡忡，但不能否認地，他們是很有潛力的盟友。$B$B如果你想獲取他們的信任，就把這袋圖騰交給他們的軍需官，不過記得注意安全。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94873,'zhTW','購買友誼：吉爾吉斯','前往淒涼之地的吉爾吉斯村，將圖騰手提包交給吉爾吉斯軍需官，大幅提高你在該部族的聲望。你的吉爾吉斯半人馬聲望必須至少是中立。','任一個半人馬的優勢部族都可能是很好的盟友，不過對於吉爾吉斯，我應該先給你一個忠告。$B$B可靠情報指出，在這場瑪格拉姆與吉爾吉斯的戰爭中，吉爾吉斯很可能正逐漸落於下風。這或許對我們有利，孤軍奮戰的部族一旦陷入絕望，就更容易接受外援。$B$B我準備了一包圖騰，讓你交給吉爾吉斯村的軍需官，他們應該有類似的人物。希望事情一切順利。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94877,'zhTW','拯救陽光林地','為戴瑪‧布蘭特在陽光林地擊敗8個暮光劫掠者、8個暮光暗影術師和8個暮光低階教徒。','環顧四周，你看到什麼？殘破的家園，以及疲憊的人們。$B$B暴風城放任我們自生自滅，防守的人員每天越來越少。城牆之內的許多人都是難民，他們勉強逃過一劫，自己的家人卻生死未卜。$B$B遠境堡不是暴風城，陌生人。我們西北邊的定居地被暮光之錘佔據，但我們不會輕易拱手讓人。如果你想要戰鬥，就前往陽光林地，消滅那裡的野蠻人。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94879,'zhTW','知識的片段','前往陽光林地，為遠境堡要塞的艾希‧安珀荷收集5份暮光書頁。','你見過北邊那座破滅的城市了，對嗎？是叫陽光林地？戴瑪試過派遣部隊，但不知道何年何月才能奪回它。我有更棒的想法。$B$B老實說，暮光之錘並不是第一次發動攻擊。他們似乎有個根據地，從那裡統籌行動，而我知道那是哪裡。當你在做你們冒險者最擅長的事時，看看你能不能順便找一下他們到處亂丟的文件。有了足夠的文件，我應該就能拼湊出他們的意圖。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94881,'zhTW','奇怪的飾品','前往陽光林地，為遠境堡的艾希‧安珀荷從暮光暗影術師和暮光低階教徒身上取回25個暮光符咒。','哇，看看是誰來了？一個勇敢的陌生$C跑來拯救我們脫離苦海？太讓人欣慰了！也許你可以幫我做一些事？我一直很想對佔據陽光林地的邪教有多一點了解。$B$B就像其他邪教一樣，他們有自己的一套階級系統。魔法天賦較高的人通常倍受青睞，而且會得到彰顯其地位的信物。這些符咒隨即會被注入力量，因此具備極為強大的邪教魔法。$B$B我想親眼看看這些信物。請你大發慈悲，拿一些來給我吧，好嗎？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94884,'zhTW','令人不安的發現','將裝滿的水晶催化劑交給遠境堡要塞的艾希‧安珀荷。','我已經受夠這個洞穴了。一旦你清出一條路，我就會趁亂溜之大吉。$B$B不過我的身體太虛弱，恐怕無法帶走那些樣本。它們的能量龐大無比，而我已經被困在這裡不知道多久了。一旦我們離開這裡，請馬上把樣本送去給安珀荷女士。我得休息一下。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94886,'zhTW','西線有戰事','到西邊的暮光之罩附近找瑞夫坦中士。','你在遠境堡這裡幫了很多忙，相信還有其他地方更能讓你一展長才。$B$B不久前，我們的一支巡邏隊失蹤了。他們原先負責巡邏西方的邊界，但根據安珀荷女士發現的情報，他們恐怕直接闖進了暮光之錘的大本營。$B$B我們可以自行處理陽光林地的收尾工作。如果那位好心的女士說的沒錯，我們就必須去找我們那位迷途的中士。他很可能正需要幫手。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94889,'zhTW','開闢道路','為瑞夫坦中士在暮光之罩中擊敗8個暮光狂熱者、8個暮光腐蝕者，以及8個暮光勇士。','暮光之錘的勢力似乎每天都在壯大，但來自暴風城的消息卻是少之又少。我們的潰敗，只是遲早的事。$B$B我不管安珀荷那樣的官僚說什麼。既然有軍隊在自己家園肆虐，我就不會拋棄這個陣地。就算我們現在離開，終究還是要再次對上這些教徒。但下一個戰場，就是在自己的家門口。$B$B如果你接到的命令是當我的保母，那就先發揮作用，幫我除掉這些狂熱者。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94911,'zhTW','自然之子','在雷霆崖和圖拉克‧符文圖騰交談。','你好，年輕的$R。我看得出你是個傑出的德魯伊。你得和雷霆崖的圖拉克‧符文圖騰談談。他會教你如何抵達塞納里奧議會在卡林多的月光林地要塞。$B$B你不會被拒之門外的，議會的德魯伊也會把知識傳授給你。$B$B正如你同胞所說的，願風能祝福你，年輕人。祝你冒險順利。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94912,'zhTW','自然之子','在暴風城和沙德拉斯‧月樹交談。','你好，年輕的$C。$B$B你有聽過塞納里奧議會嗎？我猜是沒有。和你一樣，他們是自然學者和德魯伊組成的遠古組織。你到暴風城可以找一個名叫沙德拉斯‧月樹的夜精靈。他會教你如何抵達塞納里奧議會在卡林多的月光林地要塞。$B$B去吧。如果你想拯救家園，還有很多事要學呢。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94913,'zhTW','月光林地','使用法術「傳送：月光林地」前去月光林地，在那裡與永夜港的德迪利特·星焰談話。','所有的德魯伊都是神聖的月光林地所歡迎的客人。月光林地的守衛者雷姆洛斯一直以來都在監看著所有在此沉睡的德魯伊。那麼我就教你傳送到那裡去的法術吧，如果你想要在月光林地尋求知識或者慰藉，就可以施展這個法術。$B$B你在艾澤拉斯的第一堂課，就是到月光林地去跟永夜港的德迪利特‧星焰談談關於你的前途。祝你好運，年輕的德魯伊。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94914,'zhTW','月光林地','使用法術「傳送：月光林地」前去月光林地，在那裡與永夜港的德迪利特·星焰談話。','所有的德魯伊都是神聖的月光林地所歡迎的客人。月光林地的守衛者雷姆洛斯一直以來都在監看著所有在此沉睡的德魯伊。那麼我就教你傳送到那裡去的法術吧，如果你想要在月光林地尋求知識或者慰藉，就可以施展這個法術。$B$B你在艾澤拉斯的第一堂課，就是到月光林地去跟永夜港的德迪利特‧星焰談談關於你的前途。祝你好運，年輕的德魯伊。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94923,'zhTW','丟帽','在河岸的某個魚人聚居地找到羅比的帽子。','<羅比靠到你身邊說話，彷彿正在分享某個大秘密。>$B$B喂！嘿，$G先生:小姐;，我需要你幫忙！$B$B我姊姊買了一頂帽子給我，慶祝我生日，可是我在河裡玩的時候弄丟了。因為魚人的緣故，家人本來就禁止我下水，所以我不能請爸爸或伊莉幫忙，不然他們就會知道我跑去玩水！$B$B那是一頂好帽子。我敢說一定是某個魚人把它佔為己有！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94924,'zhTW','獵殺獵人','為看守者柯涅利斯擊殺12個羅格瑪盜獵者。看守者柯涅利斯','獸人盜獵者都是嗜血的魔鬼。他們會殺死所有會動的生物，不管是人類、獅子，還是馬。他們是大河林地所有生靈的威脅，非得阻止他們不可。$B$B他們在平原上成群結隊，就像得了狂犬病的動物。一旦發現，就格殺勿論。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94928,'zhTW','給佛利茲的貨','將一捆獅子皮交給火線港的佛利茲‧焦炫。','這些皮革應該送到火線港。那是哥布林在東北方建立的港口。$B$B等你到了那裡，就把皮革交給佛利茲‧焦炫。跟她說這批貨來自柯涅利斯。我們的交易內容早就談妥了，所以她會知道那是幹嘛的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94931,'zhTW','失竊的鋸刃','為伐木場的哈利根‧透納從鬃丘的豺狼人營地取回8個鋸刃。','大部分時候，南方守望的小子們的確讓豺狼人不敢越雷池半步。但時不時就會幾個漏網之魚半夜溜進營地，製造一些小麻煩。他們特別喜歡偷走鋸刃，大概是想用鋒利的金屬做武器。$B$B要是你可以幫我們搶回一些，那就真的幫了大忙。那些豺狼人應該把它們運到西邊的山丘，藏在他們營地的某處。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94946,'zhTW','魔法城市達拉然','從微風島搭乘割天者號到達拉然城，然後在抵達時和德納里斯‧星颺交談。','我本來打算成為我們當中第一個踏足艾澤拉斯的成員，但最近的邪教事件讓我改變了計畫。因此，我將會留在瓦拉納爾這裡一段時間。不過，別擔心，當我們的人抵達達拉然後，自然會有幾位法師來接待。在我們將這裡的事安排妥當前，我會鼓勵你去探索艾澤拉斯。需要像你這樣的探員的時候，我們會告訴你。$B$B準備好以後，就到小屋外的碼頭搭乘割天者號吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94947,'zhTW','歡迎來到艾澤拉斯','使用天裔精靈暴風城傳送門，到暴風要塞向伯瓦爾‧弗塔根回報。','這下面的世界還真大，我們也必須派人好好探索。這就得靠你了。$B$B祈倫托和其他志同道合的國度一同組成了「聯盟」。這個聯盟的核心就在暴風城的南方。伊拉德林請我找人到暴風城，和一個名叫伯瓦爾‧弗塔根的人類攝政王會面。$B$B準備好之後，就使用祈倫托法師為高天盟設置的傳送門，然後前往暴風城吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94961,'zhTW','反咬一口','將20個暮光指骨交給弗索。','<豺狼人從口袋掏出一塊黃金，朝你揮了揮。>$B$B$R，我用東西換！我找到這東西的地方還有更多。幫我報仇，我就帶你去！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (94999,'zhTW','看守者之眼','將伊琳諾兒的物資包裹交給南方守望的看守者弗德里克。','喔！抱歉，我沒看到你。$B$B我正在為我的一個朋友準備一點小東西。其實…正確來說應該是一個熟人。你見過看守者弗德里克了嗎？他駐紮在南方守望，就在這裡的西邊。$B$B他時不時就會因為巡邏任務跑來牧場，我想，送他一個小東西表達我的感激，應該是個不錯的主意。$B$B我想親自送給他，但是我得照顧弟弟，而且牧場還有很多工作要做。$B$B我相信你能理解。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95034,'zhTW','有債有還','在瑟伯切爾與露蜜娜‧風詠交談。','我想你應該知道，在路上攻擊我們的其實不是豺狼人。$B$B攻擊我們的其實是個巨大的狼形生物，也就是「狼人」。他把守衛解決掉後就直衝我來，但巴諾卻跑來擋在中間。我成功施展法術嚇跑他，但巴諾卻已被咬成重傷。巴諾堅持要我棄他而去，但我拒絕了。$B$B當豺狼人找到我們的時候，我們正拖著傷軀回來。接下來的事才是最可怕的…',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95041,'zhTW','資料囤積者','在諾姆瑞根附近收集7張諾姆瑞根檔案資料卡，然後交給鐵爐堡的潔瑪‧迅移。','我們逃離諾姆瑞根之前，我就事先抄錄了我們家族文庫的資料。秘法科技的程式、第二次大戰潛水艇的船體設計、迅移奶奶的辣醬食譜…我們家族的成就都在這些檔案之中了。$B$B但我直到鐵爐堡才發現我的背包破了一個洞！有些穿孔卡片不見了，沒了它們，那些資料便難以取回。$B$B那些卡片一定是被埋在諾姆瑞根外某處的雪裡了。你可以幫我找找看嗎？我知道這十分強人所難…',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95042,'zhTW','尋找科爾寶石','帶一塊科爾寶石給梣谷的奧里克‧霜幕。','被遺忘者聖騎士…在梣谷這裡？真是有趣。$B$B所以你要找科爾寶石嗎？我也不意外，因為有時候聯盟的聖騎士會用這個材料來強化魔法武器。那殞落的聖騎士又會有什麼不同呢？$B$B如果你要這種寶石的話，就必須去北方名叫黑澗深淵的廢墟。其中的納迦還在使用這種寶石。千萬別隻身前往，$C。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95059,'zhTW','焦炫的貨箱','將焦炫的貨箱交給遠境堡要塞的騎士指揮官戴瑪‧布蘭特。','該來一次特別的外送了。$B$B遠境堡的騎士指揮官戴瑪‧布蘭特正在等這個。因為一些原因，他總是要我叫他全名。真是奇怪的傢伙。$B$B總之，你可以在這裡西南邊的要塞找到他。那是超級大的石頭堡壘。你絕不會錯過的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95062,'zhTW','焦炫的貨箱','將焦炫的貨箱交給羅格瑪的克隆羅許。','該來一次特別的外送了。$B$B老克隆羅許正在等這個包裹，他就在這裡西邊的羅格瑪。$B$B我建議你快點去找他，但務必小心為上。你可能會問為什麼？我只能告訴你，沒事就別問東問西。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95064,'zhTW','預防性措施','為泰洛堡的看守者柯涅利斯擊殺12個羅格瑪受訓者。','自從獸人抵達以來，他們已經逐漸成為一大威脅。先是佔據了河岸的土地，現在又開始向平原內部發展…$B$B說實話，我永遠不能理解他們，我也不在乎，不過他們以為能夠得寸進尺，未免太小看我了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95065,'zhTW','釣魚時間','將1個閃光的小珠和3隻夜色蟲帶去暴風城的港口給吉爾伯特‧格雷。','多棒的景色啊…這是一個老頭子所能奢求的最棒美景了。$B$B現在魚兒確實很會咬餌，但我只剩下最後一個魚餌了。我想你身上應該沒有多餘的釣魚用品吧？當然沒有，請原諒我。一想到能再次拋竿，我就會興奮過頭，沒意識到自己可能是少數走到哪都隨身帶著釣魚用品的人。$B$B你能幫我補充庫存嗎？凱薩琳‧利蘭在貿易區西邊的運河旁販賣各種釣魚用品。跟她說是老格雷叫你去的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95111,'zhTW','被低估的奇才','與奧特交談，並請他幫你鑄造刀劍。','塔倫米爾有個名叫奧特的鐵匠。他看起來就只是個賣刀劍給旅者的普通鐵匠。我從他那邊買了一把劍，之後又拿到幽暗城請人保養，結果鐵匠都對其手藝讚不絕口。他們以為是什麼大師鑄造的，結果不是，全都是奧特打造的。$B$B我想給這個獸人一個奉獻心力的機會。帶著材料到塔倫米爾，然後請奧特幫忙。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95118,'zhTW','鹹水蠻族','在東風水濱沿岸擊殺8個魚人神諭者和8個魚人戰士。','魚人，魚人，魚人！我一天到晚都聽到這個詞，來自水手、漁夫，甚至是我自己小孩的口中！每個人都在對我耳提面命！我承認，他們不是什麼大問題，卻對港口營運影響很大！$B$B幫幫我，好嗎？殺掉那些東西，我不會讓你白白出手的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95119,'zhTW','不友好競爭','前往火線港北邊的東風水濱沿岸，擊殺10個東海海盜和10個東海火槍手，','你知道東海幫嗎？一群討人厭的傢伙，而蓋棺論定的傢伙還是一個經營著「火線港」這種地方的人。$B$B這群人殘暴又嗜血，最糟糕的是，他們還踩到我的底線。盜竊貨物，擊沉船隻，這些事都讓我損失慘重！$B$B我們必須徹底打擊他們的胡作非為，先從離這裡最近的傢伙開始。沿著北邊的海灘就能找到他們。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95120,'zhTW','懸賞：老爛餌','將殺死老爛餌的證據交給碼頭管理員惠茲巴茲。','水手和泳客注意了！出現了一個特別好戰的魚人，當地漁夫給他取了「老爛餌」的綽號，他一直在攻擊行經南方水域的小艇和其他小船，尤其是鄰近被魚人肆虐的群島附近。$B$B碼頭管理員惠茲巴茲已經發布懸賞，拿出殺死那個生物的證據就能領賞。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95121,'zhTW','美味海味','為芬博‧油蜜收集12個魚人的眼球和6份沙行蟹肉。','歡迎光臨芬博的水上咖啡館！本日特餐是烤野豬肉，還有烤魚…基本上每天都一樣…$B$B我真的需要換菜單了。我看中的是一道全新的海鮮燉菜，不過我會需要一些新鮮的肉。幾個魚人眼球和一些蟹肉應該就夠了。$B$B你可以在附近的海灘找到這兩種食材。還是傳統的在地食材最棒！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95125,'zhTW','奧特的傑作','看著奧特鑄造你的劍。','這些的確是上好的材料，$C。能讓我幫你鑄造刀劍是我的榮幸，我也希望不會辜負你的期望。$B$B還請你退後一點，這樣我才能好好工作。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95126,'zhTW','月銀刃','把奧特的傑作交給銀松森林的崔凡‧羅爾。','這是你要的刀刃。你是說一個名叫崔凡的聖騎士派你來的嗎？見到他之後請代我向他道謝，讓我有這個機會。願榮譽與你隨行，朋友。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95140,'zhTW','老火眼','到銀松森林用月銀刃摧毀老火眼。','你已經有武器了，$C。希望它不會辜負你。$B$B當地人告訴我老火眼在南方狩獵，到吉爾尼斯的大門附近應該就能找到他了。把他找出來，用你新鑄的劍解決他。完成之後再回來接受塑風者的獎賞吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95147,'zhTW','失蹤的斥候','將博萊恩的訊息傳達給南方守望的戴爾頓隊長。','你說…你從哪裡來？你不該在這裡！$B$B<博萊恩強忍著痛苦。他渾身是傷、衣衫襤褸，腿上的咬傷嚴重惡化。>$B$B把這個送去給戴爾頓。沿著路先往北走，再往東走，就會看到比我腿上的傷口還要寬闊的平原。替我告訴他，他是對的，反正到時候我人已經死了，看不到他得意的嘴臉。$B$B真痛恨這些該死的山丘！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95148,'zhTW','南方守望豺狼人報告','將南方守望豺狼人報告交給遠境堡要塞的騎士指揮官。','我很想把這個血淋淋的訊息親手交給騎士指揮官，但我不能擅離職守。我已經做了一些清理，讓它不那麼…血腥。$B$B由於最近豺狼人異動頻頻，送信的事恐怕只能落到你身上。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95156,'zhTW','塞了又塞，刺了又刺','為訓練場的安珀收集3個乾草捆。','我們的訓練假人開始出現嚴重的磨損和破損。要是我們不快點修好它們，我擔心新兵可能無法做好戰鬥的準備。$B$B在你來的路上可能沒有注意到，但要塞外面有個小農場，農場主人的姓氏是威勒。他可能有不少多餘的乾草可以分給我們。$B$B如果他能夠供應物資支援我們的訓練，我會確保他得到適當補償。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95161,'zhTW','銘記我對你的愛','將染血信件送去給暮色森林的艾瓦特‧菲爾伍德。','如果你在找傑瑞米‧織心者，最好的辦法就是去暮色森林找他新過繼的養母艾瓦特‧菲爾伍德。一位親切的女性。或許是她的工作需要多一個幫手，但總比一直待在孤兒院裡還要好。$B$B如果你見到小傑瑞米，請務必告訴他，我們大家都很想他，好嗎？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95162,'zhTW','收集白牙豬肉','為博德羅克附近的納佐克收集10份大塊野豬肉。','沒被人類或暮光之錘佔據的土地很少，這座牧場是我們少數幾個食物來源之一。巨魔不太擅長當農夫，但他們很愛吃白牙豬烤肉，只要持續供應肉，他們就同意我留下。$B$B隨著戰事推進，對食物的需求也與日俱增。現在我幾乎沒有足夠的食物，這些巨魔看我的眼神就像在看下一頓大餐。$B$B如果我們要為羅格瑪供應足夠的肉，我就需要你幫忙生出肉。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95184,'zhTW','最鋒利的刀劍','把8個堅固的磨刀石拿給遠境堡訓練場的安珀‧刃語。','接受嚴苛的訓練是一回事，但這些訓練生還不了解，訓練用的劍和老兵精心保養的武器有何差別。$B$B我想是時候該讓新兵們知道，鋒利的武器有時就是勝利與死亡之間的分水嶺。$B$B如果你能幫我們找來一些磨刀石，我們一定會善加利用的。有些工匠是這個領域的名家。建議從那方面著手。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95212,'zhTW','好鞍不將就','收集6張完好花豹皮，然後帶到凍石農場。','我們已經為了奧特蘭克遠征行程準備好一批公羊了，但卻少了製作鞍座的材料。$B$B從體型龐大的凶狠花豹身上收集皮革，然後帶來給我。目的地十分寒冷，我們只能給遠征隊最好的保暖裝備！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95214,'zhTW','遭竊的火藥粉','從古博拉採掘場東邊的穴居怪手中搶回16份遭竊的火藥粉，然後回去找礦場主管瑟斯丁。','這個桶子裝的火藥粉足以把麥格尼國王的王座廳炸成一片空地。我們得在穴居怪找到方法引爆前把它搶回來。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95216,'zhTW','新的瘟疫','為幽暗城的席歐多‧格雷夫從羅德隆廢墟的枯萎之牙身上收集劇毒菌株。','歡迎來到幽暗城最核心的要地：鍊金房！在這裡，我們會對艾澤拉斯最致命的奇異標本進行實驗。$B$B我今天剛好心情不錯，所以我要讓你參與我最新的調查。看來在我們這座美麗城市上方的廢墟中，潛伏著一種毒性超強的節肢動物。據說牠的毒素甚至能腐蝕不死生物的肉體。多麼令人興奮！$B$B我想證實這些說法。如果你發現自己因為被牠咬到而逐漸衰弱，我會很希望能得到一份樣本。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95217,'zhTW','採掘場的鐵匠','收集12個銅錠和4張韌化野豬皮，然後交給弗拉斯特‧多克南。','所以你想學會如何打鐵嗎？或許我們可以互助一下。$B$B補給品早就該送來了，但我現在沒辦法修補營地。如果你能把我需要的東西找來，我就會教你如何打鐵。你覺得如何？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95219,'zhTW','港對港運送','把火線港火藥桶拿給菲拉斯羽月要塞的瑪德拉克‧綠井。','我又有工作要派給你，小子。你想周遊世界嗎？$B$B這是有史以來品質最高的貨。問題是，要送到人在菲拉斯羽月要塞的客戶那邊，距離相當遙遠。只要你看到從沒見過的高大樹林，就會知道已經到了。$B$B我的部下已經把東西打包好了，但誰也說不準它會不會突然爆炸，所以切記小心拿好，知道了嗎，小子？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95250,'zhTW','兇惡生物','在羅德隆廢墟中拾取男爵的頭顱，並將它帶回去給楚曼隊長。','$R，你想幹嘛？你看不出來我們有一場仗要打贏嗎？$B$B我的長官早已衝進戰場，他命令我堅守崗位。但自從那之後，已經過了一段時間了。$B$B我懷疑你在戰鬥中連十分鐘都撐不到，不過要是能讓你的蠢腦袋忙碌一點，那你就去找總元帥吧。他絕對是你至今為止看過最高大、最威風凜凜的英雄。你一看到他就會知道了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95254,'zhTW','懸賞：陷爪','把陷爪的鉗子交給芬博‧油蜜。','呼叫所有釣手！$B$B不只是平常的蟹肉而已，我要買整隻爪子。我看過一隻大的在水裡爬來爬去，偷吃魚餌、截斷釣魚線。$B$B任何能把那傢伙的鉗子帶給我的人，必有重賞。還能分一份我親手特製的料理。$B$B--芬博‧油蜜',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95288,'zhTW','走私者天國','為火線港的佛利茲‧焦炫收集8個走私貨物。','你看起來很習慣照別人說的做事。我喜歡這種跟班。只要稍微經過訓練，你就能派上很大的用場。來測試看看你的實力吧。$B$B近來有些東海海盜從我這裡拿了偷來的貨溜了。這實在沒什麼運動家精神。明明是我先偷的！$B$B第一堂課，跟班。絕對別背叛擅長背叛的人。讓他們知道，他們惹錯哥布林了，還要把我的貨拿回來。最好是靠蠻力。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95329,'zhTW','實地報告','前往泰洛堡，從看守者柯涅利斯那裡取得形勢報告。','北邊有座可以觀測平原的監視塔。那是個觀測地點，用來追蹤任何部落勢力的行動。$B$B駐守的監視者叫做柯涅利斯。和他談談，取得形勢報告。那裡只有他一個人駐守，所以我會定期派人去查看他的狀況。我得警告你，他…不太愛說話。所以他才被派到那麼偏遠的地方駐守。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95349,'zhTW','陶土議會','從微風島搭乘割天者號到莫高雷，然後在抵達時和阿菈娜‧雷暴行者交談。','最近的邪教事件讓我暫緩前往艾澤拉斯的計畫，我必須留在瓦拉納爾這裡一段時間。所以就由你和其他幾個塑風者去打頭陣吧。我們的塑風者抵達莫高雷後，阿菈娜‧雷暴行者會在場接待。在我們結束這裡的工作前，我會鼓勵你去探索艾澤拉斯。我們很快就會與你會合。$B$B準備好以後，就到小屋外的碼頭搭乘割天者號吧。$B$BBanu-Alah（祝你一路順風），$N。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95350,'zhTW','歡迎來到艾澤拉斯','前往奧格瑪，到智慧谷和索爾交談。','這下面的世界還真大，而新盟友會是我們生存的關鍵。$B$B陶土議會和一群有相同理念的族群組成了「部落」。附近的雷霆崖是部落的領地，往東邊就是主城奧格瑪的所在地。$B$B到雷霆崖中心找飛行管理員吧。他們會送你到奧格瑪，而你得代替塑風者找一個名叫索爾的部落酋長。願風能指引你未來的道路，$N。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95428,'zhTW','鈍拳的命令','向羅格瑪的克隆羅許回報。','小$R砸扁了暮光。也許你的部落比鈍拳想的強。$B$B你可以留在博德羅克。現在可以。$B$B和其他小傢伙說，我們很快再開始戰鬥。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95494,'zhTW','受創的自尊與獅子皮','在貧瘠之地從草原獅后和草原獅王身上收集6張草原獅毛皮。','我需要個身手好又有時間的人來幫我收集獅子皮。尋求陌生人的幫助讓我的自尊心受創，但我的腿最近受傷了。在我痊癒之前，我都沒辦法去狩獵，但答應的事我一定會完成。$B$B這個區域裡的大獅子有最好的皮革，就先解決牠們吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95507,'zhTW','弗朗恩的獵物','在貧瘠之地發動過的陷阱中收集8個受困的獵物。','你到外頭的時候如果能幫我檢查陷阱，那就幫了我一個大忙了。我在谷地各處都有設置陷阱。$B$B如果有抓到任何小型動物，都帶回來給我。但要多加留意其他野生動物。如果一個不小心，都有可能在這危險的區域喪命。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95508,'zhTW','不速之客','協助瓦爾頓挺過泰瑞‧朗德瑞克和庫爾提拉斯海軍的突襲。','沒錯，我曾是庫爾提拉斯海軍的一員。在上將大人奪下塞拉摩然後開始遠征杜洛塔時，我對他的方略有些…「意見」。特別是那些處決平民的事。$B$B其實說來話長，但是…等等…那是什麼？$B$B有一群人從山脊那邊過來了！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95561,'zhTW','我的寶貝','幫遠境堡要塞的泰莎‧曦明收集6顆新鮮的蘋果。','<曦明寶寶的哭聲響遍了遠境堡要塞。泰莎用疲倦的笑容看向你。>$B$B噢，你好啊，冒險者。抱歉這麼吵。小艾瑪今天脾氣不太好，但我不知道是為什麼。或許吃點東西會有點幫助。$B$B你能幫我找來一點東西讓她吃嗎？我丈夫出門去補充日用品，我有點忙不過來，沒辦法自己去。如果你能在附近找點蘋果來，我就能做些蘋果泥給她吃。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95603,'zhTW','鐘樓中的蝙蝠','幫蘿蘭修女在遠境堡殺死5隻棲息的夜行蝙蝠。','自從洛雷修士和我開始在遠境堡奉獻，已經過了很長的時間，這裡的教會也腐朽衰敗，變得無法使用。我相信一旦戰鬥結束，我們就能讓聖光重回這此地。不過，我擔心這可能會花上很長的時間…$B$B儘管如此，為了迎接那天的到來，我們還是得確保教會正常運作。$B$B關於這點，近來有一群蝙蝠棲息在教會上方的樓層。如果你能把牠們趕走，那就再好不過了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95621,'zhTW','山谷裡的麻煩','到貨車殘骸那邊，查出庫爾提拉斯人的來意。','今天早上，我看到下方山谷裡有一群人類似乎在尋找什麼。我用步槍視鏡仔細看了一下，結果是一群穿著庫爾提拉斯制服的士兵。$B$B如果你願意的話，前往南方貨車殘骸到這些士兵的營地附近。殺掉他們，然後查出他們為什麼要來這裡。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95646,'zhTW','高地之懼','在挖掘場殺死高地之懼，並將牠的根系核心帶去給濕地的『綠意守望者』雷希耶爾。','在這片微鹹的濕地中，蘊藏著更深、未經鹽化的南部水源。這令我感到痛苦，但我能從我的根系中感知到，一股腐化力量正穿過那道山溝滲透進來。$B$B就像低地上的那些生物一樣，牠們對這種污染的反應更為劇烈。由於自誕生之初就缺乏海洋鹽分的磨練，牠們幾乎沒有力量對抗這樣的邪惡。$B$B去那片高地，把高地之懼的根系核心帶來給我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95647,'zhTW','迷失在灌木叢中','在挖掘場尋找亞丁‧格拉斯曼','我的丈夫亞丁擁有感知自然的罕見天賦。他會攀登任何高峰，為我採集鍊金術所需的草藥和花朵，讓我們貨架和儲藏室的存貨從不匱乏。$B$B但我擔心他遇到了麻煩。前陣子有一支挖掘隊路過這裡尋求補給，他們在閒聊中提到了一種他們從未見過的高聳巨草。那就是他跟我說他一定要去親眼瞧瞧的東西。但他已經去太久了！$B$B如果你能找到關於他的任何消息，我會十分感激。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95697,'zhTW','換換口味','進入濕地的挖掘場並帶回灌木迅猛龍肉','札姆沙告訴我，我們需要更多家鄉風味的料理。$B她認為如果我們開始賣迅猛龍肉，就能吸引那些平時不常光顧博斯坦的火坑的顧客。$B$B她的點子還不賴。但我想要能超越我們出生村莊氣味的東西。我們可是在奧格瑪！博斯坦應該要端出一頓熟悉的美味，將它們升級成豪華的盛宴。$B$B最近有一位獵人從濕地回來，還帶回了一隻來自挖掘場的灌木迅猛龍的巨爪。$B$B有興趣接個工作嗎？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95737,'zhTW','尋找凱特林','與米奈希爾港的凱特林‧格拉斯曼交談。','我有的時候會和同行交流，像是研究稀有植物與當地奇特事物的草藥師或古怪學者。我們互相交換發現，有時也會對前方的危險發出警告。$B$B濕地的一位鍊金師曾寫信提及，她丈夫所屬的挖掘隊發現了消失已久的遠古草類蹤跡…但她後來再也沒有送來關於這種草的數量或採集難易度的消息。$B$B如果可以的話，去米奈希爾港打聽一下凱特林‧格拉斯曼的消息。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95772,'zhTW','尋找桑布雷德','在維爾加挖掘場尋找多林‧桑布雷德的兄弟戴文','我兄弟之前想把我拉去濕地，跟著一群從洛克莫丹來的挖掘隊同行。他說他們要進去那些從來沒有矮人踏足過的山丘裡，進行某種挖掘工作。$B$B唉，要不是我手頭上這堆要重新修改的束腰進度已經落後了，我早就去了。$B$B不過，戴文通常在出發後都會寫信回來。這次卻什麼都沒有，這讓我心裡有種不詳的預感。$B$B如果你正要朝那個方向前進，能幫我去看一下我兄弟嗎？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95792,'zhTW','掃蕩乾淨','幫嘉琳妲‧銅光擊殺8個燼鱗幼龍和4個燼鱗戰士。','如果想賺進大筆寶藏，不入虎穴焉得虎子！我背後這座洞穴裡有著未開採的大量礦藏。如果能弄一隊礦工來開挖，就能賺進大把銀子。$B$B只不過…這裡有一點點…龍族問題。算不上什麼大事啦。$B$B如果你能進去，幫我省下清走那些龍族的麻煩，我會好好獎勵你的。更別說，你還能和將來的礦業大亨打好關係呢！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95795,'zhTW','死於沼地','回去找多林‧桑布雷德','<你用這名矮人的披風蓋住了他的屍體。>$B$B前往湖畔鎮，親自將他兄弟在挖掘場內的遭遇告訴多林‧桑布雷德。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95803,'zhTW','善意的信物','把魯道夫‧格爾哈特的首級交給幽暗城的希瓦娜斯‧風行者。','現在我們已經砍下晦暗指揮官的頭顱了，我想請你拿到幽暗城去。希瓦娜斯‧風行者一點也不相信我們，還公然蔑視我們。$B$B把魯道夫‧格爾哈特的首級交給黑暗女王。讓她知道我們有能力照顧自己人，也願意為了被遺忘者的福祉奉獻一切。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95805,'zhTW','安希與姆莎的恩賜','在悶燃薰香燒成灰之前，在十分鐘內帶著它到東南方山丘的安希和姆莎聖壇。','太陽與月亮、安希與姆莎雖然不像元素一樣同屬這個世界，但他們的光芒帶來了生命、指引與希望。$B$B我們崇拜這個世界的魂靈，也一樣會崇拜他們的。$B$B如果你也想表達崇敬之意，就帶著悶燃薰香到東南邊山丘上的聖壇吧，那裡可以眺望台地，就在野豬人營地的南邊。動作要快，這樣才能在薰香燒完之前抵達聖壇。$B$B別把它弄濕了！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95809,'zhTW','編織之心','回去米奈希爾港找凱特林‧格拉斯曼','我需要休息一下，然後再自己找路出去。$B$B<他從背包裡拿出一些蘆葦，迅速地將它們編織並折成一顆愛心。>$B$B拿著這個，帶回去給凱特林。讓她知道我很快就會回家了！多虧有你清出了一條路，我會收拾好我的幾捆草藥，沿著你的路線走。$B$B謝謝你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95883,'zhTW','被折磨的靈魂','在銀松森林，從博倫的巢穴附近的不死族身上收集一個被折磨的靈魂。','<匆忙準備的儀式用品雜亂地堆放在祭壇上。根據紙條上寫的，所有物品都已經準備就緒，現在只差鮮血和受苦靈魂的獻祭了。$B$B四周的不死族看起來受盡了折磨。它們身上或許有你要找的東西。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95885,'zhTW','血紅獻祭','在博倫的巢穴使用被折磨的靈魂，對祭品之石進行血祭。','<現在剩下鮮血獻祭了。$B$B紙條上提到必須有人「自願獻祭」。$B$B你心中突然有強烈的恐懼感。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95912,'zhTW','懸賞：大劍師凱喬','把大劍師的旌旗帶給遠境堡要塞的安珀‧刃語。','我們每砍倒一個獸人，就有另一個前來取代，不知為何總是比上一個還要更強。一定是有熟練的戰士負責訓練新世代。如果我們想減少敵軍的數量，必須先確保他們沒辦法填補喪失的兵力。$B$B若有勇士願意接下這個任務，得先找到這個大劍師，解決掉他。他很可能現在就在部落哨站北邊的訓練兵營地。殺了他，取得他的旌旗，重挫獸人的士氣。$B$B-- 安珀‧刃語',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95913,'zhTW','給小公主的毛毯','幫遠境堡要塞的泰莎‧曦明收集3個山狗皮。','<泰莎輕輕搖著寶寶，希望能哄她入睡。>$B$B如果她不餓，說不定她只是累了。老實說，艾瑪是個令人開心的驚喜，但這也代表我們有點準備不足。我丈夫做了這個可愛的搖籃，不過我擔心這些毯子有點太舊了。畢竟，她值得最好的。$B$B如果你還願意幫忙，麻煩你找來一些毛皮來鋪好她的床，我會非常感激的。如果這能讓她別繼續哭，我想遠境堡的所有人都會非常感激。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95934,'zhTW','有利可圖的證據','幫嘉琳妲‧銅光找到一塊龍族立方體。','我的調查工具顯示這洞穴裡有著從未見過的礦物。我稱它為龍族立方體。這可能值一大筆錢。$B$B雖然這很令人興奮，但如果我不能證明它存在，沒人會幫我進行採掘。當然啦，我手上有工具的讀數，但人們喜歡實際碰觸閃亮的大水晶，而不是盯著圖表數字。$B$B我很確定有幾個從土裡冒出來的水晶。如果你能閃過幾隻龍族，弄來水晶，那就是幫了我一個大忙。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95943,'zhTW','工頭之難','找到工頭的木箱，然後還給遠境堡的博崔德‧鐵眉。','日安，$G小子:小妞;。我叫博崔德，博崔德‧鐵眉！隨時為你服務。$B$B<博崔德伸出一隻髒兮兮的手。>$B$B這些好傢伙委託我來監督這地方的建築工事。他們缺乏經驗，但精神可嘉！問題是，我弄丟了我的工具。$B$B我們在這裡西北邊的小片林地遇到幾個暮光成員。在保住性命和保住工具之間，我只能選擇一個。一方面，我還活著。另一方面…結局可想而知。$B$B你能幫我找回我的工具嗎？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95957,'zhTW','乾啦！','把吉普琳克的泡沫酒杯遞給火線港的葛雷‧曦明。','拿去吧，老兄。這杯是給那邊的暴躁哥的。如果這都不能讓他清醒過來，那就沒別的辦法了。$B$B喔，還有呃…碰過之後記得洗手。千萬別讓它跑進眼睛。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95961,'zhTW','離家出走','在火線港找到葛雷‧曦明。','<泰莎的寶寶繼續放聲大哭。>$B$B我猜她還不累。噢…大家都讓一切看起來好簡單。孩子的爸總是知道怎麼逗樂她。如果他能早點回來就好了。$B$B$N，我很不想麻煩你，但你可以幫忙看看是什麼害他耽擱這麼久嗎？他出去已經有一段時間，現在應該要回來了。艾瑪一看到他就會心花怒放。$B$B你應該能在火線港找到他…他最近似乎常去那裡。你看到葛雷就會知道是他了。他就像太陽一樣閃亮。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95984,'zhTW','陸行鳥之歌','把完整的陸行鳥喙交給泰洛堡的看守者柯涅利斯。','這些印記是獅子留下來的。第一眼看，這隻獅子也特別巨大。應該是附近獅群的領袖。$B$B如果在我的看守下，吃人獅子的傳聞還散播出去，戴瑪會暴跳如雷的。幸好，我有個計畫。$B$B我可以製作一個模仿負傷陸行鳥叫聲的笛子。我們可以用它把那頭野獸引出來。但我需要一個鳥喙才能做仿聲笛。平原各處都有陸行鳥。幫我弄來鳥喙，越漂亮越好！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95988,'zhTW','溫順爽口','幫火線港的旅店老闆吉普琳克收集3個爬行者唾液、新鮮的肉餌、哥布林去漬劑和過期毒藥。','你和葛雷說過話了是吧？那傢伙挺有趣的。最好別讓他再喝一滴酒了。這是間旅店，不是酒吧。我沒把他攆出去算他走運了。$B$B你想帶他走，請自便。但我不覺得他那個樣子能去得了哪裡。至少得用上一點哥布林提神劑。$B$B你何不幫我弄來一些這清單上的材料，我就幫你的朋友準備好他的「飲料」。看看他喝過我的特調之後還想不想喝酒。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95991,'zhTW','懸賞：魂喉','把魂喉的獠牙帶給遠境堡要塞的惠特利。','在這些林地運送馬匹已經夠危險了，我不需要什麼神秘的鬼魅鱷魚來偷咬我的寶貝小馬！傳聞說這傢伙比通常的鱷魚至少大上三倍。凶狠兩倍！$B$B我不喜歡賭運氣。等到有人解決那隻討人厭的怪物之前，我絕不會用我的馬兒冒險。如果有人在河邊發現那隻怪物，就把他的牙帶來給我，讓我知道能安全啟程了。在那之前，我就在這按兵不動！$B$B--惠特利',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (95999,'zhTW','懸賞：焚化者加林姆','將焚化者加林姆的破損法杖交給湖畔鎮的所羅門鎮長。','懸賞！焚化者加林姆，撕裂者山谷獸人入侵者的首領。據稱正與石望要塞的黑石氏族合作。$B$B當心焚化者加林姆。他和他的暗影施法者極度危險。勇者只要能提交證據，向所羅門鎮長證明焚化者加林姆已死，均可獲得豐厚的獎勵。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96009,'zhTW','高風險建築','為遠境堡的博崔德‧鐵眉從透納的伐木場收集10捆木材。','人類無窮的動力總是讓我感到驚奇。他們看到荒蕪的戰區，充滿獸人和邪教徒，就覺得那是開店的好地方！太神奇了。$B$B但是，我有什麼資格命令他們在哪蓋什麼呢。只要教教他們怎麼蓋就行。如果我們要把這地方蓋得像他們說的一樣大，就會需要很多的木材。$B$B近來路上變得非常危險，西北邊磨坊的木材運送幾乎完全停擺。你能幫我們弄幾捆木材來嗎？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96031,'zhTW','紮營入門指南：製皮','當你的專業技能達到一定熟練度後，到鐵爐堡與格雷塔‧頂軸交談，學習製作符合專業技能的紮營物品。','你成為製皮師了。恭喜你，$C。我認識一個人，可以教你如何製作帳篷，在大熱天為你遮陽，在雨天供你避雨。$B$B有了一頂耐用的帳篷，相信你一定能好好養精蓄銳，在旅途中保持最佳狀態。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96044,'zhTW','紮營入門指南：鍛造','當你的專業技能達到一定熟練度後，到卡拉諾斯與托格努斯‧燧火交談，學習製作符合專業技能的紮營物品。','所以說，你成為鐵匠了。如果你想確保刀刃永不變鈍，那的確是很好的選擇。$B$B我認識一個人可能幫得上忙，他可以教你如何製作砂輪。只要營地有了砂輪，附近的所有戰士和盜賊都會排隊等著磨利他們的武器。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96045,'zhTW','紮營入門指南：鍊金術','當你的專業技能達到一定熟練度後，到鐵爐堡與沃薩‧布拉克塞爾交談，學習製作符合專業技能的紮營物品。','既然你已經開始學習鍊金術，等你學有所成，我也能教你如何在營地中製作法力井。建成之後，所有治療者和施法者都會蜂擁而至，只為喝上一口恢復精神的泉水。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96046,'zhTW','紮營入門指南：採礦','當你的專業技能達到一定熟練度後，到卡拉諾斯與亞爾‧錘石交談，學習製作符合專業技能的紮營物品。','採礦或許不夠光鮮亮麗，卻能一分耕耘，一分收穫，是很值得你深入鑽研的專業技能。$B$B我認識一個人，可以教你如何在營地中製作磁石。建成之後，所有想要舞刀弄劍的人都會紛紛聚集在你的火堆旁，感受它提供的額外「加持」，以便提高他們的戰力。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96047,'zhTW','紮營入門指南：急救','當你的專業技能達到一定熟練度後，到卡拉諾斯與薩姆諾‧普爾交談，學習製作符合專業技能的紮營物品。','所以說，你選擇學習急救嗎？對於一個$C，那是很崇高…很務實的選擇。$B$B我認識一個人，可以教你如何在營地中製作急救箱。在冒險過程中，受傷是家常便飯，如果在營地提供不可或缺的治療功能，有時甚至能救人一命。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96050,'zhTW','紮營入門指南：釣魚','當你的專業技能達到一定熟練度後，到丹莫洛的湧冰湖附近與帕克斯頓‧岡特爾交談，學習製作符合專業技能的紮營物品。','你可能不這麼認為，但你的釣魚技能其實在營地中非常有用。$B$B我認識一個人，可以教你如何在營地中製作魚缸。透過這個設施，你可以為自己和同行的冒險者提供一點樂趣。冒險者越快樂，就越強大，相信這點會反映在你的戰鬥能力上。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96055,'zhTW','紮營入門指南：草藥學','當你的專業技能達到一定熟練度後，到鐵爐堡與雷納‧石枝交談，學習製作符合專業技能的紮營物品。','在我看來，你好像學到一些草藥學的技巧。你知道的，採花採草不一定是浪費時間。它可能很有用…甚至有利可圖。$B$B我認識一個人，可以教你如何在營地中製作薰香蠟燭。對於治療者和施法者而言，高精神力對於維持戰力十分重要，薰香蠟燭提供的加成一定會讓魔法使用者感激不盡。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96056,'zhTW','紮營入門指南：剝皮','當你的專業技能達到一定熟練度後，到鐵爐堡與巴爾薩斯‧剝石交談，學習製作符合專業技能的紮營物品。','能夠技術純熟地從死去的野獸身上採集皮革和毛皮，絕對是冒險者最有價值的技巧。$B$B我認識一個人，可以教你如何在營地中製作營地椅子。偶爾坐下休息也很重要，你可以利用你採集的那些毛皮製作出一張舒適的椅子。適當的休息有助於確保你維持巔峰狀態，這樣下次遇到麻煩，就能精準命中要害。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96057,'zhTW','紮營入門指南：裁縫','當你的專業技能達到一定熟練度後，到鐵爐堡與阿斯拉‧瑞克斯交談，學習製作符合專業技能的紮營物品。','裁縫是投資報酬率極高的交易技能，相信它一定能幫上你的忙。$B$B我認識一個人，可以教你如何在營地中製作陣營旌旗，前提是你有對應的能力。在任何戰場上，激勵和士氣都是成功的關鍵，振奮人心的旌旗可以讓你保持精力充沛。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96058,'zhTW','紮營入門指南：工程學','當你的專業技能達到一定熟練度後，到卡拉諾斯與布隆克‧狂齒交談，學習製作符合專業技能的紮營物品。','像你這樣的工程師可以製造各式各樣的裝置、機器人和炸彈，藉此獲得樂趣和利益。$B$B我認識一個人，可以教你如何在營地中製作材料機器人。這個實用的機器人可以讓你隨時補充物資，確保自己和盟友永遠不缺施法所需的材料。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96059,'zhTW','紮營入門指南：附魔','當你的專業技能達到一定熟練度後，到鐵爐堡與索恩斯‧火石交談，學習製作符合專業技能的紮營物品。','既然你已經展開成為附魔師的旅程，等你摸清門路後，我應該可以教你如何在營地中製作附魔魯特琴。$B$B在休息的時候來點娛樂也是很重要的事，這個小魔法能幫助你做好準備，等你再度踏上旅程時，就能從容面對各式各樣的挑戰。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96063,'zhTW','氣態黃金','為史利博‧嘶芽收集5個沼澤氣體瓶。','燃料的未來不是煤炭，也不是燃油，是燃氣才對！那些西南方的沼澤都會噴出一堆氣體，而我正好有個新發明能夠派上用場。這個新型的引擎剛好就得靠這些燃氣。不過這種燃氣非常難收集。$B$B如果你想為科技和工業的未來提供一點小小的貢獻，可以幫我收集一些燃氣嗎？你可以到水邊附近的排氣孔收集。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96081,'zhTW','創傷服裝','為遠境堡要塞的洛雷修士收集20個魔紋布。','如果要說軍隊有什麼必需的物品，那就是繃帶了。不幸的是，遠境堡沒辦法有效生產布料。因此我們很仰賴哥布林的進口，如果夠幸運的話也能從獸人那邊拿回一些。$B$B現在我們布料就快用完了。要不了多久，我就得用舊衣服做繃帶了。如果你願意幫我們的話，一定能拯救更多人的性命。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96102,'zhTW','紮營入門指南：裁縫','當你的專業技能達到一定熟練度後，到奧格瑪與斯諾恩交談，學習製作符合專業技能的紮營物品。','裁縫是投資報酬率極高的交易技能，相信它一定能幫上你的忙。$B$B我認識一個人，可以教你如何在營地中製作陣營旌旗，前提是你有對應的能力。在任何戰場上，激勵和士氣都是成功的關鍵，振奮人心的旌旗可以讓你保持精力充沛。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96107,'zhTW','箭矢之羽','把6根平原禿鷲的羽毛交給羅格瑪的妮莎‧血鼻。','獵人的一生摸過的箭矢比天上的星星還要多許多。$B$B我的箭矢都是自己親手做的。我不相信其他人。$B$B附近禿鷲的粗羽最適合用來做成箭矢了。你可以幫我收集一些嗎？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96125,'zhTW','需要解脫','在博德羅克的巨魔營地尋找敦斯頓‧威利斯。','現在已經收集到獅子皮，獸人盜獵者也全被殲滅，我終於能好好休息了。$B$B但在接替我工作的人回來之前，我沒辦法安歇。$B$B『傑出的探險家』敦斯頓‧威利斯幾天前去調查位在北方的巨魔營地。他說回來之後就要接下我的工作。$B$B去找他吧。如果他還活著，就帶他回來。如果他不幸被切成肉塊吊起來，還請你把證據帶回來，這樣戴瑪才能派其他人接替我的位置。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96130,'zhTW','查庫亞','擊敗查庫亞並帶回牠的毛皮。','附近山丘上的草原狼之中，有隻特別具攻擊性的狼。我們叫牠查庫亞。近來牠已經變成對外來旅客的威脅了。$B$B牠通常會在石牛湖西邊的樹林的樹架之間遊走。$B$B終結這個威脅，把牠的毛皮帶來給我，我就向酋長說點你的好話。務必小心，牠真的非常危險！你可能會遇到其他打算獵殺牠的獵人，或許你們可以合作。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96137,'zhTW','伊菈的匕首','擊敗10隻小黑色破壞者和7隻黑色破壞者，然後回去夜色鎮找希拉‧沃寧迪，取得更多資訊。','一把屬於伊菈的小匕首，她自稱為遊俠，防止森林中的野獸攻擊旅人，維護森林的安全。$B$B如今伊菈的靈魂仍在樹林中徘徊，她未竟的心願或許是除掉不斷在森林中奪人性命的座狼。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96139,'zhTW','維洛家族','在烏鴉嶺搜尋有趣的物品，然後回去夜色鎮找希拉‧沃寧迪。','在這樣的黑暗時刻，我們不只要牢記敵人，也應該牢記我們的英雄。如果沒有那些英勇奮戰的人，像是奧爾希雅小姐，以及在烏鴉嶺犧牲生命的人，夜色鎮早已不復存在。$B$B關於烏鴉嶺的文獻多嗎？不，當然不多。它的歷史已經跟著那裡的居民一起被抹除。即使我的圖書館藏書豐富，關於它的資訊卻少之又少。$B$B如果你碰巧有所收獲，我會很感激你把它帶來這裡。那些人不該遭到遺忘。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96204,'zhTW','塑風者之怒','和露蜜娜‧風詠同行，幫她逃離芬里斯城堡。','既然我現在自由了，我打算讓這些邪惡生物後悔對塑風者不利。$B$B我們快走吧，$C。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96222,'zhTW','赫蘭薩可汗','將瑪洛迪鑰匙碎片交給淒涼之地的烏瑪拉克。','儘管戰火蔓延整個地區，長矛谷的瑪洛迪半人馬的地位卻仍然不可動搖。如果其他部族繼續對他們的存在視而不見，隨著時間推移，我擔心他們會變得冷酷無情，並掀起更多紛爭。$B$B赫蘭薩可汗身上有塊瑪洛迪鑰匙碎片，我希望能把它當成談判的籌碼。從那裡的半人馬身上找到戰爭號角哨嘴，然後在最高的山峰上使用哨嘴，向他發出挑戰。$B$B把鑰匙帶來給我，我會向你說出我的提議。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96241,'zhTW','夥計，說到毒液','在鬱湧使用毒素提取器從啃過的屍體身上收集5份鬱湧毒素樣本。','鬱湧那邊發生了一些古怪的事。老瑪庫可聽說那裡到處都是一些從沒見過的噁心野獸在爬來爬去。$B$B有人說那些詭異的爬行生物帶有一種具有獨特屬性的毒液，這讓我蠻好奇的。拿著我的提取器，對那裡的屍體使用來收集毒液。幫我搞定這件事，我就欠你一個人情，夥計。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96259,'zhTW','保護死者','殺死10個鬱湧幼蛛和5個鬱湧士兵。','在一個叫鬱湧的地方，有一座安葬牛頭人的古老墓地，就在這營地的西北邊。近來那地方被一種特別凶狠的蜘蛛佔據了。這些蜘蛛不只對莫高雷的人民造成了威脅，還玷污了牛頭人的聖地。$B$B如果你願意到鬱湧一趟，終結蜘蛛滋生的問題，那就再好不過了。若你能幫這個忙，先祖一定會對你微笑的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96260,'zhTW','堅韌如鋼','從鬱湧紡織者身上收集3個結晶蛛絲。','你有聽說鬱湧的墓地發生什麼事了嗎？巨型蜘蛛在那裡迅速蔓延，據說牠們的毒液甚至強到能喚醒死者。要我說的話，這可真是個大麻煩。$B$B一名被派去調查的斥候奄奄一息地回來，全身還纏滿了極為堅韌的結晶蛛絲。我已經盡可能採集了一些，但如果能取得更多樣本進一步研究，那就再好不過了。$B$B把更多結晶蛛絲帶來給我，我就會好好獎賞你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96264,'zhTW','元素援助','在剃刀沼澤擊敗卡爾加‧刺肋，並收集關於野豬人計畫的情報。','所以你現在算是大牌薩滿了，是吧？你精通了元素，想要善用這力量？我想我正好有你在找的東西。$B$B如果你想贏得元素的敬意，你得償還欠他們的人情才行。他們幫你，你也幫他們。現在他們正需要幫手，來對付濫用元素之力的人。$B$B大地正在顫動，$N。它說野豬人正聚集在一塊，進行某種可怕力量的儀式。我們必須調查他們的沼澤，看看他們在做什麼。把你的發現帶回來給我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96390,'zhTW','防患於未然','在丹莫洛殺死10個黑鐵間諜。','黑鐵矮人的間諜已經滲透進了丹莫洛。雖然我還不太確定他們的目的是什麼，但我們必須在這個麻煩壯大之前，將它扼殺在搖籃裡。$B$B向東前往鐵環營地，把你在那裡發現的黑鐵間諜殺掉。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96392,'zhTW','法森的遠視能力','與大地先知法森交談，借用他的視界術，觀察黑鐵矮人的威脅。','你好啊，朋友。我是大地先知法森，我是從鷹巢山來到丹莫洛拜訪的。在旅途中，我實在無法不去注意到，我們這裡似乎碰上了一點…黑鐵矮人帶來的小麻煩。$B$B如果你有時間，我可以讓你看看我指的是什麼。我懂一點魔法，應該能派上用場。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96393,'zhTW','舊鐵爐堡入侵','進入舊鐵爐堡下的族長之廳，並砍下杜爾根‧戴格哈默的頭。','召集一些盟友，深入舊鐵爐堡下方的洞穴。進入那裡的族長之廳，並一路推進到底層寶庫。$B$B我的黑鐵語有點生疏了，但我隱約能辨認出一個名字：杜爾根‧戴格哈默。他很可能就是指揮官。砍下他的腦袋，把它帶去給麥格尼‧銅鬚國王。$B$B哦對了，你過去的時候，告訴他他的老朋友法森向他問好！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96394,'zhTW','死不瞑目','殺死15個狂怒的亡魂和10個痛苦的靈魂，讓安威瑪的靈魂能夠安息。','有什麼東西驚動了族長之廳底下的陵墓，而且從寶庫深處還傳來了奇怪的聲音。死者的靈魂一向很淺眠，不管底下發生了什麼事，似乎都驚擾到它們了。$B$B去下面看看你能幫我們做點什麼。如果有任何死者醒了過來，那就讓它們重新安息吧！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96395,'zhTW','遠古的怨恨','讓法爾椎‧安威瑪的靈魂安息，然後回去找族長之廳的鬼魅侍者。','族長…我強大的…族長…他…需要…安息。$B$B請…幫幫他…幫他…安息…$B$B被…古老的…怨恨…吞噬…無法…安息…',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96403,'zhTW','重要的傳家寶','在族長之廳收集8個矮人傳家寶。','嘿，冒險者…我需要你的協助。$B$B我原本想潛入…「看看」寶庫，結果黑鐵矮人卻搭著鑽地機從地下冒出來！我不知道他們來做什麼，但這裡有著無價之寶…呃…我是說「重要的文化遺產」！拜託你，如果有看到任何東西，就把它們帶來這裡。$B$B我向你保證，你找到的東西都會進行登錄，然後讓它們重返往日榮光。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96408,'zhTW','來丹莫洛的訪客','調查瞭望古博拉採掘場的營地。','昨天晚上，我們有個巡山人發現東邊的山丘上有營火。那裡地勢很高，能瞭望整座古博拉採掘場。$B$B這或許不是什麼大事，但我還是想請你去那座營地看看。如果他們沒有惡意，就不用理會他們。如果來者不善…相信你知道該怎麼做。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96605,'zhTW','戶外真好','坐在卡加的基礎營火旁，然後等待獲得「加強休息」加成效果。','你好，$C。你看起來像個厲害的冒險者。太好了。這個世界需要更多像我們不眠不休地追尋寶藏和榮譽的人。$B$B若要成為一名成功的冒險者，你就必須學會在野外生存的技能。不確定你知道多少，但如果你願意的話，我可以教你一兩招。$B$B坐在火堆旁好好休息一下吧。我會好好告訴你的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96606,'zhTW','戶外真好','坐在萊莉娜的基礎營火旁，然後等待獲得「加強休息」加成效果。','你好，$C。你看起來像個厲害的冒險者。太好了。這個世界需要更多像我們不眠不休地追尋寶藏和榮譽的人。$B$B若要成為一名成功的冒險者，你就必須學會在野外生存的技能。不確定你知道多少，但如果你願意的話，我可以教你一兩招。$B$B坐在火堆旁好好休息一下吧。我會好好告訴你的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
