INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96608,'zhTW','戶外真好','坐在艾里克的基礎營火旁，然後等待獲得「加強休息」加成效果。','你好，$C。你看起來像個厲害的冒險者。太好了。這個世界需要更多像我們不眠不休地追尋寶藏和榮譽的人。$B$B若要成為一名成功的冒險者，你就必須學會在野外生存的技能。不確定你知道多少，但如果你願意的話，我可以教你一兩招。$B$B坐在火堆旁好好休息一下吧。我會好好告訴你的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96626,'zhTW','紮營入門指南：烹飪','在閃金鎮和湯瑪斯交談，學習如何成為廚師。','你想學習更多紮營的技巧嗎？很好，$C。任何冒險者要學的第一步就是如何成為廚師和學習如何搭起營火。$B$B烹飪不只是為了煮出美味的餐點，也是為了紮穩營地的根基。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96628,'zhTW','冒險者','把補給包裹送去給卡拉諾斯附近的艾里克‧光錘。','等等，$N。在你進入隧道之前，我有另一件事要拜託你。$B$B我的巡山人回報說卡拉諾斯外出現了一個冒險者。你可以把這些補給品拿去給他嗎？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96629,'zhTW','紮營入門指南：烹飪','在卡拉諾斯和格雷姆羅克‧匹斯諾爾交談，學習如何成為廚師。','你想學習更多紮營的技巧嗎？很好，$C。任何冒險者要學的第一步就是如何成為廚師和學習如何搭起營火。$B$B烹飪不只是為了煮出美味的餐點，也是為了紮穩營地的根基。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96630,'zhTW','冒險者','把日誌交給位在多蘭納爾附近的萊莉娜‧暮刃。','<日記上以直白的方式詳細紀載著一個名不見經傳的人所過的生活，以及經歷過的種種冒險。$B$B其中也有多篇內容提到紮營的事情。看起來…還蠻有趣的。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96634,'zhTW','紮營入門指南：烹飪','在多蘭納爾和札瑞恩交談，學習如何成為廚師。','你想學習更多紮營的技巧嗎？很好，$C。任何冒險者要學的第一步就是如何成為廚師和學習如何搭起營火。$B$B烹飪不只是為了煮出美味的餐點，也是為了紮穩營地的根基。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96652,'zhTW','冒險者','把日記帶給剃刀嶺附近的布拉克。','<日記上以直白的方式詳細紀載著一個名不見經傳的人所過的生活，以及經歷過的種種冒險。$B$B其中也有多篇內容提到紮營的事情。看起來…還蠻有趣的。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96655,'zhTW','紮營入門指南：烹飪','在剃刀嶺和廚師托爾卡交談，學習如何成為廚師。','你想學習更多紮營的技巧嗎？很好，$C。任何冒險者要學的第一步就是如何成為廚師和學習如何搭起營火。$B$B烹飪不只是為了煮出美味的餐點，也是為了紮穩營地的根基。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96656,'zhTW','冒險者','和布瑞爾附近的伊琳諾兒‧沙克爾頓交談。','$N，你在對抗血色十字軍的過程中，證明了你是值得信賴的人物。所以我現在要指派一個特殊任務給你。$B$B我聽說往布瑞爾的路上來了一個新的冒險者。去看看她在做些什麼。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96659,'zhTW','冒險者','把補給包裹送去給血蹄村附近的卡加‧荒蹄。','等等，$N。你走之前，我有另一件事要拜託你。$B$B有個名叫卡加‧荒蹄的冒險者在血蹄村外搭建了營地。過去她曾幫了我大忙，現在我終於有機會能報答她了。你能幫我把這些補給品拿給她嗎？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96661,'zhTW','紮營入門指南：烹飪','在血蹄村和派爾‧沉默行者交談，學習如何成為廚師。','你想學習更多紮營的技巧嗎？很好，$C。任何冒險者要學的第一步就是如何成為廚師和學習如何搭起營火。$B$B烹飪不只是為了煮出美味的餐點，也是為了紮穩營地的根基。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96779,'zhTW','重創辛迪加','在希爾斯布萊德丘陵的敦霍爾德城堡中找到並擊殺湯瑪斯領主。然後回去找麥洛克斯。','有時候，$R，在正確的位置割上一刀，就能致敵人於死地。套用到組織上也一樣行得通。$B$B我們的密探已經鎖定辛迪加的一個重要人物：一個名叫湯瑪斯領主的男人。$B$B在希爾斯布萊德丘陵的敦霍爾德城堡的運作中，他扮演著不可或缺的角色。如果你希望為拉文霍德效力，就前往敦霍爾德除掉他。下手記得快、狠、準。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96821,'zhTW','「拔」腿快跑','在杜洛塔南部殺死6個脊影爬蛛和6個脊影潛伏者，之後向剃刀嶺的加索克回報。','最近從剃刀嶺過來的旅人越來越少了。毒蠍一直都不是什麼好東西，但現在我聽說路上還有蜘蛛築巢。$B$B如果你湊巧要往北，在路上殺個幾隻蜘蛛吧。之後再讓剃刀嶺的人知道路上比較安全了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96822,'zhTW','為了榮耀','從提拉加德城堡外圍收集劫掠者戰鬥斧、劫掠者之弓以及劫掠者之盾，並還給剃刀嶺的圖羅克。','我們攻擊提拉加德城堡時，失去了許多勇敢的部落戰士。但現在人類往遺跡加派了援軍，我們沒辦法回收戰士們的遺骸，榮耀他們的犧牲。$B$B去城堡附近的遺跡一趟，尋找壯烈犧牲的同胞留下的武器。我們要把這些展示在榮耀殿堂。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96825,'zhTW','水果會咬人','剃刀嶺的廚師托爾卡要你到溪邊的剃鬃營地收集8個仙人掌果。','我們的獵人和漁夫常會帶不少好吃的回來給士兵們，但他們很少能吃到甜食。$B$B我曾經看過一種仙人掌，會結出多刺、美味的果實。但這種植物只生長在西邊的山丘上，也就是那些可惡的野豬人搭建營地的地方。想辦法穿過野豬人的地盤，帶一些果實回來給我。務必小心，那果實就和野豬人一樣刺人！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96873,'zhTW','頸上麻煩','森金村的帕祖菈要你收集3個夜光殘渣。夜光殘渣可透過分解回音群島食人妖掉落的妖術墜飾取得。','東邊的食人妖因為巫醫札拉贊恩而徹底喪失了意志。他會使用各種殘酷的魔法控制被囚禁者的心靈，他最擅長的把戲，就是讓受害者佩帶附有邪惡束縛咒語的墜飾。$B$B善用你的附魔技巧，從墜飾上除去這些魔法，再把成果帶來給我。還有，如果你重視自己的自由，千萬不要戴上這種墜飾！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96874,'zhTW','巨獸脊骨斧','奧格瑪的烏格索克要你從雷霆山的野獸身上收集5個風化脊骨，還有5個劣質砂輪。','你有看過雷霆山的巨型野獸嗎？我一直在想，牠們的脊骨應該可以做成不錯的斧頭。我說給薩魯聽的時候他竟然還笑我…他又懂什麼！？$B$B作為鍛造訓練的一部分，你能幫我這個忙！幫我弄來一些脊骨，還有用來打磨的砂輪吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96875,'zhTW','雷霆山的野獸','奧格瑪的卡瑪瑞要你從雷霆山的野獸身上收集5個粗糙蜥蜴皮，還有2個熟化輕毛皮。','奧格瑪不斷地在擴張，$C。而當工人需要毛皮來裝飾新建物的牆壁或屋頂時，他們就會來找我！$B$B雷霆山的蜥蜴皮通常太厚，不適合製成防具，但卻是很棒的建築材料。把牠們的皮帶來給我，還有一些比較輕的熟化毛皮。讓我看看你的製皮技巧吧！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96896,'zhTW','義不容辭','觀察丹妮莎‧莫爾和可敬的萊尼德‧巴薩羅梅之間的對話。','當納克薩瑪斯進攻時，我和丹妮莎一同對抗天譴軍團，守護幽暗城。那一天我們失去了許多摯友，其中也包括了這座要塞以其命名的英雄：加瑞克‧班達利昂。$B$B他很可能是第一位重新領悟如何以聖騎士的身分使用聖光的被遺忘者。看到他的遺志與潛能，在丹妮莎和她的夥伴身上得以傳承，我感到無比欣慰。$B$B要是其他被遺忘者也能有同樣的想法就好了…',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96984,'zhTW','干擾之心','幫塔倫米爾的魔導師沃迪恩‧虛無之光到達拉然城收集秘法微粒。','雖然你未必是真心為我們著想，但我也不介意有其他人來幫忙。如果達拉然毀了，一切將與之同焚，這也包括幽暗城。$B$B所以你的贊助人也想幫忙嗎？好吧。我會為你的鑰匙進行灌注，讓你能穿過城市的結界。進去之後，就到這一切的起點「紫羅蘭城塞」來和我會合。祈倫托發生的事已經讓他們焦頭爛額，沒有人會阻止你。$B$B盡你所能搜刮一切，但無論發生什麼事，我們的要務是防止這場劫難的發生。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96986,'zhTW','墓地騎士','為塔倫米爾的梅里薩拉到達拉然城擊敗『墓地騎士』亞崔希斯。','背叛我們的人就在北方的法師之城城底區。這個死靈法師的力量強到可怕。他竟然敢在祈倫托的眼皮底下召喚亡者大軍。$B$B我對法師之城的命運毫不在乎，$N，但這個墓地騎士踐踏著我們被遺忘者所代表的一切。把他解決掉。讓他知道沒有人能逃出黑暗女王的掌心。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96987,'zhTW','機會教育','為下水道入口附近的瑞克希‧銅鉗到達拉然城收集《達拉然的建立》。','這可不是志同道合的投機者嗎？在這樣動盪的時刻潛入達拉然？嘖嘖。$B$B這才是我認識的$R！$B$B當那些法師忙不過來的時候，我們或許能找到一些「被錯置」的寶藏。他們有一整座都是秘法魔法書籍的圖書館。如果你能幫我找一本秘典，我就能拿去轉賣一些錢。這筆錢我會和你平分。$B$B欸，別那樣看我。你可不是來這裡校外教學的。所以你到底要不要加入？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96988,'zhTW','力量的泉源','為幽暗城的馬丁‧費爾本醫生到達拉然城收集6個碎裂的哨兵核心。','隨著達拉然城被自己的造物圍攻，現在正是取得一些樣本的好機會。$B$B想像一個被秘法強化的憎惡體大軍。黑暗女士只能被迫認可我的鍊金實力。說不定還會給我皇家藥劑師學會主席的頭銜呢。$B$B去城裡找一些造物的核心。它們不會心甘情願給你，所以務必不擇手段得到核心。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96989,'zhTW','你的第一隻騎乘迅猛龍','檢視騎乘用的迅猛龍，選擇你的第一隻坐騎。','嘿，老兄！今天是你的大日子啊。你準備好要握起這些兇猛野獸的韁繩了嗎，嗯？$B$B很多人都小看這些野獸有多麼聰明、多麼兇狠。一旦你成功和牠培養感情，絕對找不到更棒、更快、更致命的夥伴了。$B$B所以，你有個重要的決定得下。你和你的迅猛龍將一起穿梭這個世界，牠也會反過來挑選騎手。$B$B去看看吧，決定好之後再回來找我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96994,'zhTW','你的第一隻騎乘用狼','檢視騎乘用的狼，選擇你的第一隻坐騎。','Lok\'tar，$C。你想來和自己的第一隻狼建立羈絆嗎？很好。$B$B沒什麼比獸人和狼之間的羈絆更堅固了。牠們不單只是坐騎，而是一輩子的夥伴與朋友。$B$B獸人與狼之間的羈絆並非為了虛名而做出的選擇。每個獸人和狼都會建立特殊的羈絆，絕不是單純的買賣關係。$B$B你挑選牠們時，牠們也會選擇你。$B$B去看看吧，看哪一隻跟你有緣分。等你決定好了再回來找我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96996,'zhTW','你的第一隻騎乘逐風者','檢視騎乘用的逐風者，選擇你的第一隻坐騎。','現在你已經完成訓練了，看來風希望你和第一隻逐風者建立羈絆。$B$B我們從先祖的時代開始，世世代代都騎乘著這些逐風者。雖然牠們看起來細瘦修長，但其實是堅定又兇猛的坐騎。$B$B你和你的逐風者將一同穿梭這個世界，所以這將是個重要的選擇。但不必害怕，無論你做出什麼選擇，肯定都會是正確的。$B$B去看看逐風者吧，選好之後再回來找我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (96997,'zhTW','死馬和活馬一樣強','檢視騎乘用的不死馬，選擇你的第一隻坐騎。','你好，$C。我猜得出來你今天為什麼會來到我的獸欄。$B$B如果你想找坐騎，就是來對地方了。但我得先警告你，騎乘不死坐騎不是膽小鬼做得來的。$B$B所以，你有個重要的決定得做。你和你的不死坐騎會穿梭在世界各處，無論好壞。但別擔心，你做的任何決定都是最好的。$B$B去看看那些不死馬兒吧，等你下定決心之後再回來找我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97005,'zhTW','搶奪者愁拉盧克','把愁拉盧克的頭顱帶去給貧瘠之地的貝英漢。','傳聞說有個龐大的怪物，把這裡西北方的洞穴當作了巢穴，就在荊棘嶺的高原。剃鬃稱牠為愁拉盧克，或是「搶奪者」，曾經看過牠的人都說，牠大到能一口吞下一隻獸人。$B$B很少有人相信這種故事，但我相信…因為我自己也和這種怪物戰鬥過。為了悼念因這些怪物而死去的人們，那隻怪物必須死。$B$B召集強力的盟友，找到愁拉盧克的巢穴。殺死那怪物，把牠的頭顱帶回來給我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97220,'zhTW','菲爾莫爾的請求','把門樓貨物帶到位於貿易區的提亞斯乳酪店儲藏室門口。','我們這週很缺碼頭工人。$B$B你願意來減輕我們的送貨壓力嗎？$B$B把這個包裹送到門樓的儲藏室門口吧。就在提亞斯乳酪店的二樓。女主人艾蓮應該很熟悉整個流程。門樓平時會以更謹慎的方式送貨，能讓守衛軍官有更多儀式上的驚喜。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97222,'zhTW','門樓貨物','帶著門樓貨物爬上提亞斯乳酪店的樓梯，然後把東西留在門口。','沒錯，只是爬個樓梯而已，如果這個任務這麼簡單，你自己送上去應該沒問題吧？$B$B提亞斯乳酪店不是門樓的一部分，也無法使用儲藏室，但我們得共享樓層。$B$B把箱子放在儲藏室門口，守衛會派人去取貨的。他們回歸職守後就會把東西搬進去。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97223,'zhTW','血爪族母','把血爪族母的蛋拿給森金村的克薩爾迪。','你眼前的這些迅猛龍全是我自己訓練的。牠們來自卡林多各地，但最優秀的就是從我們海岸再過去的島上來的血爪迅猛龍。$B$B其中一隻叫血爪族母，非常凶猛，殺掉了不少我們村子裡的人，牠變得太過危險，不能放任牠在我們的邊境繼續造孽了。如果你能擊敗牠，把牠的蛋帶回來，我們就能培育新生的幼雛作為盟友，而非敵人。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97225,'zhTW','被遺忘的羅亞塑像','在回音群島收集8個被遺忘的羅亞塑像。把它們帶給森金村的加德林大師。','我們從札拉贊恩他們佔據的那座島上逃離時，留下了許多珍貴的塑像，那些塑像能用來和我們信奉的魂靈：羅亞溝通。$B$B札拉贊恩的追隨者毫不敬重羅亞，把這些塑像亂丟在島上各處。$B$B我們得盡快回收這些塑像，否則很可能會冒犯羅亞，這可是個大問題。$B$B快去盡可能找回羅亞塑像，再拿回來給我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97234,'zhTW','閱覽室','把包起來的閱讀資料帶到暴風城圖書館。','你是來討論傳說背後更深層意義的嗎？不是？$B$B好吧，那你參觀完之後，可以幫我把這個送到圖書館嗎？我們打算把一些沒什麼人氣的書換成更近期的著作。我列了一份清單，相信圖書館員能在現有的協議之下幫我們找到這些書籍。$B$B如果你願意幫忙的話，我們會招待免費的讀書會餐點。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97237,'zhTW','取書工作','在圖書館各處把閱讀資料找出來，然後把它們交給暴風城公園的羅伊‧路威爾斯。','我已經依照路威爾斯先生的清單查過我們所有的書庫了，這些書我們都有。$B$B不過你得親自從書櫃把這些書找出來。圖書館員的其中一個職責就是要保持警惕，那我就回去繼續整理書目了。$B$B雖然你是代替羅伊借閱這些閱讀資料，但不代表你要負責歸還，因為根據他的紙條，你只是個讀書會的官方信差。讀書會必須承擔這個責任。$B$B祝你一切順利，$N。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97243,'zhTW','火之召喚','前往風莓低地的烈焰聖殿，將眠焰火炬交給歐拉里安‧迅燃。','雖然我們在天空之牆境內，但這裡還是元素界域。只要我們願意傾聽，四大元素之靈就會與我們對話。在我們當中，有個塑風者與火元素的同調程度特別高。那個申多雷名叫歐拉里安‧迅燃。$B$B到風莓低地的烈焰聖殿把這個交給他。那個地方位在島嶼邊緣的一處隱密角落，就在瓦拉納爾的西邊。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97244,'zhTW','火之召喚','到風莓低地殺死天空祭司法拉迪爾並收集法拉迪爾的心臟。','有個名叫法拉迪爾的奧拉凱斯天空祭司。他過去曾是烈焰的呼喚者，也是忠誠的塑風者。如同許多奧拉凱斯，他用自己的忠誠換取力量，如今他的雙手沾滿了無數兄弟姐妹的鮮血。$B$B過了瓦拉納爾後，往東北方走，就能在一座農場找到天空祭司法拉迪爾，那地方就在奧基爾聖殿的南邊。殺掉那個叛徒。把他的心臟帶來給我。這個任務很血腥，但對我們即將進行的儀式不可或缺。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97245,'zhTW','火之召喚','到申德高地找到庫拉瑪的居所，在戰鬥中擊敗它。取得勝利後，將庫拉瑪的面具交給風莓低地的歐拉里安‧迅燃。','申德高地的居民提到有個名叫庫拉瑪的古老森林妖精。高地錨塔附近有座山丘，上面有個扭曲的樹樁，他們說它就住在那裡。$B$B前往高地，找到那個樹樁。用拳頭重擊樹皮，庫拉瑪就會現身。在戰鬥中擊敗它，把它的木製面具帶來給我。$B$B先提醒你，這個靈魂對你大多數的魔法都有極高的抗性。只有透過烈焰才能擊倒它。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97246,'zhTW','美食的誘惑','前往博斯坦的火坑，告訴他薩托要你將米奇的午餐親自送去給米奇。','我的兒子，米奇，一天到晚只想溜去找朋友玩。我跟他說可以去博斯坦的火坑拿午餐，但我知道他幾乎不曾去過，因為他每次回家都是飢腸轆轆。這些孩子總是把玩看得比自己的身體還重要！$B$B拜託你，去博斯坦的火坑一趟，告訴他你是來幫米奇送午餐的。你應該可以在葛羅瑪許堡後面找到米奇和他那些朋友。$B$B我白天都要待在這裡執勤，沒辦法盯著他按時吃飯。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97249,'zhTW','最喜歡的食物','將米奇的午餐交給葛羅瑪許堡後方的米奇','既然知道他父母擔心他不按時吃飯，讓自己餓肚子，我想到一個辦法。$B$B他們要我保證每天都打包不同的餐點，讓米奇不會習慣只吃某一種食物。不過，只要烤架放滿了，我們就會開始製作醬烤豬腹三明治，然後他一定會來領午餐。我們最近開始把剩下的酥脆糖衣碎片壓碎，當作配料。我們可以每天都加。$B$B把這個帶去給他。說不定他會開始提早出現，順便把朋友帶來！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97253,'zhTW','零件與碎片','從棘齒城南邊的上層海盜營地收集5把複雜的零件，之後回到棘齒城找卑鄙的維尼克斯。','嘿，你有時間嗎？$B$B事情是這樣的，我派去解決最近海盜問題的人，沒半個活著回來。試了六次之後我就想，「如果我改派機械過去呢？」結果發現，彎刀在緊要關頭也可以充當螺絲起子用，在我指示機械返回之前，它就已經被拆成碎片，丟在他們的營地各處了！$B$B我需要取回那些零件，而且既然這只是簡單快速的回收任務，我認為你生還的機率比其他人高出許多。你意下如何？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97257,'zhTW','火之召喚','等待歐拉里安開始在祭品火盆進行儀式，並聽從他的指示。$B$B你必須在倒數完畢前，將永恆之火送到瓦拉納爾。','現在我們會進行儀式。$B$B我會把祭品放在祭壇上，召喚出火之靈。如果祭品得到認可，它們就會現身並點燃永恆之火。隨後你需要將火炬往前伸，將其點燃。$B$B帶著點燃的火炬前往瓦拉納爾，把它放入恆焰火盆。你必須快點行動，在天空之牆這裡，火源之界的烈焰很快就會熄滅。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97263,'zhTW','你的包裹已送達','寄送伊德倫亂放的包裹。','<數個包裹被亂放在信箱附近。你注意到其中一個是從鷹巢山寄出，要送到鐵爐堡給伊德倫‧破颶者的。上頭另外寫著「急件」。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97265,'zhTW','憎恨怨怒','到淒涼之地的薩格隆擊敗各種怨怒薩特，然後回去葬影村找阿卡萊。','夥計，跟薩特做過交易嗎？$B$B我做過。我怎麼拒絕得了？我能得到的力量、知識，是任何一本普通的書都給不了的…而且還能得到一個充滿幹勁、魅力十足的手下。還有比這更划算的交易嗎？$B$B呸，他們當然永遠不會屈居於凡人之下。我在一無所有的時候跟他們討價還價，最後還是被棄若敝屣。$B$B現在我只想報仇。向怨怒薩特復仇。襲擊他們在東北邊的營地！讓他們的污血浸染大地。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97275,'zhTW','心急的伍特','將耶爾瑪克的藥水交給伍特。','伍特是個奇才，這點毋庸置疑。不過他的經驗、智慧和攪拌時間都有所欠缺，不知道如何尊重鍊金流程。$B$B他耗盡了我們所有最珍貴稀有的材料，卻不願停下來練習和精進他的基礎技能。$B$B把這瓶藥水交給他，這是我用快速調製法調配出來的。當他學到本土藥方和細膩手法才是一切的起點時，一定會重新審視自己的所作所為。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97277,'zhTW','葛朗德和戈茲溫','在西北方的山丘找到葛朗德和戈茲溫的營地。取回戈茲溫的機師記錄並擊殺雪豹徘徊者。','喂，我聽到戈茲溫兄弟慘叫聲的時候，剛好背對著他在烤野豬！$B$B我一轉身，就只看到兇狠的尖牙和一道殘影。那爪掌好大啊！一隻雪豹正拖著牠的地精獵物要離開。我馬上掄起獵槍朝牠開火。牠把獵物丟在地上，拔腿就跑了。$B$B幸好，老戈只有被抓傷而已。$B$B回去西北邊山丘上的營地，取回戈茲溫的機師記錄。如果你看到那隻雪豹，記得也把牠幹掉！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97279,'zhTW','失而復得的武器','收集6把被遺棄的訓練武器，然後交給洞穴中的克贊‧荊條。','隨著像你這樣的新兵不斷入伍，我們很難確保武器供應無虞。我們的武器鑄造師克贊那裡的訓練武器已經所剩不多，我也想順便了解一下你的本領，看看接下來該怎麼安排。你運氣很好，我有個兩全其美的辦法。$B$B當你出去殺野豬練練身手的時候，順便回收六把被遺棄的訓練武器。那些失敗的新兵就直接把它們丟在地上。收集完成後，就交給後面洞穴中的武器鑄造師克贊。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97282,'zhTW','風暴般的潛力','把5個充能的雷霆蜥蜴內臟拿去給枯水谷附近的雷茲拉克。','「雷茲拉克，當機會來敲門，一定要準備好抓住它。」這是加茲魯維教我的另外一句金句，我就打算這麼做。$B$B這球體看起來完好無損，應該只是沒動力了，但我有個點子，能立刻把它充能到全滿！$B$B西邊峽谷裡有一堆雷霆蜥蜴。牠們的內臟能儲藏強力的電能，正適合用來充能。$B$B去弄一些回來給我吧！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97284,'zhTW','瓦拉里爾的復仇','到淒涼之地的雷斧堡壘殺死燃刃獸人，然後回去尼耶爾前哨站找瓦拉里爾‧屠魔者。','如果瑪雷姆還活著，那麼，我懷疑燃刃獸人一定早就料到不久後就會有人找上門。他們一定會做好戰鬥的準備。$B$B我其實比較希望你保持低調，不跟他們發生衝突，但更可能的情況是，他們會把握每個跟你交手的機會，讓你與燃刃氏族刀劍相向。$B$B那不如我們一開始就先下手為強。有多少就殺多少，而我絕不會讓你白忙一場。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (97286,'zhTW','研究資格',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97287,'zhTW','精明交涉','在達拉然附近與大法師莫德菈的影像交談。','你能滲透進法師之城，確實做得不錯，但我認為我們是時候拿出更多…誠意了。$B$B雖然不樂意，但我不得不承認，在整個艾澤拉斯，達拉然擁有最豐富浩瀚的秘法知識。跟祈倫托多年來收集的秘法文獻一比，我的傑作相形失色。我認為，現在正是我們獲准加入這個精英組織的最佳時機，你不覺得嗎？$B$B帶著你獲得的這個微粒。他們一定會想盡辦法換回它，而且是不計代價。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97289,'zhTW','無盡的折磨','到幽暗城，把男爵的頭放在歐斯瑪的遺體旁。','我們都一直在製作憎惡體的頭顱，但這顆頭卻是獨一無二。這曾是聯盟總元帥的頭。歐斯瑪…應該是叫這個名字。他極度令人厭惡。黑暗女王曾親手處死他。$B$B如果它能說話的話，想想看它會吐出什麼秘密。還真的可以喔！前提是，我們得把它接到適當的宿主上。$B$B把它放到隔壁房間的遺骸旁吧。但先不要接起來。現在不行。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97290,'zhTW','無盡的折磨','把你發現的事說給幽暗城的大藥劑師法拉尼爾聽。','你這個…怪物…$B$B我為什麼…要幫你…$B$B給我滾…',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97291,'zhTW','無盡的折磨','幫幽暗城的大藥劑師法拉尼爾向貿易區的塔文‧格瑞斯特收集劇毒顱帽，在草藥學訓練師附近收集灼蝕草，以及向盜賊區的毒藥商購買苦楚精華。','把頭重新接合後，現在我們需要的就是將其束縛在黑暗女王的意志之下。這沒有什麼難度。這個怪物挨了這麼多打，腦袋也早已支離破碎了。$B$B我們只需要激發它就行了。$B$B幫我從貿易區的格瑞斯特小姐那邊取得劇毒顱帽。噢，還有從在地的草藥訓練師奧列斯塔家那邊取得一些灼蝕草。跟他們拿的時候不用客氣，這是他們欠我的。最後還需要一點苦楚精華。隨便一個毒藥商都有賣。$B$B我們得製作藥水啦！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97292,'zhTW','無盡的折磨','幫大藥劑師法拉尼爾把嘶鳴藥水注射到歐斯瑪遺骸上的系統管道中。','我製作了一個很不錯的藥水，一定能讓我們的貴賓…受到激發。$B$B把這個帶著。從他上頭的管道把這個餵給他。看看能不能讓他理解，忠誠服侍我們才是最重要的。$B$B還有，千萬別摔掉。我已經沒辦法再請新的助理了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97326,'zhTW','歇腳石','將8個光滑巨石送去給葛羅瑪許堡後方的絲拉。','嘿！你有時間幫我們吧！我知道你一定有，因為你一直面帶微笑地看著我們玩遊戲。$B$B葛羅瑪許堡後面的這個地點很棒，這裡有足夠的空間讓我們放玩偶。唯一的缺點是，我們沒有足夠的石頭作為椅子和桌子。$B$B你很高大，也很強壯…你能搬一些中等大小的光滑石頭過來嗎？讓我們必要時可以坐在上面休息。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97485,'zhTW','山崖傳統','向草藥師尼達購買一捆草藥、向附魔材料商納塔購買一捆雪松樹枝、向製皮材料商曼胡購買肌腱線，以及向烹飪材料商納爾購買儀祭燧石和火絨。$B$B將材料混合後，再從獵人高地將薰香灑入風中。','安希祝福你，朋友。$B$B我們牛頭人有將薰香灑入風中的傳統，我希望你也能入境隨俗一下。$B$B想要製作薰香，你必須向尼達購買草藥，向納塔購買雪松，向中央高地的曼胡購買肌腱線，再向上層高地的納爾購買儀祭燧石和火絨。買齊這些物品後，就將它們混在一起，然後在獵人高地向南的懸崖灑出。$B$B儀祭地點有墊子和薰香。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97530,'zhTW','清算流沙之槌','塔納利斯熱砂港的安全主管吉羅姆·比格維茲要你去取回在流沙之槌巨魔營地附近弄丟的閃亮手鐲。','那個商人的商隊在沙漠裡迷了路，結果卻遇上流沙之槌巨魔。他們只好丟棄一些貨物，吸引那些蠻卒的注意力才有機會活著逃出來。$B$B這個商人肯定跟經營船隻和飛艇的人有關係，因為他們現在要我去把弄丟的東西找回來。$B$B我只能在這裡工作。但如果你在痛宰巨魔的時候有看到閃亮的手鐲就帶回來吧，我會好好報答你的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97538,'zhTW','繪畫的顏料','雷霆崖的塔恩‧冬蹄想要30個暗色湖的昏暗草豆莢。','你好，朋友。可以請你幫個忙嗎？我的紅色顏料用完了，我想請個年輕人替我到石爪山脈跑一趟。$B$B山道半途上有個很大的湖名叫暗色湖，湖水裡生長著一種特別的植物。那個昏暗草的豆莢在曬乾後可以調出很鮮豔的紅色。幫我收集這個植物的豆莢，我會好好獎賞你的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97539,'zhTW','蛛絲縫線','把12個手術蛛絲交給阿拉希高地落錘鎮的葛列格里‧維克多醫生。','這座營地就這樣被丟著任其腐爛。圍攻所造成的損傷依然尚未修復，就好像「假裝沒看到」是這裡的政策一樣。我絕不允許同樣的衰敗發生在這裡。醫務室由我負責，而我打算讓它保持正常運作。$B$B我們的物資快要用光了。我需要更多設備，多到足以讓工人和守衛們能繼續撐下去。$B$B在緊急情況下，我們可以用扭緊的蜘蛛絲，製作出相當有效的野戰縫合線。$B$B$C，去幫我從在這片高地上出沒的蜘蛛身上弄一些過來。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97583,'zhTW','扭扭。','購買一些營養軟泥淤泥，然後回到你興奮的軟泥怪朋友身邊。如果它看起來累了，可以試著跳舞來吸引它的注意力。','<小軟泥怪似乎很開心，也嘗試模仿你跳舞的動作。不過它看起來很累。$B$B小軟泥怪停在淤泥上，並將其吸收，看起來恢復了一點力氣。$B$B看來跳舞讓它真的很疲憊。或許幽暗城的運河附近有人有販售這種營養的淤泥。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97891,'zhTW','即時藥水快遞','在時限內把不穩定的藥水交給鍊金房的馬丁‧費爾本醫生。','那邊的！快，我想請你穿過軟泥運河，把藥水拿去給鍊金房的馬丁‧費爾本醫生！$B$B它保存期限並不長，我也沒辦法親自跑一趟，如果這麼做的話我的膝蓋就要報銷了。$B$B我想這就是身為不死族的遺憾吧。$B$B不要浪費時間了！快，快去！$B$B<奧雷薩多比了個趕人走的手勢。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97894,'zhTW','奧伯丁商業','在黑海岸的奧伯丁確認高爾博多‧鋼手的情況。$B$B博古斯提到在暴風港最南邊的碼頭有一艘船可以載你過去。','很高興認識你！我是博古斯，來自獨一無二的鋼拳家族。想做公平的買賣，找我們鋼拳準沒錯！$B$B幾週前，我兄弟高爾博多加入了奧伯丁的一個商鋪。老實跟你說，在那裡為船隻供應物資可是能賺進大把大把的金幣呢！那傢伙真幸運。$B$B不過從那之後我就一直沒他的消息，如果你剛好要去那裡，能幫我確認一下他的狀況嗎？$B$B港口現在有一艘新船可以直接帶你過去。去最南邊的碼頭就對了，你不會錯過的！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97899,'zhTW','紮營入門指南：鍊金術','當你的專業技能達到一定熟練度後，到奧格瑪與伍特交談，學習製作符合專業技能的紮營物品。','所以說，你選擇成為鍊金師，與藥膏和藥水為伍。相信那一定能在你的旅途中派上用場。$B$B我認識一個人，可以教你如何在營地中製作法力井。建成之後，所有治療者和施法者都會蜂擁而至，只為喝上一口恢復精神的泉水。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97900,'zhTW','紮營入門指南：鍛造','當你的專業技能達到一定熟練度後，到剃刀嶺與杜克交談，學習製作符合專業技能的紮營物品。','所以說，你成為鐵匠了。如果你想確保刀刃永不變鈍，那的確是很好的選擇。$B$B我認識一個人可能幫得上忙，他可以教你如何製作砂輪。只要營地有了砂輪，附近的所有戰士和盜賊都會排隊等著磨利他們的武器。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97901,'zhTW','紮營入門指南：附魔','當你的專業技能達到一定熟練度後，到奧格瑪與夏格交談，學習製作符合專業技能的紮營物品。','附魔師可以強化物品，在野外的任何營地中，都是廣受歡迎的人物。$B$B我認識一個人，可以教你如何在營地中製作附魔魯特琴。在休息的時候來點娛樂也是很重要的事，這個小魔法能幫助你做好準備，等你再度踏上旅程時，就能從容面對各式各樣的挑戰。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97902,'zhTW','紮營入門指南：工程學','當你的專業技能達到一定熟練度後，到剃刀嶺與穆德拉克交談，學習製作符合專業技能的紮營物品。','像你這樣的工程師可以製造各式各樣的裝置、機器人和炸彈，藉此獲得樂趣和利益。$B$B我認識一個人，可以教你如何在營地中製作材料機器人。這個實用的機器人可以讓你隨時補充物資，確保自己和盟友永遠不缺施法所需的材料。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97903,'zhTW','紮營入門指南：急救','當你的專業技能達到一定熟練度後，到剃刀嶺與拉烏克交談，學習製作符合專業技能的紮營物品。','所以說，你選擇學習急救嗎？對於一個$C，那是很崇高…很務實的選擇。$B$B我認識一個人，可以教你如何在營地中製作急救箱。在冒險過程中，受傷是家常便飯，如果在營地提供不可或缺的治療功能，有時甚至能救人一命。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97904,'zhTW','紮營入門指南：釣魚','當你的專業技能達到一定熟練度後，到森金村附近與勞迪克交談，學習製作符合專業技能的紮營物品。','你可能不這麼認為，但你的釣魚技能其實在營地中非常有用。$B$B我認識一個人，可以教你如何在營地中製作魚缸。透過這個設施，你可以為自己和同行的冒險者提供一點樂趣。冒險者越快樂，就越強大，相信這點會反映在你的戰鬥能力上。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97905,'zhTW','紮營入門指南：草藥學','當你的專業技能達到一定熟練度後，到奧格瑪與加迪交談，學習製作符合專業技能的紮營物品。','在我看來，你好像學到一些草藥學的技巧。你知道的，採花採草不一定是浪費時間。它可能很有用…甚至有利可圖。$B$B我認識一個人，可以教你如何在營地中製作薰香蠟燭。對於治療者和施法者而言，高精神力對於維持戰力十分重要，薰香蠟燭提供的加成一定會讓魔法使用者感激不盡。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97906,'zhTW','紮營入門指南：製皮','當你的專業技能達到一定熟練度後，到奧格瑪與卡洛雷克交談，學習製作符合專業技能的紮營物品。','你成為製皮師了。恭喜你，$C。我認識一個人，可以教你如何製作帳篷，在大熱天為你遮陽，在雨天供你避雨。$B$B有了一頂耐用的帳篷，相信你一定能好好養精蓄銳，在旅途中保持最佳狀態。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97907,'zhTW','紮營入門指南：採礦','當你的專業技能達到一定熟練度後，到剃刀嶺與克魯恩交談，學習製作符合專業技能的紮營物品。','採礦或許不夠光鮮亮麗，卻能一分耕耘，一分收穫，是很值得你深入鑽研的專業技能。$B$B我認識一個人，可以教你如何在營地中製作磁石。建成之後，所有想要舞刀弄劍的人都會紛紛聚集在你的火堆旁，感受它提供的額外「加持」，以便提高他們的戰力。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97908,'zhTW','紮營入門指南：剝皮','當你的專業技能達到一定熟練度後，到奧格瑪與蘇爾德交談，學習製作符合專業技能的紮營物品。','能夠技術純熟地從死去的野獸身上採集皮革和毛皮，絕對是冒險者最有價值的技巧。$B$B我認識一個人，可以教你如何在營地中製作營地椅子。偶爾坐下休息也很重要，你可以利用你採集的那些毛皮製作出一張舒適的椅子。適當的休息有助於確保你維持巔峰狀態，這樣下次遇到麻煩，就能精準命中要害。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97914,'zhTW','拓展視野','把桑迪斯的信件交給暴風城的巴洛斯·艾力克斯頓。$B$B桑迪斯提到奧伯丁有一艘船可以載你過去。','奧伯丁是個與世無爭的地方，$C。達納蘇斯的人鮮少提起此地。多數人只會想起大崩裂從我們手中奪去的亞米薩蘭、巴莎蘭和…拉薩拉札等繁榮的大城市。$B$B而奧伯丁卻在它們的耀眼光輝之下默默留存至今。$B$B我希望我們在這裡的努力能被人看見。有一艘新船從暴風城帶來了人流和補給品。我希望你能搭乘下一班船，並把這封信交給一個名叫巴洛斯‧艾力克斯頓的人類。$B$B讓世人看見我們的家園吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97915,'zhTW','紮營入門指南：鍊金術','當你的專業技能達到一定熟練度後，到暴風城附近的艾爾文森林與鍊金師瑪洛瑞交談，學習製作符合專業技能的紮營物品。','所以說，你選擇成為鍊金師，與藥膏和藥水為伍。相信那一定能在你的旅途中派上用場。$B$B我認識一個人，可以教你如何在營地中製作法力井。建成之後，所有治療者和施法者都會蜂擁而至，只為喝上一口恢復精神的泉水。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97916,'zhTW','紮營入門指南：鍛造','當你的專業技能達到一定熟練度後，到閃金鎮與鐵匠阿古斯交談，學習製作符合專業技能的紮營物品。','所以說，你成為鐵匠了。如果你想確保刀刃永不變鈍，那的確是很好的選擇。$B$B我認識一個人可能幫得上忙，他可以教你如何製作砂輪。只要營地有了砂輪，附近的所有戰士和盜賊都會排隊等著磨利他們的武器。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97917,'zhTW','紮營入門指南：附魔','當你的專業技能達到一定熟練度後，到暴風城與貝蒂‧奎恩交談，學習製作符合專業技能的紮營物品。','附魔師可以強化物品，在野外的任何營地中，都是廣受歡迎的人物。$B$B我認識一個人，可以教你如何在營地中製作附魔魯特琴。在休息的時候來點娛樂也是很重要的事，這個小魔法能幫助你做好準備，等你再度踏上旅程時，就能從容面對各式各樣的挑戰。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97918,'zhTW','紮營入門指南：工程學','當你的專業技能達到一定熟練度後，到暴風城與斯普萊特交談，學習製作符合專業技能的紮營物品。','像你這樣的工程師可以製造各式各樣的裝置、機器人和炸彈，藉此獲得樂趣和利益。$B$B我認識一個人，可以教你如何在營地中製作材料機器人。這個實用的機器人可以讓你隨時補充物資，確保自己和盟友永遠不缺施法所需的材料。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97919,'zhTW','紮營入門指南：急救','當你的專業技能達到一定熟練度後，到閃金鎮與蜜雪兒‧貝利交談，學習製作符合專業技能的紮營物品。','所以說，你選擇學習急救嗎？對於一個$C，那是很崇高…很務實的選擇。$B$B我認識一個人，可以教你如何在營地中製作急救箱。在冒險過程中，受傷是家常便飯，如果在營地提供不可或缺的治療功能，有時甚至能救人一命。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97920,'zhTW','紮營入門指南：釣魚','當你的專業技能達到一定熟練度後，到閃金鎮附近與李‧布朗交談，學習製作符合專業技能的紮營物品。','你可能不這麼認為，但你的釣魚技能其實在營地中非常有用。$B$B我認識一個人，可以教你如何在營地中製作魚缸。透過這個設施，你可以為自己和同行的冒險者提供一點樂趣。冒險者越快樂，就越強大，相信這點會反映在你的戰鬥能力上。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97921,'zhTW','紮營入門指南：草藥學','當你的專業技能達到一定熟練度後，到艾爾文森林與草藥師博米洛伊交談，學習製作符合專業技能的紮營物品。','在我看來，你好像學到一些草藥學的技巧。你知道的，採花採草不一定是浪費時間。它可能很有用…甚至有利可圖。$B$B我認識一個人，可以教你如何在營地中製作薰香蠟燭。對於治療者和施法者而言，高精神力對於維持戰力十分重要，薰香蠟燭提供的加成一定會讓魔法使用者感激不盡。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97922,'zhTW','紮營入門指南：製皮','當你的專業技能達到一定熟練度後，到閃金鎮與艾德勒‧費歐德交談，學習製作符合專業技能的紮營物品。','你成為製皮師了。恭喜你，$C。我認識一個人，可以教你如何製作帳篷，在大熱天為你遮陽，在雨天供你避雨。$B$B有了一頂耐用的帳篷，相信你一定能好好養精蓄銳，在旅途中保持最佳狀態。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97923,'zhTW','紮營入門指南：採礦','當你的專業技能達到一定熟練度後，到暴風城與吉爾曼‧石手交談，學習製作符合專業技能的紮營物品。','採礦或許不夠光鮮亮麗，卻能一分耕耘，一分收穫，是很值得你深入鑽研的專業技能。$B$B我認識一個人，可以教你如何在營地中製作磁石。建成之後，所有想要舞刀弄劍的人都會紛紛聚集在你的火堆旁，感受它提供的額外「加持」，以便提高他們的戰力。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97924,'zhTW','紮營入門指南：剝皮','當你的專業技能達到一定熟練度後，到閃金鎮與海倫尼‧派特斯金納交談，學習製作符合專業技能的紮營物品。','能夠技術純熟地從死去的野獸身上採集皮革和毛皮，絕對是冒險者最有價值的技巧。$B$B我認識一個人，可以教你如何在營地中製作營地椅子。偶爾坐下休息也很重要，你可以利用你採集的那些毛皮製作出一張舒適的椅子。適當的休息有助於確保你維持巔峰狀態，這樣下次遇到麻煩，就能精準命中要害。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97925,'zhTW','紮營入門指南：裁縫','當你的專業技能達到一定熟練度後，到艾爾文森林的東谷伐木場與艾爾丁交談，學習製作符合專業技能的紮營物品。','裁縫是投資報酬率極高的交易技能，相信它一定能幫上你的忙。$B$B我認識一個人，可以教你如何在營地中製作陣營旌旗，前提是你有對應的能力。在任何戰場上，激勵和士氣都是成功的關鍵，振奮人心的旌旗可以讓你保持精力充沛。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97926,'zhTW','只能暫時如此','到黑海岸把艾力克斯頓的回信交給奧伯丁的桑迪斯·織風。','幫忙有這麼輕鬆就好了，$C，我真的這麼想。$B$B要是你在這裡多待一段時間，就知道生活有多不容易。暴風城不像以前那樣了，現在所剩的資源也越來越少。$B$B下次你看到長老時，把這個給他吧。這雖然不是他所期望的，但也是我唯一能給的東西了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97927,'zhTW','紮營入門指南：鍊金術','當你的專業技能達到一定熟練度後，到雷霆崖與克瑞交談，學習製作符合專業技能的紮營物品。','所以說，你選擇成為鍊金師，與藥膏和藥水為伍。相信那一定能在你的旅途中派上用場。$B$B我認識一個人，可以教你如何在營地中製作法力井。建成之後，所有治療者和施法者都會蜂擁而至，只為喝上一口恢復精神的泉水。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97928,'zhTW','紮營入門指南：鍛造','當你的專業技能達到一定熟練度後，到雷霆崖與瑟拉格‧石蹄交談，學習製作符合專業技能的紮營物品。','所以說，你成為鐵匠了。如果你想確保刀刃永不變鈍，那的確是很好的選擇。$B$B我認識一個人可能幫得上忙，他可以教你如何製作砂輪。只要營地有了砂輪，附近的所有戰士和盜賊都會排隊等著磨利他們的武器。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97929,'zhTW','紮營入門指南：附魔','當你的專業技能達到一定熟練度後，到雷霆崖與莫特‧晨行者交談，學習製作符合專業技能的紮營物品。','附魔師可以強化物品，在野外的任何營地中，都是廣受歡迎的人物。$B$B我認識一個人，可以教你如何在營地中製作附魔魯特琴。在休息的時候來點娛樂也是很重要的事，這個小魔法能幫助你做好準備，等你再度踏上旅程時，就能從容面對各式各樣的挑戰。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
