INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97938,'zhTW','紮營入門指南：鍊金術','當你的專業技能達到一定熟練度後，到多蘭納爾與塞恩德拉·細語者交談，學習製作符合專業技能的紮營物品。','所以說，你選擇成為鍊金師，與藥膏和藥水為伍。相信那一定能在你的旅途中派上用場。$B$B我認識一個人，可以教你如何在營地中製作法力井。建成之後，所有治療者和施法者都會蜂擁而至，只為喝上一口恢復精神的泉水。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97939,'zhTW','紮營入門指南：鍛造','當你的專業技能達到一定熟練度後，到黑海岸的奧伯丁與艾麗薩·鋼拳交談，學習製作符合專業技能的紮營物品。','所以說，你成為鐵匠了。如果你想確保刀刃永不變鈍，那的確是很好的選擇。$B$B我認識一個人可能幫得上忙，他可以教你如何製作砂輪。只要營地有了砂輪，附近的所有戰士和盜賊都會排隊等著磨利他們的武器。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97940,'zhTW','紮營入門指南：附魔','當你的專業技能達到一定熟練度後，到泰達希爾的神諭林地與奧蘭納·鴉眼交談，學習製作符合專業技能的紮營物品。','附魔師可以強化物品，在野外的任何營地中，都是廣受歡迎的人物。$B$B我認識一個人，可以教你如何在營地中製作附魔魯特琴。在休息的時候來點娛樂也是很重要的事，這個小魔法能幫助你做好準備，等你再度踏上旅程時，就能從容面對各式各樣的挑戰。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97941,'zhTW','紮營入門指南：工程學','當你的專業技能達到一定熟練度後，到黑海岸的奧伯丁與潔娜·雷姆尼利交談，學習製作符合專業技能的紮營物品。','像你這樣的工程師可以製造各式各樣的裝置、機器人和炸彈，藉此獲得樂趣和利益。$B$B我認識一個人，可以教你如何在營地中製作材料機器人。這個實用的機器人可以讓你隨時補充物資，確保自己和盟友永遠不缺施法所需的材料。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97942,'zhTW','紮營入門指南：急救','當你的專業技能達到一定熟練度後，到多蘭納爾與拜恩希交談，學習製作符合專業技能的紮營物品。','所以說，你選擇學習急救嗎？對於一個$C，那是很崇高…很務實的選擇。$B$B我認識一個人，可以教你如何在營地中製作急救箱。在冒險過程中，受傷是家常便飯，如果在營地提供不可或缺的治療功能，有時甚至能救人一命。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97943,'zhTW','紮營入門指南：釣魚','當你的專業技能達到一定熟練度後，到達納蘇斯與阿斯坦婭交談，學習製作符合專業技能的紮營物品。','你可能不這麼認為，但你的釣魚技能其實在營地中非常有用。$B$B我認識一個人，可以教你如何在營地中製作魚缸。透過這個固定裝置，你可以為自己和同行的冒險者提供一點樂趣。冒險者越快樂，就越強大，相信這點會反映在你的戰鬥能力上。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97944,'zhTW','紮營入門指南：草藥學','當你的專業技能達到一定熟練度後，到多蘭納爾與瑪洛尼·刃葉交談，學習製作符合專業技能的紮營物品。','在我看來，你好像學到一些草藥學的技巧。你知道的，採花採草不一定是浪費時間。它可能很有用…甚至有利可圖。$B$B我認識一個人，可以教你如何在營地中製作薰香蠟燭。對於治療者和施法者而言，高精神力對於維持戰力十分重要，薰香蠟燭提供的加成一定會讓魔法使用者感激不盡。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97946,'zhTW','紮營入門指南：製皮','當你的專業技能達到一定熟練度後，到多蘭納爾往達納蘇斯的路上與納迪婭·織髮交談，學習製作符合專業技能的紮營物品。','你成為製皮師了。恭喜你，$C。我認識一個人，可以教你如何製作帳篷，在大熱天為你遮陽，在雨天供你避雨。$B$B有了一頂耐用的帳篷，相信你一定能好好養精蓄銳，在旅途中保持最佳狀態。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97948,'zhTW','紮營入門指南：採礦','當你的專業技能達到一定熟練度後，到奧伯丁與庫德拉姆‧石錘交談，學習製作符合專業技能的紮營物品。','採礦或許不夠光鮮亮麗，卻能一分耕耘，一分收穫，是很值得你深入鑽研的專業技能。$B$B我認識一個人，可以教你如何在營地中製作磁石。建成之後，所有想要舞刀弄劍的人都會紛紛聚集在你的火堆旁，感受它提供的額外「加持」，以便提高他們的戰力。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97949,'zhTW','紮營入門指南：剝皮','當你的專業技能達到一定熟練度後，到多蘭納爾往達納蘇斯的路上與拉德納爾·織髮交談，學習製作符合專業技能的紮營物品。','能夠技術純熟地從死去的野獸身上採集皮革和毛皮，絕對是冒險者最有價值的技巧。$B$B我認識一個人，可以教你如何在營地中製作營地椅子。偶爾坐下休息也很重要，你可以利用你採集的那些毛皮製作出一張舒適的椅子。適當的休息有助於確保你維持巔峰狀態，這樣下次遇到麻煩，就能精準命中要害。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97950,'zhTW','紮營入門指南：裁縫','當你的專業技能達到一定熟練度後，到達納蘇斯與蒂安娜交談，學習製作符合專業技能的紮營物品。','裁縫是投資報酬率極高的交易技能，相信它一定能幫上你的忙。$B$B我認識一個人，可以教你如何在營地中製作陣營旌旗，前提是你有對應的能力。在任何戰場上，激勵和士氣都是成功的關鍵，振奮人心的旌旗可以足以讓你保持精力充沛。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97951,'zhTW','紮營入門指南：鍊金術','當你的專業技能達到一定熟練度後，到布瑞爾與卡羅萊‧安尼斯交談，學習製作符合專業技能的紮營物品。','所以說，你選擇成為鍊金師，與藥膏和藥水為伍。相信那一定能在你的旅途中派上用場。$B$B我認識一個人，可以教你如何在營地中製作法力井。建成之後，所有治療者和施法者都會蜂擁而至，只為喝上一口恢復精神的泉水。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
