INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97959,'zhTW','紮營入門指南：採礦','當你的專業技能達到一定熟練度後，到幽暗城與布羅姆‧基里安交談，學習製作符合專業技能的紮營物品。','採礦或許不夠光鮮亮麗，卻能一分耕耘，一分收穫，是很值得你深入鑽研的專業技能。$B$B我認識一個人，可以教你如何在營地中製作磁石。建成之後，所有想要舞刀弄劍的人都會紛紛聚集在你的火堆旁，感受它提供的額外「加持」，以便提高他們的戰力。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
