INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97963,'zhTW','紮營入門指南：鍊金術','當你的專業技能達到一定熟練度後，到申德村與妮亞莎‧迅集交談，學習製作符合專業技能的紮營物品。','所以說，你選擇成為鍊金師，與藥膏和藥水為伍。相信那一定能在你的旅途中派上用場。$B$B我認識一個人，可以教你如何在營地中製作法力井。建成之後，所有治療者和施法者都會蜂擁而至，只為一親芳澤。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97964,'zhTW','紮營入門指南：鍛造','當你的專業技能達到一定熟練度後，到申德村與艾迪‧多鑄交談，學習製作符合專業技能的紮營物品。','所以說，你成為鐵匠了。如果你想確保刀刃永不變鈍，那的確是很好的選擇。$B$B我認識一個人可能幫得上忙，他可以教你如何製作砂輪。只要營地有了砂輪，附近的所有戰士和盜賊都會排隊等著磨利他們的武器。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97972,'zhTW','紮營入門指南：裁縫','當你的專業技能達到一定熟練度後，到申德村與塔琳‧耀線交談，學習製作符合專業技能的紮營物品。','裁縫是投資報酬率極高的交易技能，相信它一定能幫上你的忙。$B$B我認識一個人，可以教你如何在營地中製作陣營旌旗，前提是你有對應的能力。在任何戰場上，激勵和士氣都是成功的關鍵，振奮人心的旌旗可以足以讓你保持精力充沛。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97973,'zhTW','紮營入門指南：裁縫','當你的專業技能達到一定熟練度後，到申德村與塔琳‧耀線交談，學習製作符合專業技能的紮營物品。','裁縫是投資報酬率極高的交易技能，相信它一定能幫上你的忙。$B$B我認識一個人，可以教你如何在營地中製作陣營旌旗，前提是你有對應的能力。在任何戰場上，激勵和士氣都是成功的關鍵，振奮人心的旌旗可以足以讓你保持精力充沛。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97977,'zhTW','自然的呼喚','收集4個瘤背圖騰，然後交給塔琳德拉。','瘤背熊怪不會輕易背叛自古以來就結交的盟友。我們必須進一步了解他們所處的困境。$B$B在他們廢棄的家園裡尋找圖騰。如果有任何圖騰能在他們離開後挺過混亂，或許上頭的印記能告訴我們這裡究竟發生了什麼事。$B$B你能在谷地的西部邊陲找到他們的營地，不過那裡可能會有劣魔和小劣魔。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97979,'zhTW','女神的力量','施放伊露恩之光以及影遁。','你生來是卡多雷，是眾星之子，也擁有著與生俱來的天賦。伊露恩的祝福會強化我們的力量，幫助我們百發百中，或幫助我們藏匿身形，如同月亮遮蔽太陽。$B$B在海加爾山保衛戰後，我們的漫長守望迎來終結，我們與其他種族共組聯盟，時機來臨時，你自然會見到他們。現在，你藏身在泰達希爾的枝幹之中。$B$B展示月亮之母的贈禮，沐浴在祂的祝福下。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (97985,'zhTW','雷霆之心','在千針石林殺死風暴之心，然後取下牠的心臟。','很有意思，對不對？這是我第一次有機會一窺創造憎惡體的奧秘。$B$B我一直在研究這些筆記，結果我們需要的是一顆心。而且要很大顆！$B$B我聽說有一隻名叫風暴之心的巨大雷霆蜥蜴，就在千針石林的峽谷邊陲徘迴。牠這樣的名號，一定會有我們需要的心臟。那顆心臟歸我莫屬！$B$B噢，我建議你找一些朋友同去。風暴之心絕非等閒之輩。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98013,'zhTW','不斷增長的勢力','在古樹之林為阿巴爾殺死12個雷鱗侍從、8個雷鱗巫師和6個雷鱗戰士。','做好在廢墟中碰上難題的準備吧，年輕人…那裡不是隨便就能進去的。$B$B成群被詛咒，如今被稱為納迦的精靈貴族在那座過去十分輝煌的城市裡遊蕩。到東北方，把他們從這片土地上趕出去。$B$B他們已經和過去的樣子…截然不同。如果是他們幫助了暮光之錘，他們只會給曾經庇護他們的森林帶來更多苦難。$B$B他們渴望戰爭，$C。那我們就…給他們戰爭。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98021,'zhTW','哨兵嶺之行','到西部荒野的哨兵嶺向格里安‧斯托曼報到。','如果你想開始做些對這個世界有幫助的事，我建議你去西部荒野南邊，一個叫做哨兵嶺的聚落，找一個名叫格里安‧斯托曼的人。他的人急需援助。$B$B從另一個生存位面來到這裡後，我們家鄉面臨的問題似乎變得微不足道。我向你保證，你對那些受這類問題影響的人提供的幫助，對他們而言意義重大，你也會在過程中變得越來越強大。$B$B祝你好運，冒險者！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98024,'zhTW','十字路口之旅','到貧瘠之地的十字路口向索克報到。','從元素界域來到這裡後，我們家鄉面臨的問題似乎變得微不足道。不用擔心，部落面臨的危險都很實際，只要你能讓自己活下來，最終一定會脫胎換骨。$B$B如果你想開始做些對這個世界有幫助的事，就往西南方走，前往稱為貧瘠之地的廣大荒原。那裡有個聚落名為十字路口。那裡驕傲的居民急需援助。$B$B願榮耀與你同行，冒險者！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98025,'zhTW','通緝：賈瓦奈爾','尋找並殺死名叫賈瓦奈爾的貓頭鷹，然後取下牠的羽毛。這隻漆黑的貓頭鷹最後一次是出現在山腳附近的亞米薩蘭廢墟北方。之後再向奧伯丁的哨兵戈琳達·納希恩回報。','注意！$B$B殺死稱為「劍羽」的貓頭鷹「賈瓦奈爾」，就可以獲得一筆賞金。$B$B不幸的是，這隻貓頭鷹已經發狂了，還在奧伯丁附近的路上攻擊旅人。$B$B賈瓦奈爾最後一次出現是在亞米薩蘭廢墟的北方，就在山腳附近。把牠漆黑的羽毛帶回來當作牠已經身亡的證據。$B$B殺死該貓頭鷹後請到奧伯丁的哨兵戈琳達‧納希恩處領取賞金。$B$B奧伯丁鄉村委員會',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98042,'zhTW','在那之前都是有趣的遊戲…','到黑海岸的主宰之劍，從暮光信徒或暴徒身上取得卓越之眼，接著再回到奧伯丁找願意收下此物的人。','<當你撕下暮光之書的唯一一張書頁時，一個不祥的聲音突然浮現在你腦海裡。>$B$B他們失敗了。$B$B你將會被遺忘。$B$B他們將會失去得到的眼睛。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98046,'zhTW','大地之冠','到達納蘇斯，把枯竭的容器交給月神殿的拉瑞亞。','<大德魯伊范達爾·鹿盔惱怒地看著你。>$B$B你怎麼還在這裡？$B$B帶著藥瓶，然後滾出我的視線，$C。很明顯，我要的解答都不在這些藥水裡，從以前到現在都是如此。$B$B或許南方月神殿的女祭司知道該如何處理。$B$B<范達爾撇開頭，不想再和你說話。>$B$B我得盯著別的東西看，你才會走是吧…',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98059,'zhTW','希爾斯布萊德的庫藏','把密封的公司請求放在希爾斯布萊德市政廳記帳桌上。','希爾斯布萊德議會並沒有回覆我們新執政官的信件。我去找路過城鎮的商人套話，也無法解釋他們為何沉默不語。$B$B我們只是想請求支援，但我卻聽說多具完好無損的弩砲存放在不見天日的地方。$B$B你就裝成辦公事的市民，把這個恭敬地放在他們的記帳桌上。$B$B事成後再回來找我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98065,'zhTW','大地之冠','到達納蘇斯，把月井殘渣交給月神殿的泰蘭妲‧語風。','你得馬上把這個交給泰蘭妲！我會把它用更儀式性的容器裝起來。$B$B不用害怕。伊露恩的高階女祭司看似冷酷，其實卻很善良。她會保護進到達納蘇斯的每個人，也會讓他們都浸沐在我們女神的光芒之下。$B$B她收到這個聖水會很高興的。你可以到我們正上方找她。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98067,'zhTW','哨兵之眼','到達納蘇斯，為月神殿的哨兵達莉亞‧日刃把哨兵貓頭鷹放在塞納里奧城堡深處的入口、達納蘇斯銀行、工匠區旅館和城鎮大門。','羽月將軍確保每個衛兵都有時間可以向伊露恩祈禱。能幹的女獵手不只需要手中的武器，也需要女神的贈禮才能擊潰敵人。$B$B你可以幫我完成每日工作嗎？從北邊的塞納里奧城堡下的通道開始，把哨兵放在城鎮中心、東北方的工匠區旅館，還有城鎮大門各處。守衛會協助你的。$B$B泰達希爾暗潮洶湧，而我們必須保持警惕。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98070,'zhTW','阻止尖嘯鷹身人','殺死5個尖嘯的鷹身人、5個尖嘯的遊蕩者鷹身人，以及5個尖嘯的喚風者鷹身人。','尖嘯峽谷住著一群鷹身人，他們不但本性凶狠，也喜歡四處劫掠。他們近期伏擊了還膽敢穿越此地的補給品商隊。$B$B如果不快點動手的話，就不會有商隊願意前往亂風崗了。$B$B去吧，盡可能解決掉那些鷹身人。事成之後再回來找我，我會好好獎賞你的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98072,'zhTW','天空中的鱷魚','收集8片完好的赤紅鱗片，並將它們帶去給米奈希爾港的詹姆士‧哈洛倫。','你可真是個行動派！如果你願意挑戰更危險一點的工作，我還有最後一個忙想請你幫一下。$B$B鱷魚皮貿易雖然收入穩定，但跟幼龍鱗片帶來的利潤相比，那根本是小巫見大巫。大家願意花大把大把的金幣買上一整袋。$B$B我都稱牠們是「天空中的鱷魚」！我的徒弟絕對搞不定牠們，但這對你來說肯定是輕而易舉！$B$B你可以在遙遠東邊的綠帶草地找到那些幼龍。不過要小心點，那些山丘上有凶狠的獸人出沒！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98093,'zhTW','肅清原野','南貧瘠之地的蘇哈莎想要你在這片區域內除掉7隻雷鱗蜥蜴和7隻亂齒潛獵者，好讓她能安全地從樹上下來。','真高興你能看到我！$B$B今天早上的天氣很好，所以我從陶拉祖營地沿著黃金之路散步。當我要回頭的時候，我卻辦不到了。一群土狼開始圍著我繞圈，而雷鱗蜥蜴又堵住了我唯一的退路。$B$B我急忙爬上了這棵樹，但現在這個時間點周圍有太多敵人了，我根本沒辦法穿過原野跑回家。$B$B你願意幫我除掉這些雷鱗蜥蜴和亂齒潛獵者嗎？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98155,'zhTW','完好的雜毛土狼皮','把5個完好的雜毛土狼皮交給克利斯蒂‧格蘭特。','千針石林的雜毛土狼有著最好的毛皮。我在旅行中從來沒看過色澤這麼美的毛皮！$B$B我想送一些回去給暴風城的姐妹們，我知道她們一定能用來做些什麼。$B$B我對戰鬥一竅不通，所以如果你能幫我收集一些雜毛土狼皮就太好了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (98156,'zhTW','一包完好的毛皮','把一包完好的毛皮交給金伯利·格蘭特。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98189,'zhTW','歸還雕像','將米奈希爾雕像帶去給米奈希爾城堡的斯托菲隊長。','天啊，這、這真是太美了！$B$B盲眼公主號本該在悲劇發生前將這東西送達米奈希爾港。我們當時只差一點就成功了！$B$B我相信這本該由我們身後米奈希爾城堡的斯托菲隊長簽收。不如由你來接手這項殊榮，完成這個任務吧？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98190,'zhTW','家族之友','將米奈希爾雕像帶去給暴風要塞的大領主伯瓦爾‧弗塔根。','你會想立刻把這東西送到暴風城的。雖然我很自豪這座城堡與港口以泰瑞納斯‧米奈希爾二世為名，但我們只不過是處於敵人暴風圈中的一片平靜港灣，這裡一點也不安全。$B$B特別是龍喉氏族，他們為了掠奪這種東西願意付出極大的代價…我甚至不敢想像他們會拿它來做什麼。$B$B這件事就不用層層上報了，$G小夥子:小姑娘;。直接帶著它去找大領主弗塔根吧。他會知道把它放在哪裡最安全。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98191,'zhTW','家族之友','將米奈希爾雕像帶去給聖光大教堂的格雷森‧破影者領主。','泰瑞納斯國王曾是個好人。一個虔誠的人。深受他的子民愛戴，而且確實是我們當初能成立這個聯盟的根本原因。$B$B諷刺的是他很謙遜，他討厭這類紀念物，所以留存下來的極為稀少。而僅存的那些之中，能在羅德隆陷落後倖存下來的更是少之又少。$B$B看來聖光已經凝聚在這個雕像中了。把它放在城中心教堂廣場的聖光大教堂裡是最合適的。把它帶去給格雷森‧破影者領主妥善保管吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98197,'zhTW','戰利品','為瓦斯塔格‧鐵顎從米奈希爾港取回6個卡茲莫丹木材和30個卡茲莫丹鐵。','這座港口最初是由舊部落建立的，作為他們從海上入侵希爾斯布萊德的預備基地。這在當時完全繞過了羅德隆的防線！$B$B無數生命因此消逝…$B$B更糟的是，那支艦隊還是用他們從卡茲莫丹掠奪來的資源建造的！$B$B在海軍上將普勞德摩爾擊敗那些蠻兵並為聯盟建立此地後，港口裡還留有大量的資源。隨著龍喉氏族展開行動，我們需要這些資源來加強城鎮的防禦。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98208,'zhTW','天空之花','為米奈希爾港的希蕾莎‧暮語取回諾德爾。','我來自巨樹泰達希爾，並從奧伯丁來到米奈希爾港，為了尋回對族人至關重要的花朵。$B$B許久以前，我們族人的船隻「飛翔魚鷹號」與庫爾提拉斯第三艦隊一同在此遇難沉沒。它的貨物之中，有一朵被稱為諾德爾的花，用你們的話來說就是「天空之花」。在我們過去的家園海加爾山山頂，它曾在滿月之下綻放。$B$B請幫我把它找回來！船骸就在城市正南方，但那裡聚集著兇猛的魚人掠奪者！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98209,'zhTW','天空之花','將諾德爾帶去黑海岸給奧伯丁的桑迪斯‧織風。$B$B你想起希蕾莎說過，米奈希爾港的船可以帶你去那裡。','你能幫我把諾德爾送到奧伯丁的桑迪斯‧織風長老手中嗎？$B$B從這裡搭船應該很快就能把你送到那裡。$B$B很抱歉我得提出這個要求，我是真心的。但我因為這一路上的跋涉，以及第一次試圖找回這朵聖花時從那些魚人惡魔手中逃脫，到現在還累得不行！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98216,'zhTW','理解現今','在戈奧茲守衛附近使用戈奧茲石，並將其泰坦鑰石帶回去給勘察員維爾加。','上古之神？！這絕對不是什麼好消息！$B$B我在這顆石頭上辨識出了一段新內容，上面提到某種守護者。無論那是什麼，肯定都和這顆石頭有關！$B$B帶著它，去挖掘場看看能不能找到某種大型的泰坦造物。接著讀出石頭上的最後一段訊息，看看會發生什麼事！$B$B如果我沒猜錯，你將會啟動那個東西。如果真的啟動了就將它消滅，但盡量留下任何有意思的東西！我們必須掌握更多資訊！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98219,'zhTW','蒙羞的中尉','到希爾斯布萊德丘陵與南海鎮的法爾林‧奧里涅爾中尉交談。','$N，再次感謝你安全地送達雕像。$B$B我還需要你幫我個忙。有一位城市守衛被調派到希爾斯布萊德丘陵的南海鎮執勤。$B$B他的父親是我的朋友，雖然我也認為他確實需要吸取教訓…但我還是希望看到他成功。如果有像你這樣的人幫助他，他一定會受益匪淺。$B$B如果你會再次路過米奈希爾港，那裡有一艘船可以載你前往那裡。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98221,'zhTW','來自灰燼','米奈希爾城堡的斯托菲隊長要求你在怒牙營地摧毀4組攻擊計畫。','在第二次大戰期間，龍喉氏族就在我們腳下這片土地建造了一支艦隊，企圖佔領希爾斯布萊德。他們差點就成功了！$B$B他們被紅龍群擊潰，只剩殘兵敗將躲藏在山脈深處。然而，最近他們在米奈希爾東北方的營地活動激增。$B$B丹奧加茲就是他們打算再次發動戰爭並奪回這片土地的證明。找出他們的攻擊計畫，記錄任何關鍵情報，然後將其銷毀。我們必須知道他們接下來會攻擊哪裡！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98223,'zhTW','老習慣','將破爛的法術書帶去給米奈希爾港的斯托菲隊長。','這本書已被嚴重燒毀，或許是被消滅龍喉氏族大部分成員的龍火所燒。$B$B在極少數可辨認的內容中，它似乎描述了與惡魔靈魂相關的儀式，該氏族曾以此控制龍族。$B$B書的內容過於殘缺而無法發揮實際作用，但從粗糙塞入獸皮的書頁來看，納克羅什似乎曾嘗試修復它。剛乾透的墨水提及了「暗影議會」。$B$B米奈希爾港的斯托菲隊長會想知道這件事的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98230,'zhTW','這片土地曾是他們的','沿著路走，在米奈希爾港東邊尋找霍文‧輕羽。','在三錘之戰後，我們原本的矮人生活四分五裂，蠻錘氏族在此定居，並建立了山中要塞格瑞姆巴托。$B$B那曾是個美妙無比的地方。無論你看向何處，獅鷲獸都在空中翱翔，俯衝穿過濕地捉魚。$B$B可惜那並沒有持續多久。$B$B霍文‧輕羽是漫長歲月以來第一批回歸的蠻錘矮人之一。他遠離城鎮，獨自生活。沿著道路向東走，你最終會找到他的。他肯定會需要人幫忙。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98240,'zhTW','赤紅木箱快遞','將赤紅木箱帶去給米奈希爾港東邊道路不遠處的霍文‧輕羽。','$N，關於那些幼龍的消息已經正式傳開了。我們已經收到訂單了！$B$B我會幫你把它們妥善包裝好，然後你再拿去交給顧客。我知道、我知道，這真的是最後一次幫忙了，我發誓！$B$B這些是要給一位叫霍文‧輕羽的人。他竟然派了他的獅鷲獸進城，還帶著訂單信！他說他就住在東邊道路旁的不遠處，如果你熟悉那裡的話，就在維爾加挖掘場再過去一點。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98245,'zhTW','刺喉縫針','為霍文‧輕羽收集10顆刺喉龍門牙。','我不知道我更討厭哪一個：該死的黑鐵氏族、龍喉氏族，還是他們騎乘的飛龍。$B$B<霍文吐口水。>$B$B我打算讓事情重回正軌。但我們需要一些補給品。$B$B這些幼龍鱗片能在很大程度上抵禦龍火，但要把它們編織在一起簡直是折磨人的難事。$B$B東北方恐龍嶺和西北方鹽沫沼澤的刺喉迅猛龍之所以得名，就是因為牠們尖銳的利齒，它們應該能穿透這些鱗片。$B$B帶一把牠們的門牙給我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98251,'zhTW','永遠不回頭','殺死6隻黑角鹿和6隻梣谷熊，然後回到墜星湖的西北方找瓦索格‧火焰。','嘎啊啊！$B$B我太生氣了。他們說梣谷的路很容易辨識。對誰容易？野獸嗎？還是鳥類？$B$B上一刻我還在採集草藥，下一刻就被困在這個深谷。我真的要繞過半個森林，才能回到我不久前所在的地方嗎？$B$B當我陷入這種狀態時，我的法術就會變得不穩定，出現…不同的效果。$B$B你可以消滅附近的野生動物嗎？牠們踩踏的愚蠢聲音聽得我心煩。我討厭這座該死的森林。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98282,'zhTW','鍊金危機','為米奈希爾港的凱特林‧格拉斯曼從瑟根石收集一個未破裂的潛獵者腺體。','有些鍊金配方需要從，嗯，非常危險的地方取得原料。而那些通常還只是基礎草藥而已！其他的原料甚至更糟糕！$B$B在我能再次出發之前，我需要製作更多解毒劑。我發誓這片沼澤裡的所有東西都有毒。就好像毒素流淌在這片土地一樣！$B$B你能幫幫我嗎？我需要一個來自遙遠東南方瑟根石的蜘蛛毒腺。但它必須是沒有破裂的，否則在你趕回這裡之前毒液就會流光了。抱歉啦！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98283,'zhTW','大屠殺','將卡納基的頭顱帶去給綠帶草地的『綠意守望者』雷希耶爾。','這片土地的自然秩序正在崩解。曾經，刺喉迅猛龍維持著這裡的生態平衡。如今牠們卻活在對其霸主的恐懼之中，那頭野獸以牠造成的屠殺而得名。$B$B我擔心這頭野獸已經被我們尚未完全根除的某種疾病給逼瘋了。$B$B牠會對恐龍嶺下方染病的熊的惡性血肉產生反應。把牠們的內臟留在牠的巢洞中。$B$B卡納基一定會來。把牠的頭顱帶給我。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98284,'zhTW','紮營入門指南：附魔','當你的專業技能達到一定熟練度後，到申德村與娜莎蘭納‧風詠交談，學習製作符合專業技能的紮營物品。','附魔師可以強化物品，在野外的任何營地中，都是廣受歡迎的人物。$B$B我認識一個人，可以教你如何在營地中製作附魔魯特琴。在休息的時候來點娛樂也是很重要的事，這個小魔法能幫助你做好準備，等你再度踏上旅程時，就能從容面對各式各樣的挑戰。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98285,'zhTW','紮營入門指南：工程學','當你的專業技能達到一定熟練度後，到影風森林與奇異的隱士交談，學習製作符合專業技能的紮營物品。','工程師總是足智多謀，而當你獨自在荒野中時，能讓自己的手藝派上用場總是件好事。沒有幾個實用裝置的營地，不算是好營地！$B$B沒錯，等你累積了一點工程學經驗後，就回來找我，我可以教你做些特別的東西！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98286,'zhTW','紮營入門指南：附魔','當你的專業技能達到一定熟練度後，到申德村與娜莎蘭納‧風詠交談，學習製作符合專業技能的紮營物品。','附魔師可以強化物品，在野外的任何營地中，都是廣受歡迎的人物。$B$B我認識一個人，可以教你如何在營地中製作附魔魯特琴。在休息的時候來點娛樂也是很重要的事，這個小魔法能幫助你做好準備，等你再度踏上旅程時，就能從容面對各式各樣的挑戰。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98291,'zhTW','龍喉之死','為霍文‧輕羽在龍喉居所殺死8個龍喉回收者、5個龍喉縛魂者和3個龍喉滲透者。','$N，我打算回到格瑞姆巴托，為蠻錘氏族奪回它。或至少摸清一些情況。$B$B別那樣看著我，我知道風險。你知道的，我可不打算就這麼揮著錘子硬衝進去。$B$B無論如何，首先我需要你的幫忙。龍喉獸人此刻正在大舉進軍。他們遍布在龍喉居所各處，那正是先前紅龍將他們擊潰的地方。$B$B在我有任何機會靠近之前，我需要你削減他們的人數。只要沿著道路往東走，你絕對不會錯過他們的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98293,'zhTW','強制繳械','在龍喉居所收集30份龍喉武器，然後將它們帶去給米奈希爾城堡的斯托菲隊長。','龍喉氏族正在囤積各種武器。最好在更多士兵配備這些武器之前，先把它們奪走。$B$B米奈希爾城堡的斯托菲隊長肯定會對這些感興趣的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98297,'zhTW','終止循環','為霍文‧輕羽在龍喉大門殺死被制伏的龍裔。','在你出去的時候，我做了一次快速的試飛。好消息是，你幫我替貝斯畢克打造的護甲效果好得沒話說！$B$B非常壞的消息是，我看到一群龍喉獸人正在奴役一頭紅色龍裔。$B$B絕對不行。絕不能讓這種事再次發生。$B$B你必須去將牠除掉。你絕對會需要找些朋友一起去。先幹掉那些控制住牠的術士，那應該能讓牠重獲自由。然後給牠一個痛快。$B$B沒有任何人能阻擋蠻錘氏族的道路。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98298,'zhTW','阿魯高的愚行','將6個狼人碎塊帶去給瑟伯切爾的達拉爾‧織曦者。','啊，這一切都變得令人尷尬地明朗了！阿魯高根本就沒有什麼魔法，更別說有足夠的力量去創造狼人了。「阿魯高的詛咒」？我呸！那力量弱到甚至撐不過幾秒鐘。$B$B這些鐐銬證明了他可以束縛這些野獸，而非創造牠們。狼人顯然是用另一種方式傳播詛咒的。我想知道是怎麼辦到的。$B$B去南方的葛雷邁恩之牆。狼人似乎正在向附近的人類傳播詛咒。撕碎那些野獸，把你能找到的任何東西帶回來給我。這需要採取更直接的做法了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98299,'zhTW','停止擴散','為瑟伯切爾的達拉爾‧織曦者殺死5個病怏怏的難民和5個憔悴的難民。','可以肯定一件事，不論是陰謀，還是另有原因，銀松森林的狼人都是阿魯高的傑作…我們不知道的是，它是如何散播的。$B$B在我研究阻止詛咒的方法時，我們的當務之急是扼制詛咒。這個詛咒似乎不會影響被遺忘者，但有一大群人類已經聚集在葛雷邁恩之牆。$B$B前往那裡，消滅那些難民，別讓他們有機會成為阿魯高的奴僕。然後盡量不要被咬到了，$R。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98300,'zhTW','給鐵爐堡的訊息','將霍文的信函遞送給鐵爐堡的麥格尼‧銅鬚國王。','我在這裡的工作還沒結束，$N。我需要傳個音信到鷹巢山給我的妻子克萊拉，同時向弗斯塔德報告最新情況。$B$B但那是我自己的事。跟蠻錘有關的那種。$B$B話雖如此，你應該讓鐵爐堡的麥格尼‧銅鬚國王也知道這一切。濕地與他的領地相距不遠，發生在他家門口的這些事都不算是什麼好事。這封信應該能讓他了解情況。$B$B你可以經由丹奧加茲返回，或從米奈希爾港飛到鐵爐堡。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98310,'zhTW','照亮我們的未來','在阿度斯、莫德爾、高爾姆和奈爾魯附近使用戈奧茲石，並將它們的核心帶回去給勘察員維爾加。','在濕地各處還有其他更龐大的魔像。它們身上各自刻著銘文，標示為阿度斯、莫德爾、高爾姆和奈爾魯，正好對應你找到的戈奧茲石缺失的碎片！$B$B我敢打賭，如果我們也能帶回它們身上的碎片，就能揭開更多關於戈奧茲石的秘密！$B$B你可以在東邊靠近格瑞姆巴托的龍喉大門找到阿度斯。莫德爾就在北方丹莫德的外面。高爾姆位於格瑞姆巴托下方、丹奧加茲的東邊。奈爾魯則在東北方的厄爐嶺後方。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (98313,'zhTW','深入研究','將維爾加文物包裹帶去給鐵爐堡的歷史學家卡尼克。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98319,'zhTW','確保山區安全','為巡山人格雷徹在灰色洞穴中尋找巡山人科尼留斯。','有食人妖問題就夠糟了，但山裡居然還塞滿了雪怪！牠們平時都呆在自己的洞穴裡，現在卻像兔子一樣大量繁殖。牠們已經佔領了這裡北邊的灰色洞穴。$B$B如果我們想要白鬚的報告，就得找到我的夥伴科尼留斯。這個木頭腦袋太衝動，就這麼一頭衝進去了。勇敢，但很蠢。$B$B進到洞穴裡看看他在哪裡。順便解決掉一些野獸。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98321,'zhTW','燧火的貨物','為卡拉諾斯的托格努斯‧燧火從灰色洞穴收集8份燧火貨物。','你好啊！很高興看到不怕弄髒手的$R。$B$B如果你在找工作，我目前的補給品恐怕有點不足。我們最可靠的礦坑被雪怪佔據，如今那裡已經遭到棄置。礦工被迫丟下一切，愴惶逃命！$B$B話說，你何不去西邊的灰色洞穴探查一下，看看你能不能找到一些我們遺失的貨物。這能為我們省下一個大麻煩。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (98322,'zhTW','確保山區安全','去卡拉諾斯西邊查看巡山人格雷徹的情況。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98323,'zhTW','確保山區安全','將巡山人格雷徹的報告送回去給卡拉諾斯的森內爾‧白鬚。','希望你在裡面解決了不少的雜種。不過科尼留斯的事還真是可惜。$B$B從你描述的情況來看，除了那個洞穴已經沒救了之外，也沒什麼好回報的。白鬚不會喜歡這個答案，但我可不敢再派任何人進去那個死亡陷阱了。$B$B$N，請隨意把這個消息帶過去吧。在山區安全之前，我可不會離開這個地方。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98326,'zhTW','霜嚎','為烈酒村的格雷塔‧甘特殺死霜嚎並收集一袋魚','你知道要在凍結的湖面上釣魚有多難嗎？我那可憐的丈夫帕克斯頓已經在湖中央待了好幾天，我們卻幾乎連一袋成果都拿不出來。$B$B好吧，我們原本是有那麼一袋成果的。直到那該死的雪怪襲擊了我，搶走了我們的收穫。我們要花好幾個禮拜才能把那些魚全部釣回來！而且前提是那個大嗓門的霜嚎沒把牠們全都嚇跑的話。$B$B幫我們個忙，去把魚搶回來，好嗎？那個流口水的怪物就躲在東南邊的灰色洞穴深處。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98340,'zhTW','巨豹之靈','與月光林地永夜港的德迪利特‧星焰交談。','看來你已經準備好踏上下一段旅程了，年輕的德魯伊。德迪利特‧星焰要找你，你可以再回到月光林地找他。$B$B你已經學會前往月光林地的魔法了，隨時都可以動身。如果你想繼續德魯伊的訓練，我建議你盡快出發。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98341,'zhTW','偉大的風裔獵豹之靈','到月光林地的南部找賽利南的化身，向它學習關於風裔獵豹的知識。','來自你家鄉的靈魂最近現身此地，請我引導你去見它。這個風裔獵豹之靈前來教導和指點你，讓你能夠變身為微風島豹靈的獵豹形態。$B$B所有德魯伊最終需要習得這項技能，雖然你家鄉的形態與我們的傳統形態似乎稍有不同。如果你想要變身為這個豹靈的獵豹形態，就需要接受我們的試煉。$B$B地點位在月光林地的南部，雙橋以南。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98342,'zhTW','巨豹之靈','從怒風獸穴取回尖牙聖物、利爪聖物和寂靜暗影聖物，然後交給巨豹之靈。','想要借用我的靈魂之力，不是說幾句誓言就可以了。為了理解和尊重我的形態，你必須證明自己能夠展現狡詐、隱密，並在被包圍時，顯露凶性。$B$B這裡的東邊有個獸穴，你必須取得裡面經過我祝福的三個聖物。強大的暴怒靈魂守護著聖物，一看到你就會發動攻擊。入口的雕像能讓你暫時隱匿身形，不被靈魂發現。$B$B將那些聖物交給我。我們就會知道你是不是準備好化身為我的形態了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98362,'zhTW','前往雷霆崖','回到雷霆崖，與長者高地的圖拉克‧符文圖騰談話。','又到我們分道揚鑣的時候了，年輕人，你接下來的訓練得回去一趟。你的導師圖拉克‧符文圖騰似乎覺得你大有前途。我也這麼覺得。聆聽他的教誨，你就能汲取巨豹之靈的力量，並化身為獵豹。$B$B回去吧。時機到了，我們會再見面的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (98372,'zhTW','不幸的結局',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98386,'zhTW','奧瑟爾伐木場','到赤脊山，幫工頭奧斯洛在奧瑟爾伐木場殺死12隻巨型狼蛛，以及摧毀6個狼蛛卵。','獸人、豺狼人，還有魚人。似乎一切萬物在阻止我及時蓋好這座橋。現在我們還聽說伐木場那邊有大量的狼蛛！$B$B你想多賺點錢的話，可以到東邊的奧瑟爾伐木場除掉那些蜘蛛嗎？如果不能派工人取貨，我還要那個地方幹嘛？$B$B噢，你有看到老奧瑟爾的話，告訴他是我幫他解決這場麻煩的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98387,'zhTW','黑石封鎖','帶回8把遭竊的武器和10份黑石補給品給湖畔鎮的治安官馬瑞斯。','沒武器就打不了仗。$B$B儘管黑石獸人在這片土地上肆虐，他們猖狂的行徑倒也不是沒有可趁之機。$B$B前往東南方石望要塞的底部，尋找他們的營地並瞄準他們的武器和補給品。$B$B我們就來看看少了軍用物資後，他們還能構成多少威脅。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98389,'zhTW','闇境明燈','為喪鐘鎮的阿拉米斯‧錘手到夜行谷地釋放6個被網住的受害者。','你好，$C。沒錯，我是一個聖騎士。就連死亡也無法阻撓聖光。$B$B我們和被遺忘者一樣，克服了死亡帶來的困境。不過，就連某些同胞也會畏懼我們。他們認為我們會把他們當成怪物一樣消滅掉。$B$B說實話，我們與不死族的關係很複雜，但我來這裡不是為了殘害同胞的。深入西北方的夜行谷地，然後釋放剛不小心被蛛網困住的蠢蛋吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98391,'zhTW','伊露恩姐妹會','到達納蘇斯和艾奎恩妮修女談話。','祝福你，$C。數千年來，我們伊露恩姐妹會一直是卡多雷社會的一大支柱。$B$B在大崩裂之前，在先祖之戰前，透過漫長守望，我們帶領族人渡過黑暗，恢復元氣。這是我們的職責，也是我們無與倫比的月亮之母的旨意。$B$B如今，我們有件極為重要的事需要你幫忙。艾奎恩妮修女正在達納蘇斯等你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98392,'zhTW','林地的黑暗','幫哨兵阿瑞尼亞·碎雲到神諭林地收集憎嘯的護符、風之女蓋朵絲的護符和巫母艾莉莎的護符。','這些腰帶…仔細看那些皮革，$N。你有看到那些纖維裡流淌的汙穢能量嗎？$B$B我對它們的來源有所懷疑，但需要更多證據才能確定。$B$B回到西邊的鷹身人巢穴，然後除掉他們的領袖。如果他們的項鍊也蘊含和腰帶相同的黑暗能量，答案就呼之欲出了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98393,'zhTW','巨豹之靈','與月光林地永夜港的德迪利特‧星焰交談。','看來你已經準備好踏上下一段旅程了，年輕的德魯伊。德迪利特‧星焰要找你，你可以再回到月光林地找他。$B$B你已經學會前往月光林地的魔法了，隨時都可以動身。如果你想繼續德魯伊的訓練，我建議你盡快出發。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98394,'zhTW','巨豹之靈','到月光林地的南部找巨豹之靈，向它學習關於獵豹的知識。','月光林地的南方，在一座俯瞰橋梁的山丘上住著一個名叫巨豹之靈的狡詐神靈。$B$B和巨熊之靈一樣，祂會教導德魯伊化身成獵豹的形體。所有德魯伊都必將尋求祂的智慧，如果你想化身成獵豹，也應該要去找祂。$B$B去找巨豹之靈，看你能不能從祂身上學到些什麼吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98396,'zhTW','巨豹之靈','從怒風獸穴取回尖牙聖物、利爪聖物和寂靜暗影聖物，然後交給巨豹之靈。','想要借用我的靈魂之力，不是說幾句誓言就可以了。為了理解和尊重我的形態，你必須證明自己能夠展現狡詐、隱密，並在被包圍時，顯露凶性。$B$B這裡的東邊有個獸穴，你必須取得裡面經過我祝福的三個聖物。強大的暴怒靈魂守護著聖物，一看到你就會發動攻擊。入口的雕像能讓你暫時隱匿身形，不被靈魂發現。$B$B將那些聖物交給我。我們就會知道你是不是準備好化身為我的形態了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98397,'zhTW','前往達納蘇斯','回到達納蘇斯，與塞納里奧區的瑪斯雷‧馭熊者談話。','又到我們分道揚鑣的時候了，年輕人，你接下來的訓練得回去一趟。你的導師瑪斯雷‧馭熊者似乎覺得你大有前途。我也這麼覺得。聆聽他的教誨，你就能汲取巨豹之靈的力量，並化身為獵豹。$B$B回去吧。時機到了，我們會再見面的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98398,'zhTW','神諭之樹','尋找附近的神諭樹皮，來接收上頭的訊息。','我對你在如此短的時間內完成任務感到非常驚訝，$N。或許我該請求你留下來幫助我…但是我知道接下來還有更艱鉅的任務在等著你。$B$B我注意到神諭之樹已經脫落了一層樹皮，看來又有任務需要你去完成了，你得去和它談談。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98403,'zhTW','扭曲的仇恨','殺死8個被污染的網木，然後把邪惡的希索爾的成熟魔苔交給多蘭納爾的塔隆凱·捷根。','邁雷納斯領主並非單獨行動，而是奉命行事。你要找的那個傢伙叫邪惡的希索爾。他似乎扭曲了曾把泰達希爾當作家園的蜘蛛，想藉著牠們毒液執行邪惡的計畫。$B$B他就在森林的最深處，一個位此西北方叫裂谷的地方。小心行事，別忘了召集盟友，因為希索爾可不好對付。$B$B消滅他的爪牙，然後帶回任何能說明薩特在此有何計畫的物證。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98404,'zhTW','偉大的風裔獵豹之靈','從怒風獸穴取回尖牙聖物、利爪聖物和寂靜暗影聖物，然後交給賽利南的化身。','想要借用我的靈魂之力，你必須接受一場試煉。為了理解和尊重我的形態，你必須證明自己能夠展現狡詐、隱密，並在被包圍時，顯露凶性。$B$B這裡的東邊有個獸穴，你必須取得裡面的三個聖物。強大的暴怒靈魂守護著聖物，一看到你就會發動攻擊。入口的雕像能讓你暫時隱匿身形，不被靈魂發現。$B$B將那些聖物交給我，通過這片土地的德魯伊試煉。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98405,'zhTW','巨豹之靈','到月光林地的南部找巨豹之靈，向它學習關於獵豹的知識。','月光林地的南方，在一座俯瞰橋梁的山丘上住著一個名叫巨豹之靈的狡詐神靈。$B$B和巨熊之靈一樣，祂會教導德魯伊化身成獵豹的形體。所有德魯伊都必將尋求祂的智慧，如果你想化身成獵豹，也應該要去找祂。$B$B去找巨豹之靈，看你能不能從祂身上學到些什麼吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98423,'zhTW','諒解條約','把諒解條約交給鐵爐堡的麥格尼‧銅鬚。','你在寶庫中找到了一塊詳細紀載了銅鬚和蠻錘矮人之間的和平條約。這項條約似乎能追溯到三錘之戰後的那個時期，而且對矮人來說是很重要的史料。鐵爐堡國王肯定會對這件文物感興趣。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98427,'zhTW','終止行動','將伐木機器人鑰匙帶去給血蹄村外的摩林‧雲巡者。','其中一張筆記提到的伐木機…我曾在旅途中見過。它們只需要花費人工砍伐的一小部分時間，就能摧毀整片森林。$B$B整片林地…那些孕育大地之母子民數千年的家園，短短幾天內就被夷為平地。$B$B我們絕不允許這種事發生在自己的家園，尤其這裡離我們孩子蹣跚學步的地方只有咫尺之遙。$B$B$N，我必須請你召集其他人手，回到東北方的礦坑，確保那台伐木機再也無法砍倒任何一棵樹。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98430,'zhTW','遠行者','幫助佩利斯‧風暴之蹄逃離白鬃石，並向雷霆崖的凱恩‧血蹄回報他平安脫險的消息。','你好，$C。是什麼讓你深入這片如此陰暗又危險的地方？$B$B我奉大酋長凱恩‧血蹄之命來到這裡，試圖與定居於此的豺狼人交涉。至於任務的其他細節，我必須保密。畢竟我們遠行者是酋長最信賴的斥候，一向對任務守口如瓶。$B$B你只需要知道，我們的善意交涉卻換來了暴力相向。如果你不幫我逃離這裡，恐怕今晚我就要成為豺狼人的盤中飧了。$B$B你願意幫我這個忙嗎？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (98435,'zhTW','雷角的報告',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98459,'zhTW','缺德','將湯姆的禮物送去濕地給米奈希爾港的巴特‧泰德沃特。','我告訴你，巴特‧泰德沃特就是個徹頭徹尾的小氣鬼！$B$B他還自稱什麼「處女號的船長」。那艘船航行過的距離跟塔納利斯的一顆石頭沒兩樣！他才不是什麼船長，他就是個在撲克牌桌上贏了幾把，才買下處女號的演員罷了！$B$B如果你有去濕地的米奈希爾港，把這個交給他，讓他知道這是老半魚送的。$B$B順帶一提，這裡有艘船可以直接把你載到港口。記得在第二站下船！$B$B還有，他打撲克牌會耍老千！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98461,'zhTW','無法回報之愛','將霍莉的便箋送去濕地給米奈希爾港附近的塔雷爾‧石紋。','如果你要離開奧伯丁，我需要你幫個忙！$B$B我和我親愛的朋友塔雷爾以前是同學。噢，他對挖掘相關的事物總是這麼迅速！我們畢業後就各奔東西了，他去了濕地，而我則來到這裡的黑海岸。$B$B<霍莉嘆了口氣，隨後眉頭微微皺起。>$B$B抱歉，還有他的妻子…麥琳。$B$B這不重要。如果你去了濕地，能幫我確認他是否平安嗎？順便把這個交給他？他大概在米奈希爾港附近。這裡有直達那裡的船。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98463,'zhTW','鎮上焦點','到荊棘谷，前往藏寶海灣的水手之家旅店拜訪尼克拉克斯·菲拉莫格。','聽著，你能來我的酒吧我很高興，但也正因如此，我才會對你說接下來的話。$B$B你想來場更熱鬧的派對嗎？那就要去藏寶海灣的水手之家旅店了。$B$B別那樣看我。我知道那個地方是哥布林在經營的。不管是酒保還是客人，任何人說的話都是情報。我只能說，如果你想看到更熱鬧的場面，就去那邊看看吧。$B$B尼克拉克斯·菲拉莫格會好好照顧你的，不用擔心。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98545,'zhTW','萊尼德的信件','把密封信件交給幽暗城的吉力克斯‧希吉克斯。','既然你來了，我想請你把這封信交給我幽暗城的朋友。我原想親自把信交給他，但我和黑暗女王有一段恩怨，請中立的第三方送信還是比較好。$B$B你要找的是個名叫吉力克斯‧希吉克斯的哥布林，他就在幽暗城的貿易區裡。我相信他會好好報答你的。$B$B<萊尼德一邊把信交給你，一邊竊笑。>',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98574,'zhTW','神聖備忘錄','閱讀神聖備忘錄，然後與安威瑪的布蘭斯托克‧卡德爾談話。','你剛才在外面忙碌的時候，有人讓我把這個備忘錄交給你。如果你有時間的話就看一下吧，好像是牧師訓練師布蘭斯托寫給你的，他就在安威瑪裡面。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98575,'zhTW','污化的石板','閱讀污化的石板，然後到試煉谷的大獸穴裡去和納托克談話。','啊，剛剛你不在的時候，有人送來了這塊石板，$N。$B$B一般來說我是不會去招惹術士的，但是如果你有時間的話，還是看看這上面說些什麼的好。如果我沒搞錯的話，這張羊皮紙是術士訓練師納托克寫的，他有事找你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98576,'zhTW','雕紋羊皮紙','閱讀雕紋羊皮紙，然後和試煉谷裡大獸穴入口附近的邁安談話。','啊，剛剛你不在的時候，有人送來了這張羊皮紙，$N。$B$B如果你有時間的話，還是看看這上面說些什麼的好。如果我沒搞錯的話，這張羊皮紙是法師訓練師邁安寫的，她有事找你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98581,'zhTW','古式符文','閱讀古式符文，然後與安威瑪的提歐‧錘暴交談。','你剛才在外面忙碌的時候，有人讓我把這個符文交給你。如果你有時間的話就看一下吧。這些銘文帶著明顯的蠻錘風格，我猜這應該來自薩滿訓練師提歐‧錘暴。看完之後，有空的話，就去安威瑪裡面找他。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98731,'zhTW','巨豹之靈的祝福','到月光林地的西北部去尋找巨熊之靈，向它學習關於熊的知識，然後回到月光林地的永夜港去找德迪利特·星焰。','既然你已經得到我的祝福，就回去找德迪利特。他會給你後續的指導。我很希望我們有一天會再見面。$B$B願暗影永遠隱藏你的身形，願你的利爪輕易撕碎敵人，年輕人。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98738,'zhTW','偉大的風裔獵豹之靈的祝福','到月光林地的西北部去尋找巨熊之靈，向它學習關於熊的知識，然後回到月光林地的永夜港去找德迪利特·星焰。','既然你已經得到我的祝福，就回去找德迪利特。他會給你後續的指導。$B$B很可惜，我目前沒東西能教給你了。我很希望有一天你會來微風島拜訪我。我覺得你很有潛力，年輕的申多雷。$B$B願暗影永遠隱藏你的身形，願你的利爪輕易撕碎敵人，願風帶領你邁開步伐。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98739,'zhTW','巨豹之靈的祝福','與德迪利特交談。','既然你已經得到我的祝福，就回去找德迪利特。他會給你後續的指導。我很希望我們有一天會再見面。$B$B願暗影永遠隱藏你的身形，願你的利爪輕易撕碎敵人，年輕人。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98815,'zhTW','高地龍皮','將4張灌木迅猛龍皮帶回去給米奈希爾港的皮匠詹姆士‧哈洛倫。','這片高地散落著某種遺跡，一支探險隊目前正在探索其中的秘密。據我所知，在那片山地沼澤中，潛伏著當地特有的野生動物與猛獸。你要不要帶上幾個裝備齊全的朋友去那裡闖一闖，然後我們來做個交易？$B$B我不在乎牠們是不是躲起來了，我只要牠們的皮！幫我帶四隻灌木迅猛龍的皮來，我會為你準備好值得的交易報酬。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98824,'zhTW','史前稜石','將泰坦聖物帶去鐵爐堡的探險者大廳給資深探險家麥格拉斯。','它的切面上鐫刻著如泰坦般的銘文，除了鐵爐堡的探險者大廳之外，沒有更適合它去的地方了。$B$B我倒是希望，你會因為它而被載入史冊中：「由$N尋回！由勘察員維爾加進行鑑定…」啊，我有點得意忘形了。$B$B資深探險家麥格拉斯會負責接待你，鑑於你所持之物的精妙性質，如果你把它捐給博物館，他一定會表達出最慷慨的謝意。$B$B真是不錯的發現！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98887,'zhTW','暗矛島嶼衝突','把3枚暗矛島嶼榮譽獎章交給戰場外的部落戰爭使者。','塞拉摩遠征軍非常頑強，不斷派遣增援部隊來鞏固他們在暗矛島嶼的陣地。$B$B去吧，向他們展現部落的偉力！把你在這片關鍵戰場上的勝利證明帶給我，你就能獲得豐厚的報酬。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (98888,'zhTW','暗矛島嶼衝突',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98895,'zhTW','暗矛島嶼交鋒','把3枚暗矛島嶼榮譽獎章交給戰場外的聯盟准將。','與暗矛劫掠者的戰況正在持續升溫。要是沒有人及時伸出援手，我們將會失去暗矛島嶼的所有權。$B$B作為自豪的聯盟成員，你的使命就是確保這種事不會發生。把你在前線的貢獻證明拿來給我，如此一來你就會被視為聯盟的英雄受人敬重！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`VerifiedBuild`) VALUES (98896,'zhTW','暗矛島嶼交鋒',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (98906,'zhTW','暗矛島嶼之戰！','贏得一場暗矛島嶼戰場，然後回去商旅海岸找尼祖克‧布夫。','$C，暗矛島嶼之戰陷入了僵局。讓那些聯盟的蠢貨看看誰更強。$B$B昂首挺胸為暗矛部族效力，在戰鬥中奪取勝利吧。$C，羅亞絕對會賜予你祝福的！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99046,'zhTW','下落不明的信使','在通往神諭林地的路上尋找哨兵伊拉亞‧葉影。','森林議會不久前派了一小隊哨兵前往神諭之樹。神諭之樹會傳遞訊息給我們的長者，而安全將這些訊息送達達納蘇斯則是我們的職責。$B$B我收到消息，我們最近的一位信使至今尚未抵達。神諭之樹傳達訊息的頻率雖有變化，但這次的時間久得很不尋常。$B$B請沿著西邊的路前往神諭林地尋找她。這次的信使輪到伊拉亞‧葉影擔任，但她仍在訓練中。願伊露恩指引你。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99047,'zhTW','尚未死去','為哨兵伊拉亞‧葉影前往多蘭納爾向拜恩希尋求援助。','我和我的姐妹…被派往…神諭之樹…$B$B樹…訊息。我…到處都是…鷹身人…$B$B<伊拉亞咳出鮮血，面容因痛苦而扭曲。>$B$B我的時間可能不多了…沒有人來。拜託你…去多蘭納爾…找拜恩希…',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99048,'zhTW','遺失之手','在提拉加德城堡北方尋找黑格蘭‧影眼。','破碎之手氏族的一名成員先前一直在遠處監視著提拉加德城堡，他們是一群手段更為…隱密的戰士。然而，她突然間不再送來報告了。$B$B我懷疑那些人類根本沒有能力抓住她，所以我擔心背後有更危險的威脅在作怪。去看看你能不能找到她。希望那些訊息只是延誤了而已。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99049,'zhTW','地底威脅','尋找是什麼攻擊了黑格蘭‧影眼的線索。','周遭區域一片狼藉，留有明顯的打鬥痕跡。無論伏擊黑格蘭的是什麼怪物，都未能毫髮無傷地離開。附近可能有事發經過的線索。$B$B奧戈尼爾大概會想看看攻擊者留下的任何證據。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99050,'zhTW','巨樹恩惠','為多蘭納爾的拜恩希收集6片帶露水的鞭笞者複葉、一個空瓶和一份清涼的泉水。','我需要你幫忙採集所需的材料，來緩和這種折磨，讓伊拉亞有足夠的時間回到這裡接受進一步治療。$B$B值得慶幸的是，我們棲身的家園依然豐饒，可以在我們危難之際伸出援手。$B$B核心材料是帶露水的鞭笞者複葉。你可以在正南方的奧拉密斯湖周圍，或是在湧泉湖及其西北方的河流沿岸找到它們。$B$B此外，我還需要一個空瓶和一些泉水。這兩樣東西都可以在鎮上買到，或是透過交易取得。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99051,'zhTW','地底威脅','收集9片納迦刺鰭。','這不是那些海蛇第一次來騷擾我們了。必須給他們點教訓，讓他們明白這裡絕不容許他們撒野。$B$B找出他們的斥候在哪裡紮營，然後把他們屠殺殆盡。帶回他們的鰭作為證明。我們得盡快行動，確保他們徹底學到教訓。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99052,'zhTW','地底威脅','殺死杜洛塔北海岸的海巨人，並帶回你成功的證明。','我的斥候來報，有一個海巨人跟著那些納迦來到了這裡。雖然不確定對方是不是刻意為之，但無論如何他都是個危險的威脅。$B$B他雖然年輕，不過還是能在一瞬間把毫無防備的獸人撕成兩半。我需要你痛下殺手，但建議你最好找幫手來一起對付他。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99053,'zhTW','逃離班奈希爾','幫助哨兵莉妮莎‧暮花逃離班奈希爾獸穴，並向多蘭納爾的哨兵凱拉‧星歌回報她安全的消息。','我的祈禱靈驗了！我很高興你一路奮戰來到這裡。$B$B我是受神諭之樹所派，前來向在此地沉睡的德魯伊傳達訊息，沒想到這裡已經完全被熊怪佔領了！我還來不及撤退，他們就突然出手把我抓到這底下。我真怕自己會變成他們的下一頓大餐。$B$B我不知道你怎麼想，但我討厭這個地方。地底絕不是卡多雷該待的地方。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99073,'zhTW','減輕痛苦','將笞水藥膏帶去通往神諭之樹的路上給哨兵伊拉亞‧葉影。','藥膏準備好了。快點把它拿去給伊拉亞。$B$B我不確定藥膏能不能完全治好她。腐化侵蝕得很快，且隨著蔓延而變得更嚴重。$B$B就算無法根治，至少也能減輕她的痛苦。光是這一點，就值得你盡快動身了。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99079,'zhTW','遠行者瑪拉','在血蹄村東邊尋找遠行者瑪拉‧長風，就在莫高雷的邊緣。','遠行者是我們之中最受信任的斥候。雖然他們只對牛頭人酋長效忠，但年輕的貝恩有時也會尋求他們的協助。$B$B眼下正是這樣的時刻。遠行者瑪拉日前被派往我們東邊的邊境附近，在過了三天後的昨晚卻並未歸來。當這種情況發生時，確認他們的安全便是我們的職責。$B$B我必須確保村莊的安全。證明你的實力，去尋找瑪拉的下落。你可以透過遠行者標誌性的頭帶與羽毛法杖來認出她。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99080,'zhTW','趕走他們','殺死6個加拉克半人馬和4個加拉克前鋒，並將『掠取者』赫拉克的頭顱帶去給貝恩‧血蹄。','牢牢記住我的話：我們絕不向半人馬退讓半寸草木。$B$B在他們得到充分休息、抓到機會突襲我們的村莊之前，前往他們的營地。將他們屠殺殆盡。確保沒有任何一個人能逃往貧瘠之地招集援兵。$B$B如果你找到這支突擊小隊的首領，就把他的首級帶回來給我，向其他敢犯我先祖之地者傳達一個警告。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`QuestDescription`,`VerifiedBuild`) VALUES (99081,'zhTW','噩耗','從瑪拉背後中箭的方向望去，你可以看到一座似乎是新建的半人馬營地。那裡的活動跡象，表明有一支突擊小隊已經潛入了莫高雷。$B$B這位遠行者依然緊握的手中還抓著一份情報。勇者野蹄會想知道瑪拉的下場，以及殺害她的兇手。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99082,'zhTW','牛頭人酋長','晉見雷霆崖的牛頭人酋長凱恩‧血蹄。','你保衛族人的勇氣值得嘉獎。前往西北方的雷霆崖，那是我們宏偉的城市，在溫暖的月份裡，它的陰影會為我們帶來庇蔭。去那裡晉見我的父親吧。$B$B正是他與年輕的大酋長索爾一同領軍，收復了這片平原，並永遠趕走了半人馬。你展現出不遜於牛頭人酋長的勇氣，他一定會給予你豐厚的賞賜。$B$B你必須搭乘升降梯才能見到位於中央高地的牛頭人酋長。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99101,'zhTW','古老宿敵','將遠行者瑪拉的報告帶去給貝恩‧血蹄。','貝恩‧血蹄是我們村莊的領袖。必須立刻讓他知道這起入侵事件。$B$B把遠行者瑪拉的報告拿去給他。你能在城鎮中央找到他。$B$B請快一點。已經沒時間浪費了！',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99108,'zhTW','切磋較量','在決鬥中擊敗3名其他的玩家或是見習戰士，然後向塔恩‧石蹄回報。','你好，年輕的$C。雖然你不是名戰士，我也無法傳授你戰士之道，但這不代表你無法從我的教導中受益。$B$B你眼前便是競技場。在競技場中，不論你的出身為何、手持長劍還是戰錘，全都無關緊要。人人平等，也都得在正面交鋒中打磨自己的技巧。$B$B你願意踏入我們的場地，親自學習我們的方式嗎？你可以挑戰這裡任何一名見習戰士，也可以挑戰任何願意應戰的對手，我都無所謂。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99123,'zhTW','迷失在暗影中','協助帕朱逃離科卡爾峭壁，並將成功的消息告訴森金村的沃納爾大師。','我之前決定要獨自來峭壁這邊偵察一番。不幸的是，我的魔力在錯誤的時機耗盡，然後我就只能躲在這裡。$B$B如果你能幫助我逃出去，我會非常感激。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99127,'zhTW','漁網災難','檢查水晶湖的捕魚籠。','今天魚就是不咬餌，而且牠們似乎出了什麼問題。不只是魚鉤空空如也，我在水裡連一條小魚的影子都沒看見。$B$B李昨晚在這裡設了幾個捕魚籠，去看看它們是否有些收穫。如果發現任何怪東西，記得拿來給我看。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99128,'zhTW','黏滑威脅','在水晶湖擊殺7個魚人和4個魚人士兵，然後回去找傑生‧瑪瑟斯。','這只會是湖對岸那些魚人幹的好事。那些噁心的小傢伙帶著一口尖牙，脾氣也同樣凶狠。$B$B如果我們置之不理，整座湖很快就連一條魚也不剩了。如果你能去清掉一些魚人，就是幫了我一個大忙。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (99129,'zhTW','魚人諮詢','與雷米談談傑生的魚人問題。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99130,'zhTW','誘人的提議','收集6瓶動物之血和18片暮色草花瓣當作魚人誘餌，然後回去閃金鎮找雷米。','我有幾個對付魚人的點子，其中一個還能順便幫助其他人。$B$B有一種常在附近的農場發現的雜草叫暮色草，大量食用其花瓣會讓大多數的動物中毒。如果用這種植物製作魚人誘餌，或許就能讓那些生物學會離遠一點。$B$B而且這還能幫一些農夫清理田地，真是一石二鳥…或者說一石二魚。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99131,'zhTW','引魚入彀','回去找傑生‧瑪瑟斯。','告訴瑪瑟斯，他今天晚點可以來取誘餌。我會向他詳細說明正確用法。$B$B希望他的賣魚生意能盡快重返正軌，而這世界上的魚人也能變得少一點。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99143,'zhTW','瓶罐與飾物','在附近的魚人營地收集6件閃亮的垃圾。','那些魚人的思考方式肯定跟真正的魚差不多，對吧？這表示他們喜歡的東西，魚也會喜歡！$B$B如果你能翻翻牠們的垃圾，把任何看起來適合當誘餌的東西帶回來給我，我就會給你些報酬。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`VerifiedBuild`) VALUES (99144,'zhTW','尋求庇護','幫助巴瑞斯‧黎明石逃離十字軍前哨，然後向布瑞爾的夏莉‧斯迪威爾回報他已成功脫困。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99152,'zhTW','地上如此，地下亦然','為『破壞者』熙達收集6根微弱發光骨頭。','西南方暗影谷的晦暗者固然是個問題，但我們也不能任由城鎮下方的地窖滋生禍患，最終演變成天譴軍團對班達利昂要塞的全面攻勢。$B$B我得把這些學徒訓練到足以應付那種情況。至於你，則是要接受我所謂的速成課程。$B$B前往暗影谷地底，取回那些可悲傢伙的骨頭，好讓我們進一步研究。我需要仍殘留初始復生魔法的骨頭，就是會發光的那些。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99153,'zhTW','漏網之魚','在暗影谷地底找到隱藏的水晶碎片，然後向埃弗蘭‧巴巴羅回報。','嘿，就是你！消息在行伍之間傳得很快，我聽說了你對納克薩瑪斯戰場遺跡附近的邪教徒所幹的事。$B$B問題是，其中一名邪教徒帶著一塊聚焦水晶逃走了，而且那水晶看起來還帶有一些能量。我們推測它就藏在暗影谷的地下。它不是在復活死者，就是在強化死者，兩種情況都很糟。$B$B在事情失控前找到那塊水晶吧。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99156,'zhTW','巡查後方','將撕裂者的心臟交給亡靈守衛林奈。','該死的！你巡邏時又來了一份新報告。有人在提里斯法林地東部目擊到一具四處遊蕩的失控憎惡體，就在毒蛛峽谷那一帶。$B$B這有點不對勁，憎惡體不可能就這樣溜過亡靈壁壘而不被發現。$B$B此事必須嚴格保密，僅讓必要人員知悉。話說回來，這種生物可沒那麼容易倒下。如果你不想成為它的下一餐，最好找些盟友幫忙。$B$B把事情處理好，你就會得到應有的獎勵。帶回他的心臟作為證明。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99158,'zhTW','山中曙光','將蠟燭木箱交給霧松避難所的伽文神父。','山裡頭有一名隸屬於銀色黎明的牧師，這個神聖的團體致力於找出並消滅不潔與非自然之物。$B$B不過，伽文神父更偏好救助和治療他人，而不是拿起武器。他打理了一座老舊建物作為旅人的歇腳處，取名叫做霧松避難所。我有一箱聖潔蠟燭需要送給他。如果你正好要往那個方向走，可以替我送去嗎？',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99159,'zhTW','尋覓溫暖','收集14個木柴塊。','我的爐火樂意溫暖任何靈魂，不過我想請你幫個忙。$B$B我只是需要更多柴火。我通常會自己處理這檔事，但最近我實在是分身乏術。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99160,'zhTW','凝霜之怒','消滅10個小型冰元素。','你或許已經注意到附近的元素生物。幾天前，一大片岩石和冰層從山峰崩落，驚擾了這些元素。$B$B即使沒有元素現形，這些冰封的山脈對一般矮人或人類而言也已經十分危險。我已經不再適合戰鬥了，但無論你能消滅多少元素，都有助於讓這條路變得更安全。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99161,'zhTW','凝霜之怒','殺死阿瓦拉並取回其核心。','我注意到，山崩後最先出現的元素生物體型比其他同類還要龐大。我想，它應該就是近期偶發的天氣異常與小型山崩元凶。$B$B我一直稱呼它為「阿瓦拉」，如果你能殺死它，並取回其核心作為證明，我會給你獎勵。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99162,'zhTW','險惡嚴寒','收集罹難巡山人的步槍。','即使是鐵爐堡的巡山人，在穿越丹莫洛群山時也必須保持警覺。崩落的冰雪往往會奪走較資淺成員的性命。$B$B雪崩過後，我通常會搜尋生還者或罹難者的蹤跡，同時向聖光祈禱，希望什麼也找不到。然而最近元素活動異常，我不敢走得太遠。假如你有找到失蹤的巡山人員並帶回他們的步槍，我會把步槍送回鐵爐堡。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
