INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99260,'zhTW','菲里恩的任務','和瓦拉納爾的伊拉德林‧和風交談。','我接到任務，要從瞰臺矗立之石那裡蒐集元素能量流動的重要資料。這份資料對我們的計畫相當關鍵，能讓我們安全往返天空之牆與艾澤拉斯。如果沒有這份資料幫助計算，我們駕駛割天者號穿越元素界域的目標就會失敗。$B$B資料現在很有可能遺失了，但以我目前的狀態也不允許再去蒐集一次。我和頂尖博學者說你救了我一命，他希望能和你再聊聊。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`,`VerifiedBuild`) VALUES (99411,'zhTW','凱爾失蹤了！','莫高雷血蹄村的亞哈伯‧麥蹄希望你幫忙餵餵他寶貝的狗狗，狂亂的凱爾。$B$B餵凱爾吃嫩陸行鳥肉，然後回去找亞哈伯‧麥蹄。','幫幫我，$N！我最寶貝的寵物，凱爾跑丟了！我只知道牠平常會在血蹄村附近亂跑，牠現在一定是迷了路又餓著肚子。$B$B你願意幫我找到牠並且餵牠嗎？只要牠吃飽了，牠就會安靜下來並且回家來。$B$B你需要去找食物來餵牠。牠最喜歡的就是嫩陸行鳥肉了，在東邊有不少陸行鳥。你只需要獵殺一隻陸行鳥，並且拿牠那多汁的肉給凱爾。你要是看見凱爾在村子裡，把肉放在地上，牠一定會過來找你的。',0) ON DUPLICATE KEY UPDATE `LogTitle`=VALUES(`LogTitle`),`LogDescription`=VALUES(`LogDescription`),`QuestDescription`=VALUES(`QuestDescription`);
