INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (92834,'zhTW','我通常不同意塑風者的意見，但他們拒絕和奧拉凱斯和平交涉的判斷正確無誤。我試著採取道德手段，卻害了一位摯友因而喪命，我將一生背負著這個錯誤，直到死去為止。',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (92840,'zhTW','對我來說，塑風者和奧拉凱斯之間其實沒什麼差異，除了其中一邊明顯更暴力以外。兩者都對自身錯誤的信仰如奴隸般服從，如果放置不管，兩者都是非常危險的存在。$B$B我們渴望深入了解這個國度，以及當中所蘊含的魔法，但這些舉動卻被認為褻瀆了他們的傳統。他們狹隘的思想恰恰說明為何我們的任務如此重要。如果沒有我們，還有誰會鼓起勇氣拯救微風島？',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
