INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (93319,'zhTW','這些鬼鬼祟祟的賊偷我們的補給物資已經有好幾個月了。我試著說服安妲組織部隊掃蕩強盜藏身的洞穴，一勞永逸，但她不想把僅剩不多的保安官調離村子。$B$B考量到南邊法拉斯村的邪教徒勢力逐漸壯大，我看這也不能怪她。',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
