INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (97003,'zhTW','我們集結了六名身經百戰的戰士，才終於擊敗其中一隻怪物，但在我們殺死牠之前，牠就已經奪走了四名戰士的性命。$B$B如果這些可怕的野獸大量出現，野豬人恐怕會對這片土地造成災難性的破壞。',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (97223,'zhTW','血爪向來以狡詐和迅速聞名，如果從蛋開始養育到成年，牠們會是非常可靠的夥伴。$B$B不幸的是，成年迅猛龍不太好訓練，我也多次試著要捕獲族母。但她近來變得太過危險了。$B$B儘管如此，我還是希望能保全她的血脈，在森金這裡繼續培育她的後代，當作同伴。',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
