INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (97485,'zhTW','有很多事情值得將薰香灑入風中。像是請大地之母照拂其他人、為狩獵祈禱、慶祝特別的一刻，或是尋求先祖的指引都可以。$B$B也有可能是為了截然不同的事情。$B$B雖然我們會虔誠之心待之，不過也不是非做不可的儀式。一般來說，揮灑薰香有一些傳統要遵守，但每個氏族都有不同的做法。',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (97538,'zhTW','你回來了！你在暗色湖有找到昏暗草豆莢嗎？$B$B我們牛頭人世世代代都用這種植物做成的顏料，不管你帶回多少都很好。雖然有很多方法可以製作紅色顏料，但我覺得昏暗草調出來的紅色最為鮮豔厚實。',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
