INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (98190,'zhTW','$C，我們來聊聊吧。我能感覺到你攜帶著某種聖光之物。',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (98191,'zhTW','$C，願聖光與你同在。顯然你不是來這裡閒聊的，怎麼了？',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (98197,'zhTW','在浪潮之下要保持警覺。底下有很多可怕的怪物！',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (98282,'zhTW','運氣如何？我知道這麼問很討人厭，但我真的很需要完整的腺體！',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (98298,'zhTW','獠牙、利爪、砂囊，對我來說都沒差別。要研究一種生物，最簡單的方法就是親眼看看牠的內臟。',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (98387,'zhTW','你找到的大多數物品也都是從湖畔鎮搶過去的。想到我的同胞能蓬勃發展，獸人的勢力逐漸衰弱就讓我感到欣慰。',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (98392,'zhTW','你有從鷹身人的領袖身上搶回護符嗎？',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (98403,'zhTW','<塔隆凱壓低了聲音。>$B$B希索爾還在外頭遊蕩嗎？',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (98407,'zhTW','如果不與最凶狠的豺狼人交手，就無法對他們做全面的評估。把那些鞭笞者解決掉！',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (98423,'zhTW','$C，你有從深淵帶什麼東西給我嗎？',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (98545,'zhTW','那是什麼？你說萊尼德派你來的？天啊，自從納克薩瑪斯從天上ˋ展開攻擊後，我就沒看過那個老傢伙了。',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (98815,'zhTW','$C，歡迎回來。你的裝備需要上點皮革油嗎？',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (98823,'zhTW','來吧。有尋必有得。',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (98824,'zhTW','參觀一下我們的藝廊，不過請不要觸碰任何文物，除非是你要拿來這裡捐給圖書館的那一個。',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (99049,'zhTW','你找到她了嗎？',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (99050,'zhTW','你拿到材料了嗎？我擔心伊拉亞撐不了多久。',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (99051,'zhTW','希望那些海蛇敗類沒有對你造成麻煩？',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (99052,'zhTW','讓他們嘗嘗鮮血與雷霆！',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (99073,'zhTW','<伊拉亞已經無法開口回應。只有微弱吐出的喉音，證明她還活著。>',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (99127,'zhTW','有什麼收穫嗎？',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (99152,'zhTW','你最好別空手而歸。要嘛帶回我要的骨頭，要嘛讓人用擔架把你抬回來，好證明你至少為了取得它們拚盡了全力。',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES (99153,'zhTW','找到那個該死的東西了嗎？',0) ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (65610,'zhCN','你手上是什么，$N？用……月布做的头巾？你可别是想来追求我。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (79008,'zhCN','你意外发现了另一具焦灼的遗骸，一张钉在木板上的字条吸引了你的目光。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (79192,'zhCN','肯定有出身穷苦的冒险者和佣兵在这里安营扎寨。你注意到微风翻开了某张纸条的一角，便伸出手去。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (79974,'zhCN','矮人工程学，永远的奇迹。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (79975,'zhCN','眼前的营火刚添过木柴，匆匆离去的痕迹一目了然。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (79976,'zhCN','一张厚重的帆布摊放在配套的设备之上。你随意地翻开了背包。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (79980,'zhCN','你从地里拖出了一个信使行囊，里面塞满了补给品和一张脏兮兮的羊皮纸。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (91723,'zhCN','干得好，朋友。让我再试着校准一次……',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (91724,'zhCN','看来一切都已恢复正常。谢谢你，$N。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (91725,'zhCN','啊，这下我就放心了！看起来一样都没少。谢谢你！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (91732,'zhCN','哦，真不错。看见那光泽了吗？现在可造不出这样的好东西了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (91743,'zhCN','真是太感谢你了！来，这本指导手册送给你了，反正我也用不上。$B$B但还是有好多书下落不明。而且狗头人似乎并没有把它们吃掉。那它们偷书到底是想干嘛？',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (91745,'zhCN','拿着书的狗头人？对，我是见过它们抱着书跑来跑去，嘴里还互相大喊大叫的。那些书绝对是从修道院里的图书馆偷出来的。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (91752,'zhCN','多谢你找回这些失窃的书，$N。我这就把它们还给帕克斯顿修士。$B$B你都快成咱们这儿的大英雄了。干得漂亮！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (91758,'zhCN','我能帮你追踪这只害兽。稍等，我给你做点好用的东西。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (91772,'zhCN','这是什么，$N？你在追踪狗头人？$B$B那还用说，它们肯定是冲着法戈第矿洞去的！那地方早就狗头人泛滥了。$B$B干得不错。我正愁没人去帮我解决那个大麻烦呢。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (91858,'zhCN','丹妮莎派你来的？那我已经知道你的来意了。你可是一脚踏进了个天大的烂摊子，$C。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (91859,'zhCN','我虽然不喜欢你们这些$C，但不得不承认，你来得正是时候。看来运气好有时比本事强，是吧？',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (91860,'zhCN','<眼前的尸体无疑属于一名牛头人。它在被扔上火堆前，显然遭到了严重啃噬。不过，你没有发现此前提到的那名精灵女子。或许她还活着，就藏在附近堡垒的更深处？$B$B此行必定十分危险，但想查明真相，只有这一个办法。>',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (91861,'zhCN','你是被遗忘者，对吧？能帮忙放我出去吗？$B$B恐怕我时间不多了。快点！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (91862,'zhCN','多谢，$C。可惜咱们还没彻底脱险。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (91899,'zhCN','辛苦了，$N。最近打劫商路的暴徒和窃贼越来越猖獗。如果你在附近还发现了其他箱子，请带到这里来，剩下的交给我们。$B$B这是你的报酬。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92124,'zhCN','对，我听见了。我都提醒帕克斯顿修士三次了，说狗头人正在修道院下头挖地道呢。$B$B看来狗头人偷走了不少书，连书架都被搬空了好几个。你最好去问问帕克斯顿修士接下来该怎么办。$B$B既然你都来了，咱们能聊聊专业技能吗？不管你有什么问题，我都乐意解答，还能给你指点一下镇上的训练师在哪儿。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92479,'zhCN','先安顿好自己，熟悉一下周围的环境。以后需要训练，随时回来找俺，白天黑夜俺都在。$B$B这片土地正变得越来越危险。等你遇见其他人，就会发现他们各有难处，需要有人搭把手——而这些事，正适合身手不凡的$C。祝你好运。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94472,'zhCN','拿着它，并且记住：这是神圣之物。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94473,'zhCN','愿火焰在你的心中燃烧，$N。$B$B火焰元素在等着你。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95034,'zhCN','那么现在你明白了。在被十几把豺狼人的刀刃刺穿、濒临力竭之际，他竟然还撑起身子想要攻击我。在最后一刻我们四目相对，我能看出他仍然知道自己是谁，也认出了我。他清楚正在发生什么，却完全无法控制自己。那才是最可悲的部分。$B$B若真有可能，我要亲眼看着那只葬送了他的怪物死去，让它再也无法将这种恐怖加诸于其他生灵。我以头顶的苍天起誓。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95998,'zhCN','既然我们已经掌握了基础知识，你何不去学一门专业技能呢。他们也会教你一些窍门，让你能制作出适合你新专业的营地设施。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96130,'zhCN','剥夺如此美丽生灵的性命着实令人扼腕，但为了族人的安危，这又是迫不得已之举。我会确保这张毛皮物尽其用。多谢。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96204,'zhCN','再次向你道谢$N。我方才与这里的特雷凡熟络了一番，才得知正是他派你来寻我的。$B$B在我的旅途中，听闻过不少关于$C……不那么客气的评价。作为一名穿行于部落领地、受天空眷顾的申多雷精灵，我深知偏见与偏执是何等容易滋生。$B$B你和你的同胞，如今在塑风者中已经结交了一位挚友。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96604,'zhCN','既然打好了基础，不如去附近村子找专业训练师学门手艺。他们也会教你如何制作适合你新专业的营地设施。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96626,'zhCN','学会这个，你就能在荒郊野外随时扎营了。你现在学的只是皮毛，所以营地周围还摆不下太多物件。$B$B精进你的烹饪技艺，说不定能生起更旺的篝火。$B$B要是你精通其他专业技艺，还能从训练师那里学到怎么布置营地。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96627,'zhCN','谢谢关照，$C。那个元帅就是爱瞎操心。$B$B嘿，看你这身打扮，也是个冒险者吧。想不想学学怎么露营？',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96655,'zhCN','学会这个，你就能在荒郊野外随时扎营了。你现在学的只是皮毛，所以营地周围还摆不下太多物件。$B$B精进你的烹饪技艺，说不定能生起更旺的篝火。$B$B要是你精通其他专业技艺，还能从训练师那里学到怎么布置营地。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96821,'zhCN','苦工们不敢往南走已经有一阵子了，$N。既然你清理出了一条路，我们就能让他们回去重新开工。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96822,'zhCN','我们将永远铭记这些勇士，$N。是你确保了这一点。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96825,'zhCN','我要用它们做点好吃的，顺便留下种子种进地里。总有一天，整个奥格瑞玛周围都会长满这种仙人掌果！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97223,'zhCN','谢谢你，$N。我很高兴能让它的血脉得以延续，并将它们培养成我们的盟友。你为部族立下了一件大功。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97279,'zhCN','谢谢你把这些武器带回来，$N。我会马上着手修理，好让下一批新兵能用得上。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97289,'zhCN','<这具躯体抽搐着苏醒过来，深陷在死前最后一刻的恐慌之中。>$B$B你……',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97291,'zhCN','这几样刚刚好。等这位贵客尝过了我的杰作，我倒要看看他还能剩下几分傲骨。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97292,'zhCN','完美。让他的皮肉先在药水里“炖”上一会儿。总得给他点时间适应新家嘛。$B$B这可怜虫我暂时用不着了，但必须死死盯住他。关于奥斯玛尔的未来，我可是有着周密的计划。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97891,'zhCN','啊，太棒了！我一直都在等奥雷萨多把药水送过来。之前他送来的那六瓶，全都在半路上就彻底失稳了，不过你这一回可是来得正是时候！$B$B拿着，这是给你的辛苦费。好了，现在没别的事了，除非你找我还有其他生意要谈？$B$B如果没有的话，那就赶紧离开吧，别妨碍我继续做实验。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97920,'zhCN','好了，你现在可以制作自己的鱼缸了。大多数人都不太喜欢在城镇中心安营扎寨，所以如果你想试试看，就需要去野外。$B$B哦，记住，没有营火的营地是不完整的。扎营之前，你需要先升起一堆火。大多数厨师都能教你如何生火。如果你还没学过，可能需要找个懂烹饪的人去学学基础。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98025,'zhCN','虽说得知这件事已经被顺利摆平了让我感到很欣慰，但没能找到别的解决办法，这多少还是让我心里有些难受。长久以来，贾伊瓦内尔其实一直都算得上是这一带的某种守护者，我实在搞不懂，究竟是什么鬼东西导致它彻底堕入疯狂的。$B$B无论如何，都要谢谢你今天所付出的这一切，$C。通往奥伯丁的大路总算是又恢复安全了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98298,'zhCN','看来笑到最后的赢家是我，哈哈！阿鲁高就是个彻头彻尾的蠢货。而我，达拉尔·道恩维沃尔，终于撕下了他那虚伪的面具。$B$B这些残肢断臂足以证明，这种诅咒跟那个满嘴胡言的白痴根本八竿子打不着。$B$B遗憾的是，这也意味着他给出的治疗方案连张废纸都不如。看来，我们还得继续摸索解除狼人诅咒的办法。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98299,'zhCN','看来吉尔尼斯人是铁了心不让任何人跨越那道高墙了。不过往好处想，这也算因祸得福。这意味着狼人诅咒基本上没什么机会侵入他们的城市。$B$B你敢想象，如果整个王国都被这种诅咒吞噬，那将会是怎样一副人间炼狱的景象吗？',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (99127,'zhCN','所有的陷阱都被祸祸成这副德行了？看来咱们新搬来的这帮讨债鬼，比我预想的还能折腾。再不想办法解决，我这生意可就要赔光了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (490,'zhTW','你立下了很大的功勞，$N。你會因你的貢獻而得到獎賞。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (8399,'zhTW','幹得好，$N。感謝你，我們在梣谷的自然屏障又能安穩地度過一天了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (65601,'zhTW','你在哪邊聽到克里吉的？你有他的消息嗎？勸你最好別耍我...',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (65604,'zhTW','哈！不出所料，果然贏了！$B$B你制服了魅魔，我很高興能教導你如何召喚惡魔。你的力量不斷在成長，我深信這只是邁向更強力量的一塊墊腳石。$B$B我會把圍巾交給瑪格。我認識那個$R很多年，我沒想到，除了克里吉，他居然會如此關心一個人。$B$B這同時提醒我們，我們跟惡魔的區別，我們能利用他們的邪惡，可是他們永遠無法操控我們。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (65610,'zhTW','$N，有什麼發現?一條...用月布織成的圍巾?希望你不是在向我求愛。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (78127,'zhTW','謝謝你，$N，因為有你的努力，我們的知識才得以拓展下去。$B$B若你有找到對圖書館有助益的魔幻大作，請帶來給我吧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
