INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (79974,'zhTW','矮人工程學，一如既往令人讚嘆。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (79975,'zhTW','篝火才剛剛添過柴薪，不過種種跡象都表明這裡的人匆忙離去。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (79976,'zhTW','沉重的帆布蓋住整理過的設備。你逕自取走了這個包裹。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (79980,'zhTW','你把信差包從土裡扯了出來。在一堆補給品中塞著一張髒兮兮的羊皮紙。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (86576,'zhTW','啊，你找到鷹身人收集的那些日長石了！鷹身人就愛收集閃亮的東西，但牠們完全不知道這些石頭真正的價值。這些石頭能吸收炫目的日光，反射出太陽的閃耀，讓我們能用太陽的榮耀來裝飾聖壇和家園。在夜裡，月亮的銀光也會照亮它們。$B$B這些石頭能提醒我們和天空之光的連結。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (87288,'zhTW','哦，這些毛皮真是美極了。對這麼莊嚴的動物採取暴力手段著實可惜，不過確保道路安全也是很重要的，而且這些毛皮能製成非常美麗的毛毯和披巾。$B$B來，我給你個東西讓你緬懷牠們。這東西既柔軟又結實。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (87760,'zhTW','這是一趟漫長的旅程，$N，但很值得。$B$B費盡千辛萬苦，你總算奪走納迦用來奴役這些海洋生物的魔棒。我一定會摧毀它，而那些蛇頸龍和海龜也終於能夠平靜度日。$B$B再次謝謝你。你的堅持終於得到成果，而我個人真的非常感激你。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (91723,'zhTW','做得好，我的朋友。讓我試著再次校準…',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (91724,'zhTW','一切似乎都正常運作。謝謝你，$N。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (91725,'zhTW','喔，真讓人鬆了一口氣！看來全都在這裡了。謝謝你！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (91899,'zhTW','謝謝你，辛苦了，$N。最近有許多強盜和小偷埋伏在貿易路線各處。如果你還有看到其他箱子，就把它們先送來這裡吧。剩下的交給我們處理。$B$B這是給你的報酬。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (91900,'zhTW','謝謝你，辛苦了，$N。最近有許多強盜和小偷埋伏在貿易路線各處。如果你還有看到其他箱子，就把它們先送來這裡吧。剩下的交給我們處理。$B$B這是給你的報酬。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
