INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (91921,'zhTW','<奎恩接過藥水並一飲而盡。>$B$B啊，我感覺到它的效力了。我想我很快就可以動彈了。$B$B你幫了我一個大忙，$N。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92401,'zhTW','我要你做的事對你並不公平，就算你直接轉身離開也是很合理的事。謝謝你，陌生人。我無法以同等方式回報你的恩情，不過希望這幾樣東西中有一樣合你的意。$B$B希望下次再會時，場面不再如此哀悽。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92415,'zhTW','你說織心者？織心者…$B$B哦！小傑瑞米‧織心者。多年以前，羅德隆遇襲之後他就被送到了這裡。他在那場襲擊中失去了雙親，可憐的小傢伙。$B$B其實他在不久前被一位來自暮色森林的善良女子收養了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92421,'zhTW','讓那些拒絕接受女妖之王恩惠的傢伙面對正義的制裁！$B$B有了這些肢體部位，我們的兄弟姐妹就有撐下去的希望了。班達利昂隊長一定會為你感到驕傲。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92422,'zhTW','雖然我很確定像他那樣的人遲早會有人遞補，但我們也只能希望他們的人數在此期間能有所減少。$B$B謝謝你，$N。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92432,'zhTW','看來賈克斯成功找到外援了。$B$B雖然嚴格來說這是不被允許的，但在危急關頭，我們不能因為傲慢而拒絕盟友的幫助。別被那些守衛騙了。局勢根本沒有得到控制。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92434,'zhTW','在如此危急的時刻，部落竟然對我的城市產生了興趣，這絕非巧合。$B$B事實上，這正合我意。我有一個提議。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92459,'zhTW','你在哪裡找到這個的？頂閣嗎？$B$B<大法師瑟琳卓臉色一沉，但很快又恢復了鎮定。>$B$B我認為你最好將這整件事逐出你的腦海，朋友。眼下，祈倫托歡迎像你這樣能力高超的$C。歡迎來到達拉然。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92481,'zhTW','讓我仔細看看你。沒錯，我相信你會成為一名優秀的年輕$C。秘法的力量在我們族人之中確實已經衰微，但仍有人試圖在這雲海之中的數千年間，重新找回我們所失去的大部分事物。我深信你將會在這場永無止境的秘法知識探索中一馬當先，並最終讓我們引以為榮。$B$B如果你想更進一步，再和我說話吧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92482,'zhTW','$C之道充滿了危險，只有擁有最敏銳的感官和最迅速的反應的人，才能在荒野之中成長茁壯。看著你，讓我想起了許多年前，當我站在自己導師面前時的模樣。我相信你具備了所需的資質，但說到底，這完全取決於你個人。$B$B如果你想更進一步，再和我說話吧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92514,'zhTW','你有去找伊菈雅了嗎？那很好。最近高天盟和塑風者之間的關係很緊張，不過在申德村這裡，他們還算和平。這裡的每個人都知道有個比紛爭還更嚴重的事。$B$B情勢說完了，你看起來是能幹粗活的人。我有些強盜問題需要解決，希望你能幫幫忙。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92516,'zhTW','做得好，而且還十分迅速。還不錯。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92517,'zhTW','強盜已經被驅散，現在少了一個必須解決的問題了。雖然我必須承認，我開始擔憂強盜的殘黨會投奔邪教尋求庇護，進一步壯大他們已經相當具有威脅性的勢力。$B$B儘管如此，能拿下的勝利還是得好好把握。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92528,'zhTW','洛舒娜也在那裡？她就是整個可惡邪教的領袖！$B$B如果他們打算對申德村和西部瞭望塔發動攻擊，我們必須做好準備。但很奇怪…為什麼要針對瞭望塔？$B$B村子我能理解，但是瞭望塔呢？那裡沒什麼戰略性價值，只不過是個小小的監視站罷了。$B$B無論如何，我們都得準備迎戰。他們會發現高地人沒那麼好欺負的。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92529,'zhTW','怎麼回事？莎妮雅姐妹派了一位想為馭風者效命的新人侍僧來嗎？我們今天真是受到四風之觸祝福！$B$B我們歡迎所有想沐浴在奧拉基爾祝福之中的人。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92550,'zhTW','感謝風啊，你回來了！$B$B你回來之前，莎妮雅‧銀澗偷溜出城外了，肯定是看到我們的人開始武裝，所以才開溜。$B$B你幫了申德村一個大忙，我們欠你一個人情。如果邪教又返回高地，他們會發現申德並不是好對付的目標。$B$B$N，願風指引你。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92551,'zhTW','太好了！少了日常的補給物資，我們這段期間只能勉強度日。我會和治安官合作，確保這些物資能重新分配給迫切需要幫助的人們。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92553,'zhTW','這些蛋不好弄來，但是風啊，用熊獸油脂煎過之後真是太美味了。$B$B如果你正好有空閒時間，而且喜歡料理，我可以教你幾招我的拿手絕活。說一聲就行，我很樂意訓練你。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92579,'zhTW','<閱讀信件時，維菈妮雅的表情逐漸暗了下來。>$B$B安妲信任你，派你送來這封信，所以我也會試著相信你。我們繼續討論之前，我需要先諮詢僅存的幾位保安官，擬定一個計畫，以防邪教對這裡發動攻擊。暫時先享受一下瓦拉納爾吧。$B$B如果你想找點事做，有很多村民會需要像你這樣強壯的年輕冒險者幫忙。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92596,'zhTW','高天盟的使命對我們族人的生存至關重要。我們非常敬重庇護我們的元素，但我們也必須面對現實，他們已經不在了，我們必須自立自強。$B$B考慮到奧拉凱斯這種內部威脅，還有這界域不安定的現狀，我們身為埃德薩拉斯精靈貴族後裔的宿命，就是活用我們的天賦，確保申多雷能夠再次靠一己之力，自強不息。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92640,'zhTW','目前塑風者和高天盟之間的關係非常緊張，但若沒辦法讓雙方都加入，我們的計畫就沒辦法成功進行。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92642,'zhTW','你還活著？我猜該感謝風，帶來了一點小小的奇蹟。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92643,'zhTW','<這男子明顯已經死去，是在房屋外頭和你戰鬥的那些刺客下的手。你蹲下來檢視屍體時，注意到某種物體閃爍著，發出反射的光芒…>',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92644,'zhTW','你說你抵達的時候，背叛者已經死了？真是不幸的消息。$B$B<你把在死去的邪教徒屍體身上找到的水晶遞給對方。>$B$B有意思…',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92645,'zhTW','貝吉蘿絲死了？四風祝福你，$C。$B$B看來我們真的能活著離開這裡了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92646,'zhTW','我派了幾個治療者過去，確保維菈妮雅和她剩下的部隊能活著回來。她現在應該已經回到高階長者的居所休息了。$B$B穆倫已經啟程返回艾澤拉斯，不過我和他談過塑風者下一步該怎麼走，以及我們對艾澤拉斯的使命。遺憾的是，這座島現在處於有史以來最脆弱的時候，我們需要有個計畫，才能保護微風島免於受即將到來的威脅摧殘。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92685,'zhTW','我說越血腥越好的時候，你真的有聽進去呢。很好。這能讓我知道你確實痛打了他們一頓。$B$B認真說，感謝你至今為止所做的一切。我這幾週以來，一直漫無目的地在農場附近遊蕩，好像在等末日到來一樣。我現在能夠再次抱持希望了。$B$B費拉烏和他的爪牙隨時都會出現，剩下的就是出去面對他們。你怎麼說？要跟我一起結束這一切嗎？',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92693,'zhTW','我…我不敢相信一切都結束了。我得休息一下，冷靜下來，我的心臟都快跳出胸口了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92699,'zhTW','你好，歡迎你。拉斯里爾寄了一封關於你的魔法書信給我，他提到你看起來挺有前途的。$B$B現在親眼見到你，我能理解他為什麼會建議你來找我了。你身上散發著鮮豔的秘法光環。這裡的人幾乎都沒有像你這樣的資質，更別說是為了拯救家園所需的意志力了。你有援助高天盟所需的勇氣和力量嗎？$B$B我們就等著看吧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92700,'zhTW','長者琥珀風捎來訊息，談到你和你在申德村的事蹟。我們歡迎你，朋友。$B$B你的光環頗強，而且你顯然和魂靈之間有著共鳴。近來這裡有天之視覺的人越來越少了，如果我們想撐過這段艱難的時期，微風島就會需要擁有這份天賦的人。我很高興你能來找我。$B$B我希望將來能更進一步和你來往。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92701,'zhTW','<閱讀信件時，維菈妮雅的表情逐漸暗了下來。>$B$B安妲信任你，派你送來這封信，所以我也會試著相信你。我們繼續討論之前，我需要先諮詢僅存的幾位保安官，擬定一個計畫，以防邪教對這裡發動攻擊。暫時先享受一下瓦拉納爾吧。$B$B如果你想找點事做，有很多村民會需要像你這樣強壯的年輕冒險者幫忙。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92706,'zhTW','終於有人把那個東西給宰了！你知道當鎮上的人都在喊「有鯊魚」的時候，要派團隊下水有多難嗎？$B$B我或許該把那個怪物的鰭拿來煮湯喝，這樣才能真正一解我心頭的怨恨。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92708,'zhTW','你理解了嗎？天空之牆外有著充滿知識，和無盡潛力的世界。這裡永遠都會是我們的家，但我開始相信通向救贖的路就在下方。我們必須前往艾澤拉斯，取得能拯救微風島的力量。這就是我們該走的路。$B$B你有足夠的勇氣，能在時機來臨時加入我們嗎？',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92709,'zhTW','你懂了嗎？重新發現前人的遠古魔法，就是找出微風島的秘密、保全我們未來的關鍵，但為了拯救家園，我們必須重新發現千年以來我們喪失的一切。$B$B艾澤拉斯就是關鍵。祈倫托會為我們指引方向。$B$B我們準備離開時，你應該去看看瓦拉納爾這裡的其他高天盟成員狀況如何。大部分成員手上都有任務，需要像你這樣的幫手來完成。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92727,'zhTW','<你眼前的背袋上有一些看似乾血漬的斑點。進一步查看污漬後，你發現上頭繡有名字：「菲利安‧焰風」。>',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92742,'zhTW','謝謝你。我來看看…',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92744,'zhTW','目前為止…這些鰓似乎還算健康。不過我們不能放心得太早。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92745,'zhTW','做得好，$N。但毒素的源頭恐怕是藏在其他地方…',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92747,'zhTW','這些都是什麼？',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92748,'zhTW','需要炸掉什麼東西嗎？',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92749,'zhTW','這是個好的開始！現在把它們綁在一起…再加入一點點額外驚喜…',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92750,'zhTW','嗯…想找什麼特別的東西，不是嗎？',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92751,'zhTW','太好了…這正是我們需要的！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92752,'zhTW','很高興你回來了，$N。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92753,'zhTW','看來你已經找到熔爐、放置好炸彈了…現在要做的事只有一件。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92812,'zhTW','我會把這個加入我們的收藏中的。多虧你的貢獻，我們的力量增長了，雖然若要超越瑪格拉姆部族，我們還有很長的路得走。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92819,'zhTW','我不知道該說什麼，$N。沒想到暴風城居然讓他們的軍事野心凌駕於人民的福祉之上…',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92834,'zhTW','高天盟因實用主義和邏輯而自傲，而邏輯思考可以導出，在大部分情況下迴避衝突以及傷亡都是最謹慎的選擇。$B$B<伊拉德林的雙眼開始發光，閃爍著秘法能量。>$B$B…不過呢，邪教把我們的謹慎誤解成懦弱，他們完全沒準備好為這個錯誤付出代價。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92840,'zhTW','我個人也不希望讓塑風者濺血，但這場毫無意義衝突的責任完全在他們身上。我們只想和平地收集資訊，他們卻以暴力回應。$B$B很遺憾，消息已經傳出去了，塑風者聲稱這件事是一場「屠殺」。他們不敢在瓦拉納爾這裡報復，但一定會懷恨在心。$B$B$N，你幫了高天盟很大的忙。謝謝你。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92860,'zhTW','貝拉桑的事我很遺憾。他其實是我表兄弟，也是一位好法師，微風島盡忠職守的一員。我們會為他報仇的。$B$B你看起來也急著想幫忙。來吧，我們進一步談談目前的狀況。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92871,'zhTW','你看起來也急著想幫忙。來吧，我們進一步談談目前的狀況。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92881,'zhTW','我有件小事，正需要像你這樣的冒險者提供協助。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92909,'zhTW','非常感謝你！我會開始進行逃跑計畫。在此同時，請收下這個！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (92947,'zhTW','我們歷經千辛萬苦才走到這一步，但一切還未結束。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93036,'zhTW','你好啊，孩子，我叫莎妮雅‧銀澗，我是奧拉凱斯教團的低階祭司。你想進一步了解我們的君主，『馭風者』奧拉基爾嗎？$B$B馭風者的門扉一向會對公正之人和悔過者敞開。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93065,'zhTW','我們已經做好萬全的準備了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93089,'zhTW','我很高興聽到高階長者影歌贊同我們進行遠征。現在邪教已被擊敗，我們也做好了萬全準備，我想是時候了。$B$B安斯雷姆非常努力，確保了割天者號能在達拉然和微風島間往來。我們已經盡可能進行過測試了，該是第一批人啟程的時候了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93090,'zhTW','我很高興聽到高階長者影歌贊同我們進行遠征。現在邪教已被擊敗，我們也做好了萬全準備，我想是時候了。$B$B穆倫非常努力，確保了割天者號能在微風島和那個叫莫高雷的地方之間往來，陶土議會目前正以那裡為家。我們進行了幾次試航，有些同胞已經在另一邊等著了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93159,'zhTW','…我沒什麼可說的了。我…呃…來到這裡之前，待在其他地方。現在我來到這裡，也有了朋友，還有我的東西。我、我是說我做的東西。我需要的就是這些了。至少我是這麼認為。$B$B不過我得說，能和會回話的人聊天實在不錯。森林之靈也會嘗試回應，但他們最後都只會對著我唱歌而已。其實那也不錯啦，但沒、沒什麼有啟發性的對話。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93160,'zhTW','感謝你，陌生人！這些只要烤過之後就會非常美味了！$B$B失陪了，料理不會花太多時間的。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93165,'zhTW','做得好。消滅邪教有益無害。希望這能傳達訊息，讓他們理解夜爪不好惹，而且還對他們恨之入骨。$B$B得自己去面對邪教，我看你扛下的任務不簡單啊。如果你能割下更多耳朵，就通通帶回來吧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93172,'zhTW','謝謝你，陌生人。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93318,'zhTW','邪教徒和高地強盜已經讓我們忙不過來了，我們不需要再多一隻巨大的弗德飛狐來危害民眾。你今天的所作所為是件壯舉。如承諾所言，這是你的獎勵。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93319,'zhTW','謝了，$C。這應該能幫我們度過難關。但如果沒辦法盡快重新打通補給路線，幾顆風石被偷走也算不上什麼重要的問題了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93320,'zhTW','我們暫時擋住敵人了，但他們人數眾多，我們也戰到筋疲力盡。我們必須迅速打破僵局。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93461,'zhTW','你有去找拉斯里爾了嗎？很好。最近高天盟和塑風者之間的關係很緊張，不過在申德村這裡，他們還算和平。好吧，至少在村莊裡是這樣沒錯。在荒野發生什麼事就沒人知道了。$B$B情勢說完了，而你看起來是能幹粗活的人。我有些任務需要完成，你願意幫個忙嗎？',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93680,'zhTW','下水道鑰匙？還好要用這東西的人不是我。$B$B不過我們還有一些工作要做，才能安全使用這把鑰匙。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93735,'zhTW','<里安尼把臉探到傀儡的沉重盔甲之下，試圖分析其中的機關。他根本就沒注意到你的存在。>$B$B該死的風暴，核心到底在哪裡啊？是誰把迴轉和風也拆掉了？這個傀儡的風還沒消散而去根本就是奇蹟！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93736,'zhTW','一碰到這些精華就讓我感到…十分不安。我能感受到它散發出邪惡且悔恨的氣息。沉重到足以讓我窒息。$B$B<安妲莉雅微微顫抖。>$B$B我不想再進一步研究了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93737,'zhTW','謝謝你幫忙收集這些材料。我想你應該遇上不少麻煩吧。$B$B有了這些零件，我就可以讓傀儡恢復運作了。希望它還保留一點記憶，讓我們知道是誰偷走它的零件的。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93738,'zhTW','太古怪了，所以是高天盟把傀儡弄壞的嗎？$B$B我認識貝拉桑。他是維菈妮雅‧颶拳的表親，他的母親也是塑風者。他竟然涉入此事，真令人遺憾。$B$B讓我靜一靜。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93739,'zhTW','你回來了。希望你在旅程中收穫良多。$B$B據我所知，你的同胞仍在莫高雷安定紮根。在等待他們的期間，我鼓勵你去探索奧格瑪周邊的領地。尤其是貧瘠之地，那裡總是需要像你這樣滿懷熱忱的冒險者。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93740,'zhTW','<當你把風石符咒交給阿雅莎時，她看起來有些恍惚，心神不寧。>$B$B抱歉，$N。今天…真的很難熬。謝謝你為塑風者做的一切。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93746,'zhTW','等等…什麼？貝拉桑…死了？$B$B<阿雅莎聽著你說事情發生的經過。>$B$B高天盟和奧拉凱斯在商討和平協議？根本就沒辦法跟那群殺人狂談和平。伊拉德林到底為什麼要派貝拉桑自己一個人去？$B$B這件事你別放在心上，$N。這不是你的錯。這又全都要怪高天盟的傲慢。你只是在不恰巧的時機遇上這件事罷了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93835,'zhTW','我已經派遣剩餘法師，確保維菈妮雅和她的部隊能安然逃離。她現在應該在高階長老影歌的住所休息。$B$B安斯雷姆已經返回艾澤拉斯，但在他離開前，我和他討論過高天盟下一步該怎麼做。雖然我們挺過今天的難關，但微風島還是危機重重，我們也必須為未來做好準備。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93836,'zhTW','<塔拉尼斯‧影歌認真聽你講述奧基爾聖殿上發生的事，以及阿雅莎離開微風島的計畫。>$B$B我得進一步思考這件事，不過從正向角度看，我們已經除掉洛舒娜和教團的領袖了。我們的家園還沒遭到入侵，按照元素諸神的時間線來看，可能要過好幾年…甚至好幾十年，奧拉基爾才會把矛頭轉向我們。$B$B雖然現在有許多事要擔憂，但也值得歡慶。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93926,'zhTW','<倒臥的遺體似乎還沒腐爛，看來是剛剛才被殺死的。檢視保安官身上的灼傷後，可以明確得知，他們是被教團施法者的風暴法術殺死的。>',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93927,'zhTW','所以他們都陣亡了。這些該死的教徒！$B$B雖然你成功除掉了祭司，也在高塔阻止了那些教徒，但不得不承認，我現在更加擔心你之前說他們對尖塔所做的這件事了。鑒於他們存了一大箱風石，代表他們需要大量的能量。$B$B這讓我不禁思考，他們的目標到底是什麼？是為了玷汙尖塔，還是攻擊村莊？這一切又都是為了什麼？',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93948,'zhTW','我…聽到姪子死了非常難過。謝謝你幫我找到它，還帶回來給我。$B$B高地有這樣能幹的年輕申多雷還真是罕見。如果你願意幫忙，就跟瓦拉納爾保安官隊長維菈妮雅‧颶拳談談吧。這些日子，我們真的急需援手。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93949,'zhTW','相信瓦拉納爾到處都有這些生物，但每解決掉一隻附魔躍空者，這座城市裡的人就能安心一些。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93951,'zhTW','雖然為我們頭髮的裝飾收集羽毛看起來是雞毛蒜皮的小事，但像這樣的時候，有點小確幸也是很不錯的。$B$B如果我製作的東西能為別人帶來快樂，那一天就會感覺很美好。謝謝你幫我帶回這些，讓我能為微風島帶來快樂。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (93958,'zhTW','<維菈妮雅看起來受了重傷。>',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94006,'zhTW','孩子，你想習得利爪之道嗎？那就來吧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94013,'zhTW','太好了，$N！你學得真快。基礎技巧你都會了，現在就來學會如何和動物夥伴締結深厚的連結吧。$B$B學會之後，就到野外歷練歷練。成為微風島上首屈一指的$C吧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94050,'zhTW','嗯，一個剛剛出道的獵手。我可以把馴服和引導寵物的技能傳授給你，你不僅可以教你的寵物學習新的技能，還可以餵養它，如果它在戰鬥中死亡的話，你還可以復活它。$B$B記住，$N，永遠對自然的平衡保持敬畏的態度，對大自然永遠抱有崇敬之情。出發吧，我們以後會再見面的。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94369,'zhTW','<塔拉尼斯‧影歌認真聽你講述奧基爾聖殿上發生的事，以及伊拉德林離開微風島的計畫。>$B$B我得進一步思考這件事，不過從正向角度看，我們已經除掉洛舒娜和教團的領袖了。我們的家園還沒遭到入侵，按照元素半神的時間線來看，可能要過好幾年…甚至好幾十年，奧拉基爾才會把矛頭轉向我們。$B$B雖然現在有許多事要擔憂，但也值得歡慶。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94411,'zhTW','直接和我們申多雷的兄弟姊妹挑起紛爭，雖然會削弱各自的力量，但為了避免更慘痛的悲劇發生，就必須當機立斷。$B$B高天盟的法師完全沒有顧及他們施法後帶來的後果。連結我們島嶼的力量十分脆弱，要是有人一個不小心，被摧毀的可是我們的家園。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94413,'zhTW','有時我實在是難以分辨奧拉凱斯教團的狂熱，以及塑風者拒絕改變的決心。$B$B如果他們真的深信風會引導我們，那就應該感覺得到風吹向何方，而不是逆風行事。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94485,'zhTW','<伊蕾嘉兒從你手裡接過黏黏的苔蘚時，虛弱地微微一笑。>$B$B謝謝你，$N。你做得很好。這正是我需要的。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94486,'zhTW','謝謝你收集這些羽毛。我一定不會浪費這些羽毛，不讓始祖鳥白白喪命。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94487,'zhTW','<伊蕾嘉兒憔悴地看著你收集來的染血傳家寶。>$B$B這麼多有才華的年輕人就這樣喪生了。謝謝你把這些帶回來，$C。$B$B我會暫時好好保管這些東西，然後再交給高階長老。可以先把它們收起來，等待更夠格的下一代成年後成為它們的主人。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94488,'zhTW','<伊蕾嘉兒面露苦澀地看著被砍下的頭顱，然後點頭一下。>$B$B謝謝你，$N。無論我心中有多麼憤怒，也很難親自對自己的表親下手。$B$B不用為他哀悼。他的傲慢與邪惡今天不知道殺死多少無辜之人。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94489,'zhTW','<當你說明喬瑞爾的命運和其他德魯伊的情況時，伊蕾嘉兒的臉色變得十分蒼白。>$B$B不…不！這比我想的還要糟糕…$B$B<伊蕾嘉兒啜泣，咬牙切齒地發出一聲痛苦的嘶吼。>$B$B他們得付出代價。他們都得血債血償。我發誓，任何與奧拉凱斯有關的人將一嚐我的怒火！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94491,'zhTW','<洛瑟倫聽著你訴說德魯伊巢穴裡發生的事時，一臉驚恐。>$B$B我、我很抱歉，$N。我需要一點時間消化。我實在不知道該怎麼形容失去這些人的感受。$B$B這確實是個慘痛的消息。如果這封信函屬實，他們的同黨就在瓦拉納爾這裡。更糟的情況是，這個人是個叛徒。我會立即把這封信拿去給高階長老瞧瞧！我不會讓我的同胞白白犧牲。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94568,'zhTW','我們可以試著派保安官直接與教團勢力對峙，但正面開戰對我們很不利。$B$B我們得想想其他辦法。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94638,'zhTW','失去她的痛苦實在是無法衡量，但這對平衡來說是必要之舉。雖然這是個難過的事，但你也展現了堅定的決心。$B$B做得很好，$C。我將賜予你祝福，讓你能變成我同胞的形態。成為那些無法保護自己的人的希望信標，在他們需要的時候伸出援手吧。$B$B去吧。接納利爪之道吧，孩子。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94911,'zhTW','高等精靈…來雷霆崖找我說話。天是要塌下來了嗎？$B$B風之形塑者，我和陶土議會的兄弟姊妹竭誠歡迎你來艾澤拉斯。塞納里奧議會的$C夥伴有許多知識可以和你分享，自然之子。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94913,'zhTW','啊，看來你已經精通熊形態之道了。很好，很好。你走在對的路上了，年輕的$C。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94946,'zhTW','啊，你來了。太好了。我們要花點時間好好整頓，這段時間你可以去城裡好好看看。但要注意，不要去離城市太遠的地方。$B$B雖然這片新大陸的景色如詩如畫，但在毫無準備情況下離開達拉然也是很危險的。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94947,'zhTW','你好，$C。我是暴風城的攝政王，名叫伯瓦爾‧弗塔根。$B$B祈倫托信差告訴我最近會有高天盟的成員來訪，看來就是你了。王座廳裡已經有好一段時間沒看過高等精靈的身影了，但能迎接你這位貴賓是我的榮幸。$B$B我在此代替國王歡迎你來到暴風城，而你也可以自由在聯盟領地中探索。歡迎來到艾澤拉斯，天裔精靈。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94961,'zhTW','沒錯，非常好！現在我們離開這裡，去找寶藏。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94978,'zhTW','馴服得好，$N！看來你已經很熟練了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (94979,'zhTW','你回來了！動作還真快，$N！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95065,'zhTW','來得正好！我剛好用最後一個魚餌釣起一條大魚。今天收穫不錯。這些魚都很愛咬餌！$B$B這樣吧，既然你這麼善良，願意幫我這個老頭子維持生計，不然你就拿走幾條魚吧？',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95118,'zhTW','解決掉他們了？很好！相信很快就會有更多魚人冒出來，不過，至少在那之前，我的耳根可以清淨一點。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95119,'zhTW','做得很好，$R。現在，我們去抓大魚吧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95120,'zhTW','很好，這地方的煩心事又少了一件，我真的欠你一個人情。拿去，別一下子就花得一乾二淨。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95121,'zhTW','刀工很不錯啊，我的副主廚。一鍋海鮮燉菜馬上上桌！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95161,'zhTW','哦不…$B$B謝謝你特地把這個拿來，但我想傑瑞米還沒準備好面對它。監護員南丁格爾說過，自從羅德隆遭受襲擊以來，我的小傑瑞米就再也沒有開口說過話，而我現在也不打算強迫他。讓他看這個只會帶給他更多痛苦。$B$B別那樣看著我。我不會向他隱瞞他的過去，但他需要時間來療傷。等他長大一點，我就會把這個交給他的。謝謝你順道過來，但我想你該離開了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95216,'zhTW','你把牠殺死了？？$B$B嗯。你運氣很好，這些膿液應該足以逆向解析牠的屬性。你不會想和皇家藥劑師學會為敵的。$B$B快滾出我的視線！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95288,'zhTW','看來你有學會第一堂課的教訓了，跟班。你學會了我的智慧金言，但這次我不跟你收費！我算是個好老闆吧？$B$B在你下一次出任務前，花點時間好好反思這個教訓吧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95349,'zhTW','看來是微風島來的冒險者。太好了。看來風真的有眷顧我們！要完全整頓好要花點時間，這段時間你就好好去探索這片新大陸吧。$B$B艾澤拉斯是個令人感到興奮的新世界，但也十分危險。在你展開這段熟悉環境的冒險前一定要做好萬全準備。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95350,'zhTW','Lok\'tar，$C。我叫索爾，是部落的酋長。$B$B陶土議會信差告訴我最近塑風者會派出成員，看來就是你了。能在奧格瑪看到高等精靈還是頭一遭，但部落會誠心歡迎你。$B$B祝你能在部落領地順利探索。願榮耀與你同在，塑風者。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95494,'zhTW','很好，這些看起來還不錯。我和當地的製皮匠約好了，要用這些皮革換一些製品來販售。$B$B我從未違背過約定，就算受傷了，我也不打算這麼做。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95495,'zhTW','弗朗恩請你來的嗎？太好了。感謝你把這些皮革送來給我。弗朗恩因為傷勢不能來真是太可憐了。我有件事想跟他說。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95507,'zhTW','多謝有你的協助，$C。我還以為我這該死的腳傷要讓我餓著肚子睡覺了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95508,'zhTW','看來我們都沒事。我…知道有一天他們會來找我。多虧今天有你幫忙，我欠你一條命。$B$B請收下這個。雖然不多，但這是我能做的。$B$B祝你旅途平安，$C。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95621,'zhTW','所以他們在找逃兵…看來過往的事找上我了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95646,'zhTW','情況比我擔心的還要糟糕。一股古老的力量正蠢蠢欲動。為了他們自身的安全，你最好去帶個口信，讓那些興致高昂的挖掘者們停止挖掘。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95697,'zhTW','瞧瞧這大理石般的油花！牠們在上面到底是吃什麼長大的？非常感謝你大老遠為我們跑這一趟。如果你不介意等一會兒，我們現在就幫你做幾份，當然是免費招待！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95737,'zhTW','拉娜一定在想，我答應要讓我丈夫帶回去的那些草種子到底在哪裡！知道她和我一樣擔憂，就讓我感到一絲欣慰。我們兩人感覺到的異樣，肯定和挖掘場脫不了關係。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95774,'zhTW','我會把這些飾物放在奧格菈的紀念碑旁，這樣我就能時時緬懷她了。到我死為止，我的血將充滿復仇的怒火！我每次揮舞刀刃，所有敵人都會以她的名義倒下。$B$B你幫了我…幫了我們…取得莫大的榮耀。$B$BLok\'tar，$N。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95795,'zhTW','噢不…$B<他把頭埋在雙手中，抽泣了起來。>$B$B我當時應該跟著他們一起去的。$B$B我打造的大部分東西都是要給他的，原本打算給他個驚喜，但他過來拿旅途所需的物品時，這些東西都還沒準備好。$B$B現在雖然完成了，但我實在沒有心力去重鑄或把其中的任何一件賣掉。$B這個就送給你吧。你為我帶來了這沉重的一天，這是我唯一能為你做的事了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95803,'zhTW','我不會質疑丹妮莎的一片赤誠，以及想為你在被遺忘者中掙得一個地位的決心。不過，我想這不會是我們最後一次看到你的兄弟姐妹發狂起來，利用聖光對付自己的同胞。$B$B或許有一天，我會認定忍受你們那惡毒的組織不再是被遺忘者的最佳利益。我建議你繼續盡心盡力為同胞服務。$B$B我們會好好盯著你們的。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95805,'zhTW','<當你把薰香丟到火裡後，香氣瀰漫四周，最後只留下一個空袋子和些微的成就感。>',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95809,'zhTW','天啊，那聽起來真可怕！$B$B聖光保佑，我很感激他是倖存者之一。$B$B<她將蘆葦編織的愛心緊貼在自己的心口。>$B$B我這就開始為他準備一頓豐盛的餐點。謝謝你為我帶回這個消息。我希望你能收下這個，作為我們的謝禮。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95883,'zhTW','<被折磨的靈魂在祭品之石前釋放出一股邪惡的能量。$B$B看來你就快要完成儀式了。>',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95885,'zhTW','<祭品之石現在失去了作用。看來你的儀式耗盡了它的力量。你不知道這有什麼作用，但一切都結束了。$B$B粗糙的石頭碎裂崩解，沒了用途。$B$B但石頭殘骸中閃著奇特的光芒…>',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95913,'zhTW','噢，你回來了！你真是個奇蹟，$N。這些看起來又溫暖又舒適…還很柔軟。$B$B$B$B當然，這些都是給艾瑪的。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95981,'zhTW','自從達拉然周圍的屏障消失後，祈倫托便一直牢牢掌控著道路。可以肯定的是，他們在提防著什麼。$B$B不過，現在原因已經無所謂了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (95999,'zhTW','幹得好，$N！焚化者加林姆本來正準備加強石望要塞的防禦工事。藉由這次勝利，我們或許能成功奪回那座要塞！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96063,'zhTW','太好了！這些就夠了。不如再幫我一個忙吧？',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96130,'zhTW','得終結這麼一隻美麗生物的生命實在教人難過，但為了保障人民的安全，我們必須這麼做。我會好好善用這毛皮的。謝謝你。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96139,'zhTW','這本書似乎是關於維洛家族。我應該聽說過他們當中的一些人。一群好人。但不確定是否值得專門寫一本書介紹他們。$B$B我會給你這本書的複本。如果旅行途中，你發現其他跟他們有關的物品，我很樂意收下它們。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96241,'zhTW','呵…我說有獨特的性質的時候，可不是在說笑！不過你的狀況看起來不賴，那就沒問題了。$B$B多虧有你幫忙，$C。非常感謝。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96259,'zhTW','感謝你為這裡的人們所做的一切。要徹底清除這些蜘蛛可能還需要一段時間，但你的努力已經幫助我們站穩腳步，讓我們有能力繼續對抗這些邪惡生物。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96260,'zhTW','這些真是極好的樣本，用來實驗可說是綽綽有餘了。$B$B來，這個給你。我用之前回收的少量蛛絲樣本，成功織成了一件特殊的披風。希望它能在你的旅途中派上用場。$B$B大地之母保佑你，$C。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96261,'zhTW','甦生的死者？育母還有夜精靈的型態？這些新情報真教人擔憂。這背後的意義究竟為何…恐怕得之後再來推敲了。$B$B感謝你，$N。你幫了陶土議會和莫高雷的人民一個大忙。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96392,'zhTW','$C，現在你看見了吧？他們人多勢眾，我們從天上看還只是其中一部分而已。$B$B你看起來是個可靠的人。不如去擊潰他們吧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96393,'zhTW','黑鐵矮人入侵了…就在我們腳下？聽到黑鐵指揮官被解決掉了，我十分欣慰。$B$B守衛會去處理剩下的烏合之眾。我們會封鎖突破點，加強下層的防禦，不讓其他人有機可乘。$B$B謝謝你為鐵爐堡付出的一切，$C。這個小東西給你，當作是謝禮。噢，如果你看到蠻錘大地愛好者法森的話，告訴他，他欠我一個人情。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96394,'zhTW','啊，太好了，看來一切都搞定了。我可不能讓其他守護者因為有「憤怒的亡靈」而拒絕進到大廳戍守，你說是吧？',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96403,'zhTW','你看看，你真是個積極的猛漢！我這個地精說話算話，這是你應得的獎勵！$B$B現在讓我看看寶…我是說找回來的傳家寶。我得開始把這些東西…咳咳，「登錄」起來，這樣才能盡快物歸原主。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96604,'zhTW','你已經學會基礎技能了，接著就去附近的村落，向訓練師學習交易技能。他們也會教你如何製作屬於你新專業技能的營地設施。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96606,'zhTW','你已經學會基礎技能了，接著就去附近的村落，向訓練師學習交易技能吧。他們也會教你如何打造適合你新專業技能的營地。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96630,'zhTW','那是我的日記嗎？我已經找好一段時間了。謝謝你，$C。$B$B嘿，你看起來也是個冒險者。想不想學一點紮營的技巧啊？',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96634,'zhTW','學會之後，你就可以在野外任何地方建立營地了。剛剛學到的只是基本技巧，所以你還沒辦法放置太多家具。$B$B提升烹飪等級，就能搭起更大的營火。$B$B如果你想學習其他交易技能，也可以找其他訓練師來學習營地設置家具的其他技巧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96652,'zhTW','那是我的日記嗎？我已經找好一段時間了。謝謝你，$C。$B$B嘿，你看起來也是個冒險者。想不想學一點紮營的技巧啊？',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96655,'zhTW','學會之後，你就可以在野外任何地方建立營地了。剛剛學到的只是基本技巧，所以你還沒辦法放置太多家具。$B$B提升烹飪等級，就能搭起更大的營火。$B$B如果你想學習其他交易技能，也可以找其他訓練師來學習營地家具布置的基本技巧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96821,'zhTW','這段時間苦工們一直都很害怕往南走，$N。現在你把路清乾淨了點，他們終於能繼續工作了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96822,'zhTW','我們會永遠記得這些戰士的，$N。你幫了我們一個大忙。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96825,'zhTW','我能用這些做點好吃的料理，種子就留下來種植。總有一天，奧格瑪到處都會長滿帶刺的果子！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96873,'zhTW','做得好。我為被殺死的食人妖感到遺憾，但現在束縛法術已經解除，他們的靈魂能夠安息了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96875,'zhTW','你的努力幫助了奧格瑪成長。你在城內來去時，務必記住這點。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96896,'zhTW','我打算繼續在這裡待一會，和朋友們聊聊，但我很快就會回東瘟疫之地的聖光之願禮拜堂了。如果你剛好路過，記得打聲招呼。我們隨時都歡迎身強體壯的冒險者來幫更多忙。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96986,'zhTW','做得好。那個怪物根本就不夠格和亡者為伍。就讓他歸於塵土吧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (96988,'zhTW','碎了、碎了，都碎了。$B$B這些我都不能用！我只有說阻止那些哨兵，可沒說要把它們打爛！它們根本就不構成任何威脅吧？$B$B我成為憎惡體魔導師的夢想就此止步了。暫時而已。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97003,'zhTW','太驚人了，$C。這樣一來，我帶著這個證明恐怖怪物存在的證物回奧格瑪時，就沒人會質疑我說的話了。你放心，這榮耀當然是你的，但我絕對會讓所有人都知道你的功績。$B$BLok-tar！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97223,'zhTW','感謝你，$N。我很高興能夠保全牠的血脈，繼續培育牠們作為盟友。你幫了我們部族一個大忙。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97225,'zhTW','你幫了我們部族一個大忙。$B$B和某些部族不同，我們部族非常崇敬羅亞，而我們實在是欠祂太多了。$B$B我可不希望暗矛部族失去祂的寵愛。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97242,'zhTW','這種香蒲和長矛草只有奧格瑪才有。這些草藥受到艾薩拉山脈流下的泉水灌溉，得到岩地吸滿血汗的礦石粉塵滋養，因此蘊藏強大的效力。$B$B我會把這些交給耶爾瑪克，他或許能透過親自示範，讓伍特願意專心聽講。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97246,'zhTW','當然了。米奇的父母跟我說好，每天幫米奇打包一份午餐，不過，如果那個男孩沒來拿午餐，我也沒辦法把食物送到他手裡。$B$B有時候，他一週根本出現不到幾次，真不知道他哪來的精力可以從早玩到晚。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97249,'zhTW','博斯坦的肉？那是給我們其中一個的嗎？$B$B喔！$B$B哇…聞起來真的好香！真美味。$B$B謝謝你幫我送午餐來。每天跟朋友走在通往葛羅瑪許堡的路上，我光用聞的就能知道博斯坦今天準備了什麼餐點。這是我最喜歡的東西，糖醋醬！不過又不太一樣。我喜歡那些風味強烈的脆屑。$B$B要是餐點每天都這麼好吃，我覺得我們得中場休息一下，一起去拿午餐！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97250,'zhTW','所以謠言都是真的！我想也是，東邊海岸的氣氛近來一直相當緊張。我早就知道，衝突延伸進我們的領地只是早晚的事了。$B$B不過，我還是不認為我們有參與破壞旅店的行動。很多部落居民都仰賴那條路來貿易或旅行。如果你有時間，也許可以進一步調查。$B$B無論如何，今天又是部落的勝利，也給了聯盟一次嚴厲的警告！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97253,'zhTW','哇塞！幹得好啊，朋友！你讓我不必再聽加格斯普吉特那些關於金屬有多貴重的鬼話了。更重要的是，我可以立刻開始打造新的原型機了。$B$B呃，我沒事先想好要給你什麼獎勵…你喜歡箱子嗎？',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97275,'zhTW','咕嚕…什麼？$B$B你說這個藥水是耶爾瑪克用長矛草和香蒲做的，完全沒加其他材料？我完全不知道藥劑師還會用到這種平常隨處可見的植物。$B$B也許他是對的。一下子就跳到最罕見、最少了解的植物，我可能會錯失很多東西。$B$B$N，從我先前調配的這些藥水中挑一瓶吧。我很感謝你特地跑來我們的店。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97279,'zhTW','謝謝你把這些武器送回來，$N。我會把它們修好，給下一批新兵使用。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97282,'zhTW','嘿，多謝啦，夥計！你真是幫了我大忙，我真得好好感謝你。$B$B希望用這些內臟就能把它充飽。我敢打賭，這能讓那些討人厭的鷹身人不敢再打我商隊的主意了。希望這真的有用。$B$B無論如何，你的任務已經完成了。這是你應得的報酬。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97289,'zhTW','<軀體在不斷扭動下恢復生機，驚恐地經歷臨終前的最後一刻。>$B$B你…',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97290,'zhTW','他不願意合作嗎？太好了。我最喜歡挑戰了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97291,'zhTW','這些就足夠了。我們就來看看這尊貴的傢伙臣服在我的傑作之下還能高傲到哪去。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97292,'zhTW','太好了。我們就讓他的肉體受熱一段時間。給他一點時間適應新家。$B$B現在我暫時用不上這個怪物了，但我們還是得多加留意。歐斯瑪未來還能為我所用。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97326,'zhTW','你為什麼能一次搬這麼多巨石？$B$B這些實在太棒了。大多數甚至還有很平坦的表面。在你把它們一路搬來這裡後，我們可以在地上把它們推來推去，挪到想要的地方。$B$B謝了，$N！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97485,'zhTW','你做得很好。$B$B感謝你花時間進行我們其中一個歷史悠久的傳統，$R。希望在你的旅途中，你會發現很多事都值得感謝。$B$B如果你想要再次進行儀式，你應該可以重新購買我派你去收集的東西。$B$B願安希的溫暖與你同在。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97538,'zhTW','啊，謝謝你，$N。$B$B你竟然願意為了一個老牛頭人麻煩的小事這樣跋山涉水，也因為有你的幫忙，我這個季節有足夠的顏料了。$B$B多謝你讓我得以有生計，我也會用你辛苦取來的顏料好好創作。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97583,'zhTW','<軟泥怪獲得能量後不斷抖動。它現在認定跟著你就有吃的，所以似乎想與你同行。>',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97891,'zhTW','啊，太好了！我一直在等奧雷薩多把藥水送來。上次他送的六瓶在半途就變得很不穩定，但你卻及時把東西送來了！$B$B這給你，算是一點報酬。這樣就沒別的事了，還是你有什麼想請我幫忙的嗎？$B$B如果沒有的話就走吧，這樣我才能繼續在沒人打擾的情況下實驗。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97894,'zhTW','老博古叫你來的？他總是愛替我操心。$B$B我們這裡確實能用上更多人手。由於最近發生的悲劇，生意幾乎完全停擺了，而我想你應該能幫忙讓一切重回正軌。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97901,'zhTW','好了，你可以製作自己的附魔魯特琴了。大多數人都不太樂見有人在城鎮中心搭建營地，如果你想測試一下，就得去找個荒郊野外。$B$B每個營地都需要營火。你需要升起營火，作為營地的基礎。大多數廚師都能教你如何升火。如果你還沒學會這個基本技巧，就去找個能教你烹飪的訓練師。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97903,'zhTW','好了，你現在可以製作自己的急救箱了。大多數人都不太樂見有人在城鎮中心搭建營地，如果你想測試一下，就得去找個荒郊野外。$B$B喔，記住，每個營地都需要營火。在搭建營地之前，需要先升起營火。大多數廚師都能教你如何升火。如果你還沒學會，可能需要找個能教你廚藝的人，學習一些基本技巧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97904,'zhTW','好了，你現在可以製作自己的魚缸了。大多數人都不太樂見有人在城鎮中心搭建營地，如果你想測試一下，就得去找個荒郊野外。$B$B每個營地都需要營火，老兄。在搭建營地之前，需要先升起營火。大多數廚師都能教你如何升火。如果你還沒學會，就去找個能教你廚藝的人，學習一些基本技巧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97908,'zhTW','好了，你現在可以製作自己的營地椅子了。大多數人都不太樂見有人在城鎮中心搭建營地，如果你想測試一下，就得去找個荒郊野外。$B$B喔，記住，每個營地都需要營火。在搭建營地之前，需要先升起營火。大多數廚師都能教你如何升火。如果你還沒學會，可能需要找個能教你廚藝的人，學習一些基本技巧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97914,'zhTW','<巴洛斯把信打開來讀，笑容也逐漸退去。>',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97919,'zhTW','好了，你現在可以製作自己的急救箱了。大多數人都不太樂見有人在城鎮中心搭建營地，如果你想測試一下，就得去找個荒郊野外。$B$B喔，記住，每個營地都需要營火。在搭建營地之前，需要先升起營火。大多數廚師都能教你如何升火。如果你還沒學會，可能需要找個能教你廚藝的人，學習一些基本技巧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97926,'zhTW','確實是個難過的消息。不過，謝謝你願意走這一趟。$B$B無論暴風城或達納蘇斯是否來援助我們，奧伯丁的命運都只能交由我們來決定。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97938,'zhTW','好了，你現在可以製作自己的法力井了。大多數人都不太樂見有人在城鎮中心搭建營地，如果你想測試一下，就得去找個荒郊野外。$B$B喔，記住，每個營地都需要營火。在搭建營地之前，需要先升起營火。大多數廚師都能教你如何升火。如果你還沒學會，可能需要找個能教你廚藝的人，學習一些基本技巧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
