INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97959,'zhTW','好了，你現在可以製作自己的磁石了。大多數人都不太樂見有人在城鎮中心搭建營地，如果你想測試一下，就得去找個荒郊野外。$B$B喔，記住，每個營地都需要營火。在搭建營地之前，需要先升起營火。大多數廚師都能教你如何升火。如果你還沒學會，可能需要找個能教你廚藝的人，學習一些基本技巧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97965,'zhTW','好了，你現在可以製作自己的急救箱了。大多數人都不太樂見有人在城鎮中心搭建營地，如果你想測試一下，就得去找個荒郊野外。$B$B喔，記住，每個營地都需要營火。在搭建營地之前，需要先升起營火。大多數廚師都能教你如何升火。如果你還沒學會，可能需要找個能教你廚藝的人，學習一些基本技巧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97967,'zhTW','好了，你現在可以製作自己的魚缸了。大多數人都不太樂見有人在城鎮中心搭建營地，如果你想測試一下，就得去找個荒郊野外。$B$B喔，記住，每個營地都需要營火。在搭建營地之前，需要先升起營火。大多數廚師都能教你如何升火。如果你還沒學會，可能需要找個能教你廚藝的人，學習一些基本技巧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97970,'zhTW','好了，你現在可以製作自己的磁石了。大多數人都不太樂見有人在城鎮中心搭建營地，如果你想測試一下，就得去找個荒郊野外。$B$B喔，記住，每個營地都需要營火。在搭建營地之前，需要先升起營火。大多數廚師都能教你如何升火。如果你還沒學會，可能需要找個能教你廚藝的人，學習一些基本技巧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97977,'zhTW','噢，這比我想的還要嚴重。$B$B這些紋刻顯示瘤背部族一直夢到被某種強大暗影屠殺殆盡。不出多久，這樣的恐懼便轉化成憤怒，他們更把矛頭轉向過去的精靈朋友。意識到自己的心智正逐漸消逝實在是…$B$B幫助我們更加了解泰達希爾發生的事是我們的唯一希望。多謝有你協助，$N。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97979,'zhTW','你已經見識過我們女神的力量了。務必善加利用，祂也絕對不會棄你而去。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (97985,'zhTW','太棒了！我真的難掩我的興奮之情。噢，那顆心臟還有電流嗎？太驚人了。這樣我就不用再額外電擊來讓它恢復心跳了！$B$B這能成為憎惡體的心臟，而且筆記沒有錯的話，它也符合其中描述的大小。$B$B啊，計畫能順利進行的感覺真好。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98013,'zhTW','別怕，年輕人。為了邪惡的主人洗劫自己的家園…$B$B這不可饒恕。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98021,'zhTW','好幾個月來，我一直在向暴風城求援，結果派來的是一個瘦巴巴的精靈？好吧，求人的人也沒資格挑三揀四。$B$B歡迎來到西部荒野，$C。我們來看看你能不能派上用場。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98024,'zhTW','怎麼回事？一個精靈？你說是大酋長派你來的？$B$B<索克哼了一聲，上下打量著你。>$B$B在我看來，你有點太瘦弱了，不過沒關係。在這裡，一個人不是愈挫愈勇，就是成為死人。那就是這片土地的生存法則。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98025,'zhTW','知道有人解決麻煩真是太好了，不過令我難過的是，我們只能了結牠的生命。賈瓦奈爾過去曾是這片土地的守護者，我也不知道是什麼原因讓牠發狂。$B$B無論如何，多謝有你的努力，$C。前往奧伯丁的道路又再次回歸安寧了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98042,'zhTW','<桑迪斯好一段時間都沒說話。>$B$B這是遠古邪惡力量的印記，$C。我會馬上把它帶到達納蘇斯來研究。$B$BAnde\'thoras-ethil（願你忘憂無慮）。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98046,'zhTW','不要把大德魯伊的話放在心上，$N。瑪法里恩不在之後，他就肩負著沉重的負擔。$B$B等等！瓶子裡還殘留一點液體！該不會這就是他咒語失敗的原因吧？',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98065,'zhTW','當我的愛人不在時，鹿盔盡了許多心力，但他畢竟不是瑪法里恩。他也不負責管理達納蘇斯的事務，那是我必須獨自扛起的重擔。$B$B<泰蘭妲的臉色平定了下來。>$B$B抱歉。正如所見，我們正面臨許多挑戰。$B$B現在由范達爾暫時擔任大德魯伊，也希望你能給予他同等的敬重。但他的職責在於德魯伊之道，而我做的一切不僅和伊露恩有關，更是按照她的旨意來帶領我的同胞。$B$B這每一滴水都受到了女神的祝福。謝謝你協助把它們保存下來。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98067,'zhTW','多謝有你的協助。雖然我在每日的儀式中就能尋求寧靜，但能有額外的時間進行反思也蠻好的。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98070,'zhTW','這真是個好消息！我會把鷹身人被解決掉的消息告訴我們的供應商。商隊該擔心的事又少一件了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98072,'zhTW','你真是天生好手！話說，如果你某天打算遠離冒險生活，就來找你的好兄弟詹姆士吧。我馬上為你安排工作！$B$B不過，我想那時候你就會變得更老了。哦，管他的！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98093,'zhTW','$N，感謝你願意出手相助。我會讓陶拉祖營地知道是你救了我。有你幫忙真是太幸運了，不然我可能會被困在那裡一整天！$B$B這是我能拿出的所有謝禮，希望對你有用。$B$B等我慢慢爬下去之後就會離開了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98189,'zhTW','你成功把它從那些怪物的手上奪回來了！如今先王留下來的文物已經所剩無幾了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98190,'zhTW','感謝你找回這個雕像。知道它沒有落入壞人之手讓我如釋重負。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98191,'zhTW','聖光啊…它看起來就像他的兒子一樣…$B$B<格雷森‧破影者領主停頓了片刻。>$B$B這個雕像確實受到了祝福。它與泰瑞納斯的聯繫、以及它在那怪物對國王下毒手後依然留存了下來…對那些信仰其力量的人來說，它蘊含著龐大的能量。$B$B目前最好把它放在這裡，由聖騎士教團負責看守。我們會進一步對它進行冥想，以了解更多關於其恩賜的奧秘，也許它能在未來的黑暗時期為我們提供幫助。$B$B謝謝你，$C。願聖光祝福你。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98197,'zhTW','啊！雖然有點潮濕，但只要放在太陽底下幾天就能曬乾了。$B$B謝謝你，$C。難得不用完全依賴塞拉摩或奧伯丁的物資運送，這感覺真好！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98219,'zhTW','啊，當然了。又一個暴風城的精英跑來關心我。就跟上個月一樣！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98221,'zhTW','連鐵爐堡也是？納克羅什果然繼承了他父親的野心！$B$B當然了，他所缺乏的是在戰爭中展現出毀滅力量的紅龍奴隸大軍。他著實下了一步險棋…而他將為此付出慘痛的代價。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98282,'zhTW','太好了！這正好是我需要的。你知道嗎，你真是個英雄。$B$B請拿著吧，如果我不把你的勞動成果分一些給你，那就太失禮了。在外面要注意安全！',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98285,'zhTW','好了，你現在可以製作自己的材料機器人了。大多數人都不太樂見有人在城鎮中心搭建營地，如果你想測試一下，就得去找個荒郊野外。$B$B喔，記住，每個營地都需要營火。在搭建營地之前，需要先升起營火。大多數廚師都能教你如何升火。如果你還沒學會，可能需要找個能教你廚藝的人，學習一些基本技巧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98298,'zhTW','看來笑到最後的人是我，哈哈！阿魯高真是個傻瓜。而我，達拉爾‧織曦者，徹底揭穿了他這個騙子的真面目。$B$B這些碎塊就是我所需的所有鐵證，足以證明這個詛咒跟那個喋喋不休的蠢貨一點關係也沒有。$B$B遺憾的是，這也意味著他提供的解藥同樣一文不值。看來解開狼人詛咒的方法還得繼續尋找下去了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98387,'zhTW','做得好，$N。黑石獸人斷了與燃燒平原之間的補給後，就沒辦法在這裡長久維持了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98391,'zhTW','很高興你這麼快就來的。姐妹會需要你的協助。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98392,'zhTW','<阿瑞尼亞細細檢視著護符。>$B$B你有看到寶石裡閃爍的綠色漩渦嗎？這果然被魔苔給腐化了。$B$B我從幽影谷和林地某處也聽到相似的消息，說這樣的物質讓整個世界都和我們對抗起來。$B$B我會馬上把這個消息告訴長官。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98398,'zhTW','當你看著掉落的樹皮時，有個聲音傳到你的腦海之中。那個聲音很平靜，好像微風撫過樹葉那樣輕柔。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98403,'zhTW','我早就該知道用來扭曲蜘蛛的就是這個東西。$B$B我曾聽說這個物質就是為我們帶來腐化的源頭。雖然這不是這個樣本已經過了很長一段時間，但或許握有我們未知的情報。$B$B照理來說，我得請你把這個交給達納蘇斯進行研究。不過，這件事還是先暫時保密，不然多蘭納爾將會聲敗名裂。$B$B相信你能守住這個秘密。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98407,'zhTW','你收集得還真多。$B$B這雖然無法解決我們的問題，但知道他們不敢再度進犯，我也能好好休息一下了。做得好，$N。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98423,'zhTW','沒錯，在蠻錘、銅鬚和黑鐵矮人之間的內戰後，我的祖先瑪多蘭是第一位鐵爐堡的銅鬚國王。這份條約是在銅鬚氏族贏得山脈的領地後，為了確立停止敵對行動和和平條約而起草的。$B$B如你所見，蠻錘和銅鬚矮人都在上頭簽了字…但黑鐵矮人卻沒有。$B$B謝謝你找回這樣東西，還把它帶來給我，$C。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98512,'zhTW','幸好你回來了。那些奧拉凱斯看起來是冷血的殺手。$B$B多謝有你的協助，我回到瓦拉納爾會把這件事寫在報告裡。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98545,'zhTW','多謝你把這個拿來給我，夥計。$B$B等等…他說我會給你報酬？我可沒說好欸！$B$B好吧。你可以在這些失物中挑一個垃圾拿走。知道那些被遺忘者在剪頭髮的時候會把這麼多東西遺忘在這裡，你一定會很吃驚。雖然這是開他們沒腦袋的玩笑，但我想應該其中可能有很多人真的沒有腦袋。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98815,'zhTW','這一定是我碰過最優質的皮革了，這些絕對能為我所有的精美飾邊增添絕佳的細節。謝謝你，$N。$B$B試穿看看這些，挑一件你喜歡的當報酬吧。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98823,'zhTW','啊…這塊裂片正發出世界本身的嗡鳴。其中的光芒是來自過去的記憶，閃爍著歷史的微光。這個泰坦機械想必長久以來一直在等待著被人理解。$B$B你把它帶給我們是明智的決定。陶土議會將會守護它、研究它，並在我們得以接收它的訊息時，共同分享它所保存的真相。$B$B旅行者，你今天向元素致予了敬意。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (98824,'zhTW','你手上拿的是什麼…$B$B哇！瞧瞧這個奇蹟！光線穿透它舞動的樣子，簡直就像我第一次在古老的奧達曼挖掘時所見過的一樣。我絕不可能認錯這上面的守衛者印記。$B$B你把這寶物帶回來，可是幫了探險者協會一個大忙。像這樣的發現，將會大大拓展整個世界的見識。$B$B我們一定會將你的貢獻鉅細靡遺地記錄下來！真的做得太好了，冒險者。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (99046,'zhTW','伊露恩保佑…我絕不會…獨自死去…',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (99047,'zhTW','鷹身人受到某種汙穢折磨，這種汙穢也遍佈在這片森林中。我敢說伊拉亞哨兵也受到了影響。$B$B我們得把握時間。用不了多久她就會傷重不治。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (99048,'zhTW','黑格蘭冰冷的屍體倒在小屋的殘骸中。$B$B殺死她的東西似乎並不是人類。附近或許有事發經過的線索。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (99049,'zhTW','這個旌旗和刀刃碎片是納迦的東西！他們一定是從北方的海岸過來的。$B$B我們不能讓他們在這裡建立據點。兩面夾擊的壓力對剃刀嶺來說太過沉重了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (99050,'zhTW','謝謝你幫忙。請收下這個作為瓶子和泉水的補償。$B$B好了，該來做藥膏了。應該不會花太多時間。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (99051,'zhTW','希望這樣能把他們趕回北方去。我會派幾個士兵負責注意有沒有脫隊者或可疑的動靜。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (99052,'zhTW','哈！我在這裡都能聽見他倒下的聲音！$B$B為你今天的戰果自豪吧，能誇耀自己與海巨人大戰一場後全身而退的人可不多。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (99053,'zhTW','感謝伊露恩，幸好有你在附近，才讓莉妮莎免於落入瘤背熊怪手中的悲慘命運。她是我們最優秀的成員之一，也是我的摯友。$B$B請收下這個謝禮。願它能協助你繼續守護卡多雷的安全。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (99073,'zhTW','<隨著你幫助伊拉亞吞下藥膏，她的呼吸也迅速變得平緩。她或許無法活下來，但至少變得相對平靜。>',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (99108,'zhTW','$C，你的本領令我備感榮耀。也許新一代還是有希望的。$B$B用這些來處理你的傷口，這個嚴酷的世界還有許多戰鬥等著你。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (99123,'zhTW','啊，帕朱自己惹上麻煩了，對吧？$B$B希望這次她能學到教訓，不要再獨自行動。謝謝你幫助她。她是個很有潛力的獵人，只是行事往往更像迅猛龍，而不是老虎。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (99127,'zhTW','所有捕魚籠都變成這樣了？看來那些討厭的新鄰居，造成的破壞比我們所知的還嚴重。再不想辦法，我可要破產了。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (99152,'zhTW','新兵，幹得好。看來我們還真能把你訓練成材。$B$B有了這些骨頭，我們或許就能進一步了解，為何如此龐大的威脅能在我們眼皮底下隱藏這麼久。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (99153,'zhTW','幹得好，而且動作俐落！現在該進入我最喜歡的部分了…',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (99260,'zhTW','$N，謝謝你拯救菲利安。想必他已經告訴你派他去取回的資料有多重要了吧。$B$B如果沒有那份資料，我們開啟通往艾澤拉斯安全航線的願景便會岌岌可危。我們的密探回報，塑風者已經掌握了穿越界域的方式，並且他們一定會嚴加看管那個秘密。$B$B一如既往，他們死守教條的傲慢行徑總是凌駕於人民的利益之上。他們只比奧拉凱斯好一點而已。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES (99411,'zhTW','幹得好，$N！凱爾一吃飽就跑回來睡著了。感謝你的幫忙。',0) ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
